// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":26,"question":"ما الفرق بين التعاليم الإسلامية والتقاليد الإسلامية؟ وهل نُطلق على الحجاب الشَّرعي تقليدًا إسلاميًّا أو تعليمًا إسلاميًّا؟ أفتونا مأجورين.","title":"ما الفرق بين التعاليم والتقاليد الإسلامية؟","answer":"الجواب: الأوْلى في مثل هذا أن يُقال: تعليم إسلامي، وتعاليم إسلامية، أحكام شرعية، أحكام إسلامية. أما التقاليد ما لها وجه، التقاليد للعوائد والأعراف، ولا ينبغي استعمالها، وربما أوهم بذلك أنها أشياء ما لها أساس، إنما هي تقليد وأعراف، هذا غلط. بل يقال في الأحكام الشرعية: أحكام إسلامية، تعاليم شرعية، وما أشبه من العبارات التي تنسب العمل إلى الشرع المُطهر إذا كان من الشرع المطهر. أما إذا كان أعرافًا: في البناء، في الفُرُش، في أكل الطعام، هذه أعراف، فإنَّ الناس تختلف، أما ما يتعلق بأحكام الشرع فيُقال: تعاليم إسلامية، أو أحكام إسلامية، أو تعاليم شرعية، أو أحكام شرعية، أو ما أشبهها من العبارات.","link":"https://binbaz.org.sa/fatwas/2806/ما-الفرق-بين-التعاليم-والتقاليد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0279.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":40,"question":"سؤاله الثالث يقول: فيه سماحة الشيخ دلني على كتاب أو كتابين جيدَين؛ لأتفقه بهما في أمر ديني!","title":"ما الكتب التي يوصى بها للتفُّقه في الدين؟","answer":"الجواب: أدلك على كتب مناسبة، منها:\n- \"بلوغ المرام\" للحافظ ابن حجر، وهو كتاب جيد في الحديث.\n- و\"الأربعون النووية\"، وتتمتها لـ ابن رجب خمسين حديثًا.\nوهذان الكتابان في الحديث كتابان عظيمان.\nوفي الفقه أدلك على:\n- \"آداب المشي إلى الصلاة\"، للشيخ محمد بن عبد الوهاب رحمه الله، فإنه كتاب جيد في الصلاة، وفي الزكاة، وفي الصيام، جمع فيه كلمات طيبة وعبارات مفيدة.\nوهكذا أرشدك إلى \"زاد المعاد\"، لـ ابن القيم، فإنه كتاب جيد مفيد، سماه مؤلفه: \"زاد المعاد في هدي خير العباد\"، وهو كتاب جيد ومفيد.\nوهذان كتابان جيدان، مفيدان.\nومن الكتب الطيبة النافعة:\n\"الوابل الصيب في الكلم الطيب\" لـ ابن القيم رحمه الله، فإنه ذكر فيه فوائد جمة في أوله، وأبوابًا مفيدة في الأذكار.","link":"https://binbaz.org.sa/fatwas/2820/ما-الكتب-التي-يوصى-بها-للتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0013.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":53,"question":"وصلنا من الأخوات سؤال يقول: يا فضيلة الشيخ إذا أرادت المرأة العمل في مجال الدعوة في المجتمع فما هي الكتب التي تنصحون بقراءتها ومناقشتها بين النساء سواء للمتعلمات أو الجاهلات بشكل مبسّط؟","title":"ما أهم الكتب في الدعوة إلى الله؟","answer":"الجواب: أهم شيء القرآن الكريم، تعليم القرآن وما تيسّر منه؛ لأنه كتاب الله فيه الهدى والنور: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] فنصيحتي لأخواتي الدعاة إلى الله من النساء أن يعنين بالقرآن الكريم تفقهًا وتفيقهًا وتعليمًا للنساء، وما يتعلق بالسور القصيرة، وأهم ذلك الفاتحة، تعليم الفاتحة ومعانيها؛ لأنها أم القرآن، وفيها: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وفيها: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] هذا من أهم ما يُبَيَّن، معنى الصراط المستقيم ما هو، معنى: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] معنى صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ [الفاتحة:7] وهكذا ما في كتاب الله من الأحكام والبيان؛ كُلٌّ على حَسَبه، لطالبات العلم شيء، وللعامة من النساء شيء آخر. ثم تعليم العقيدة: ما معنى لا إله إلا الله، ما معنى شهادة أن محمدًا رسول الله؛ حتى يعرفن الله على بصيرة وحتى يعلمن معنى لا إله إلا الله وأنه لا معبود حَقٌّ إلا الله؛ فيخلصن العبادة لله وحده من صلاة وصوم وصدقة، وغير ذلك كله لله وحده، ثم تعليم الصلاة كيف تصلي، والطهارة كيف تطهر من الجنابة من الحيض من النفاس، كيف الطهارة الصغرى من الأحداث التي توجب الطهارة، كيف تصوم، كيف تزكي مالها وحُلِيَّها، كيف تحج إذا جاء الحج، كيف تطيع والديها، كيف تطيع زوجها وما حق زوجها عليها، إلى غير هذا، ومن الكتب التي تناسب قراءتها ما ألف في أمر النساء وشأن النساء وما في كتاب الله من شأنهن وما جاءت به السنة بشأنهن، في \"بلوغ المرام\" مثلًا كتاب صغير مختصر مفيد، عمدة الحديث في أحاديث الرسول ﷺ، عمدة الفقه للموفق ابن قدامة، \"ثلاثة الأصول\" للشيخ محمد بن عبد الوهاب، \"كتاب التوحيد\"، \"العقيدة الواسطية\"، وما أشبه هذه من الكتب الصغيرة التي تنفعهن وتفيدهن، أو ملخص منها؛ حتى يستفيد منهن العامة والطالبات الصغيرات اللآتي يحتجن إلى ذلك ولم يتعلمن في المدارس.\nأما من يتعلم في المدارس الطيبة فسوف يستفيد من المنهج الذي عنده والمقررات التي عنده، ولكن لا مانع من الزيادة؛ أن تكون الداعية تزيد الطالبة علمًا وتفقيهًا وتوجيهًا، وتعلّم العامية ما يلزمها مما لا يسعها جهله في إخلاص العبادة لله بالصلاة بالطهارة في الزكاة في الصيام كما تقدم، في حق الزوج في حق الوالدين في حق الأقارب في حق الجيران وما أشبه ذلك، ومن أحسن الكتب أيضًا وإن كان مطولا بعض الطول \"زاد المعاد في هدي خير العباد\" لابن القيم فإنه كتاب مفيد ونافع، وهكذا \"فتح المجيد شرح  كتاب التوحيد\" كتاب مفيد أيضًا في العقيدة، وهكذا \"آداب المشي إلى الصلاة\" مختصر مفيد في الصلاة وفي الزكاة وفي الصيام للشيخ الإمام محمد بن عبد الوهاب رحمة الله عليه، هذه كتب مختصرة مفيدة.","link":"https://binbaz.org.sa/fatwas/2964/ما-اهم-الكتب-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0027.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":63,"question":"سماحة الشيخ أفيدونا أثابكم الله، من المعلوم أن ديننا وسط، ولكن الإفراط في بعض المسائل، فهل معنى هذا التوسع في الفُتْيا أو التمسك بسد الذرائع والتوسع في الفتيا، والاقتصار على النصوص؟","title":"ما النصيحة لمن يتوسع في الفُتْيا؟","answer":"الجواب: هذا مقام عظيم مقام، مقام....... فالواجب عدم التوسع في الفتيا، الواجب على المؤمن أن يخاف الله ويراقبه، وألا يفتي إلا عن بصيرة وعن نص عَرَفَه، وإذا لم يكن هناك نص فلا بدّ من اجتهاد عند الضرورة وتحرٍّ للحق إذا كان من أهله إذا كان عنده علم بالنصوص من الكتاب والسنة والقواعد الشرعية، فلا بدّ يتحرى الحق عند الضرورة، ويجتهد في الإفتاء عند الضرورة. كان الصحابة  يتدافعون الفتوى بينهم؛ حرصًا منهم على السلامة وحذرًا من خطر الفتوى فينبغي للمؤمن ألا يكون حريصًا على الفتوى، لا سريعًا في الفتوى، وإذا رأى من هو أفضل منه أحال إليه؛ لأنه أقرب إلى الصواب منه، كما فعل الصحابة رضي الله عنهم وأرضاهم؛ فينبغي للمفتي ألا يتوسع في الفتوى، وأن يحرص على تحري الحق بالدليل، وأن يفتي على مقتضى الدليل حسب الطاقة والإمكان، إرشادًا للأمة وتوضيحًا للحق، وإذا كان في المقام إشكال؛ توقف ولم يُفْت حتى يحقق الأمر وحتى يتضح له وجه الصواب وإن كان من أعلم الناس؛ فالصحابة أعلم الناس بعد الأنبياء وكانوا يتوقفون في مسائل كثيرة ويحيل بعضهم على بعض؛ حذرًا من خطر الفتوى، وهكذا الأئمة بعدهم،  ورحمهم.","link":"https://binbaz.org.sa/fatwas/2979/ما-النصيحة-لمن-يتوسع-في-الفتيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0038.mp3","categories":["العالم والمتعلم","أصول الفقه"]},{"id":68,"question":"هذه سائلة تقول: أنا أريد أن أحفظ القرآن الكريم فبماذا تنصحني، وأرجو منكم الدعاء لي بأن الله يثبتني، ويسهل لي حفظ القرآن؟","title":"ما الوصية لمن يريد حفظ القرآن الكريم؟","answer":"الجواب: أوصيكِ بالجد في ذلك، والمواظبة في حفظ القرآن ليلاً أو نهاراً، والاستمرار وسؤال الله التوفيق والإعانة، وأن تكون عندك مدرّسة جيدة إذا تيسر، أو زميلة تساعدك في ذلك مع الاستمرار، وسؤال الله العون والتوفيق، والله يعينك، متى جاء الإخلاص والصدق؛ يَسَّر الله الأمر وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا[الطلاق:4].","link":"https://binbaz.org.sa/fatwas/2986/ما-الوصية-لمن-يريد-حفظ-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0045.mp3","categories":["القرآن وعلومه","العالم والمتعلم"]},{"id":78,"question":"سائلٌ يقول: هناك مَن يُحذِّر من كتب الإمام النووي وابن حجر رحمهما الله تعالى، ويقول: إنَّهم ليسوا من أهل السنة والجماعة، فما الصَّحيح في ذلك؟","title":"ما صحة التحذير من كتب النووي وابن حجر؟","answer":"الجواب: لهم أشياء غلطوا فيها في الصِّفات: ابن حجر، والنووي، وجماعة آخرين، ليسوا فيها من أهل السنة، وهم من أهل السنة فيما سلموا فيه ولم يُحرِّفوه، هم وأمثالهم ممن غلط.","link":"https://binbaz.org.sa/fatwas/3049/ما-صحة-التحذير-من-كتب-النووي-وابن-حجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0055.mp3","categories":["العالم والمتعلم"]},{"id":234,"question":"هنا مجموعة من الأسئلة فضيلة الشيخ، تدور حول دراسة العلوم الدنيوية: هل تُعتبر من الدراسة المُفيدة للمسلم؟","title":"ما حكم وأهمية دراسة العلوم الدنيوية؟","answer":"الجواب: لا شكَّ أن الدراسة للعلوم الدنيوية أمرٌ مطلوبٌ، والله يقول سبحانه: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60]، فالمسلمون بحاجةٍ إلى العلوم الدنيوية حتى يستعينوا بها على طاعة الله، وعلى الاستغناء عمَّا في أيدي الناس، وعلى جهاد أعداء الله، مع كون المسلمين يتعلَّمون الجيولوجيا والهندسة والطب وغير ذلك مما يُعينهم، وكذلك ما يخترعون في القوة التي يُجاهد بها الأعداء؛ كل ما يُعينهم على جهاد الأعداء واتِّقاء شرِّ الأعداء ويغنيهم عن الأعداء فهو أمرٌ مطلوبٌ: يَا أَيُّهَا الَّذِينَ آمَنُوا خُذُوا حِذْرَكُمْ [النساء:71]، وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60].\nفالاشتغال بالعلوم الدنيوية التي تنفع المسلمين إن كان لله؛ أُجِرَ عليها، مع فائدتها العظيمة، وإن كان يتعلَّمها للدنيا ليستفيد في دنياه فهذا مباحٌ ولا يضرُّه ذلك. لكن العلوم الدينية أهم، فليأخذ منها بنصيبٍ، ويجتهد في تعلم دينه، والتَّفقه في دينه، ثم مع ذلك يتعلم ما ينفعه في دنياه إذا استطاع ذلك، وإذا جمع بين الأمرين فهو خيرٌ إلى خيرٍ، يقول النبيُّ ﷺ: مَن يُرد الله به خيرًا يُفقهه في الدين، فإذا تفقَّه في دينه واستفاد مع ذلك في دنياه طبًّا أو صنعةً أخرى تنفعه أو أشياء مما ينفع العبدَ في هذه الدنيا؛ فذلك خيرٌ إلى خيرٍ.\nوقد قال عليه الصلاة والسلام في الحديث الصحيح لما سُئل: أي الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيع مبرور، وقال عليه الصلاة والسلام: ما أكل أحد طعامًا أفضل من أن يأكل من عمل يده، وإن نبي الله داود كان يأكل من عمل يده، كان صاحب حدادةٍ، كان يصنع الدروع عليه الصلاة والسلام، وهو نبي الله، يصنع الدروع التي يُتَّقى بها في الحرب، تُستعمل في الحرب، وكان زكريا نجارًا، وهو نبيٌّ من أنبياء الله عليه الصلاة والسلام.\nفإن انتفع بصنعة النِّجارة، أو الدروع، أو المدافع، أو الصواريخ، أو سائر أنواع السلاح؛ فهذا خيرٌ عظيمٌ، ومع النية الصَّالحة، فهو على خيرٍ عظيمٍ، وهو عبادة.\nكذلك صحَّ عن رسول الله عليه الصلاة والسلام أنه قال: الساعي على الأرملة والمسكين كالمُجاهد في سبيل الله، قال: وأحسبه قال: وكالصَّائم لا يُفطر، والقائم لا يفتر، فالساعي يعني: العامل على نفع الفقير والأرملة والمسكين، يُعينهم على ما عندهم من فقيرات: بنات، أخوات، وأولاد  فقراء أو يتامى يستسعى عليهم حتى يستغنوا عمَّا في أيدي الناس، حتى ينفق عليهم، كالمُجاهد في سبيل الله، هذا أمرٌ عظيمٌ، وخيرٌ كبيرٌ، فطالب الرزق بالزراعة، بالتجارة، بالصناعة على خيرٍ عظيمٍ.\nفتعلم العلوم الدنيوية أمرٌ مفيدٌ ونافعٌ، بشرط ألا يشغل عن علم الآخرة وعمَّا ينفعه في الآخرة، فإن جمع بينهما فقد جمع خيرًا إلى خيرٍ، وإن صلحت نيته في علوم الدنيا كانت عبادةً، وإذا تعلَّمها للدنيا فليس له ولا عليه، تعلم شيئًا مباحًا، لا حرج عليه، لكن متى صلحت نيته وأراد بهذا نفع المسلمين وتقويتهم ضدّ عدوهم؛ جمع الله له الخيرين: الأجر، ومع ذلك النَّفع بهذا المُتعلَّم.","link":"https://binbaz.org.sa/fatwas/4092/ما-حكم-واهمية-دراسة-العلوم-الدنيوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0244.mp3","categories":["العالم والمتعلم"]},{"id":262,"question":"صاحب السماحة، ما واجب العلماء في أداء الأمانة العلمية نحو الصَّحوة الإسلامية، ومسؤوليتهم في قيادتها وترشيدها وفَّقكم الله؟","title":"ما واجب العلماء تجاه الصحوة الإسلامية؟","answer":"الجواب: واجبهم أن يُعينوا المُوفَّقين لهذه اليقظة والحركة، وأن يقودوهم إلى الخير، وأن يُشجِّعوهم، وأن يُبَصِّروهم ويُنَبِّهوهم على ما قد يغلطون فيه، حتى تكون هذه اليقظة وهذه الحركة حركةً سديدةً، ويقظةً مُستقيمةً إلى الأمام؛ ليسعد بها أهلُها ومَن تابعهم، هذا هو واجب أهل العلم: تشجيع الشباب وغير الشباب على ما مَنَّ الله عليهم من اليقظة والانتباه، والرغبة في الدين، والإخلاص لله في ذلك، والحرص على أداء ما أوجب الله، وأن يُشجعوا على هذا الخير، ويشكروا عليه، رجالًا كانوا أو نساء، فهي يقظةٌ عامَّةٌ للرجال والنساء، موجودة في هذه البلاد –المملكة- وفي غير المملكة.\nفهي بحمد الله تُبَشِّر بالخير في زمن هذه الغُربة، يقظة عظيمة إسلامية ظاهرة في آسيا، وفي إفريقيا، وفي أوروبا، وفي أمريكا، وفي كل مكانٍ، وفي هذه المملكة بحمد الله شيءٌ كثيرٌ من ذلك.\nفالواجب على أهل العلم أن يُشجعوا أهلَها، وأن يشرحوا لهم ما قد يخفى عليهم، وأن يُنَبِّهوهم على ما قد يقع من الزيادة والخطأ، حتى تكون المسيرةُ صالحةً ومستقيمةً على الطريق السَّوي، من دون إفراطٍ أو تفريطٍ، فإنَّ السائر إلى الله قد يُبتلى بالإفراط والغلو؛ لجهله وحرصه على الدين على غير بصيرةٍ، فيُفرّط ويزيد ويقع في البدع، وقد يُبتلى الإنسانُ بالتفريط والجفاء إذا ضعف إيمانُه؛ فيقع في المعاصي والشُّرور، وخير الأمور أوساطها، التوسط هو الحقُّ، فلا إفراطَ ولا تفريطَ، ولا غلوَّ ولا جفاء، بل يلزم الحقّ الذي سار عليه نبينا عليه الصلاة والسلام وصحابته  وأتباعهم بإحسانٍ، يلزم طريقهم، ويستقيم على طريقهم، ولا يحيد عنهم، لا يمنةً، ولا يسرةً، وإذا رأى مَن حاد بغلوٍّ وإفراطٍ نصحه حتى يردَّه إلى الصواب، وإذا رأى مَن حاد عن هذا الطريق بالجفاء والإعراض والغفلة نصحه حتى يرجع إلى الصَّواب.","link":"https://binbaz.org.sa/fatwas/4256/ما-واجب-العلماء-تجاه-الصحوة-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0307.mp3","categories":["العالم والمتعلم"]},{"id":263,"question":"سماحة الشيخ، بما أنَّ وحدة الجماعة المُسلمة هي الأصل في بناء المجتمع المسلم، وبما أنه قد ثبت أنَّ التفرق تحت اسم الأحزاب أو الجماعات يهدم هذا الأصل أو يُضعفه على الأقل، ويجعل إفساد ذات البين مكان الأخوة الإسلامية، و ما واجب علماء الإسلام في ردِّ المسلمين إلى الأصل وتحذيرهم من التَّفرق والتَّحزب أثابكم الله؟","title":"ما واجب العلماء تجاه الحزبيات والتَّعصبات؟","answer":"الجواب: لا شكَّ أنَّ تفرق المسلمين وتقطعهم فرقًا وأحزابًا مما يُطمع عدوَّهم فيهم، ومما يُضعف كيانهم وكلمتهم، ومما يُسبب خذلناهم عند اللِّقاء، قال الله سبحانه: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا [آل عمران:103]، وقال : إِنَّ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا لَسْتَ مِنْهُمْ فِي شَيْءٍ [الأنعام:159]، وقال تعالى: وَلَا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِنْ بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ [آل عمران:105]، في آياتٍ كثيرة يحثّ فيها سبحانه على الاجتماع والتَّعاون والتَّرابط، ويُحذّر من الاختلاف والتَّفرق، ويقول سبحانه: وَلَا تَنَازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ [الأنفال:46].\nفالمسلمون إذا اجتمعوا على كلمةٍ واحدةٍ، وتعاونوا على البرِّ والتَّقوى، وتناصحوا؛ صار ذلك أعظم سببٍ لنصرهم وحمايتهم من مكايد عدوهم، وصار أعظم سببٍ لهيبة عدوهم منهم، وعدم الإقدام على ما يُسبب قيامهم عليهم، وثورتهم ضدهم، كالحبال إذا اجتمعت والعصي إذا اجتمعت لم يستطع قطعها ولا كسرها وهي مُجتمعة، فإذا تفرَّقت عصًا عصًا، وحبلًا حبلًا؛ سهل قطعها وكسرها.\nفالمسلمون إذا اجتمعوا، وتعاونوا على البر والتقوى، وصدقوا مع ولي أمرهم، وصاروا يدًا واحدةً، وجسدًا واحدًا، وبناء واحدًا في نصر الحقِّ، والأخذ به، والدعوة إليه، وفي ترك الباطل، والتحذير منه؛ فإنهم بذلك يستحقُّون نصر الله، وتعظم منزلتهم في القلوب، ويقوى كيانهم، ويخافهم أعداؤهم، ويُنصرون عليهم عند اللقاء.\nأما التَّخلف فهو هضمٌ لهم، وتمزيقٌ لهم، الاختلاف والتنازع فيه هونٌ لهم، وفيه تفريقٌ لشملهم، وبسببه يطمع الأعداء في القضاء على المسلمين، وتفريق كلمتهم.\nفهذه الجمعيات والأحزاب الموجودة في أرض الإسلام يجب عليها أن تتجمع، وأن يكون هدفها واحدًا، وإن تباعدت الأقطار يكون هدفها واحدًا، ومطلبها واحدًا، وهو طاعة الله ورسوله، والاستقامة على دينه، وترك ما نهى الله عنه ورسوله، هكذا تكون أهداف الجميع وإن تباعدوا، فإنَّ الهدف إذا اتَّحد فهم شيءٌ واحدٌ.\nوهذه الجماعات والأحزاب يصعب القضاء عليها، لكن يجب أن تنقاد لأمر الله، ويجب أن تُؤثر طاعة الله، وأن تُعين كلُّ واحدةٍ الطائفة الأخرى على طاعة الله ورسوله، وأن يكون هدفهم واحدًا، وهو الاستقامة على دين الله، وتنفيذ أحكامه، وترك ما خالف شرعه، فإذا اتَّحدت كلمتهم على هذا وتعاونوا على هذا لم يضرّهم تنوع الجمعيات، أو تنوع الأسماء، إذا اتَّحدت الأهدافُ، وتضافرت الجهود، وصار هدفُهم واحدًا، ومقصودهم وحدًا، وهو تحقيق طاعة الله ورسوله، وترك ما نهى الله عنه ورسوله.\nوهذا إنما يتيسّر بقيام العلماء أينما كانوا من واجبهم وتعاونهم، وأن يكون لهم الاجتماعات والمُذاكرة في هذا الأمر، وبذل المُستطاع في تخفيف ما بين الجمعيات والأحزاب من نفرةٍ واختلافٍ، وبذل المُستطاع في جمع كلمتهم، وتوحيد صفِّهم لنصر دين الله، واتِّباع شريعته، هذا هو طريق السعادة، والله المُستعان.","link":"https://binbaz.org.sa/fatwas/4257/ما-واجب-العلماء-تجاه-الحزبيات-والتعصبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0308.mp3","categories":["العالم والمتعلم"]},{"id":276,"question":"أرجو منكم توضيح الطريق الأمثل لطلب العلم، وكيف يكون؟ وهل له شروط؟ وما العلوم التي يبدأ بها أولًا دون غيرها؟ وما الكتب التي تنفع؟","title":"ما الطريق الأمثل في طلب العلم؟","answer":"الجواب: طلب العلم مثلما تقدم من أهم المُهمات، وأعظم شرطٍ له: الإخلاص لله ، ثم الجدّ والمُثابرة والصبر، وكثيرٌ من الناس قد يطلب العلمَ، ولكن لا يكون عنده الجدُّ والصبر والثبات، فلا بدّ من نيَّةٍ صالحةٍ وإخلاصٍ لله  في ذلك، ولا بدّ من جدٍّ ونشاطٍ وصبرٍ.\nثم العناية بالأصول: دراسة العقيدة، وهي الكتب المُختصرة في بيان حقيقة ما بعث الله به الرسل، وأنزل به الكتب، وخلق من أجله الثَّقلين، حتى تكون هي الأساس، وهي: الإيمان بالله وحده، وأنه المُستحقُّ للعبادة، والإيمان بأسمائه وصفاته كما جاءت في الكتاب والسنة، بغير تحريفٍ، ولا تعطيلٍ، ولا تكييفٍ، ولا تمثيلٍ، وحفظ ما تيسَّر من المتون في ذلك، وحفظ ما تيسر أيضًا من متون الحديث، مع ما يلزم من العناية بالقرآن الكريم، وحفظ ما تيسر منه في أول الطريق، ولا يزال يسير في حفظ كتاب الله مع ما تيسر من المتون في العقيدة والحديث حتى يُكمل كتاب ربِّه حفظًا، وحتى يكمل ما تيسر من المتون الأساسية لحفظ العقيدة، وجملة من الأحاديث الشريفة التي يحتاجها المؤمنُ في عقيدته، وفي أصل دينه.","link":"https://binbaz.org.sa/fatwas/4273/ما-الطريق-الامثل-في-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0322.mp3","categories":["العالم والمتعلم"]},{"id":277,"question":"أنا طالب علم، وطلبي لهذا العلم هو من أجل أن أتوظَّف أو أكسب المال، بينما لو تخرجتُ من الدراسة ولأجل الوظيفة لم أحرص عليه كحرصي حينما توجد وظيفة، هل يجوز الجمع بين نيَّة الدين والدنيا، يعني: يتعلم للمال.....؟","title":"حكم طلب العلم للوظيفة والدنيا","answer":"الجواب: الواجب تخليص النية وجعلها لله وحده، لتعلم حكم الله وما خُلقت لأجله، وحتى تعمل بشرع الله على بصيرةٍ، ويكون ذلك الأمر الثاني تبعًا، فإنَّ الرزق عند الله، ولا بدّ من العمل لطلب الرزق، لكن تكون النية مُمحضةً لله وحده في طلب العلم، ثم إذا حصلت العلمَ فلا مانع من أن تتوظف أو تعمل أعمالًا حُرَّةً ليس لها دخلٌ في الوظائف.\nأما طلب العلم لأجل الوظيفة فهذه خسارة كبيرة، وغلط عظيم، ولكن المؤمن قد ينوي هذا، ثم يُوفَّق للنية الصَّالحة، كما قال بعضُ السلف: \"طلبنا العلم للدنيا -وفي اللفظ الآخر: طلبنا العلم لغير الله- فأبى أن يكون إلا لله\"، فالطالب قد يطلب العلم للوظيفة أو لأسبابٍ أخرى، ثم يُعان ويُوفَّق على الإخلاص، يُوفَّق للإخلاص ويخلص لله.\nفالحاصل أنَّ على طالب العلم المُجاهدة، ويُجاهد نفسه ليكون طلبه لله، وهذه النية التي تُخامره وتُقلقه يُحاربها حسب طاقته، حتى يكون طلبُه لله وحده، ثم تجيء الوظيفة، وتجيء الدنيا بعد ذلك تبعًا، والله المستعان.","link":"https://binbaz.org.sa/fatwas/4275/حكم-طلب-العلم-للوظيفة-والدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0324.mp3","categories":["العالم والمتعلم"]},{"id":278,"question":"يقول سائلٌ آخر: من الشُّبَه التي ترد على النفس: أني إذا حفظتُ القرآن مثلًا نسيت، وإذا حفظتُ أحاديث أو غير ذلك أنسى، فيكون حُجَّةً عليَّ، فلا داعي لأن أحفظ، فكيف تردُّون على هذه الشُّبَه؟","title":"ما النصيحة لمن يخشى نسيان حفظ العلم؟","answer":"الجواب: كل هذا من الشيطان، فإن الإنسان إذا اجتهد فحفظ ما تيسر لا يضرُّه لو نسي، أما حديث: مَن حفظ القرآنَ ثم نسيه لقي الله وهو أجذم فهو حديثٌ ضعيفٌ لا يصحُّ عن النبي ﷺ، وقد نسي النبيُّ ﷺ في صلاته وقال: إنما أنا بشر، أنسى كما تنسون، فإذا نسيتُ فذكِّروني، ونسي بعض الآيات فقال: رحم الله فلانًا، لقد أذكرني آيةَ كذا وآيةَ كذا كنتُ أسقطتُها، هذا لا بد منه، هذا من طبيعة البشر.\nفالإنسان يجتهد ويتعلم ويحفظ ما تيسر من القرآن والحديث، ولو قُدر أنه نسي بعض الآيات وبعض الأحاديث لا يضرُّ، لا ييأس، هذه الدار دار المُجاهدة، لا بدّ من جهادٍ: يحفظ وينسى، ثم يُجاهد، ثم يحفظ، ثم ينسى، وهكذا حتى يستقرَّ.\nوهكذا الناس: كل مَن حفظ القرآنَ لا بدّ أن ينسى شيئًا، لكن مع المُجاهدة ومع الصدق ومع الصبر يستقرُّ، والحمد لله.\nوهكذا في الأحاديث يحفظ وينسى، ويحفظ وينسى، مع المجاهدة يستقرُّ، أو يستقر أكثره، والحمد لله.\nلا يضرُّك إذا نسيتَ شيئًا، وإنما يضرُّك الإهمال والإعراض والغفلة، أما ما دمت تُجاهد وتحرص وتتذكر ما نسيت فهذا جهادٌ عظيمٌ في سبيل الله، ولك فيه أجرٌ عظيمٌ في هذا الجهاد.","link":"https://binbaz.org.sa/fatwas/4276/ما-النصيحة-لمن-يخشى-نسيان-حفظ-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0325.mp3","categories":["العالم والمتعلم"]},{"id":279,"question":"يُلاحظ على كثيرٍ من الشباب الصالح أنَّ قسمًا منهم اتَّجه إلى طلب العلم وترك الدعوة إلى الله، مع القُدرة على ذلك، والقسم الآخر اتَّجه إلى الدعوة إلى الله وترك طلب العلم، فأيُّهما أفضل؟","title":"كيف يكون الجمع بين طلب العلم والدعوة؟","answer":"الجواب: لا هذا، ولا هذا، الواجب الجمع بينهما، وألا يزال طالبًا وداعيًا إلى الله ، فوقتٌ لهذا، ووقتٌ لهذا، والأمر ممكنٌ، فطالب العلم يعتني بطلب العلم ويتزود، والله قال لنبيه: وَقُلْ رَبِّ زِدْنِي عِلْمًا [طه:114]، وهو نبي الله عليه الصلاة والسلام، فلا يزال طالبُ العلم في طلب العلم، ولو كان في القمة لا بدّ أن يطلب العلم، ولا بدّ أن يجتهد في المُراجعة، وفي المُذاكرة -مذاكرة أهل العلم فيما أشكل عليه- حتى يزداد علمًا، فيجمع بين الأمرين: بين حلقات العلم، بين مطالعة الكتب، بين المُذاكرة مع زملائه وإخوانه، وبين الدَّعوة إلى الله في أهله وجيرانه وبلده وغيرها، فلا ينفرد للدعوة فقط، ولا ينفرد للتعلم فقط، ولكن يجمع بينهما.\nففي أول الطلب وقبل أن يصل إلى درجة أهل العلم الذين يستقلُّون بالبحث يكون همُّه الطلب، وتكون همَّته مصروفة إلى طلب العلم، ويكون وقته على هذا الشيء الذي يكون هو المُقدم، وهو طلب العلم، حتى يزداد علمًا، وحتى يتأهَّل للدعوة، ويتأهل للمُذاكرة ومُراجعة الكتب في أول الطريق، لا يتأهَّل لهذا الشيء، فلا بدّ أن يكون عنده علمٌ بالأصول: أصول الفقه، مصطلح الحديث، معرفة الأحكام الشرعية؛ حتى يتأهل لمُراجعة الأدلة، وترجيح الراجح من مسائل الخلاف، وتزييف الزائف، وحتى يتصدر للدَّعوة إلى الله، وحتى لا يقع في تحليل ما حرَّم الله، أو في تحريم ما أحلَّ الله؛ لقلة علمه.\nفلا بدّ من العناية أولًا وقبل كل شيءٍ بطلب العلم والتَّفقه في الدين، ولا يمنعه هذا أن يدعو إلى الله على حسب علمه في محيطه وما حوله، ثم إذا بلغ مبلغ أهل العلم جدَّ في الدعوة إلى الله ، مع بقائه في طلب العلم، ومع بقائه في أسباب التَّحصيل والمُراجعة والمُذاكرة ومُطالعة الكتب، وتحقيق ما أشكل عليه من مسائل الخلاف، لكنه مشغولٌ بالدعوة أكثر؛ لتأهّله لهذا الشيء، ولكونه حصَّل من العلم ما يجعله أهلًا لأن يُعلِّم، ولأن يدعو إلى الله، ويُرشد الناس إلى الخير.","link":"https://binbaz.org.sa/fatwas/4277/كيف-يكون-الجمع-بين-طلب-العلم-والدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0326.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":300,"question":"أنا شابٌّ أريد طلب العلم، فأي العلوم أبدأ بها؟ وأي المتون أبدأ بحفظها؟ مع العلم أني طالبٌ مُستجدٌّ في كلية الشريعة. جزاكم الله خيرًا.","title":"ما الكتب التي يبدأ بها طالب العالم المبتدئ؟","answer":"الجواب: ينبغي لطالب العلم أن يبدأ بكتاب الله، والعناية بكتاب الله قراءةً وتدبُّرًا وتجويدًا وحفظًا لما تيسر منه، ثم مع ذلك المتون التي تصلح بها عقيدته وفهمه للقرآن، كما تعلمنا وتعلم غيرنا، تبدأ بكتاب العقيدة حتى ترسخ في القلب في الصِّغر -مع حفظه لكتاب الله وما تيسر منه، والإكثار من تلاوته- مثل: كتاب \"التوحيد\" و\"كشف الشبهات\" و\"العقيدة الواسطية\" و\"ثلاثة الأصول\" وأشباه ذلك من الكتب المُختصرة المُوجزة فيما يتعلق بالعقيدة التي بعث الله بها نبيَّه محمد عليه الصلاة والسلام. ثم بالكتب المُوجزة أيضًا في القواعد العربية، في الفقه والحديث، حتى يكون عنده أساسٌ محفوظٌ، مثل الصغار؛ يبدؤون بـ\"الآجرومية\" أو ما يقوم مقامها، أو مثل \"القطر\" وما يقوم مقامه بعد ذلك، ثم آخره ما يكون كـ\"الألفية\" لابن مالك وما يتعلق بشروحها وحواشيها، فيما يتعلق بالقواعد العربية.\nلكن في الأساس يبدأ بكتب العقيدة مع القرآن الكريم، والقرآن هو أصل كل خيرٍ، وهو أصل العقيدة، وهو أصل السعادة، وما تيسر من حفظ السنة، مثل: \"الأربعين النووية\" وتتمّتها لابن رجب \"خمسون حديثًا\"، كلها مهمة، ومثل: \"عمدة الحديث\" بعد، إذا تيسر له ذلك حال طلبه، ثم \"بلوغ المرام\" كذلك.\nهذه أصول في الحديث، وفي العقيدة: كتاب \"التوحيد\" و\"العقيدة الواسطية\" و\"كشف الشبهات\" و\"ثلاثة الأصول\"، هذه من الصِّغر، وفي الفقه مثل: \"عمدة الفقه\" للمُوفَّق، ومثل: \"مختصر المقنع\" المُسمَّى \"زاد المُستقنع\"، ومثلهم من الكتب التي تُؤلف في الفقه، وهي مُختصرة، تكون أصلًا في الفقه، يستنبط منها، ويتخرج منها إلى معرفة الكتب المطولة، والمسائل التي يرى الحاجة إلى البحث فيها بالأدلة.","link":"https://binbaz.org.sa/fatwas/4302/ما-الكتب-التي-يبدا-بها-طالب-العالم-المبتدى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0349.mp3","categories":["العالم والمتعلم"]},{"id":314,"question":"هذا أحد الإخوة أتى بكتاب \"صفوة التفاسير\"، يقول: إنه وُزِّع في المسجد، فهل هناك يا فضيلة الشيخ ملاحظة على هذا الكتاب؟","title":"ما الرأي في كتاب صفوة التفاسير للصابوني؟","answer":"الجواب: \"صفوة التفاسير\" للشيخ محمد الصَّابوني فيه أغلاطٌ كثيرةٌ، فينبغي عدم توزيعه؛ لأنَّ أكثر العامَّة لا يفهمون الأغلاط، أما طالب العلم فقد يعرف الغلطَ وينتبه لذلك.\nوقد كتبنا لمؤلفه وبينا له بعض الأغلاط التي فيه، وقد كان وعدنا أنه إذا بلغ فسوف يقوم بالواجب من إعادة الطبع، ونرجو أن يُوفَّق لذلك، نرجو أن يُعينه الله حتى يُزيل الأخطاء التي بلغ إيَّاها.\nس: في أجزاء مُعينة أخطاء فيها؟\nالشيخ: لا، في كل جزءٍ بعض الشيء، وقد كتبنا هذا وأرسلتُ إليه.","link":"https://binbaz.org.sa/fatwas/4338/ما-الراي-في-كتاب-صفوة-التفاسير-للصابوني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0364.mp3","categories":["العالم والمتعلم"]},{"id":341,"question":"ما رأي فضيلتكم في بعض الصحف والمجلات الخاصَّة بالإسلام، والتي ترد من خارج المملكة؟ وكذلك ما رأي فضيلتكم في بعض الكتب الدينية مثل كتاب \"تنبيه الغافلين\"؟","title":"ما الرأي في كتاب \"تنبيه الغافلين\"؟","answer":"الجواب: ينبغي للمؤمن أن يحذر كل كتابٍ أو صحيفةٍ فيها ما يضرُّ بالدين أو الدعوة إلى الفساد، كل كتابٍ أو صحيفةٍ أو مجلةٍ تنشر الفساد أو الدعاية الباطلة أو الأفكار الهدَّامة يجب الحذر منها، أو الصور الخليعة يجب الحذر منها.\nأما \"تنبيه الغافلين\" فهما كتابان: أحدهما لابن النحاس، هو كتابٌ جيدٌ مفيدٌ، والثاني لأبي اللَّيث السَّمرقندي، وهذا كتابٌ فيه أحاديث موضوعة، وأحاديث ضعيفة، لا ينبغي التَّعويل عليه، وهو كتاب أبي الليث السمرقندي، أما ما يتعلق بكتاب النَّحاس فهو كتابٌ طيبٌ، فيه وصايا وتوجيه طيب.","link":"https://binbaz.org.sa/fatwas/4429/ما-الراي-في-كتاب-تنبيه-الغافلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0394.mp3","categories":["العالم والمتعلم"]},{"id":344,"question":"قد كانت محاضرتكم قيِّمةً -جزاكم الله خيرًا- ومفيدةً، ويحزّ في نفسي معرفة بعض الأمور التي تهمّ كل مسلم، فما الكتب التي تُوصون باقتنائها، خاصَّةً ما يتعلق بالعقيدة؟","title":"ما أهم الكتب التي ينصح بها في العقيدة؟","answer":"الجواب: أهم شيءٍ -أيها الأبناء- وأعظم شيءٍ في هذا الباب هو كتاب الله ، هذا أهم شيء وأعظم شيء: العناية بالقرآن، فعلم الصحابة كان من القرآن، وعلم التابعين كان من القرآن، ثم السنة بعد ذلك، فأهم شيء أوصينا به القرآن العظيم: حفظًا وتدبُّرًا وتعقُّلًا واستنباطًا، ومُراجعة التفاسير فيما أشكل، ولا سيَّما التفاسير المأمونة: كابن جرير، وابن كثير، والبغوي، ونحوهم من التفاسير المهمة، هذا أعظم شيءٍ وأكبره، وهو أصل العلم، وأصل الخير.\nفمَن رُزق القرآن وتدبَّر القرآن والعناية بالقرآن؛ فقد أفلح كثيرًا، لا سيَّما مع الإخلاص وطلب الهداية.\nثم السُّنة: حفظ ما تيسر من السنة: كـ\"بلوغ المرام\" و\"عمدة الحديث\" و\"المنتقى\"، هذه الكتب العظيمة إذا تيسر حفظها أو ما تيسر منها فهذا كنزٌ عظيمٌ مع كتاب الله ، ومع مُراجعة كتب أهل العلم في التفسير وشروح الأحاديث.\nوأما الكتب المؤلفة فهي كثيرة، لكن أحسنها فيما أعلم: كتب شيخ الإسلام ابن تيمية، وكتب العلامة ابن القيم رحمه الله، والحافظ ابن رجب، وأشباهها من كتب المحققين هؤلاء، ومثل: شرح \"الطحاوية\" لابن أبي العز، وأشباهها من كتب أهل السنة، هذه أكمل من غيرها، وأفضل من غيرها. والكتب كثيرة، ولكن قلَّ كتابٌ إلَّا ولا يخلو من شيءٍ، لكن طالب العلم يعرض ما أشكل عليه على الكتاب والسنة، ولا يأخذ كلَّ ما في الكتاب، ولو كان مؤلفه عظيمًا، ولو كان شيخ الإسلام ابن تيمية، ولو كان ابن القيم، ولو كان من التابعين، ولو كان من الكبار: كأحمد، وإسحاق، والشافعي، وغيرهم، كل هؤلاء علماء، وكل واحدٍ منهم قد يُخطئ في بعض المسائل، فإذا أشكل على طالب العلم شيءٌ عرضه على أهل العلم، وتذاكر فيه مع أهل العلم، وعرضه على الأدلة؛ حتى يستفيد الحقَّ على بصيرةٍ، وعلى هُدى.\nومن الكتب التي تُعنى بالعقيدة: \"التدمرية\" و\"الحموية\" و\"العقيدة الواسطية\" و\"شرح ابن أبي العز على عقيدة الطحاوي\"، هذه كتب لها أهميتها في هذا الباب.\nوكذلك أيضًا كتاب \"التوحيد\" للشيخ محمد، و\"فتح المجيد\" لحفيده الشيح عبدالرحمن بن الحسن، وحفيده الثاني سليمان له كتاب \"تيسير العزيز الحميد\"، هذه أيضًا كتب عظيمة، وهكذا \"الدرر السنية\"، لا سيَّما المجلد الأول في العقيدة، وفتاوى شيخ الإسلام في العقيدة، كلها من المهمّات.","link":"https://binbaz.org.sa/fatwas/4432/ما-اهم-الكتب-التي-ينصح-بها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0397.mp3","categories":["العالم والمتعلم"]},{"id":432,"question":"نرجو من فضيلتكم توجيه كلمة إلى طلاب العلم الشرعي الذين يقعون في أخطاء كبيرة، ومن هذه الأخطاء: التكلم على الأئمة الكبار، والتقليل من مكانتهم بدون سببٍ؟","title":"ما التوجيه لطالب العلم الذي يقع في العلماء؟","answer":"الجواب: هذا أيضًا مما ينفِّر، الكلام في العلماء مما يُنفِّر عن طلب العلم، ومما يُقلل قيمتهم في نفوس الناس، فالواجب احترام العلماء، والدعوة إلى سؤالهم، والاستفادة منهم، وتشجيعهم على أن يقولوا ويعملوا، وإذا علمت من عالم تقصيرًا أو خطأ ذهبت إليه أنت وإخوانك وبُحث معه، كالسائل والمسترشد، وشجعتموه على الدعوة إلى الله، والخطابة في المساجد، والتذكير بالله، وعدم الغفلة، ويُبين له أن المسلمين في حاجةٍ إلى أمثالك، وأن الدعوة من أهم المهمات، وأنك وأمثالك ممن يُرجى فيهم الخير، وممن يُؤمل فيهم الخير، فالتعاون مطلوبٌ.\nومهما بلغ العالم هو لا يستغني عن التذكير، ولا يستغني عن التشجيع مهما كان، فلا يحتقر طالب العلم نفسه أن ينصح، ولا يكون همه الجرح والثَّلب ونشر النقائص حتى ينفِّر الناسُ من العلماء، وحتى لا يستفيدوا من العلماء، وحتى تحل البغضاء محل المحبة، لا، هذا لا يجوز، بل يجب التعاون على إصلاح الأوضاع، وتنبيه العالم على خطئه، وتشجيعه على القيام بالمهمة، وتنبيهه على الغفلة، حتى تكون كلمة العلماء واحدة، ومتضافرة في الدعوة إلى الله، والتوجيه إلى الخير، والنصيحة للمسلمين، وبيان أحكام الله لعباده.\nويكون طلبة العلم مُشجعين ومُعينين ومُراقبين، وحملة للعلم ينقلونه من عالم إلى عالم، ومن جهةٍ إلى جهةٍ، ومن قريةٍ إلى قريةٍ، ومن حيٍّ إلى حيٍّ، هذا هو الطريق الذي يجب، وهذا هو الذي كان يعمله الصحابة، حضروا مجلس النبي صلى الله عليه وسلم، وحملوا العلم من مجلسه صلى الله عليه وسلم، ثم بلَّغوه الناس، هذا يذهب إلى قومه فيُبلغهم، وهذا يذهب إلى قومه فيُبلغهم، وهم متعاونون، وإذا دعت الحاجةُ تناوبوا؛ كل واحدٍ ينوب عنه أخوه في حضور المجلس، مثلما قال عمر، كان هو وأحد الأنصار يتناوبان: هذا ينزل يومًا، وهذا ينزل يومًا، حتى يحضروا حلقات العلم، فيرجع هذا وقد حمل ما سمع إلى أخيه عمر، وإلى مَن حوله، ثم يرجع عمر في اليوم الثاني قد حمل ما حمل، وهكذا، فإذا كانت هناك حاجةٌ تناوب الناسُ: إذا تباعدت المسافة هذا ينزل يومًا ويحضر مجالس العلم، ثم ينزل الآخر، أو يُسافر هذا إلى العالم الفلاني يسمع منه، ثم يأتي ويُسافر الآخر، وهكذا.\nوالعلماء اليوم قليلٌ، علماء السنة علماء الحقّ الذين يُرجى فيهم الخير ليسوا بالكثرة، أما كثرة اسم العلماء، ووجود العلماء والمدرسين فموجود، هم كثيرون، لكن يحتاجون إلى التَّشجيع، وقد يكون بعض العلماء غافلًا عمَّا يجب عليه في بعض الأمور، فإذا جاءه أبناؤه وإخوانه ونبَّهوه وشجَّعوه قالوا: الحي الفلاني محتاج، والمحل الفلاني محتاج، وأنت بحمد الله عندك من العلم ما عندك، فاتَّق الله وبلّغ الناس، وعلّم الناس، وأنت رأينا منك كذا وكذا، وأنت مثلك يُقتدى به، فلعلك تنتبه لهذا الأمر، رأينا منك أنك تتساهل في حضور صلاة الجماعة، أو أنك تُرخي ثيابك، أو أنك تأخذ من لحيتك، أو ما أشبه ذلك، فالتنبيه مطلوبٌ، لكن بالعبارة الحسنة، والأسلوب الحسن، ومراعاة ما قلتُ سابقًا: أن يكون المُنَبِّه ما هو بواحدٍ، يكونون جماعةً، التزاور يكون بالجماعة: اثنين، ثلاثة، أربعة؛ لأنَّ هذا أكثر في الاحترام، وأقرب إلى الانتفاع والاستفادة.","link":"https://binbaz.org.sa/fatwas/4856/ما-التوجيه-لطالب-العلم-الذي-يقع-في-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0490.mp3","categories":["العالم والمتعلم"]},{"id":437,"question":"يوجد في بعض المدن أناسٌ ممن درسوا على أيدي كثيرٍ من المشايخ المشهورين بالعلم والتقوى، وعندما يطلب منهم الشبابُ اليوم الجلوس للدراسة على أيديهم يرفضون ذلك، فهل هذا العمل يُعدُّ من كتمان العلم؟ وهل عليهم إثمٌ في عدم تبليغهم لما علموه؟ أرجو توضيح ذلك.","title":"هل رفضُ تعليم الناس يدخل في كتمان العلم؟","answer":"الجواب: الذي أعتقد أنه يلزمهم متى تيسر لهم مَن يقرأ عليهم، يلزمهم حسب الطاقة، في الأوقات المناسبة، يلزمهم أن يُعلِّموا الناس مما أعطاهم الله، وأن يُبلِّغوا الناس مما أعطاهم الله، ولا يكتموا، بل يلزمهم أن يُعلِّموا الناس، والناس في حاجةٍ، وتعليم العلم فرض كفايةٍ، والكفاية غير حاصلةٍ الآن -مَن يقوم بالكفاية- لا في الرياض، ولا في غيرها، فالحاجة ماسَّة إلى تعليم العلم.\nوالواجب على العلماء أينما كانوا أن يُعلِّموا، وأن يُرشدوا الناس إذا تيسر لهم مَن يتعلم، ولو من طريق الإذاعة، ولو من طريق الصَّحافة.","link":"https://binbaz.org.sa/fatwas/4861/هل-رفض-تعليم-الناس-يدخل-في-كتمان-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0495.mp3","categories":["العالم والمتعلم"]},{"id":691,"question":"السؤال الثاني: ما حكم تسمية طلاب العلم بـ \"المطاوعة\"؟","title":"ما حكم تسمية طلاب العلم بـ \"المطاوعة\"؟","answer":"الجواب: الناس طبقات: العالم، وطالب العالم، والعامي، طبقات ثلاث، كل طبقة أصناف وأنواع، ومن عادة أهل نجد هنا، من عادة بعضهم، يسمي من كان من الوسطى، أو طالب العلم الذي يصلي بالناس، أو يعلمهم القرآن، يسمونه: مُطَوَّعًا، أي: قد طوَّعه الله، جعله الله عابدًا له، مطيعًا له  برتبة زائدة على العامة، فوق العامة ودون العالم؛ لأن معنى مُطَوَّع أي: قد طوَّعه الله وجعله يعمل بطاعة الله، وينفع الناس، ويصلي بهم، ويعلم أولادهم، فيقال له: مطوع، عرفًا جاريًا في كثير من أنحاء نجد، وأظنه غير معروف في البلاد الأخرى، هذا معنى مطوِّع. وإذا لقب بهذا على حسب العرف فلا بأس بذلك، ولكن إذا ترك ذلك ولقَّبه باسمه كان أحب إليه، كأن يقول: يا أبا فلان، يناديه بكنيته، أو يا فلان، باسمه المعروف، أو يا أخي، إذا كان هذا أحب إليه، فلا بأس؛ لأن بعض الناس قد يكره أن يقال له يا مطوِّع، فإذا كان يكره ذلك، فإنه بإمكانه أن يكلمه ويخاطبه بما يحب، وأما إذا كان لا يكره ذلك أو يحب ذلك؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/17338/ما-حكم-تسمية-طلاب-العلم-بـ-المطاوعة","audio":"undefined","categories":["العالم والمتعلم"]},{"id":736,"question":"التقيتُ ببعض الشباب الصالح، وتناقشت معه حول التعليم، فوجدتُه يُنكر تعلم العلوم غير الشرعية، مثل: الفيزياء، والكيمياء، والأحياء، والحساب، والجبر، والجغرافيا، ونحو ذلك، ويزعم أن هذا هو منهج السلف، ولا يرى دخول أبناء المسلمين في المدارس والجامعات، فما رأي فضيلتكم في مثل هذه الآراء؟","title":"ما حكم من ينكر تعلم العلوم الدنيوية؟","answer":"الجواب: هذا رأيٌ خاطئٌ وغلطٌ، الله يقول: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا خُذُوا حِذْرَكُمْ [النساء:71]، فالمؤمن يتعلم ما ينفعه في دينه ودنياه.\nولكن علوم الشرع هي المُقَدَّمة، يتعلم ما لا يسعه جهله من دينه، ويتبصَّر، فالتَّفقه في الدين أمرٌ لازمٌ، وفرض كفايةٍ، ولكن كونه يتعلم ما لا يسعه جهله من الذكور والإناث فهذا أمرٌ لازمٌ لأمور دينه.\nولكن على الأمة أن تتعلم أيضًا ما ينفعها في دنياها: من الصناعات النافعة، ومن الاستعانة بها على قتال الأعداء وجهاد الأعداء، فيتعلم شؤون الزراعة، ويتعلم شؤون استخراج خزائن الأرض: من البترول والمعادن وغير ذلك؛ حتى تستغني عن أعداء الله، وتستخرج من بطون الأرض ومن خزائن الأرض ما ينفعها.\nوقد قال النبيُّ ﷺ: إنَّ الله أعطاني خزائن الأرض، وفي اللفظ الآخر: مفاتيح خزائن الأرض، قال أبو هريرة : لقد مضى رسولُ الله وأنتم تمتثلونها: أي: تستخرجونها؛ لما فتح الله عليهم بلاد الروم وبلاد فارس، وأخذوا أموالهم، وانتفعوا بما عندهم، واستفادوا من سلاحهم وعلومهم ما ينفعهم في دينهم، لكن يجب أن تكون خادمةً لشرع الله، وأن تكون مُعينةً على طاعة الله، وألا تصدّ عن سبيل الله.\nفالعلوم الشرعية هي الأساس، وهي الأصل، والعلوم الأخرى المباحة يُستعان بها على حفظ الدين، وعلى منفعة المسلمين، وعلى جهاد الكافرين.","link":"https://binbaz.org.sa/fatwas/20605/ما-حكم-من-ينكر-تعلم-العلوم-الدنيوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0543حكم تعلم العلوم الغير الشرعية فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["العالم والمتعلم"]},{"id":811,"question":"ما الكتب التي تنصحون بها المُبتدئين من طلبة العلم في هذه التَّخصصات: فنريد كتابًا واحدًا في العقيدة، وفي التفسير، وفي الحديث، وفي النحو، وفي الفقه، وفي الفرائض، وأصول الفقه، والبلاغة، والأدب؟","title":"ما الكتب التي يُنصح بها طالب العلم المُبتدئ؟","answer":"الجواب: أعظم كتابٍ، وأشرف كتابٍ، وأصدق كتابٍ أنصح به كلَّ طالب علمٍ: العناية بالقرآن، والإقبال عليه، وهو كتاب العقيدة، وكتاب الفقه، وكتاب الأحكام، وكتاب التاريخ الإسلامي، جامعٌ لكلِّ شيءٍ، فأنصح كل طالبٍ أن يُعنى بالقرآن، وأن يجتهد في حفظه والإكثار من تلاوته وتدبُّر معانيه، ولا سيما الذين جاوزوا المرحلة الثانوية، فهم أحقُّ الناس بأن يعتنوا به ويحفظوه؛ لأنهم الآن في مرحلةٍ جامعيةٍ، بعدها يتولون الأمور: من قضاء، ودعوة، وتعليم، وغير ذلك، فليكن عندهم حفظ كتاب الله أهم شيءٍ، حتى يستفيدوا من كلام الله، ثم سنة الرسول ﷺ: يحفظ فيها ما تيسر له من كتاب \"بلوغ المرام\"، أو \"عمدة الحديث\"، أو \"منتقى الأخبار\" حسب طاقتهم.\nوبعد هذا كله كتب العقيدة كثيرة، وكتب أخرى يختار منها ما يُناسبه، ومن أحسنها في العقيدة: كتاب \"التوحيد\" و\"العقيدة الواسطية\"، هذان كتابان مختصران في العقيدة، وإذا ضمَّ إلى ذلك \"كشف الشبهات\" و\"ثلاثة الأصول\"، فهذا أيضًا جيد.\nفالحاصل كتاب \"التوحيد\" و\"ثلاثة الأصول\" و\"كشف الشبهات\" و\"العقيدة الواسطية\" من أخصر الكتب وأحسنها في العقيدة.\nوفي الفقه: \"عمدة الفقه\" للموفق، جيدة، مختصرة.\nوفي المصطلح: \"نخبة الفكر\" كتابٌ جيدٌ نافعٌ، على اختصاره، في مصطلح الحديث.\nوفي الأصول: كتب كثيرة في الأصول الفقهية: كـ\"الورقات\" كتابٌ مختصرٌ، و\"روضة الناظر\" للموفق، كتاب أيضًا مختصر جيد ومفيد، وهناك كتبٌ أخرى موجودة معلومة، لكن \"روضة الناظر\" و\"الورقات\" للمُبتدئ كتابان، \"الورقات\" كتاب صغير، و\"الروضة\" كتاب جيدٌ.\nوفي التفسير: \"الجلالين\" كتاب جيد، عليه ملاحظات، وعليه أشياء، طالب العلم صاحب العقيدة الطيبة ينتبه لها، وفي إمكانه أن يعرفها، وعندي عزمٌ إن شاء الله في التَّعليق عليه، وقد شرعتُ في ذلك: في تتبع ما فيه من الأخطاء، لعله يُطبع معه إن شاء الله، المقصود أنه كتابٌ جيدٌ مفيدٌ على اختصاره.\nو\"مختصر تفسير ابن كثير\" للشيخ نسيب الرفاعي مختصرٌ جيدٌ مفيدٌ في تفسير ابن كثيرٍ رحمه الله.","link":"https://binbaz.org.sa/fatwas/20842/ما-الكتب-التي-ينصح-بها-طالب-العلم-المبتدى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0638ما هي الكتب التي تنصحون بها للمبتدئين في طلب العلم؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":816,"question":"سماحة الشيخ، السلام عليكم ورحمة الله وبركاته، وبعد: نسمع في هذه الأيام أن هناك شبابًا يفهم الإسلام من بعض جوانبه، وكل طائفةٍ تُسمِّي نفسها باسمٍ، أرجو كلمةً توجيهيةً لهؤلاء الشَّباب؟","title":"حكم من يأخذ بعض الإسلام ويترك بعضه","answer":"الجواب: الواجب على الشباب والشِّيب وعلى كل مؤمنٍ ومؤمنةٍ أن يأخذ الإسلام كله، وأن يطلبه كله، لا بعضه، يتفقَّه في الدين ويتبصَّر فيما قاله الله ورسوله، وبما شرعه الله ورسوله، ويستقيم على ذلك، ولا يتمسك ببعض دون بعض، بل يدرس الإسلام كله، ويعتني به كله؛ حتى يفهم ما أمر الله به، ويعمل به، وحتى يعرف ما نهى الله عنه ويجتنبه، وأن يكون الجميعُ متعاونين؛ جميع الجمعيات وجميع الشباب في كل مكانٍ يجب أن يكونوا مُتعاونين على البرِّ والتقوى، لا يؤذي بعضُهم بعضًا، ولا يذمُّ بعضُها بعضًا، ولا يحقر بعضُهم بعضًا، ولا يحسد بعضُهم بعضًا، فيتعاونون: ماذا قال الله؟ ماذا قال رسوله؟ ما معنى الآية؟ ما معنى الحديث؟ ماذا حكم الله في كذا وكذا؟ ما الدليل؟\nثم يأخذون كلام أهل العلم، يستعينون بكلام أهل العلم من الأئمة الكبار في كُتبهم، لا يدَّخرون وسعًا في ذلك، فإنَّ أهل العلم كتبوا وبيَّنوا رحمة الله عليهم، فيستعينون بكتبهم الكبيرة والصَّغيرة، مثل: كتب الموفق ابن قُدامة، والنووي، وشيخ الإسلام ابن تيمية، وابن القيم، وابن كثير، وغيرهم من أهل العلم، يُستعان بالكتب التي وجدت في المذاهب، ولا سيما الكتب التي تعتني بالأدلة: قال الله، وقال رسوله، فيستفيدون منها، وهكذا كتب الحديث وشروحها، هكذا طالب العلم. لكن الصغير يبدأ بالكتب المختصرة، ولا يُدخل نفسَه فيما لا يُحسنه، يبدأ بالكتب المختصرة، ويعتني بحفظ القرآن، ويحفظ كتاب \"التوحيد\"، \"العقيدة الواسطية\"، \"ثلاثة الأصول\"، \"كشف الشبهات\"، \"أصول الإيمان\"، \"فضل الإسلام\"، وأشباه ذلك من الكتب المختصرة؛ حتى يستفيد شيئًا بعد شيءٍ، ولا يدخل مع الناس فيما لا يعلم، وفيما يصعب عليه، بل يعرف قدر نفسه ويقف عند حدِّه.\nولكن يجب على الفاهمين أن يكونوا شيئًا واحدًا، وأن يتعاونوا على البر والتقوى، وألا يتفرَّقوا، وأن يُعين بعضُهم بعضًا على فهم النص، وعلى ما دلَّ عليه، وألا يأنف إذا أرشده أخوه، أو دلَّه أخوه على فائدةٍ، فليقل: جزاك الله خيرًا، فالعلماء الكبار تخفى عليهم المسائل الكثيرة، فإذا أرشدهم أخوهم فرحوا بذلك، كالصحابة، فهم أعلم الناس بعد الأنبياء، وكان بعضُهم يُرشِد بعضًا، ويدل بعضُهم على بعضٍ، والآخر يقول: سمعتُ رسول الله، ويقول: سمعتُ فلانًا عن رسول الله، فيفرحوا بذلك فرحًا عظيمًا، ثم التابعون بعدهم: كابن المسيب، وطاووس، وأبي سلمة ابن عبدالرحمن، والشعبي، وغيرهم، يتعاونون، وهكذا مَن بعدهم: كمالك، وأبي حنيفة، والشافعي، كلٌّ يحتاج إلى علم أخيه، والتعاون مع أخيه.\nفالذي يأنف أن يُرشَد أو ينتقد؛ قد خالف أهل السنة، كل واحدٍ منا له أغلاط، ويفهم أشياء، ويغلط في أشياء، فليفرح بمَن يُعينه ويدله على الخير ويُرشده إلى مسألةٍ خفيت عليه، أو دليلٍ خفي عليه.\nثم ليُجعل التعاون هو الميزان والدَّيدن بين الجميع، لا أن يذهب كل واحدٍ على حدةٍ ويُنافس الآخر ويُعاديه، لا، هذه طريقة أهل البدع من الجهمية والمعتزلة والرافضة وغيرهم، أما أهل السنة لا، أهل السنة يتعاونون فيما بينهم، ويُرشد بعضُهم بعضًا، ويُعين بعضُهم بعضًا، ويكونون جمعيةً واحدةً، ويكون هدفُهم واحدًا، وهو اتِّباع الحقِّ.","link":"https://binbaz.org.sa/fatwas/20854/حكم-من-ياخذ-بعض-الاسلام-ويترك-بعضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0650كلمة توجيهية لمن يأخذ بعض الإسلام ويترك بعضه؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":818,"question":"نسمع في هذه الأيام كلمات تدل على أنَّ مَن يبحث عن كل ما صحَّ عن رسول الله ﷺ يُوصَف بالتَّشدد بالدين، فما رأي سماحتكم في ذلك أثابكم الله؟","title":"حكم من يعيب الحريصين على السُّنة","answer":"الجواب: الشيخ: هؤلاء عجزوا فوصفوا مَن طلب العلم بهذا، لما عجزوا هم وتساهلوا ورضوا بالدنية والكسل عابوا من جدَّ في طلب العلم بهذا العيب، هذا عيبهم هم، أما مَن طلب العلم وحرص على الدليل من كتاب الله وسنة رسوله فهذا هو الذي يستحق المدح والثناء، وهذا هو طريق السلف، وهذا طريق أصحاب النبي ﷺ، ربما سافر بعضُهم المسافات الطويلة من مدينةٍ إلى مدينةٍ: إلى مصر أو إلى الشام لطلب حديثٍ واحدٍ، هكذا شأن أهل العلم: العناية بالقرآن، وحفظ ما تيسر منه، والعناية بالدليل، والعناية بالسنة، والحرص على معرفة الدليل فيما يقول الناس.\nكيف تعرف الحقَّ من الباطل إلا بهذا؟\nبماذا تعرف أنَّ ما قاله الشافعي هو الصواب أو أحمد أو مالك أو أبو حنيفة أو الأوزاعي أو المتأخِّرون أو ابن تيمية أو ابن القيم أو غيرهم؟\nبماذا تعرف الصَّواب؟ تعرف لأنَّك حنبلي؟ أو لأنك شافعي؟ لا، أو لأنَّك من أهل مكة؟ أو لأنك من أهل المدينة، أو من أهل الرياض، أو من الشام؟ لا، إنما تعرف الحقائق بالأدلة، هذا هو الطريق، يعرف أحكام الله، ويعرف الصواب من الخطأ، والحقّ من الباطل بالأدلة: قال الله، وقال رسوله، فمَن عاب هؤلاء فهو المعيب.\nولكن الوصية لهؤلاء أن يتَّقوا الله، وألا يتكبَّروا على الناس، وألا يُشددوا فيما لم يُشدد الله فيه، بل يلتزموا الحقَّ، فإن دين الله وسط، فالواجب عليهم أن يتحرّوا الوسط، وأن يتحرّوا التيسير والتَّسهيل، وألا يُشددوا بلا دليلٍ، قال الله جلَّ وعلا: وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ هُوَ اجْتَبَاكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]، وقال تعالى: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185]، وقال النبيُّ ﷺ: يَسِّروا ولا تُعسِّروا، وبشِّروا ولا تُنَفِّروا، وتطاوعوا ولا تختلفوا.\nفالواجب على دُعاة الحقِّ وعلى أهل السنة أن يكونوا مُتواضعين، لا مُشددين، ولا مُنَفِّرين، بل متواضعين، مُتبصِّرين، دعاةً للخير بأسلوبٍ حسنٍ، برفقٍ وحكمةٍ، لا بشدةٍ، ولا بعنفٍ، هكذا ينبغي، وهكذا يجب. أما الكسالى فيُتركون على كسلهم، يُنصحون ويُوجَّهون، لكن إذا كسلوا وضعفوا فعيبهم لهم وعليهم، لا لأهل السنة وطلبة الحديث.","link":"https://binbaz.org.sa/fatwas/20852/حكم-من-يعيب-الحريصين-على-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0648هل من يبحث عن ما صح عن النبي صلى الله عليه وسلم يعتبر متشدد في الدين؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":819,"question":"ما توجيهاتكم للقائمين على المركز الصيفي لهذا المعهد؟ وما نصائحكم للشباب المُشاركين فيه؟","title":"ما النصيحة للشباب والطلاب تجاه المجتمع؟","answer":"الجواب: توجيهاتي لإخواني وأبنائي ونصيحتي لهم هو أن يكونوا حريصين على فهم الحقِّ من غير رياء، ومن غير عدوانٍ على أحدٍ، ومن غير تكبُّرٍ، بل يكون كلُّ واحدٍ حريصًا على أن يفهم ما قاله الله ورسوله، وأن يعلم إخوانه ويُرشدهم، وأن ينصحهم، وأن يتعاون على البر والتقوى، وأن يكونوا مُتواضعين فيما بينهم، ليس بينهم تكبُّرٌ من بعضهم على بعضٍ، لا لأنه كبير السن، أو لأنه أفهم، أو لأنه في الكلية وذاك ليس بالكلية، أو لأنه في الثانوي وذاك ليس في الثانوي، بل في المتوسط، لا، يكون عندهم من التواضع والتعاون على الخير والمحبة لكل ما ينفع إخوانهم، عندهم من هذا ما يجعلهم شيئًا واحدًا، مُتحابين في الله، متعاونين على البر والتقوى، مُتناصحين: إذا رأى من زميله ما يُخالف الشرع نصحه بالأسلوب الحسن، والكلام الطيب، لعله يرجع إلى الصواب، من غير تعنيفٍ، ولا تشهيرٍ، ولا غيبةٍ له في المجالس، هكذا يكون الإخوان.\nفنصيحتي للجميع وتوجيهي للجميع أن يتَّقوا الله، وأن يتعاونوا على الخير بكل ما يستطيعون، وأن يكون هدفُهم إصلاح شؤنهم، وإصلاح أوضاعهم، وأن يتعلَّموا العلم، وأن يتفقَّهوا في الدين، وأن يتعاونوا على الخير، وأن يحذروا أن يكون من أهدافهم ثلبُ بعضهم بعضًا، وغيبةُ بعضهم لبعضٍ، وتشهيرُ بعضهم للآخرين بزلَّةٍ يزلها، وكذلك يجب الحذر مما تقدَّم: من التَّكبر، والتَّعاظم، واحتقار الغير.\nونصيحتي لهم أيضًا: أن يتواضعوا مع المدرسين، وأن يسألوهم ما أشكل عليهم بكل أدبٍ، هكذا ينبغي لطالب العلم، مع ما تقدَّم من المسارعة إلى ما أوجب الله: من الصلاة في الجماعة، وبرّ الوالدين، وصلة الرحم، والعطف على الفقير والمسكين والجار، وبذل السلام، وردّ السلام، وتشميت العاطس، وعيادة المريض، واتِّباع الجنائز، إلى غير هذا من الأخلاق الفاضلة، لا يملّون، ولا يضعفون، هكذا أهل العلم، وهكذا طلاب العلم.","link":"https://binbaz.org.sa/fatwas/20851/ما-النصيحة-للشباب-والطلاب-تجاه-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0647كلمة توجيهية للشباب ؟ ابن باز رحمه الله فتاوى المحاضرات.mp3","categories":["نصائح وتوجيهات","العالم والمتعلم"]},{"id":832,"question":"ما حكم قراءة بعض الكتب الممنوعة شرعًا، وذلك للردِّ عليها؟","title":"حكم قراءة الكتب المخالفة للشرع للردِّ عليها","answer":"الجواب: مَن عنده قدرة ورجا أن ينفع الله به فإنه يقرأ ويردّ إذا رأى المصلحةَ في ذلك. أما إذا كان علمه قليلًا ويخشى أن يفتتن بها فلا يقرأها. إذا كان عنده علمٌ وبصيرةٌ ويستطيع الردَّ عليها وكشف الشُّبهة؛ فهذا من الجهاد في سبيل الله.","link":"https://binbaz.org.sa/fatwas/20858/حكم-قراءة-الكتب-المخالفة-للشرع-للرد-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0653ما حكم قراءة الكتب الممنوعة شرعاً ولذلك للرد عليها؟ ابن باز رحمه الله.mp3","categories":["العالم والمتعلم"]},{"id":864,"question":"يقول هذا السائل: سماحة الوالد، ما دور المدرس؟ وما رسالته تجاه هذه الأعداد الكبيرة من الطلاب؟ وماذا يحصل بتقصيره؟ وهل يخصّ الواجب الأستاذ أم المسؤولية على الجميع؟","title":"ما دور المدرس ورسالته وحكم تقصيره؟","answer":"الجواب: لا شكَّ أن دور المدرس نحو الطلبة ونحو المسلمين دورٌ عظيمٌ، وواجبه كبير؛ لأنه إنما طُلب وعُيِّن وكُلِّف ليُوجه الطلبة إلى الخير، وليُوجههم إلى العلم النافع، والعمل الصالح، ويُبصرهم بما ينبغي الأخذ به، ويدلهم على الطريق في طلب العلم، والاكتفاء بكتاب الله وسنة رسوله عليه الصلاة والسلام، وليحثّهم على التعاون فيما بينهم، والاستفادة من بعضهم البعض، فواجبه عظيم، وأن ينصح لهم، ويُبلغهم المعلومات على الوجه الذي يراه مناسبًا لهم، حتى يفقهوها ويفهموها.\nفعليه أن يجتهد في إيصال المعلومات إلى قلوبهم بالطرق التي يراها مناسبةً: من كمال الإيضاح، وكمال النَّصيحة، والتَّنبيه على ما قد يغفلون عنه، ووصيتهم بالتعاون والمذاكرة فيما بينهم، والعناية بالدروس، وحفظ الوقت، إلى غير ذلك مما يراه مناسبًا؛ ليزدادوا علمًا، وليتبصَّروا، ولتكون معلوماتهم أكمل بسبب ما وجَّههم إليه، وأرشدهم إليه في أخذهم، وفي فهمهم، وفي حفظ أوقاتهم، وفي عملهم بمقتضى ما يُوجَّهون إليه، والله سائله عن ذلك.\nوهو يتحرى أداء الأمانة على الوجه الذي يراه أنسب لهم، وأصلح لهم، وأنفع لهم..... وهو مشكورٌ على صبره واجتهاده، وله أجران إن أصاب، وأجر واحد إن أخطأ، إذا بذل وسعه، واجتهد في إيصال العلوم إليهم، وتبصيرهم، وإعداد الدرس، والانتباه لما قد يخفى عليهم حتى يُوجَّهوا إليه، وحتى يُرشدوا إليه، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/20907/ما-دور-المدرس-ورسالته-وحكم-تقصيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0702ما هو دور المدرس وماهي رسالته تجاه طلابه وماذا يحصل بتقصيره؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":883,"question":"نرجو من سماحتكم توجيه كلمة للشباب الذين يجلسون يتحدثون عن بعض المشايخ، ويقولون: هذا أشعري، وهذا إخواني، وغير ذلك من غير علمٍ، وهل يجوز من هؤلاء الشباب الخوض في اتِّهام العلماء بهذه الاتهامات بعلمٍ أو بغير علمٍ؟","title":"ما النصيحة لمن يخوض في المشايخ والدعاة؟","answer":"الجواب: الواجب على الشباب وغير الشباب التَّثبت في الأمور، وألا يرموا أحدًا بشيءٍ إلا عن بصيرةٍ وعن علمٍ، حتى لا يقولوا على الله بغير حقٍّ، وحتى لا يكذبوا على الناس، وحتى لا يُسببوا مشاكل بين الناس.\nفإذا كان المقصودُ الدَّعوة إلى الله فليُبيّن الخطأ، يُقال: هذا خطأ، وإذا قاله فلانٌ فهو خطأ: كمدرسٍ سمعه، أو واعظٍ سمعه، يقول: هذا خطأ، إذا عرف أنه خطأ بالدليل، سواء كان من فلانٍ، أو من فلان، أو من فلان.\nأما أن يكون همُّه التَّجريح والغيبة فلا ينبغي هذا، ولا تجوز غيبة الناس، لا تجوز غيبة المسلم، الله يقول: وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12].\nأما إذا كان المقصود التَّنبيه على الحقِّ، والتَّنبيه على الباطل، وبيان أنَّ ما قاله فلانٌ حقٌّ، وما قاله فلانٌ باطلٌ من تأويل الصِّفات، أو تأييد ما عليه الخوارج أو المعتزلة، حتى يُبين للناس الخطأ في ذلك؛ فهذا مأجورٌ، وواجب، هذا من إنكار المنكر.\nأما أن يتكلم في أحوالهم الداخلية المستورة فهذا من الغيبة، وإنما يجوز الكلام فيما ظهر من الباطل للتَّحذير منه، ومن الحقِّ للدعوة إليه، والتَّشجيع على الأخذ به، أما الأمور الداخلية التي لا يعلمها إلا الله، وهي مستورة، فلا يجوز التَّعرض لها، بل ذلك من الغيبة.\nوأما ما يتعلق بالجماعات: الإخوان المسلمين، وأنصار السنة، وجماعة التبليغ، وغير ذلك، فالواجب على مَن يتكلم في ذلك أن يتكلم بعلمٍ، وأن يكون على بصيرةٍ، وإلا فليُمْسِك، فإذا كان عنده علمٌ فليقل للإخوان المسلمين: إنَّكم فعلتُم كذا وكذا، والواجب كذا وكذا، وليقل لأنصار السنة: كذا، وليقل للجماعة الفلانية يعني: يُبين لهم بينه وبينهم، أو بين مَن يراه منهم من أفرادٍ، من باب النَّصيحة له، إذا كان عنده علمٌ، كما ينصح إخوانه الآخرين الذين يقترفون بعض المعاصي، أو بعض الفتاوى الباطلة، وإن كانوا مُنتسبين إلى غير هؤلاء، فيقول: يا أخي، قلتَ كذا، وهذا خطأ، قلتَ كذا، وهذا خطأ، والدليل كذا، لكن بالحكمة والكلام الطيب والأسلوب الحسن، لا بالعنف والشّدة.","link":"https://binbaz.org.sa/fatwas/20917/ما-النصيحة-لمن-يخوض-في-المشايخ-والدعاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0712توجيه كلمة للشباب الذين يتكلمون على بعض المشائخ والعلماء ؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":887,"question":"نحن في مؤسسة تعليمية تحرص على كتاب الله، فما دور حافظ القرآن الكريم في صدره؟ وماذا عليه لو قصَّر في العمل بالقرآن، خاصَّةً إذا كان الإنسانُ من هذا البلد الحرام؟ وهل لحامل القرآن من آدابٍ يجب أن يتخلَّق بها؟","title":"ما الآداب التي تنبغي لحامل القرآن الكريم؟","answer":"الجواب: نعم، نعم، حامل القرآن عليه أن يتأدَّب بآداب القرآن؛ بامتثال الأوامر، وترك النَّواهي، ويحزّبه حسبما يسَّره الله له، وأن يُكثر من تلاوته، مع تدبُّر معانيه، وألا يكون كالغافلين المعرضين، بل يُحقق ما حمله من كتاب الله بالعمل، بالتَّخلق بأخلاق القرآن التي مدحها الله ودعا إليها، والحذر من الأخلاق التي ذمَّها الله وعابها وذمَّ أهلها، والاستقامة على طاعة الله ورسوله، والنشاط في ذلك ليلًا ونهارًا، وحفظ الوقت؛ حتى يكون أسوةً صالحةً، وقدوةً صالحةً لغيره من زملائه وغيرهم.\nوأن تظهر عليه آثار كتاب الله في قوله وعمله وسلوكه، مع أهله وجيرانه وزملائه وغيرهم، هكذا يكون المؤمن، قال تعالى في وصف النبي ﷺ: وَإِنَّكَ لَعَلَى خُلُقٍ عَظِيمٍ [القلم:4]، قالت عائشة رضي الله عنها: \"كان خلقُه القرآن عليه الصلاة والسلام\" يعني: يمتثل أوامر القرآن، وينتهي عن نواهيه، ويتأدَّب بالآداب التي مدحها الله في كتابه، وأثنى على أهلها، ويحذر الأخلاق والأعمال التي ذمَّها الله، أو ذمَّ أهلها.","link":"https://binbaz.org.sa/fatwas/20912/ما-الاداب-التي-تنبغي-لحامل-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0707ما هي آداب حامل القرآن الكريم التي يجب أن يتخلق بها؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":889,"question":"هل كل ما ورد في \"مجموع الفتاوى\" لابن تيمية صحيح النسبة إليه أم أنَّ هناك فتاوى نُسبت إليه؟","title":"ما صحة نسبة مجموع الفتاوى لابن تيمية؟","answer":"الجواب: المعروف أنَّ جامعها الشيخ العلامة عبدالرحمن بن قاسم رحمه الله قد اجتهد وحرص على جمعها من مظانِّها، وسافر في ذلك الأسفار الكبيرة، ونقَّب عنها، ومعه ابنه محمد، واجتهدا في ذلك.\nوالذي نعلم مما اطّلعنا عليه منها أنها صواب، وأنها صحيح نسبتها إليه، ولا يلزم من ذلك أن يكون كل حرفٍ وكل كلمةٍ، ما وقع فيها خطأ من بعض النُّساخ، أو بعض الطُّبَّاع، قد تقع بعضُ الكلمات الخطأ من بعض النُّساخ وبعض الطُّبّاع، ولكن تُراجع الأصول، ويتبين الخطأ، ويظهر الخطأ، فإذا وجدت كلمةً أو عبارةً لا تُناسب ما هو عليه من العقيدة، وما هو معروفٌ في كلامه؛ تُردّ إلى الأصول، ويُعلم أنها خطأ: إما ممن نسخها، أو ممن جرى على يديه الطبع.\nفعقيدة الشيخ معروفةٌ، وكلامه معروفٌ في الكتب رحمه الله، وإذا وجد إنسانٌ في الفتاوى كلمةً أشكلت عليه، أو عبارةً أشكلت عليه؛ فالواجب أن يردَّها إلى النصوص المعروفة من كلامه في كتبه العظيمة، هذا هو الواجب على أهل الحقِّ: أن يردّ المشتبه إلى المحكم، كما هو الواجب في كتاب الله، وفي سنة رسوله عليه الصلاة والسلام، وفي كلام أهل العلم جميعًا.","link":"https://binbaz.org.sa/fatwas/20915/ما-صحة-نسبة-مجموع-الفتاوى-لابن-تيمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0710هل كل ما ورد في مجموع الفتاوى لأبن تيمية صحيح النسبة إليه؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":916,"question":"إذا قال قائلٌ بأن الكتب الموجودة بين أيدينا الآن من كتب الأئمَّة مثل: كتب الإمام أحمد بن حنبل، وشيخ الإسلام ابن تيمية، لو قال بأنَّها مُحرَّفة، ويقول بأنه كيف يمكن أن تأتينا هذه الكتب عبر هذه القرون الطويلة سالمةً من التحريف، وهو يُنكر وجود الأئمة أصلًا ويقول: كيف ثبت بأنه كان هناك رجلٌ اسمه أحمد بن حنبل مثلًا، فبماذا يردّ على هذا؟ وبماذا يُنصح؟","title":"ما الرد على زعم تحريف كتب أئمة السلف؟","answer":"الجواب: يُردّ عليه بأنَّ هذه الأمور قد تواترت وعلمها العلماء، وعرفوا مَن كتبها، وعرفوا مَن قالها بنقل الكاتب عن الكاتب، أو العلماء عن العلماء، المخطوطات المضبوطة المعلومة، التواقيع المضبوطة، فمَن أنكر ذلك كفر، هذا إنكارٌ للواقع، إنكار لواقع معلوم، مكذب، معناه: التكذيب للأئمة والعلماء، وإنكار شيء قد أجمع عليه الناسُ، وعلمه الناسُ، فبعد هذا يقول: ما هناك محمد ولا صحابة! انتهى، فالذي نقل لنا هذه الكتب هم الذين نقلوا أخبار الصحابة وأخبار النبي ﷺ، فمَن أنكر وجود النبي ووجود الصحابة، وأنكر وجود العلماء؛ فعلى عقله وعلى دينه الفناء والذهاب، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/20968/ما-الرد-على-زعم-تحريف-كتب-اىمة-السلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0764إذا قال القائل بأن كتب الأئمة الموجودة مثل ابن تيمية وأحمد بن حنبل محرفة,فكيف يرد عليه؟ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":965,"question":"بعضُ الشباب يرى أنَّ طلب العلم الشرعي لا يوجد إلا عند العلماء في الحلقات فحسب، ويترك بذلك الدراسة النِّظامية في المدارس، فما نصيحتكم والله يحفظكم؟","title":"ما الرأي في أن طلب العلم بالمساجد فقط؟","answer":"الجواب: هذا غلطٌ، وليس بصحيحٍ، بل توجد في المعاهد والكليات علوم عديدة: من جهة الشرعية، من جهة أصول الدين، من جهة الحديث، من جهة القرآن، فيها علمٌ عظيمٌ، المهم النُّصح والجد والنشاط في ذلك، ولا مانع أن يجمع بين الأمرين، لا مانع أن تكون له دراسة نظامية، ودراسة مع المشايخ في الليل، أو في الخميس وفي العُطل التي يستطيع الدراسة فيها، لا مانع أن يجمع بين المصلحتين والاتجاهين. لكن مَن زعم أنَّ الدراسة النِّظامية ليس فيها علمٌ فهو غالطٌ، لكن أراد أن يُسلِّي نفسه لما لم ينتظم، أراد أن يُسلِّي نفسه حتى يعذرها بهذا التأخر، وإلا فالدراسة النِّظامية فيها مصالح دينية ودنيوية وتشجيعية، فإن المنتظم يتشجع مع إخوانه ويستفيد وينفع الله به الأمة إذا كانت معه الشَّهادة، ينفع به الأمة، ويحصل له بها أيضًا المساعدة في دنياه، فلا ينبغي التَّعلق بهذا الكلام، ولا التأثر بهذا الكلام. وفَّق الله الجميع.","link":"https://binbaz.org.sa/fatwas/21006/ما-الراي-في-ان-طلب-العلم-بالمساجد-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0803ما رأيكم فمن يرى أن طلب العلم فقط في المساجد وحلقات العلم؟ ابن باز فتاوى المحاضرات.mp3","categories":["المساجد ومواضع السجود","العالم والمتعلم"]},{"id":967,"question":"أنا شابٌّ سلكت طريق الهداية ولله الحمد، ولكني اتَّجهتُ إلى طلب العلم الشرعي، وفجأة تركتُ العلم الشرعي واتَّجهتُ إلى الدعوة، ثم تركتُ الدعوة وجاءتني رغبةٌ بالذهاب إلى الجهاد، وأريد منكم أن تُوضِّحوا لي الطريقة المُثلى لكي أكون شابًّا مُتوازنًا بغير إفراطٍ ولا تفريطٍ، وجزاكم الله خيرًا.","title":"ما النصيحة للشباب لتجنب الإفراط والتفريط؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلَّى الله وسلَّم على رسول الله، وعلى آله وأصحابه ومَن اهتدى بهُداه.\nأما بعد: فإنَّ طلب العلم فرضٌ على جميع المسلمين والمسلمات؛ لأنه لا سبيلَ إلى معرفة العبادة التي خُلق لها الجميع إلا بالعلم، وقد سمعتُم قبل قليلٍ أننا خُلقنا لنعبد الله، كما قال سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، وهذه العبادة لا نعرفها إلا بالعلم بما قاله الله ورسوله، فطلب العلم مُتعين على الذكور والإناث، على الإنسان أن يتعلم من العلم ما لا يسعه جهله: كيف يعبد ربَّه؟ كيف يُصلي؟ كيف يصوم؟ كيف يُزَكِّي؟ كيف يحج؟ يتعلم ما لا يسعه جهله.\nفإذا مَنَّ الله عليه بالعلم الذي يجب عليه، وصار على بصيرةٍ في دينه، وأحبَّ أن يتفرغ لطلب الدنيا: للتجارة، للصناعة، للزراعة، لا بأس، مع عدم إعراضه عن العلم، بل يتذكر العلم، ويحضر حلقات العلم، ويُشارك مع أهل العلم؛ حتى لا ينسى العلم، وإذا أحبَّ أن يتفرغ للجهاد كذلك، فالجهاد أمره عظيم، وفائدته كبيرة، ومن أفضل الأعمال، بل هو أفضل الأعمال التي يتطوع بها الإنسان. وأما الدَّعوة فلا بد فيها من شرطها: أن يكون على علمٍ، فلا يشتغل بالدعوة إلا إذا كان على علمٍ، على بصيرةٍ بما يدعو إليه، وبما ينهى عنه، على علمٍ بالأدلة الشرعية، قد تفقَّه في ذلك، فحينئذٍ يعمل ما علم، ويدعو إلى الله جلَّ وعلا، كما قال : وَالْعَصْرِ  ۝  إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر]، فرتَّب الأمور أربع مراتب: الأول: العلم الذي ينتج عنه الإيمان، فإذا تعلَّم ما يجب عليه وما يلزمه الإيمانُ به: من الإيمان بالله، ورسوله، والفقه في دينه، وعمل، يدعو بعد هذا، قال: وَتَوَاصَوْا بِالْحَقِّ، أولًا: يتعلم ويُؤمن بما أوجب الله عليه، ويتبصَّر في ذلك، ويعمل بما أوجب الله عليه، ثم يشتغل بالدعوة إلى ما علم من دين الله، ويتواصى مع إخوانه بالحقِّ والصبر عليه.","link":"https://binbaz.org.sa/fatwas/21015/ما-النصيحة-للشباب-لتجنب-الافراط-والتفريط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0812اريد منكم أن توضحوا لي الطريقة المثلى لكي أكون شاباً متوازناً بغير أفراط ولا تفريط؟ ابن باز.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":1043,"question":"أرجو أن تُرشدنا إلى كتب مُختصرة ومُبسطة في علم الحديث والفقه والعقيدة، جزاكم الله خيرًا.","title":"ما الكتب التي يُوصى بها في الحديث والعقيدة؟","answer":"الجواب: من الكتب المختصرة في العقيدة: كتاب \"التوحيد\" لشيخ الإسلام محمد بن عبدالوهاب رحمه الله، و\"ثلاثة الأصول\"، و\"كشف الشبهات\"، فهي كتب مختصرة عظيمة الفائدة، ومنها \"العقيدة الواسطية\" لشيخ الإسلام ابن تيمية، و\"التدمرية\" له أيضًا، و\"الحموية\" له أيضًا، كلها كتب عظيمة ومفيدة، ومنها \"لمعة الاعتقاد\" للموفق ابن قدامة، و\"الطحاوية\" للطحاوي، وعليها شرحٌ عظيمٌ مفيدٌ لابن أبي العز، نبَّه على بعض الأخطاء، وأوضح كلام أهل السنة والجماعة.\nهذه كتب عظيمة في العقيدة، ومنها كتاب \"التوحيد\" لابن خزيمة، كتابٌ عظيمٌ مفيدٌ أيضًا، وكتاب \"السنة\" لعبدالله بن أحمد بن حنبل كتابٌ عظيمٌ، وكتاب \"الرد على بشر المريسي\" لعثمان بن سعيد الدارمي، هذه كتب أيضًا مفيدة وعظيمة في العقيدة.\nوفي الحديث: \"بلوغ المرام\" كتابٌ جيدٌ ومختصرٌ، و\"عمدة الحديث\" للشيخ عبدالغني المقدسي، مختصرة أيضًا جيدة، فينبغي حفظ هذين الكتابين مع \"الأربعين النووية\"، وتتمَّتها لابن رجب، قد جمع خمسين حديثًا من جوامع الكلم، مهمة، حفظها مهمٌّ أيضًا ومفيد.\nوإذا كانت عند الرجل همَّة عالية ورفيعة فـ\"المنتقى\" كتابٌ عظيمٌ، إذا تيسر حفظه، فهو كتابٌ عظيمٌ ومفيدٌ.","link":"https://binbaz.org.sa/fatwas/21082/ما-الكتب-التي-يوصى-بها-في-الحديث-والعقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0878ارجو أن ترشدنا إلى كتب مختصرة في علم الحديث والفقه والعقيدة؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":1056,"question":"ما الكتب التي يُوصي الشيخُ بها طلبة العلم في العقيدة؟","title":"ما كتب العقيدة التي يُوصى بها طلبة العلم؟","answer":"الجواب:\nالوصية أولًا بكتاب الله: القرآن، هو أفضل الكتب وأعظمها، وهو كتاب العقيدة، وكتاب الأحكام، وكتاب الآداب، وكتاب الأخلاق، قد جمع كلَّ خيرٍ: فيه العقيدة، وفيه الأحكام، وفيه الدعوة إلى الأخلاق الكريمة، والصفات الحميدة، والنهي عن ضدِّها.\nووصيتي لكل مؤمنٍ ولكل مؤمنةٍ: العناية بالقرآن، والإقبال عليه، والإكثار من تلاوته وتدبُّر معانيه، والمذاكرة في ذلك، والمدارسة بينه وبين زملائه، كما قال جلَّ وعلا: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ [النحل:89] كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ [ص:29].\nفالوصية العناية بالقرآن، والإكثار من تلاوته وحفظه، أو ما تيسر منه، والمذاكرة فيه، ومطالعة كتب التفسير؛ حتى تستفيد الفائدة العظيمة. ثم السُّنة -سُنة النبي ﷺ- والكتب التي حفظت السنة من أهم الأشياء العناية بها: كالصَّحيحين، والسنن الأربع، هذه كتب عظيمة، ينبغي لأهل العلم العناية بها، وتدبُّرها، والإكثار من مُراجعتها، وسؤال أهل العلم عمَّا يُشكل من بعض الأحاديث التي فيها، حتى يكون المؤمنُ على بصيرةٍ من كتاب الله وسنة رسوله محمدٍ ﷺ.\nوهكذا بقية الكتب: كتب الحديث كـ\"موطأ مالك\"، و\"مسند أحمد\"، و\"مسند أبي داود الطيالسي\"، و\"صحيح الحاكم\"، و\"صحيح ابن حبان\"، وغيرها من كتب أهل الحديث، هذه كلها مفيدة لأهل العلم.","link":"https://binbaz.org.sa/fatwas/21080/ما-كتب-العقيدة-التي-يوصى-بها-طلبة-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0876ما هي الكتب التي توصي بها لطلبة العلم في العقيدة؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":1057,"question":"المعروف في كتب الحديث أنَّ الطبراني في \"الكبير\" قد جمع أكثر مما حرص عليه أهلُ الصحاح الستة، فهل يرقى ما أورده الطبراني في \"الأوسط\" و\"الكبير\" إلى مكانة كتب الأئمة الستة، أم أن طالب العلم يحتاج إلى تثبتٍ وبحثٍ في هذا؟ وبماذا تنصحون طالب العلم، جزاكم الله خيرًا؟","title":"ما درجة أحاديث \"الجامع الكبير\" للطبراني؟","answer":"الجواب:\nنعم يحتاج إلى تثبتٍ؛ لأن الطبراني في معاجمه الثلاثة يجمع الضعيفَ والصحيحَ والموضوعَ، فلا بدّ من عنايةٍ بالأسانيد، وهكذا ما عدا \"الصحيحين\"، لابدّ من العناية بالأسانيد: كالسنن الأربع، والبيهقي، والدارمي، والحاكم، وابن حبان، وغيرهم، لا بد من العناية بالأسانيد، وهكذا الدارقطني وغيره، كل هذه الكتب تحتاج إلى عنايةٍ من أهل العلم، فما صحَّ وجب الأخذ به، وما ضَعُف إن كانت له شواهد تُسْنِده وتُحَسِّنه أخذ بها، وإلا تُرك، ولا تُؤخذ هذه الكتب على علَّاتها من دون نظرٍ، ولا تمييزٍ، لا، لا بد من تمييزٍ.\nوالطبراني ممن جمع وأكثر رحمه الله، لكنه يجمع الغثَّ والسَّمينَ، والضعيفَ والصحيح، فلا بد من عنايةٍ وتمييزٍ بين الصالح والطالح من جهة الأسانيد، وثقة الرجال، واتصال الأسانيد وعدم انقطاعها، إلى غير هذا من العلل المعروفة عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/21081/ما-درجة-احاديث-الجامع-الكبير-للطبراني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0877ما رأيكم في كتاب الجامع الكبير للطبراني؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":1059,"question":"ما مدى صحَّة قول القائل: إنني أطلب العلمَ للعلم، أو لذات العلم؟ وهل يتعارض هذا القول مع طلب العلم في سبيل الله؟","title":"ما حكم قول: \"إني أطلب العلم لذات العلم\"؟","answer":"الجواب:\nهذا يُراد به في الغالب: أني لا أطلبه للدنيا، ولا أطلبه للرياء والسمعة، وإنما أطلبه لفضله وما يترتب عليه من الخير، هذا هو الغالب على مَن يقول هذا الكلام، يعني: يطلبه لله؛ ليستفيد ويعلم حكم الله، وما شرع الله، وما حرَّم الله، وليس يطلبه للدنيا أو للرياء، هذا هو الغالب على مَن يقول هذا الكلام.\nأما إذا كان يُريد أن يطلبه للعلم؛ أن يُقال له: عالم، وليعلم ما ورد في الكتاب والسنة، لكن لا للعمل، ولا لطاعة الله ورسوله؛ هذا خاسرٌ، لكن ما أظنّ مسلمًا يريد هذا ويقصد هذا، وإنما الغالب على مَن يقول هذا -أو هو المقصود على كل حالٍ- أنه يطلبه لفضله وما يترتب عليه من المصالح التي منها: معرفة ما أوجب الله، وما حرَّم الله، ومعرفة العبادة التي خُلقنا لها، ليس يطلبه للرياء والسُّمعة، أو لطلب الوظائف، ليس لهذا، أما إن كان مقصوده أنه يتعلم لمجرد العلم، ليُقال: إنه يعلم، ليُقال: إنه عالم، فهذا من جنس تعلُّمه للرياء والسُّمعة، هذا خاسرٌ، نسأل الله السَّلامة.","link":"https://binbaz.org.sa/fatwas/21124/ما-حكم-قول-اني-اطلب-العلم-لذات-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0920ما مدى صحة قول القائل أني أطلب العلم للعلم أو لذات العلم؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":1060,"question":"قد زاحم طلبُ العلم المعيشي طلبَ العلم الشرعي، فما أمسى الرجلُ والمرأةُ يجهلان الكثير من أمور العبادات والمُعاملات، فلم يَعُد للتَّفقه في الدِّين حيزٌ في وقت المسلم، فما الحدُّ الواجب تعلمه من الدين؟ وهل يأثم مَن ترك التَّفقه في الدين؟","title":"هل يأثم من ترك التفقه في الدين؟","answer":"الجواب:\nيقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، والواجب من العلم هو تحصيل ما يُعينك على فهم ما أوجب الله، ومعرفة ما فرض الله عليك، وما حرَّم عليك، هذا هو العلم الواجب، هو أن تتعلم من دينك ما لا يسعك جهله. وهكذا المرأة، عليها أن تتعلم من دينها ما لا يسعها جهله، هذا الواجب؛ وذلك بمعرفة التوحيد وضدِّه، ومعرفة أسماء الله وصفاته، وما يليق به سبحانه، ومعرفة حقّه على عباده من الطَّاعات، وما حرَّم عليهم من المعاصي؛ حتى يسير إلى الله على بصيرةٍ، حتى يعبد ربَّه على علمٍ، وعلى هدًى.\nأما التَّوسع في ذلك بحيث يعرف أنواعَ العلوم النَّافعة، ويتبصَّر في ذلك، ويعرف المستحبَّات والمكروهات، فهذا فضلٌ، وليس بواجبٍ، ولكنه فضلٌ، ويُطلق عليه بعضُ العلماء أنه فرض كفايةٍ، حتى لا يخلو المجتمع من عالم بما شرعه الله، وعالم بما نهى الله عنه أو كرهه. لكن الفرض أنه يلزمه ما لا يسعه جهله، يعني: يلزمه أن يعلم ما خُلِقَ له، وما أوجب الله عليه من طاعته وطاعة رسوله ﷺ، وأن يعلم ما حرَّم الله عليه حتى يجتنبه، فإذا عرف هذا كله فقد أدَّى الواجبَ، وصار تعلمه بعد ذلك من المستحبَّات، ومن مزيد العلم في المستحبَّات، والتوسع في العلم، يكون ذلك من باب خيرٍ إلى خيرٍ، وفضلٍ إلى فضلٍ، ومَن رزقه الله السّعة في الوقت والقُدرة على تكميل العلم فذلك أفضل وأوْلى؛ حتى ينفع الناسَ، وينفع نفسه.","link":"https://binbaz.org.sa/fatwas/21123/هل-ياثم-من-ترك-التفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0919ماهو الحد الواجب تعلمه من الدين وهل يأثم من ترك التفقه في الدين؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":1073,"question":"أنا إمام مسجدٍ تابع للأوقاف في الحوية، وهي تبعد عن الطائف عشرين كيلو، وسؤالي: هل عليَّ إثمٌ في ترك إمامة المسجد لكلٍّ من صلاة المغرب والعشاء، ليس هروبًا من الإمامة، وإنما رغبة في الحضور إلى الطائف من أجل العلم؟","title":"حكم تغيُّب الإمام بعض الصلوات لطلب العلم","answer":"الجواب:\nلا حرج في ذلك، الحمد لله، إذا تيسر لك مَن يقوم مقامك ويُؤدي الأمانة مثلك وأحسن منك، يُصلي بهم، فلا بأس بذلك، هذا من باب التَّعاون على البر والتقوى، إذا وجدتَ إنسانًا يُعينك ويُصلي بهم مكانك المغرب والعشاء، وهو أهلٌ لذلك، وأنت تحضر في المسجد الآخر لطلب العلم؛ فلا حرج في ذلك؛ لأنك لم تُخلّ بأمرٍ يضرُّ الجماعة.","link":"https://binbaz.org.sa/fatwas/21144/حكم-تغيب-الامام-بعض-الصلوات-لطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0940يقول السائل أنا إمام مسجد وأذهب إلى مسجد آخر صلاة المغرب والعشاء لطلب العلم فما حكم ذلك؟.mp3","categories":["العالم والمتعلم"]},{"id":1081,"question":"أيّهما نُقدّم: الدَّعوة أم طلب العلم؟","title":"أيهما يُقدَّم: طلبُ العلم أم الدعوة؟","answer":"الجواب:\nقَدِّم طلب العلم والدَّعوة معه، الدعوة ما يمكن أن تُقدّم، الذي ما عنده علمٌ كيف يدعو؟! الذي ما عنده علمٌ جاهل. يُقدّم طلب العلم، والدَّعوة تكون مع ذلك، كلما حصّلتَ علمًا تدعو، إذا عرفت الصلاةَ وأحكامها تدعو إليها على علمٍ، عرفت الزكاة وأحكامها تدعو إليها على علمٍ، عرفت التوحيد وحقيقته والشِّرك وحقيقته تدعو إلى ذلك على علمٍ، وهكذا كلما عرفتَ شيئًا وتبصّرتَ فيه وكنتَ على بينةٍ؛ تدعو إليه على بصيرةٍ. ولا دعوة إلا بعلمٍ، فالعلم هو السابق، والدَّعوة هي التَّابعة.","link":"https://binbaz.org.sa/fatwas/21135/ايهما-يقدم-طلب-العلم-ام-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0931أيهما تقدم الدعوة أم طلب العلم؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":1084,"question":"هل العلم مُقتصر على العلوم الشرعية التي هي قول الله تعالى وقول رسوله ﷺ؟ فإذا كان غير ذلك فكيف نرد على مَن يقول: إن العلم مُقتصرٌ عليها، وأن العلوم الأخرى، مثل الكيمياء وغيرها، يجب ألا تُدرس؟","title":"هل طلب العلم يُقصد به العلم الشرعي فقط؟","answer":"الجواب:\nالعلم عند الإطلاق -كما سمعتُم في صلب المحاضرة وفي الأسئلة- عند أهل العلم، عند علماء الإسلام هو العلم الشرعي: قال الله، وقال رسوله، وما يتعلق بذلك. ولا حرج في تعلم العلوم الأخرى النافعة؛ لقصد نفع الناس في دنياهم: من طبٍّ، وهندسةٍ، وجيولوجيا، وعلم العمارة، وغير ذلك مما يحتاجه الناس، لا حرج في ذلك، ومع النية الصالحة يُؤجر، مع النية الصالحة يُؤجَر في ذلك؛ لأنَّ الناس في حاجة إلى أطباء، وإلى مهندسين، وإلى محاسبين، وإلى مُقاولين معماريين، إلى غير ذلك مما يحتاجه الناسُ، وإلى جيولوجيين يعرفون حاجة البلاد وما فيها من الخير ومن الكنوز.\nكل هذه العلوم مطلوبة، لكن ليست مُرادة عند الإطلاق، ليست داخلةً في قوله: وَأُولُو الْعِلْمِ [آل عمران:18] وأمثالها، لا، لكن تدخل في الحثِّ على نفع المسلمين، والنصح للمسلمين، فالدين النَّصيحة والتعاون على البر والتَّقوى، تدخل في الأشياء العامَّة؛ لأنها مع النية الصالحة تكون بِرًّا وتقوى، مع النية الصالحة، وأما مَن تعلَّمها للدنيا فهي مباحة، ما يتعلق بها أجرٌ، فإذا كان مع الإباحة نوى الخير: نوى أن ينفع الناس، نوى أن يُعين ولاة الأمور على الخير، نوى أن ينفع المجتمع؛ فله نيته الطيبة، وله أجره بهذه النية الطيبة.","link":"https://binbaz.org.sa/fatwas/21132/هل-طلب-العلم-يقصد-به-العلم-الشرعي-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0928هل العلم مقتصر على العلم الشرعي فقط؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم"]},{"id":1086,"question":"إننا نجد كثيرًا –وللأسف- من طلبة العلم الشرعي مَن يشغله طلبه للعلم عن إصلاح المُجتمع والدخول فيه، وإذا ناقشته قال: سوف أدعو بعدما أطلب العلم، فما رأيك في هذه المقولة؟","title":"كيف يُجمع بين طلب العلم وإصلاح المجتمع؟","answer":"الجواب:\nالواجب أن يقوم بنصيبه من إصلاح المجتمع، مع العناية بطلب العلم، فلا يمنعه طلبُ العلم من المشاركة في إصلاح المجتمع والتَّوجيه والإرشاد والدَّعوة حسب علمه، ولا يكون هذا الكلام عذرًا في الجملة، وإن كان عذرًا من بعض الوجوه في عدم التَّفرغ لهذا الأمر، لكنه حسب طاقته يعمل، أما التفرغ فيكون بعد الحصول على العلم، وانتهاء المهمة من الطلب الرسمي إلى التنفيذ والعمل، ومع العلم أيضًا؛ لأنه لا يزال طالب العلم في طلب العلم أبدًا، ولو أخذ الدكتوراه، ولو طلب العلم خمسين سنةً فهو لا يزال طالب علم أبدًا حتى يلقى ربَّه، ينبغي له أن يعلم هذا، وما خفي عليه أكثر مما علم.\nفطالب العلم يجب أن يعلم أنه لا يزال في حاجةٍ إلى العلم ولو بلغ ألف عام، ولو عمَّر أكثر من عمر نوح فهو في حاجةٍ إلى طلب العلم، فلا ينبغي أن تمنعه الوظيفة أو درجة علمية من المزيد من طلب العلم، والحرص على مُراجعة العلماء، والمذاكرة، ومراجعة الكتب، وتدبر القرآن؛ ليزداد علمًا.  ولكن مع ذلك يُشارك أيضًا في إصلاح المجتمع حسب طاقته: في طريقه إلى المدرسة، في طريقه إلى الجامعة، في طريقه إلى الصلاة، في طريقه لحاجاته في السوق، في سفره، في السيارة، في الطائرة، في القطار، في السفينة، في الباخرة، ما له عذر أن يقول: أنا طالب علم فقط، عليه أن يُشارك، لكن بالعلم، ما هو بالجهل، عليه أن يُشارك بالعلم، لا يقول بغير علمٍ، إذا كان ما عنده علمٌ لا يتكلم، وما كان فيه علمٌ وبصيرةٌ فليتكلم، ولا يقول: أنا حتى الآن في طلب العلم! كل الناس في طلب العلم، لو كان شيخُ الإسلام ابن تيمية موجودًا الآن فهو طالبٌ للعلم حتى يموت، وهكذا الصحابة في طلب العلم حتى يموتوا، كلٌّ في طلب العلم، ما أحد يستغني عن طلب العلم أبدًا، ولو كان مَن كان في التَّحصيل.\nفالحاصل أنه لا يجوز أن يمنعه طلبُ المزيد من العلم من المشاركة في إصلاح المجتمع، سواء كان في الثانوي، أو في المتوسط، أو في الجامعة، أو في الدراسات العليا، أو في أي قسمٍ، عليه أن يُشارك حسب طاقته: في أهله، في جيرانه، في قراباته، في جُلسائه، في طريقه، في أي مكانٍ يُشارك في طلب العلم، ويُشارك في توجيه الناس إلى الخير، ويُشارك في إصلاح المجتمع، لكن يتحرى الأساليب الطيبة، يتحرى الرفق، يتحرى الكلمات الطيبة، والأسلوب الحسن الذي ينفع ولا يضرّ، الذي يُقرِّب ولا يُنَفِّر، الذي يُسبب دخول العلم على قلب الإنسان وقبوله إيَّاه، وليحذر العنفَ أبدًا أينما كان.","link":"https://binbaz.org.sa/fatwas/21130/كيف-يجمع-بين-طلب-العلم-واصلاح-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0926هل هناك تعارض بين طلب العلم وإصلاح المجتمع؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":1130,"question":"لقد طلب مني بعضُ الإخوة أصحاب محلّ بيع شريط فيديوهات أن أعمل شريطًا فيه بيان كيفية تغسيل الميت، حتى يتعرف مَن لا يعرف ذلك عليه؟","title":"ما حكم عمل شريط فيديو لكيفية تغسيل الميت؟","answer":"الجواب:\nإذا كنتَ ذا علمٍ فلا بأس، جزاك الله خيرًا، لا بد من التَّثبت والتَّشاور مع أهل العلم إذا كان عندك بعض الشيء من الجهل، وإلا فأنت بحمد الله مشكورٌ إذا كنت على بصيرةٍ.","link":"https://binbaz.org.sa/fatwas/21202/ما-حكم-عمل-شريط-فيديو-لكيفية-تغسيل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0998ما حكم عمل شريط فديو لكيفية تغسيل الميت؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":1143,"question":"أخت تسأل وتقول: هل يجوز لي أن أكتب ردودًا على بعض المقالات التي تُنشر في بعض المجلات كالصحف، سواء كانت لكاتبٍ أو كاتبةٍ، بهدف أن أُصحح ما جاء في مقالتهم من أخطاء في اللغة، أو في أفكار تمس الدين؟ وهل يجوز أن أُكاتب الرجال، خاصةً من المؤلفين، بهدف مُناقشتهم لأفكارهم التي أجدها خاطئةً وتتعارض مع الدين؟ وجزاكم الله خيرًا.","title":"حكم مشاركة المرأة في الرد على المخطئين","answer":"الجواب:\nنعم، نعم، تقدم أنَّ الدعوة إلى الله مُشتركة بين الرجال والنساء، وأن واجب المرأة هو واجب الرجل في كل شيءٍ، إلا ما خصَّه الدليل، فالرد على المخطئين والغالطين مُشترك بين الرجال والنساء، بالكلام والمشافهة، وبالكتابة، وبالهاتف، كل ذلك طيب، والسؤال عمَّا أشكل من طريق الكتابة، ومن طريق الهاتف، أو من طريق المشافهة. كل هذا من حقِّ الجميع، للرجال والنساء، لكن بشرط العلم، لا تكتب ولا ترد ولا تُناقش إلا عن علمٍ، وهكذا الرجل لا يقل على الله بغير علمٍ، ولا تقل على الله بغير علمٍ، إن كان عندها علمٌ تكتب وتتكلم، وهكذا الرجل إذا كان عنده علمٌ؛ لأنَّ الله جلَّ وعلا حرَّم على الناس أن يقولوا عليه بغير علمٍ، وأخبر أن الشيطان يدعو إلى هذا ويأمر به، قال : قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [الأعراف:33]، فجعل القول على الله بغير علمٍ فوق مرتبة الشرك ولا حول ولا قوة إلا بالله؛ لأنَّ القول على الله بغير علمٍ فيه شرٌّ كثيرٌ: يقع فيه الشرك، ويقع فيه الكفر، وتقع فيه المعاصي، إلى غير ذلك.\nوقال سبحانه: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ  ۝  إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [البقرة:168- 169]، فالشيطان يأمر بأن نقول على الله بغير علمٍ.\nفليس للمرأة ولا للرجل الردّ على أحدٍ أو الكتابة في أي شأنٍ إلا عن علمٍ وعن بصيرةٍ، كما قال تعالى: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علمٍ.","link":"https://binbaz.org.sa/fatwas/21189/حكم-مشاركة-المراة-في-الرد-على-المخطىين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0985الدعوة لله مشتركة بين الرجال والنساء.mp3","categories":["العالم والمتعلم"]},{"id":1148,"question":"هناك اتِّجاه بين الحداثيين للتَّقليل من شأن التراث، بل إنَّ بعضهم يستخفُّ بكل قديمٍ، ويُطالب بالقيام ضدّ كل موروثٍ، فما قولكم لمثل هؤلاء؟ وما نصيحتكم لمَن يعرف بعض هؤلاء ويُصادقهم ولا ينصحهم أو يُنكر عليهم؟","title":"ما كيفية الرد على الحَدَاثيين ومواجهتهم؟","answer":"الجواب:\nالذي نعرف من الحداثيين أنهم ملاحدة، وأنهم دُعاة للكفر والضَّلال، وأنهم دُعاة لضد الشريعة، يدعون الناس إلى ترك الشريعة، وترك كل قديمٍ، وأن يعتنقوا ما يرون من الجديد الذي يُناسبهم، سواء من غربٍ، أو من الشرق، وهذا إلحادٌ وضلالٌ وكفرٌ عظيم.\nفالواجب محاربتهم ومُقاطعتهم وهجرهم والإنكار عليهم حتى يتوبوا ويرجعوا من هذا الباطل العظيم، والواجب على الدولة إذا عرفت أحدًا منهم أن يُستتاب، فإن تاب وإلا قُتِل مُرتدًّا؛ لقول النبي ﷺ: مَن بدَّل دينَه فاقتلوه.\nفالواجب على الدولة وفَّقها الله أن تعتني بأخبارهم وأشخاصهم، فمَن عُرف منهم دُعِيَ إلى الحقِّ، وأُرشد إلى الصواب، وبُيِّن له الهدى، فإن تاب فالحمد لله، وإلا وجب قتله؛ حتى لا يضل الناس، ومَن عرف منهم أحدًا فالواجب أن ينصحه ويُحذره من الباطل، لعلَّ الله يهديه بأسبابه، فإن أبى فليرفع عنه إلى الجهات المسؤولة؛ حتى لا يضرَّ الناس بدعوته الباطلة وشرِّه العظيم.\nنسأل الله السلامة، نسأل الله لهم الهدايةَ، نسأل الله لنا ولهم الهداية، وأن يردَّهم إلى الصَّواب.","link":"https://binbaz.org.sa/fatwas/21204/ما-كيفية-الرد-على-الحداثيين-ومواجهتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1000هناك اتجاه بين الحداثيين في التقليل من شأن التراث بل أن بعضهم يستخف بكل قديم فما رأيكم ؟.mp3","categories":["العالم والمتعلم"]},{"id":1151,"question":"ما رأي فضيلتكم في تحقيق بعض كتب المُبتدعة باعتبار أنها من التراث؟","title":"حكم تحقيق بعض كتب المُبتدِعة من التراث","answer":"الجواب:\nهذا فيه تفصيل: إن كان في تحقيقه فائدة للمسلمين لو ردَّ عليه، وللاستفادة؛ لما فيه من الخير، ورأى أن المصلحة في إحيائه وإبرازه لبيان باطله وللانتفاع بما فيه؛ فلا بأس، . أما إن كان إظهاره يضرُّ المسلمين؛ فلا خير في تحقيقه، ولا في إبرازه، بل يجب إتلافه.","link":"https://binbaz.org.sa/fatwas/21212/حكم-تحقيق-بعض-كتب-المبتدعة-من-التراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1008ما رأي فضيلتكم في تحقيق بعض الكتب المبتدعة باعتبار أنها من التراث؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":1156,"question":"كم نتمنَّى أن تُبَيِّنوا لنا حفظكم الله كيف كان طلبُكم للعلم؟ وكيف كان تدرجكم فيه؟ لعله يكون في هذا توجيهٌ سديدٌ لنا في حياتنا العلمية والعمليَّة.","title":"كيف كان طلبُ سماحة الشيخ ابن باز للعلم؟","answer":"الجواب:\nأنا طلبتُ العلم وأنا صغيرٌ وبصيرٌ، وكملتُ حفظ القرآن والحمد لله قبل البلوغ، قرأتُ القرآن على الشيخ عبدالله بن فريد رحمه الله في الرياض، ودرستُ العلم وأنا صغيرٌ في الرياض على مشايخ عدَّة، منهم: شيخنا قاضي الرياض صالح بن عبدالعزيز آل الشيخ رحمه الله، وكان بجوار بيتنا، يُصلي في المسجد الذي حولنا.  ثم لزمتُ الشيخ محمد بن إبراهيم رحمه الله عشر سنين أو أكثر من ذلك، وقرأتُ عليه غالب الدروس المتعلقة بالحديث والفقه والنحو والمصطلح وأصول الفقه، مع حلقةٍ علميةٍ كبيرةٍ رحمه الله، وهو أكبر شيوخي، وهو أستاذٌ كبيرٌ مُوفَّقٌ رحمه الله، تخرجتُ على يديه، وقرأتُ على غيره، لكن قراءتي عليه هي قراءةٌ مهمةٌ، وهي قراءة التَّحصيل العظيم من طريقه رحمه الله؛ لأنه كان حسن التعليم، وحسن العناية بالطلبة، ومجالسه مُستمرة، وحلقاته في الصباح والمساء مُستمرة: صباحًا، وضحوةً، وظهرًا، وعصرًا، ومغربًا رحمه الله، ولازمتُه حتى تعينتُ في القضاء عام سبع وخمسين من الهجرة، في منطقة الخرج.\nوذهب بصري في أول سنة خمسين من الهجرة، وأنا ابن تسع عشرة سنة، حين أصاب بصري التَّأثر كان سنة ستٍّ وأربعين، وبقي معي بعض الشيء، يعني: أهتدي في طريقي، وأُطالع بعض الشيء، وأقرأ بعض الشيء، لكن قد ضعف البصر، وفي نهاية العام التاسع والأربعين وأول العام الخمسين ذهب البصرُ كله والحمد لله.\nهذا بعض ما جرى من طلبي، وحفظتُ القرآنَ كما تقدَّم في حال الصِّغَر قبل الاشتغال بغالب العلوم.","link":"https://binbaz.org.sa/fatwas/21207/كيف-كان-طلب-سماحة-الشيخ-ابن-باز-للعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1003كيف كان طلبكم للعلم حفظكم الله؟.mp3","categories":["العالم والمتعلم"]},{"id":1162,"question":"كثيرًا ما نسمع عن بعض الأحكام الفقهية أنَّ فيها خلافًا بين العلماء، فما أسباب الخلاف؟ وماذا يفعل الإنسانُ تجاه ذلك؟ هل يختار ما يُريد من القولين أم أيسرهما أم أشدّهما؟ أم ماذا يفعل؟","title":"ما أسباب الاختلافات الفقهية والموقف منها؟","answer":"الجواب:\nالخلاف موجودٌ في بعض المسائل بين العلماء، في المسائل الفرعية، لا في الأصول، الأصول مُجمعٌ عليها والحمد لله، لكن توجد بعض المسائل الفرعية: بعض مسائل الصلاة، بعض مسائل الزكاة، بعض مسائل الصوم، بعض مسائل الحج، بعض مسائل المعاملات، بعضها فيها خلافٌ بين العلماء.\nوأسباب الخلاف أمورٌ:\nمنها: اختلاف الفهم: ليست أفهامُ الناس واحدةً، هذا يفهم من النص شيئًا، والآخر يفهم خلافه، فالناس فهومهم مختلفة، وذكاؤهم مختلف.\nومنها: عدم حفظ الأدلة: هذا يحفظ من الأدلة كثيرًا، وهذا لا يحفظ إلا قليلًا.\nومنها: كمال الحرص على طلب الحقِّ وضعفه: بعض الناس عندهم حرصٌ كاملٌ على طلب الأدلة، والحرص عليها، حتى يستوفي المقام، وبعض الناس يتساهل في طلب الأدلة، ويكتفي بالقليل فيُخطئ.\nوهناك أسبابٌ أخرى. والواجب على المؤمن في مسائل الخلاف إن كان طالبَ علمٍ: أن يتحرى الأدلة، وينظر في الأدلة، ويأخذ بالدليل الذي ظهر له معناه، وقال به بعضُ مَن مضى من أهل العلم، يُوافقه إذا ظهر له أنَّ الحقَّ معهم بالدليل: من آيةٍ، أو حديثٍ، ولا يتبع هواه ويتبع الأسهل، لا يأخذ بالدليل، ولو كان أشدّ، ما دام ظهر له أنه أقرب إلى الأدلة الشرعية.\nأما إن كان ليس بطالب علمٍ، أو طالبًا صغيرًا لا يقوى على فهم الأدلة، فهذا يسأل أهلَ العلم، يسأل الأساتذة، ولا سيما خيارهم، ومَن يظن فيه الخير منهم، والعناية، والفهم، والعلم، يسألهم ويجتهد؛ حتى يُرشدوه إلى الصَّواب.","link":"https://binbaz.org.sa/fatwas/21221/ما-اسباب-الاختلافات-الفقهية-والموقف-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1017ما أسباب خلاف العلماء في المسائل الفقهية وماذا يفعل المسلم تجاه ذلك؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":1168,"question":"ما سبيل الإخلاص في طلب العلم؟","title":"ما سبيل الإخلاص في تعلم العلم؟","answer":"الجواب:\nأن تتعلم لوجه الله ، لا لقصد الدنيا وحطامها، ولا للرياء والسّمعة، ولكن تتعلم لتعرف دينك، وتعمل بشرع ربك، ترجو ثوابه، وتخشى عقابه، هذا هو الإخلاص.  وما جاء بعد هذا من أمور الدنيا: من وظيفةٍ، أو مساعدةٍ، فهو خيرٌ إلى خيرٍ، لكن يكون الباعثُ لطلب العلم هو أن تقصد وجه ربك، بأن تعرف دينك، وتعمل بشرع الله على بصيرةٍ: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]، إِنَّ إِبْرَاهِيمَ كَانَ أُمَّةً قَانِتًا لِلَّهِ حَنِيفًا [النحل:120].\nفالإخلاص لله هو: أن تقصد وجهه الكريم وما عنده من الخير بعملك: من طلب علم، وصلاة، وجهاد، وغير هذا من شؤون الدين.","link":"https://binbaz.org.sa/fatwas/21215/ما-سبيل-الاخلاص-في-تعلم-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1011ما سبيل الأخلاص في تعلم العلم؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":1179,"question":"يقول: إنني كلما تعلمتُ علمًا ثم مضى عليه وقتٌ معينٌ نسيتُ ما تعلَّمته، فهل هذا مبررٌ لي لأترك طلب العلم؟","title":"حكم ترك طلب العلم بسبب مشكلة النسيان","answer":"الجواب:\nلا، ليس بمبررٍ، عليك أن تجتهد ولا تيأس، وأن تستمر في طلب العلم، والتَّحفظ والمذاكرة، وحاسب نفسك، أخشى أن تكون أُصبتَ بمعصيةٍ أقمتَ عليها، فحاسب نفسك، وتُبْ إلى الله من المعاصي، وجاهد، وسَلْ ربَّك التوفيق، وأبشر بالخير.  فالإنسان قد يُصاب بمعصيةٍ أصرَّ عليها فيُحرم من علمٍ كثيرٍ، فعليك أن تتوب إلى الله، وأن تُحاسب نفسك، وأن تجتهد في الدراسة والمذاكرة مع بعض زملائك الطيبين، ولا سيما في الأوقات المناسبة: أوقات فراغ القلب من ليلٍ أو نهارٍ، وأبشر بالخير، لا تيأس، الله يقول: وَلَا تَيْأَسُوا مِنْ رَوْحِ اللَّهِ [يوسف:87].","link":"https://binbaz.org.sa/fatwas/21253/حكم-ترك-طلب-العلم-بسبب-مشكلة-النسيان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1141كلما تعلمت علماً ثم مضى عليه وقت ونسيته هل هذا مبرر أن أترك العلم؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":1188,"question":"ظاهرة مُزعجة انتشرت بين بعض الشباب المُلتزم، وهي التَّسرع في الفتوى، والاستعجال في إطلاق الأحكام، نرجو توجيه سماحتكم إلى خطورة هذا المسلك؟","title":"حكم التسرع في الفتوى وإطلاق الأحكام","answer":"الجواب:\nنعم، قد نبَّهنا على هذا، الواجب على طلبة العلم أن يتثبَّتوا في الأمر، وألا يعجلوا في الفتوى قبل أن يعرفوا الأحكام على بصيرةٍ، فالتَّعجل فيه خطرٌ عظيمٌ، ولكن يتثبت طالب العلم، فإذا عرف الدليل وتيقَّن أنه مُصيبٌ للحقِّ أمكنه أن يتكلم، ذكروا عن مالكٍ رحمه الله أنه لم يتولَّ الفتوى حتى سأل أهلَ العلم مشايخه: هل هو صالح لذلك؟ فلما أشاروا عليه وقالوا: نعم؛ أفتى.\nالمقصود أنَّ أهل العلم لا يجرؤون على الفتوى إلا بعد التَّثبت والطُّمأنينة إلى أنَّ عندهم من العلم ما يكفي للفتوى، وأنهم على بصيرةٍ في قول الله ورسوله، بعد التَّشاور مع أهل العلم، بينهم وبين أهل العلم، حتى يُدرك ويعرف أنه على بصيرةٍ فيما يقول، ولا يعجل، ومتى كان عنده أدنى شكٍّ فلا يعجل، بل يُرشدهم إلى مَن يعلم أنه أهلٌ للفتوى، أو يُؤجِّلهم حتى يدرس الموضوع، وينظر في الأدلة الشرعية إذا كان أهلًا لذلك، حتى يُبلِّغهم الحكم الشرعي بعد التَّثبت، وبعد معرفة الدليل. هذا المقام خطيرٌ جدًّا، وجديرٌ بالعناية.","link":"https://binbaz.org.sa/fatwas/21244/حكم-التسرع-في-الفتوى-واطلاق-الاحكام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1150رأي سماحتكم بالتسرع في الفتوى والاستعجال في أطلاق الأحكام؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":1189,"question":"إذا صدر في المسألة أكثرُ من فتوى من علماء يُوثَق بعلمهم، فما حكم اتِّباع أكثر من فتوى في أوقات مُتعددة؟","title":"ما المشروع للمسلم عند تعدد فتاوى العلماء؟","answer":"الجواب:\nإذا صدرت فتاوى متعددة فطالب العلم لا يعجل، يتأمَّلها إن كان طالب علم وينظر ما هو أقربها للدليل فيأخذ به، ينظر ما هو الأقرب للدليل فيأخذ به، أو يستشير مَن يرى من أهل العلم حتى يدلَّه على ما هو الأقرب للدليل، ولا يعجل؛ لأنَّ الحقَّ واحدٌ لا يتعدد. فإذا تعددت الفتوى واختلفت فتأمَّل ولا تعجل إن كنتَ من أهل العلم، وإلا فاعرضها على مَن ترى من أهل العلم، تراه أقرب إلى العلم، وأقرب إلى الفقه من بعض المفتين، حتى يُرشدك إلى ما هو الصواب، ولا تعجلْ في الأمور.","link":"https://binbaz.org.sa/fatwas/21243/ما-المشروع-للمسلم-عند-تعدد-فتاوى-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1151أذا صدر في المسألة أكثر من فتوى من علماء يوثق بعلمهم فماذا أفعل؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":1193,"question":"ما دور العلماء في تحقيق الأمن؟ أفيدونا جزاكم الله خيرًا.","title":"ما دور العلماء في تحقيق الأمن بالمجتمعات؟","answer":"الجواب:\nدور العلماء هو الإرشاد إلى الخير، التَّوجيه إلى الخير، وتعليم الناس ما أوجب الله عليهم، وتحذيرهم ما حرَّم الله عليهم.\nودور ولاة الأمور الإلزام بذلك، ولاة الأمور من الأمراء عليهم الإلزام بذلك، وعلى الحاكم إذا رُفع إليه الأمرُ الإلزام بذلك.\nوعلى العلماء والدُّعاة إلى الله الإرشاد إلى الخير، ودعوة الناس إلى ما أوجب الله، وتحذيرهم ما حرَّم الله ؛ وبذلك يحصل الأمن، بتقوى الله وطاعة الله يحصل الأمن، قال تعالى: وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَى لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدُونَنِي لَا يُشْرِكُونَ بِي شَيْئًا [النور:55]، وقال سبحانه: وَلَيَنْصُرَنَّ اللَّهُ مَنْ يَنْصُرُهُ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ  ۝  الَّذِينَ إِنْ مَكَّنَّاهُمْ فِي الْأَرْضِ أَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنْكَرِ وَلِلَّهِ عَاقِبَةُ الْأُمُورِ [الحج:40- 41]، وقال تعالى: الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ يعني: بشرك أُولَئِكَ لَهُمُ الْأَمْنُ وَهُمْ مُهْتَدُونَ [الأنعام:82].\nفبطاعة الله ورسوله، والقيام بأمر الله، وإلزام الناس بالحقِّ من جهة ولاة الأمور، ونشر العلم والدَّعوة من جهة العلماء؛ بهذا كله يحصل للعباد الخير العظيم، والسَّعادة في الدنيا والآخرة، والأمن العاجل والآجل.\nنسأل الله أن يُوفِّق المسلمين لما يُرضيه، وأن يُصلح العلماء والأمراء وجميع المسلمين، وأن يُوفِّقهم للخير.","link":"https://binbaz.org.sa/fatwas/21239/ما-دور-العلماء-في-تحقيق-الامن-بالمجتمعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1155ما دور العلماء في تحقيق الأمن؟ ابن باز فتاوى.mp3","categories":["العالم والمتعلم"]},{"id":1212,"question":"إني أحبُّك في الله حبًّا لا يعلمه إلا الله ، ما حكم طلب العلم؟","title":"ما حكم طلب العلم؟","answer":"الجواب:\nأولًا: أحبَّك الله الذي أحببتنا له، يقول النبيُّ ﷺ في الحديث الصحيح: سبعة يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجل قلبه معلَّق بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، ورجل دعته امرأةٌ ذات منصبٍ وجمالٍ فقال: إني أخاف الله، ورجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شماله ما تُنفق يمينه، ورجل ذكر الله خاليًا –يعني: ما عنده أحد- ففاضت عيناه يعني: بكاء من خشية الله. متَّفقٌ على صحته.\nهذا الحديث العظيم الجليل يدل على أنَّ من السبعة الذين يُظلّهم الله في ظله: مَن تحابَّ في الله، المتحابُّون في الله من أي جنسٍ، أو في أي بلد، أو في أي مكان، أو في أي عصرٍ؛ هم داخلون في هذا الحديث العظيم.\nويقول ﷺ في الحديث الآخر: يقول الله  يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أظلهم في ظلِّي يوم لا ظلَّ إلا ظلِّي، نسأل الله أن يجعلنا وإياكم منهم.\nأما ما يتعلق بطلب العلم: فالواجب على طالب العلم أن يحرص على طلب العلم، وأن يتفقه في الدين، وأن يجتهد في أن يعرف أحكام الله، فالواجب أن تعرف ما أوجب الله عليك، وما حرَّم الله عليك، هذا هو الواجب، كل إنسانٍ يلزمه أن يتعلم ما لا يسعه جهله مما أوجب الله عليه وحرَّم عليه، أما التوسع في العلم ومعرفة أحكام الشرع فهذا فرض كفايةٍ، كما هو مقرر عند أهل العلم، فرض كفاية إذا قام به مَن يكفي سقط عن الباقين، ولكن أين مَن يكفي الآن؟ أين مَن يكفي؟\nالواجب على مَن رزقه الله التَّفرغ لطلب العلم أن يهتم بهذا الأمر، وأن يواصل، وأن يعتني من الجامعة إلى التخصص؛ لأنَّ ذلك أكمل في العلم، وأبلغ في قبول الدعوة، كل مَن كان مؤهله أكبر كان أقرب إلى التأثر بدعوته، إذا أخلص لله نيته، ثم هو أحوط فيما يتعلق بمزيد من العلم والبصيرة، فمن يسَّر الله له طلب العلم فليغتبط بهذا الشيء، وليفرح بهذا الشيء، كما قال الله سبحانه: قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُوا هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ [يونس:58].\nولا شكَّ أن من فضل الله أن يسَّر لك طلب العلم، واختارك لطلب العلم، ومن رحمته لك أن يسر الله لك مَن يُعلِّمك من أهل السنة، فافرح بهذا، واحمد الله عليه، وواصل الطلب، واصبر، وصابر، واحفظ وقتك، احفظ الوقت فيما يتعلق بالدروس، والعناية بها، وتدبرُّها قبل أن تأتي إلى المدرس، وفيما يتعلق بالمطالعة في بيتك، ومع زملائك، ومما يتعلق بالقرآن، والعناية به، والإكثار من تلاوته، وحفظ ما تيسر منه، وفيما يتعلق بالعمل؛ لأنَّ العمل يُعين على العلم، ويُسبب التوفيق، إذا كنتَ ممن يحرص على العمل في العلم، ويحرص على النوافل وأنواع التَّطوعات؛ كان هذا من أعظم الأسباب لتوفيق الله لك.","link":"https://binbaz.org.sa/fatwas/21257/ما-حكم-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1137ما حكم طلب العلم؟ ابن باز فتاوى.mp3","categories":["العالم والمتعلم"]},{"id":1244,"question":"ما حكم إلصاق الشَّائعات بالعلماء وطلبة العلم ليبعدوا عن توجيه الناس وإرشادهم وإبعاد الناس عن الاستماع لهم؟","title":"ما حكم إلصاق الشائعات بالعلماء وطلبة العلم؟","answer":"الجواب:\nهذا من الظلم وسُوء العقيدة -نسأل الله العافية- يعني: الناس إذا بعدوا عن العلماء بقوا في الجهالة، إذا أُبعد الناسُ عن العلماء ولم يسألوهم ولم يحضروا حلقات العلم بقوا في الجهالة، فالعلم من طريق العلماء: قال الله، وقال رسوله، وهم حملته، كما بيَّن النبيُّ ﷺ: أن حملة العلم هم أصحاب الغيث الذي استقرَّ في الأرض حتى نفع الله به الناس، أو شرب منه الناس، فالعلماء هم حملة العلم، يُبلغونه.\nالناس الجهَّال ما يُبلِّغون، ولا يستفيد منهم الناس، بل يضلون الناس، كما في الحديث الصحيح: يقول ﷺ: حتى إذا لم يُبْقِ عالمًا اتَّخذ الناسُ رؤوسًا جُهَّالًا، فسُئلوا، فأفتوا بغير علمٍ؛ فضلُّوا وأضلُّوا، بعض الشباب الجاهل قد يظن أنَّ العالم إذا كان في القضاء أو في الإفتاء أو مدرسًا أنه ما يكون عالمًا حتى يتفرَّغ ويُصلي في المسجد، ومن البيت إلى المسجد فقط، هذا العالم عنده، أما الذي يتوظَّف حتى يقضي بين المسلمين، أو يُفتي المسلمين، أو يدرس في المعاهد، هذا ليس بعالم!\nهذا جهلٌ عريضٌ، هذا جهلٌ لا حدَّ له -نسأل الله العافية- على العلماء أن يتسلَّموا الوظائف وينفعوا الناس، عليهم أن يقضوا، وعليهم أن يُفتوا، وعليهم أن يدرِّسوا، وعليهم أن يكونوا أمراء، عليهم أن يكونوا وزراء، حتى يُعلِّموا الناسَ، حتى يتحمَّلوا العلمَ، حتى ينقذوا الناسَ من الجهالة، إذا تولَّاها جُهَّالٌ ضاعت أمورُ المسلمين، هلك الناسُ، ولكن الجهل مثلما قال ابنُ القيم:\n\n\t\n\t\t\n\t\t\tوالجهل داء قاتل وشفاؤه\n\t\t\tأمران في الترتيب متَّفقان\n\t\t\n\t\t\n\t\t\tنصّ من الكتاب أو من سنةٍ\n\t\t\tوطبيب ذاك العالم الرباني\n\t\t\n\t\n\nفالذي ما عنده علمٌ كيف يُداوي الناس، يُداوي الناس وهو مريض؟!","link":"https://binbaz.org.sa/fatwas/21310/ما-حكم-الصاق-الشاىعات-بالعلماء-وطلبة-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1053ما حكم ألصاق الشائعات بالعلماء وطلبة العلم؟.mp3","categories":["العالم والمتعلم"]},{"id":1247,"question":"هناك مَن يدَّعي أنَّ دعوة العلماء إلى العقيدة وغيرها هي تحجير للعقل؛ لأنها لا تهتم بالتربية، فما قولكم في هذا أثابكم الله؟","title":"حكم من يرى الدعوة للعقيدة تحجيرًا للعقل","answer":"الجواب:\nالعقيدة هي أصل الدين، هي أساس الملَّة، بقي النبيُّ ﷺ فيها عشر سنين يدعو إلى العقيدة قبل أن تُفرض الصلاة، يدعو إلى توحيد الله، والإيمان برسوله محمد ﷺ، فهي الأساس، ولما بعث النبيُّ ﷺ معاذًا إلى اليمن قال له: ادعهم إلى أن يشهدوا أن لا إله إلا الله، وأني رسول الله، وفي اللفظ الآخر: فليكن أول ما تدعوهم إليه شهادة أن لا إله إلا الله، وفي رواية البخاري: فادعهم إلى أن يُوحِّدوا الله، فإن هم أجابوك لذلك فأعلمهم أنَّ الله افترض عليهم خمس صلوات في كل يومٍ وليلةٍ.. الحديث، فأمره أن يُعلمهم أولًا التوحيد والعقيدة، وهذا واجبٌ، ولا سيما في البلاد التي يكثر فيها الشركُ، ويكثر فيها دعاةُ غير الله، فلا بد من تعليمهم، حتى يُنقذهم من دعوة القبور والأموات، حتى تنفعهم أعمالهم، لو صلَّى وهو يُشرك بالله وأيش تنفع الصلاة؟ يقول سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88].\nإذا كان يدعو البدوي، أو يدعو محمدًا عليه الصلاة والسلام، أو يدعو أبا بكر، أو عثمان، أو عليًّا، يدعوهم، أو يدعو الحسين، أو الحسن، أو فاطمة، ويستغيث بهم، ويقوم ويُصلي هل تنفعه الصلاة؟! هل ينفعه الصوم؟!\nالله يقول سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وهو محمد عليه الصلاة والسلام، لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ  ۝  بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ [الزمر:65- 66]، ويقول جلَّ وعلا: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88].\nفالعقيدة ما هي بتحجّر، العقيدة تبصيرٌ للناس بالشيء الذي خُلِقُوا له، وبيان الأساس، وإذا كانوا مسلمين يعلمهم إيَّاها مع الأعمال الأخرى، وإن كانوا كفَّارًا لا، يبدأهم بالعقيدة أولًا، أما إذا كانوا مسلمين يُبَصِّرهم فيها؛ لئلا يغلطوا فيها، يُبصِّرهم ويشرح لهم العقيدة، حتى يكونوا على بينةٍ، وحتى لا يقعوا في الشرك، ويُبين لهم ما يتعلق لهم بصلاتهم وصومهم ومُعاملاتهم، وغير ذلك.","link":"https://binbaz.org.sa/fatwas/21307/حكم-من-يرى-الدعوة-للعقيدة-تحجيرا-للعقل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1050هناك من يدعي أن دعوة العلماء إلى العقيدة هي تحجير للعقل؟ ابن باز.mp3","categories":["العالم والمتعلم"]},{"id":1365,"question":"بعض الجماعات يهتم بالأخلاق أكثر مما يهتم بالتوحيد والدعوة إلى التوحيد، هل هذا صحيح؟","title":"حكم العناية بالدعوة للأخلاق أكثر من التوحيد","answer":"الجواب:\nيُعَلَّم، أهم شيء التوحيد أولاً، ثم بقية الواجبات من صلاة وغيرها مع ترك المحارم التي أعظمها الشرك، فكونه يجتهد في حُسْن الخلق يجتهد في السخاء والجود، يجتهد في طيب الكلام، فهذا تكميل.\nس: يقولون: التوحيد: كل الناس مسلمون حتى لو كانوا صوفية أو غيرهم، يقولون: التوحيد ينفِّر الناس، هذه دعواهم؟\nج: هذا من الجهل، هذا من الجَهَلَة، هذه دعوة الرسل، دعوة الرسل إلى التوحيد، والذي يرى أن التوحيد مُنَفِّر هذا من إخوان الجاهلية، من الجَهَلَة، مثل أبي لهب وأبي طالب وأشباههم الذين ابتعدوا عن الدعوة إلى التوحيد؛ حتى لا ينفروا آباءهم وإخوانهم.","link":"https://binbaz.org.sa/fatwas/21458/حكم-العناية-بالدعوة-للاخلاق-اكثر-من-التوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الواجب على الجماعات الاهتمام بالأخلاق أو بالتوحيد والدعوة إليه.mp3","categories":["العالم والمتعلم"]},{"id":1404,"question":"إذا كان النساء متحجبات هل للإنسان في إمكانه أن يدرسهن أو يوجههن أو ينصحهن؟","title":"حكم وعظ الرجل للنساء ونصحه لهن","answer":"الجواب:\nنعم، مثلما أتى النبي ﷺ النساء لما صلى العيد وقف عليهن وذكَّرهن ووعظهن وأمرهن بالصدقة.\nس: إن كان كاشفات لا يجوز؟\nج: ينصحهن، يعلمهن أن الواجب الحجاب، يعلمهن الحجاب ولا يهملهن وينصحهن، من جملة ما يعلمهن: الحجاب، وعدم التبرج بالزينة، وعدم الخلوة بالرجل، وعدم التقصير فيما أوجب الله، عدم التقصير بحق الزوج، يعلمهن ما قد يجهلن.\nس: لكن يكون بينه وبينهن حجاب أم يقابلهن وهن كاشفات؟\nج: يغض بصره ويتكلم.","link":"https://binbaz.org.sa/fatwas/21497/حكم-وعظ-الرجل-للنساء-ونصحه-لهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تدريس وتوجيه النساء.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":1423,"question":"شباب وصلوا في العلم درجة طيبة ونُصحوا بالحُسنى أن يوجِّهوا الناس فقالوا: يكفي أن نرفع عن أنفسنا الجهل، هل لهم حجة في ذلك؟","title":"حكم مَن تعلَّم علمًا ويأبى أنْ يُعَلِّم الناس","answer":"الجواب:\nلا ما يجوز، اللي عنده علم يبيِّن للناس، الله أخذ على من عنده علم أن يبيِّن وَإِذْ أَخَذَ اللَّهُ مِيثَاقَ الَّذِينَ أُوتُوا الْكِتَابَ لَتُبَيِّنُنَّهُ لِلنَّاسِ وَلَا تَكْتُمُونَهُ [آل عمران:187] لكن بس لا يتكلمون إلا بعلم ورفق وحكمة لا بالجهل.....\nس: هذه حجتهم ولا يُعَلِّمون الناس؟\nج: هذا غلط، خَيْرُكُمْ مَن تَعَلَّمَ القُرْآنَ وعَلَّمَهُ، وفي الحديث يُروى عنه ﷺ أنه قال: إنَّ اللَّهَ وملائكتَهُ يصلُّونَ علَى مُعلِّمِ النَّاسِ الخيرَ، وأعظم منه قوله تعالى: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا... [فصلت:33]، وقال جل وعلا: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]. ويقول ﷺ: مَن دَلَّ علَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ والأحاديث في هذا كثيرة.","link":"https://binbaz.org.sa/fatwas/21518/حكم-من-تعلم-علما-ويابى-ان-يعلم-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من تعلم علما ولا يبينه للناس بدعوى أنه رفع نفسه عن الجهل.mp3","categories":["العالم والمتعلم"]},{"id":1702,"question":"هل يجوز كتم العلم لمصلحةٍ؟","title":"ما حكم كتمان العلم لمصلحةٍ؟","answer":"الجواب:\nيكتم العلمَ الذي ما يليق بالمجلس، كأن يخاف أنهم يتَّكلوا أو ما أشبه ذلك، لكن إذا وضَّح لهم أحسن، يُوضِّح لهم الأسبابَ التي تمنعهم من الاتكال.\nس: إخبار معاذٍ خوفًا من الكتم؟\nج: مثلما قال ﷺ: لا تُبَشِّرهم فيتَّكلوا يعني: قد يجهلون ويحسبون مجرد التوحيد ولو فعلوا المعاصي سببًا لدخول الجنة وعدم العذاب، وهذا غلط؛ لأنَّ الله جلَّ وعلا يقول: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، فمَن مات على المعاصي فهو على خطرٍ، قد يُعفى عنه وقد يُعذَّب.","link":"https://binbaz.org.sa/fatwas/21808/ما-حكم-كتمان-العلم-لمصلحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كتمان العلم لمصلحةٍ.mp3","categories":["العالم والمتعلم"]},{"id":1808,"question":"بالنسبة لمدرس المواد الدينية هل يدخل في الذين يتعلَّمون العلمَ يبتغون عرضًا من الدنيا؟","title":"حكم تدريس المواد الدينية مقابل أجر","answer":"الجواب:\nإذا كان قصده وجه الله وأخذ مساعدةٍ ما يضره، مثل المجاهد الذي يُعْطَى ما يُعينه على السفر والجهاد.","link":"https://binbaz.org.sa/fatwas/21916/حكم-تدريس-المواد-الدينية-مقابل-اجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مدرس المواد الدينية هل يدخل في الذين يتعلَّمون العلمَ يبتغون عرضًا من الدنيا.mp3","categories":["العالم والمتعلم"]},{"id":1894,"question":"يوجد قارئ أحسن الله إليك، نفع الله به عبادًا كثيرين، وهدى الله على يديه كثيرًا من الكفر إلى الإسلام، ويقرأ عند عالمين كبيرين من أهل العلم، ولو علما بقراءته على الناس لربما قالا له: لا تقرأ علينا، ويقول: هل أترك القراءة البتة وأتفرغ للعلم أم أجمع بينهما؟","title":"كيف يوفق قارئٌ بين رُقْيَة الناس وطلب العلم؟","answer":"الجواب:\nيقول النبي ﷺ: لا بأس بالرُّقَى ما لم تكن شركًا، فإذا أحبَّ أن يُحسن إلى الناس فجزاه الله خيرًا، يُحسن إلى الناس في وجهٍ وعلى طريقةٍ لا تمنع من طلب العلم في أوقاتٍ مناسبةٍ، يجمع بين هذا وهذا، يطلب العلم ويتفقه في الدين، وإذا حصل عنده فرصة وقرأ على إخوانه المسلمين لا بأس، النبي قرأ على المريض، والصحابة لما مرُّوا على جماعةٍ في البَرِّ  من العرب لديغٌ سيدهم قرأوا عليه.\nس: يقول: يُنْكِر عليَّ المشايخُ: لماذا أتَّخذ هذا عادةً من العصر حتى العشاء؟\nج: على كل حال، يُعلمهم بالأسباب، وعليه تقوى الله، والحذر من شرّ نفسه وهواه، فقد يكون يحمله الطمع في الدنيا، فإذا لم يكن قصده الدنيا فلا يأخذ إلا القليل، ويرفق بالناس.\nس: لا ينظر إليها البتة إن كان من جهة الدنيا، لكن هم سبحان الله متشددون في هذا الأمر؟\nج: على كل حالٍ، الله الله يوفقه إذا كان يأمن على نفسه، وإن لم يكن يأمن على نفسه ويخشى أن قراءته على المرضى تجرُّه إلى شرٍّ كبيرٍ يتركها، فقد تجرُّه إلى مسألة النساء، وقد تجرُّه إلى الطمع، فعليه أن يدرس الموضوع.\nس: إذن لا يذكر لهما شيئًا؟\nج: يعمل بما يرى أنه مصلحة، ولو ما علَّمهم.","link":"https://binbaz.org.sa/fatwas/22005/كيف-يوفق-قارى-بين-رقية-الناس-وطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين القراءة على الناس وطلب العلم.mp3","categories":["العالم والمتعلم"]},{"id":1910,"question":"بالنسبة لما يُسمَّى بالمَرِّي، من أي رأس مالٍ يكون؟","title":"حكم تعلم علم الآثار والقيافة","answer":"الجواب:\nلا هذه من جهة الأثر لا بأس بها، كونه يتعلم الآثار المُرَّة وغير المُرَّة لا بأس، فعلم الآثار لا بأس به، ويُسمونها الأثر، فإذا تعلم أثر فلان أو أثر فلان، أو ما يتعلمه من جهة المياه -كأصحاب المياه- أنَّ الأرض هذه فيها ماء، والأرض هذه ما فيها ماء، هذه تُعلم بعلامات، والقافة معروفة عند العرب: قافة الأثر وقافة الأنساب معروفة، فالناس يعرفون الأنساب بالشَّبه، وهناك أناس يعرفون الأثر: هذا أثر فلان، هذا أثر فلان، لهم خبرة ودراية، وهذا موجود.\nس: يُقال لها: قافة؟\nج: يُسمُّونها قافة.\nس: هل هي من باب الفراسة؟\nج: قيافة الأثر نوعٌ من الفراسة، لكن يُسمُّونها قِيافة.","link":"https://binbaz.org.sa/fatwas/22023/حكم-تعلم-علم-الاثار-والقيافة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تعلم علم الآثار أو القافة أو القيافة.mp3","categories":["العالم والمتعلم"]},{"id":2043,"question":"تسمية الكتاب بالمُلَح، المعنى أحسن الله إليك...؟","title":"معنى تسمية بعض الكتب بالمُلَح ونحوها","answer":"الجواب:\nيعني أنه ما تَقَيَّد بشيء، من هنا ومن هنا، أحاديث مجمعة في كل شيء، ما هي بخاصة بشيء، والمُلَح جمع مُلْحة، يعني فيها ما يشتاق لها الناس.....، إما ترغيب أو ترهيب، أو أخبار عن حوادث، أو نحو ذلك، هذا المقصود.","link":"https://binbaz.org.sa/fatwas/22160/معنى-تسمية-بعض-الكتب-بالملح-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تسمية الكتاب بالملح.mp3","categories":["العالم والمتعلم"]},{"id":2054,"question":"إذا كان طالب علمٍ وأراد أن يُتاجر لكي يكتسب مالًا ويتصدق على الفقراء، ألا يُخْشَى عليه أن يقع في حبِّ الدنيا؟","title":"حكم تجارة طالب العلم بنية الإنفاق والتصدّق","answer":"الجواب:\nلا، لقد اتَّجر الصحابةُ وهم أفضل منا، وعملوا، ونفعوا الناس؛فعبدالرحمن اتَّجر، والصديق اتَّجر، وعمر اتَّجر، وغيرهم من الصحابة اتَّجروا، والأنصار مزارعون، وعندهم المزارع العظيمة ، ونفع الله بهم المهاجرين.\nس: لكن كثيرًا من طلاب العلم فعلوا ذلك ووقعوا في حبِّها؟\nج: لا، عليه بتجارةٍ لا تشغله عن طلب العلم وعن التَّفقه في الدين.","link":"https://binbaz.org.sa/fatwas/22172/حكم-تجارة-طالب-العلم-بنية-الانفاق-والتصدق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التجارة لطالب العلم.mp3","categories":["العالم والمتعلم"]},{"id":2067,"question":"يقول ابنُ القيم: مَن طلب الدنيا بنية أن يُحْسِن إلى الناس بها تكون أحبولةً من الشيطان، فيقع في حبِّ الدنيا وينشغل بها؟","title":"هل يجوز طلب الدنيا بنية الإحسان للناس؟","answer":"الجواب:\nلا، ما يضرُّ إذا طلب الرزق، مثلما قال ﷺ: احرص على ما ينفعك، فإذا أراد أن يتصدَّق ويُحْسِن وينفع الناسَ فهو مأجورٌ، كما فعل الصديقُ، فالصديق  أنفق أموالَه في نصر الدين وحماية النبي ﷺ والإنفاق عليه، وكذلك عمر أنفق الأموال الجزيلة، وهكذا عبدُالرحمن بن عوف، وهكذا أغنياء الصَّحابة، فقد نفع اللهُ بهم المسلمين.","link":"https://binbaz.org.sa/fatwas/22185/هل-يجوز-طلب-الدنيا-بنية-الاحسان-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلب الدنيا بنية الإحسان إلى الناس.mp3","categories":["العالم والمتعلم"]},{"id":2068,"question":"ما حكم تأليف الكتاب من باب التِّجارة؟","title":"حكم نشر العلم بقصد الدنيا والتجارة","answer":"الجواب:\nإذا ألَّف كتابًا لينفع المسلمين وباعه...\nس: هو قصده التِّجارة؟\nج: ما يكون له أجرٌ، إلا إذا كان قصد نفع المسلمين، أمَّا إذا كان قصده الدنيا فليس له إلَّا الدنيا.","link":"https://binbaz.org.sa/fatwas/22186/حكم-نشر-العلم-بقصد-الدنيا-والتجارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نشر العلم بقصد الدنيا.mp3","categories":["العالم والمتعلم"]},{"id":2100,"question":"قول بعض أهل العلم: أن أفضل النَّوافل بعد الفرائض طلبُ العلم؟","title":"هل طلب العلم فريضة أم نافلة؟","answer":"الجواب:\nطلب العلم فريضةٌ وليس نافلةً؛ حتى يتعلم دينه ويتفقّه فيه، لكن نوافله أفضل العبادات.\nس: هل حضور الدروس واجب؟\nج: عليه أن يتعلم، سواء بالحضور أو بالتَّعَلُّم، كله واحد؛ حتى يتفقّه في دينه.","link":"https://binbaz.org.sa/fatwas/22218/هل-طلب-العلم-فريضة-ام-نافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم طلب العلم هل هو فريضة أن نافلة.mp3","categories":["العالم والمتعلم"]},{"id":2295,"question":"عدم سؤال المشايخ أو العلماء ماذا يُسمَّى؟","title":"ما حكم التهاون في سؤال المشايخ والعلماء؟","answer":"الجواب:\nيُسمَّى: خورًا وضعفًا؛ لأنَّ النبي ﷺ يقول: احرص على ما ينفعك، واستعن بالله ولا تعجزنَّ، فالإنسان يحرص على ما ينفعه في الدين والدنيا، فإذا ترك هذا فهذا هو العجز.","link":"https://binbaz.org.sa/fatwas/22419/ما-حكم-التهاون-في-سوال-المشايخ-والعلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يُسمَّى عدم سؤال المشايخ والعلماء.mp3","categories":["العالم والمتعلم"]},{"id":2510,"question":"من تمسك بالسنة كما ينبغي؛ قَصَّر ثوبه وأعفى لحيته، كثير من المسلمين يقولون عنه: هذا متشدد وهذا متزمت وهذا كذا وكذا، ماذا يكون موقف الإنسان؟","title":"كيف يُعامل من يصف السُّنة بالتشدُّد والتزمُّت؟","answer":"الجواب:\nلا يبالي بهم، يقول: هذه السنة، والله يهديكم، يخاطبهم بالتي هي أحسن، هداكم الله هذه السنة، وبس، يعلمهم بالدليل والحمد لله، ولا يضرونه، ولا يبالي بهم، مثلما فعل المنافقون مع أهل السُّنة وَإِذَا مَرُّوا بِهِمْ يَتَغَامَزُونَ [المطففين:30].","link":"https://binbaz.org.sa/fatwas/22640/كيف-يعامل-من-يصف-السنة-بالتشدد-والتزمت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التمس بالسنة يعد تشددا وتزمتا.mp3","categories":["العالم والمتعلم"]},{"id":2811,"question":"حد العلم الواجب على الإنسان؟","title":"ما حد العلم الواجب على الإنسان؟","answer":"الجواب: ما لا يسع جهله، معرفة ما أوجب الله عليه، وما حرم عليه، لا يسعه جهلُه.","link":"https://binbaz.org.sa/fatwas/22960/ما-حد-العلم-الواجب-على-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حد العلم الواجب على الإنسان.mp3","categories":["العالم والمتعلم"]},{"id":2815,"question":"لكن يكون جُلُّ وقته للعلم إذا كان داعية؟","title":"هل يكون جُلُّ وقت الداعية للعلم؟","answer":"الجواب: حسب التيسير فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] قد يكون عنده حاجة ما عنده مَن يقوم بها، عنده حاجة إلى ما ينفقه على أهله، يكون له وقت للعلم والدعوة والتوجيه، ووقت لطلب الرزق. وطلب الرزق لا يمنع من الدعوة؛ مع البائع ومع المشتري ومع صاحب الدكان، ومع من يمر به ومع من يقف معه، إلى غير ذلك، طلب العلم الحمد لله متيسّر في أي مكان.","link":"https://binbaz.org.sa/fatwas/22964/هل-يكون-جل-وقت-الداعية-للعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكون جل وقت الداعية للعلم.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":2817,"question":"طالب العلم إذا كان لا يعرف عن صحة الحديث؟","title":"حكم الرواية بالمعنى وما لا تُعرف صحته","answer":"الجواب: يقول: يُرْوَى، يُذْكَر عنه، لا يَجْزم، يُرْوَى ويُذْكَر، ولا يَجْزِم حتى يعرف، يَحْرُم عليه الجزم. س: ولو علم اختلاف العلماء به؟ الشيخ: يقول الحافظ العراقي: وهذا هو المعروف عند أهل العلم، وقال: والإنسان يجتهد فيما يتعلق بالأدلة على التحريم والوجوب، أما الوعظ والتذكير فأمره أوسع؛ لا يجزم، يُروى عنه أنه قال كذا، يُذكر عن رسول الله ﷺ أنه قال كذا، يشجّعهم على الأعمال الطيبة. س: والرواية بالمعنى؟ الشيخ: لأهل العلم ما هو لكل أحد، لأهل العلم، إذا كان من أهل العلم؛لا بأس، إذا كان من أهل العلم يعرف المعاني؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/22966/حكم-الرواية-بالمعنى-وما-لا-تعرف-صحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طالب العلم إذا كان لا يعرف عن صحة الحديث.mp3","categories":["العالم والمتعلم"]},{"id":2820,"question":"معلوم أن أهل العلم متفاوتون في علمهم، فبعض الناس يقول: لا يؤخذ العلم إلا من الأكابر، ويترك الأصاغر مع أن عامة الأمة، أي طلاب العلم، مِن الأصاغر؟","title":"هل يُؤخذ العلم من الأكابر والأصاغر؟","answer":"الجواب: خُذْ العلم ممن تظن عنده العلم صغيرًا أو كبيرًا أو وسطًا، خذ العلم من أهله، كان الناس يأخذون العلم من أهله، كان ابن عباس من أصغر الصحابة، كانت الوفود تَرِدُ عليه وتأخذ منه العلم مع وجود الكبار من الصحابة كعبدالرحمن بن عوف والزبير بن العوام والحارث بن عبيد الله وجماعة، فالمقصود إذا عُرِف الشاب بالعلم والبصيرة يُؤخذ عنه العلم..... العلم الشرعي؛ قال الله، قال رسوله.\nس: في المسألة السابقة يستدلّون بالحديث الذي جاء فيه أن طلب العلم على الأصاغر مِن علامات الساعة؟\nالشيخ: لا ما له أصل، هذا ما أعرف له أصلًا.","link":"https://binbaz.org.sa/fatwas/22969/هل-يوخذ-العلم-من-الاكابر-والاصاغر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخذ العلم من الأكابر والأصاغر.mp3","categories":["العالم والمتعلم"]},{"id":2822,"question":"بالنسبة لاستماع الأشرطة سواء كانت محاضرات أو ندوات أو خطبًا أو دروسًا: هل يُعتبر من العلم؟","title":"هل يُعتبر استماعُ الأشرطة مِن العلم؟","answer":"الجواب: نعم، مِن العلم النافع، إذا كان صاحبها أهلًا لذلك، إذا كان صاحب الشريط مِن أهل العلم.\nس: أو مِن طلبة العلم؟\nالشيخ: إذا كان مِن أهل العلم الذين يُؤخذ بقولهم ويُؤمَن أن لا يقول على الله بغير علم، مِن أهل العلم المعروفين المشهورين.","link":"https://binbaz.org.sa/fatwas/22971/هل-يعتبر-استماع-الاشرطة-من-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل استماع الأشرطة يعتبر من العلم.mp3","categories":["العالم والمتعلم"]},{"id":2836,"question":"وإن الملائكة تضع أجنحتها لطالب العلم على ظاهره؟","title":"معنى وضع الملائكة أجنحتها واستغفار الحوت","answer":"الجواب: الله أعلم.\nس: استغفار الحيتان للعالم من سائر الحيوانات؟\nالشيخ: حتى يعني: حتى الحيتان وكل شيء، حتى؛ لأن فتواه وتعليمه ينشر الحق والخير، يُوجَد المطر ويُوجَد النبات، وينتفع البادي والحاضر والدواب وغير الدواب.","link":"https://binbaz.org.sa/fatwas/22985/معنى-وضع-الملاىكة-اجنحتها-واستغفار-الحوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وضع الملائكة أجنحتها لطالب العلم واستغفار الحيتان.mp3","categories":["العالم والمتعلم"]},{"id":2837,"question":"ترك طالب العلم الجواب تَوَرُّعًا مع علمه بأنه لا يتوقف في المسألة...؟","title":"حكم ترك طالب العلم جواب السائل تَوَرُّعًا","answer":"الجواب: ما يجوز له، إلا إذا كان أحاله إلى غيره، إذا رأى الإحالة إلى غيره لتورع أو لأن غيره أعلم منه فلا بأس، كان الصحابة يحيلون، يحيل بعضهم على بعض، أما كونه يترك الناس جهالًا ويقول: هذا تَوَرُّع، هذا ما هو تَوَرُّع، إذا كان ما في إلا هو؛ يجتهد.\nس:إذا كان يعلم أنه ليس الموقف توقف عليه؟\nالشيخ: إن كان عنده شك لا يفتي بغير علم، ومن كان قصده الورع ويوجد من هو أعلم منه يحيل إليه، يقول: رُح اسألوا فلان ما يخالف.\nس: حديث أبي هريرة: من سئل عن علم... صحيح؟\nالشيخ: نعم.\nس: هل يدخل في حديث أبي هريرة: ألجم بلجام من نار إذا سئل رجل عن جماعة ضالة فسكت، هل طريقه صحيح إلى طريق النبي ﷺ؟\nالشيخ: نعم يدخل في هذا.","link":"https://binbaz.org.sa/fatwas/22986/حكم-ترك-طالب-العلم-جواب-الساىل-تورعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ترك طالب العلم الجواب تورعا.mp3","categories":["العالم والمتعلم"]},{"id":2943,"question":"الذي يحضر حلقات العلم والمحاضرات والندوات هل يُطلق عليه: طالب علم؟","title":"هل يُعدُّ \"طالب علم\" مَنْ يحضر حلقات العلم؟","answer":"الجواب: ما في شك، لا شك أنه طالب علم.","link":"https://binbaz.org.sa/fatwas/23099/هل-يعد-طالب-علم-من-يحضر-حلقات-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إطلاق لقب طالب علم على من يحضر حلقات العلم.mp3","categories":["العالم والمتعلم"]},{"id":2977,"question":"العلم الذي لا ينفع هي علوم الدنيا؟","title":"ما هو العلم الذي لا ينفع؟","answer":"الجواب: كل علم لا ينفع داخل فيه، حتى علم الشرع إذا ما نفعه صار حجة عليه، نسأل الله العافية، إذا لم يعمل به صار حُجة عليه.\nس: علوم الدنيا ألا تدخل في العلم الذي لا ينفع؟\nالشيخ: لا، علوم الدنيا قد تنفع، النجار ينفعه علمه، والحداد ينفعه علمه، والسواق ينفعه علمه، لكن بعض الناس عنده علوم شرعية مثل اليهود وعلوم السوء لا تنفعهم، علومهم حجة عليهم يوم القيامة إلى النار، نسأل الله العافية.\nس: المقصود بالمنفعة في الدنيا والآخرة؟\nالشيخ: يَعُمُّ هذا وهذا.","link":"https://binbaz.org.sa/fatwas/23134/ما-هو-العلم-الذي-لا-ينفع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو العلم الذي لا ينفع.mp3","categories":["شروح الحديث","العالم والمتعلم"]},{"id":3023,"question":"إذا استنقص أحدًا مثلا قال: هذا سلفي، أو هذا تبليغي، أو هذا إخواني، وكذا، بقصد تنقيص الشخص، هل تعتبر مِن الغِيبة؟","title":"حكم نِسْبةُُ شخصٍ لجماعة معينة للتنقيص منه؟","answer":"الجواب: لا، ذِكْرُه بهذا ما هو بغِيبة، ذِكْرُه بما أظهر ليس مِن الغيبة، هو الذي أظهر نفسه، هو الذي هتكها.\nس: شخص قال مثلًا: هذا سلفي، يعني استهزاء به مثلًا، يعني يقول إنه يزكي نفسه، أو كذا، أو مثلًا قال: هذا الشخص لا يهمك، هذا إخواني، أو هذا الشخص مثلًا تبليغي؟\nالشيخ: إذا كان فيه بِدعة ينُصح فيها، صفته كذا وصفته كذا، يعني مِن أهل البدع، لا بأس، يُبِلِّغ عنه حتى يُحذر.","link":"https://binbaz.org.sa/fatwas/23182/حكم-نسبة-شخص-لجماعة-معينة-للتنقيص-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القدح في العلماء وفي أهل السنة والجماعة.mp3","categories":["الأخلاق المذمومة","العالم والمتعلم"]},{"id":3100,"question":"هل هناك كتب توصون بها من أراد أن يتعلم أصول الفقه؟","title":"ما الكتب التي يُوصى بها في أصول الفقه؟","answer":"الجواب: فيه للفتوحي، وفيه الورقات، وفيه لصاحب المغني \"روضة الناظر\"، مراجعتها مفيدة.","link":"https://binbaz.org.sa/fatwas/23260/ما-الكتب-التي-يوصى-بها-في-اصول-الفقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كتب يستفاد منها في أصول الفقه.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":3166,"question":"وسائل الدعوة توقيفية، هذا الصحيح؟","title":"هل وسائل الدعوة توقيفية أم اجتهادية؟","answer":"الجواب: وسائل الدعوة اجتهادية، ما هي بتوقيفية. التوقيفي العلم، لا بد من العلم قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] إذا جاء العلم ينفّذ العلم بالكتابة أو بالكلام أو بالهاتف أو بأي وسيلة يستطيعها، الدعوة إلى الله.","link":"https://binbaz.org.sa/fatwas/23329/هل-وساىل-الدعوة-توقيفية-ام-اجتهادية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل وسائل الدعوة توقيفية أم اجتهادية.mp3","categories":["العالم والمتعلم"]},{"id":3215,"question":"من يقول إن من يفسر الرؤى بلا علم في علم الرؤى كَمَنْ يفتي بلا علم؛ أنه يأثم؟","title":"حكم تفسير الرؤيا بلا علم","answer":"الجواب: لا يجوز يفسر إلا بعلم. لا فتوى ولا رؤيا، كلها ليس له إلا أن يكون على بصيرة، عن معرفة وعن بصيرة يطمئن إليها.","link":"https://binbaz.org.sa/fatwas/23378/حكم-تفسير-الرويا-بلا-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تفسير الرؤيا بلا علم.mp3","categories":["العالم والمتعلم"]},{"id":3216,"question":"هل هناك كتاب مختص لتفسير الرؤيا؟","title":"ما الذي يُعتمد عليه في تفسير الرؤى؟","answer":"الجواب: فيه بعض الكتب، لكن مثل هذا إنما ينبغي لأهل العلم، أهل البصيرة الذين يعرفون الأحاديث ويعرفون ما دل عليه القرآن، يكون على بصيرة.\nس: يعتمدون عليها؟\nالشيخ: ما هو على كل حال، يعتمدون على ما عنده من العلم.","link":"https://binbaz.org.sa/fatwas/23379/ما-الذي-يعتمد-عليه-في-تفسير-الروى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاعتماد على كتب أم على أهل العلم عند تفسير الرؤى.mp3","categories":["العالم والمتعلم"]},{"id":3254,"question":"ما حكم قراءة القصص البوليسية والألغاز؟","title":"ما حكم قراءة القصص البوليسية والألغاز؟","answer":"الجواب: لا أعرف القصص البوليسية، والألغاز الامتحان، اللَّغَز يُؤتى بكلام ظاهره خلاف باطنه للامتحان... لا ينبغي خطاب الناس إلا عند الامتحان وإرادة امتحان الشخص أو الطالب، إذا كان من باب الامتحان ومن باب الاختبار، وإلا فالسنة للمؤمن أن يكون كلامه واضحًا، إذا خاطب إخوانه كلامه واضح ما فيه ألغاز؛ يُبَيِّن حتى يفهمه أخوه فهمًا جيدًا.","link":"https://binbaz.org.sa/fatwas/23418/ما-حكم-قراءة-القصص-البوليسية-والالغاز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قراءة القصص البوليسية والألغاز.mp3","categories":["العالم والمتعلم"]},{"id":3261,"question":"من لديه كتاب \"في ظلال القرآن\" هل له أن يستفيد منه أو يَحْرِقه؟","title":"حكم اقتناء كتاب \"في ظلال القرآن\"","answer":"الجواب: والله ما تأملته كثيرًا، وفيه بعض الأخطاء، لكن كونه يُحفظ عنده ويستفيد منه إذا كان طالب العلم، الحمد لله، أما إذا كان ليس من أهل العلم يطلب كتب السلف؛ كتب شيخ الإسلام ابن تيمية وكتب ابن القيم وكتب الحديث الأئمة المعروفين، وفي ظلال القرآن فيه أخطاء، وطالب العلم الفاهم يعرف الأخطاء، وقَلَّ كتاب إلا وفيه أخطاء غير كتاب الله.","link":"https://binbaz.org.sa/fatwas/23425/حكم-اقتناء-كتاب-في-ظلال-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كتاب في ظلال القرآن.mp3","categories":["العالم والمتعلم"]},{"id":3346,"question":"هل لطالب العلم أن يعصي أبويه في طلب العلم يا شيخ؟","title":"هل تجوز معصية الوالدين في طلب العلم؟","answer":"الجواب: فيه تفصيل: هذا إذا كان فيما يجب عليه لا طاعة لمخلوق في معصية الخالق. أما في مزيد من العلم والتوسّع في العلم: يجمع بين الأمرين، لا يعصي والديه في حاجاتهما، ويطلب العلم حسب الطاقة، يجمع بين الأمرين.  أما في تعلم دينه، وما لا يسعه جهله؛ يلزمه، ويجب، وليس له طاعة أحد في ذلك إنما الطاعة في المعروف.","link":"https://binbaz.org.sa/fatwas/23512/هل-تجوز-معصية-الوالدين-في-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لطالب العلم أن يعصي والديه في طلب العلم.mp3","categories":["العالم والمتعلم"]},{"id":4254,"question":"الشيخ محمد بن عبدالوهاب كم مكث في الدعوة هنا؟","title":"كم مكث الشيخ محمد بن عبدالوهاب في الدعوة؟","answer":"الجواب: مكث في الدعوة قريب من ستين سنة، أربعة وأربعين تقريبا أو خمسة وأربعين إلى ست، قريب خمسين سنة أو أكثر، أو ستين سنة. هو كان في حريملاء لما قدم إلى العراق ثم انتقل من حريملاء إلى عيينة عند عثمان بن معمر أميرها وساعده على ذلك، وكان في جبيلة قبر لزيد بن الخطاب مبني عليه بنية فهدموه. ثم انتقل من عيينة إلى الدرعية عام سبع وخمسين ومائة، فمكث في الدرعية من سبع وخمسين، يعني أربعة وأربعين سنة وست من عام ألف.. وثلاثة عشر، فصار خمسين في الدرعية، وسنوات قبلها في عيينة، وسنوات في حريملاء، يمكن ستين سنة أو أكثر، رحمه الله؛ لأن عمره واحد وتسعين سنة.\nس: وكان آل سعود معه في هذه الفترة كلها؟\nج: في الدرعية لما كان في الدرعية سنة 57 بدأ الدعوة في 58 في الدرعية والإمام محمد بن سعود أميرها كان معه في هذا، خمسين سنة رحمه الله، ثم ابنه عبد العزيز معه ثم أولاده.","link":"https://binbaz.org.sa/fatwas/24524/كم-مكث-الشيخ-محمد-بن-عبدالوهاب-في-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كم مكث الشيخ محمد بن عبد الوهاب في الدعوة.mp3","categories":["العالم والمتعلم"]},{"id":4737,"question":"وإذا قال المُفتي أو الإمام: لا أعلم ذلك ورد عن الرسول ﷺ. يقصد في حدِّ علمه؟","title":"ما حكم قول المُفتي أو الإمام: ما ورد كذا عن الرسول؟","answer":"إذا قال: لا أعلم. هذا طيب، لكن المصيبة إذا قال: لم يرد عن الرسول. ولا ينبغي استعمال قول: ما ورد. وإن قصد في حدِّ علمه، بل ينبغي استعمال \"لا أعلم\" أو \"لا أعرف ذلك\" أو \"لم أقف على شيء في الباب\" ونحو هذا.","link":"https://binbaz.org.sa/fatwas/25062/ما-حكم-قول-المفتي-او-الامام-ما-ورد-كذا-عن-الرسول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول المُفتي أو الإمام لا أعلم ذلك ورد عن الرسول.mp3","categories":["العالم والمتعلم"]},{"id":4775,"question":"إذا اختلف على المستفتي فتوى المفتين فبأي الأقوال يأخذ؟","title":"بماذا يُعمل عند اختلاف فتوى المفتين؟","answer":"ما وافق الحق، ما وافق الأدلة الشرعية، ما وافق الكتاب والسنة فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] وإذا اشتبه عليه يسأل من يظنه أقرب وأفهم وأفقه، حسب الاجتهاد، يتحرى.","link":"https://binbaz.org.sa/fatwas/25139/بماذا-يعمل-عند-اختلاف-فتوى-المفتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا اختلف على المستفتي فتوى المفتين فبأي الأقوال يأخذ.mp3","categories":["العالم والمتعلم"]},{"id":4792,"question":"تنصح طالب العلم المبتدئ في قراءة المطولات؟","title":"هل يبدأ طالب العلم بالمختصرات أم المطولات؟","answer":"لا، المبتدئ عليه بالاختصار، لا يشوّش على فكره فتلتبس عليه الأمور، عليه حفظ المتون، ومراجعة الكتب القريبة التي ما فيها إشكال، معناها واضح فيما يتعلق بالمتن، وقراءته؛ لأنه إذا دخل الكتب الموسعة تلتبس عليه الأمور.","link":"https://binbaz.org.sa/fatwas/25170/هل-يبدا-طالب-العلم-بالمختصرات-ام-المطولات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نصحية الشيخ ابن باز لطالب العلم المبتدئ.mp3","categories":["العالم والمتعلم"]},{"id":4805,"question":"إذا كان المسلمُ سلك طريقًا يلتمس به علمًا: كالطب، والهندسة، فهل يدخل في هذا الحديث، يعني غير العلوم الشرعية؟","title":"«من سلك طريقًا يلتمس فيه علمًا» هل يشمل العلم الدنيوي؟","answer":"الأقرب -والله أعلم- أنَّ المراد به العلوم الشرعية، أما العلوم الأخرى فهي مباحة، إذا كان أراد بها الخير يُرجى له الخير، إذا أراد بها نفع المسلمين: كطبٍّ، أو هندسةٍ، أو حسابٍ، وأراد به نفع المسلمين؛ يُرجى له الخير إن شاء الله، لكن العلم إذا أُطلق: قال الله، قال رسوله، هذا العلم.","link":"https://binbaz.org.sa/fatwas/25200/من-سلك-طريقا-يلتمس-فيه-علما-هل-يشمل-العلم-الدنيوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من سلك طريقًا يلتمس فيه علمًا... هل يدخل في هذا علم الطب، والهندسة ونحوه.mp3","categories":["شروح الحديث","العالم والمتعلم"]},{"id":4995,"question":"القراءة بالدور؟","title":"ما حكم قراءة القرآن الجماعية بالدور؟","answer":"الجواب: ما أعلم فيها شيئا، يعني جماعة يعني؟\nس: نعم جماعة، هذا يقرأ وجهًا، وهذا يقرأ وجهًا؟\nج: ما في بأس، كل ما قرأ واحد يقرأ الآخر، من باب المدارسة؛ مثل ما دارس النبي جبرائيل عليه الصلاة والسلام.\nس: من قال: هذا ما ثبت عن السلف؟\nج: لا ما في بأس، إنما هذا كان السلف يفعلون يتدارسون القرآن، وفي الحديث الصحيح: ما اجتمع قوم يتلون كتاب الله ويتدارسونه بينهم إلا نزلت عليهم السكينة وغشيتهم الرحمة التدارس تارة يكون بإعادة المقروء، وتارة هذا يقرأ وهذا يقرأ.","link":"https://binbaz.org.sa/fatwas/28699/ما-حكم-قراءة-القران-الجماعية-بالدور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم قراءة القرآن الجماغية بالدور؟.mp3","categories":["العالم والمتعلم"]},{"id":5014,"question":"بالنسبة للمسألة في الكتب الخاصَّة بالتَّوزيع: هل تُعَدُّ من المسألة المذمومة؟","title":"حكم سؤال طالب العلم الكتب المُعدَّة للتوزيع","answer":"الجواب: لا، إذا صارت تُوزّع يطلب نصيبَه منها إن كان طالب علمٍ يطلب نصيبه من الجهة التي تُوزّع الكتب.","link":"https://binbaz.org.sa/fatwas/28826/حكم-سوال-طالب-العلم-الكتب-المعدة-للتوزيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم سؤال طالب العلم الكتب المعدة للتوزيع.mp3","categories":["العالم والمتعلم"]},{"id":5093,"question":"سؤاله الثالث يقول فيه: سماحة الشيخ دلني على كتاب أو كتابين جيدَين؛ لأتفقه بهما في أمر ديني!","title":"هل من كتب يُنصح بها للتفقه في الدين؟","answer":"الجواب: أدلك على كتب مناسبة، منها: - \"بلوغ المرام\" للحافظ ابن حجر، وهو كتاب جيد في الحديث. - و\"الأربعين النووية\"، وتتمتها لـ ابن رجب خمسين حديثًا. وهذان الكتابان في الحديث كتابان عظيمان. وفي الفقه أدلك على: - \"آداب المشي إلى الصلاة\"، للشيخ محمد بن عبد الوهاب رحمه الله، فإنه كتاب جيد في الصلاة، وفي الزكاة، وفي الصيام، جمع فيه كلمات طيبة وعبارات مفيدة. وهكذا أرشدك إلى \"زاد المعاد\" لـ ابن القيم، فإنه كتاب جيد مفيد، سماه مؤلفه: \"زاد المعاد في هدي خير العباد\"، وهو كتاب جيد ومفيد. وهذان كتابان جيدان، مفيدان. ومن الكتب الطيبة النافعة: \"الوابل الصيب في الكلم الطيب\" لـ ابن القيم رحمه الله، فإنه ذكر فيه فوائد جمة في أوله، وأبوابًا مفيدة في الأذكار.","link":"https://binbaz.org.sa/fatwas/29997/هل-من-كتب-ينصح-بها-للتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 13.mp3","categories":["العالم والمتعلم"]},{"id":5101,"question":"أحد الإخوة من الفلبين يسأل ويقول: من أساليب  تنصير المسلمين في الفلبين الآن تقديم المساعدات المادية والمعنوية من قبل القساوسة على إمام المسجد وجماعته على أن يسمحوا للقسيسين النصارى إلقاء محاضرة عن خليط من الإسلام والمسيحية بدلا من خطبة الجمعة وذلك أسبوعيًّا، و كيف نواجه هذا الأسلوب؟ أفيدونا جزاكم الله خيرًا.","title":"ما كيفية مواجهة أساليب التنصير في بلاد المسلمين؟","answer":"الجواب: الواجب على المسؤولين عن المسلمين - العلماء وغيرهم - أن يحولوا بين هؤلاء وبين ما أرادوا، وأن يبذلوا المساعدة المستطاعة للمسلمين، وأن يكفوهم الحاجة إلى عدوهم، وأن يحذروا مكائد الأعداء، وأن يحثوا المسلمين على الصبر والحرص على البعد عن أعدائهم والاختلاط بأعدائهم والسماع لتوجيهات أعدائهم؛ فإنهم يدعون إلى النار، وأهل الإسلام يدعون إلى الجنة. فعلى المؤمن أن يصبر وأن يحتسب وأن يتصبر على ما قد يصيبه من ضعف وحاجة حتى يجد ما يسدها، وعلى إخوانه المسلمين أن يواسوهم وأن يحسنوا إليهم وأن يتعاونوا في ذلك بكل ما يستطيعون ولو بالقليل؛ فإن القليل مع القليل يكون كثيرًا، إذا بذل هذا مستطاعه والآخر كذلك والآخر كذلك تجمع الخير الكثير وانتفع به المحاويج من المسلمين، واستغنوا به عن شر أعدائهم ومكائد أعدائهم الذين يتربصون بهم الدوائر ويبذلون المال الذي يقودهم إلى النار، نسأل الله السلامة. ثم من المهمات أن على رؤساء الأقليات الإسلامية وعلى أعيانهم أن يكتبوا لمن يرون فيه الخير وأن يوضحوا حاجة إخوانهم الفقراء، وأن يستعينوا بمن حولهم من رؤساء المراكز الإسلامية والجمعيات الإسلامية حتى يتم التعاون، لا يغفلوا، على الجميع أن يتعاونوا على البر والتقوى وعلى إيجاد المكاسب الطيبة التي تعينهم على طاعة الله في بلادهم، على أن يعتنوا بالمكاسب والصناعة التي تنفعهم بأي عمل ينفعهم حتى يستغنوا عن الحاجة إلى أعدائهم، الرسول يقول عليه الصلاة والسلام في الحديث الصحيح: احرص على ما ينفعك واستعن بالله ولا تعجزن رواه مسلم في الصحيح.  فعلى المؤمن أن يبذل وسعه في طلب الرزق والحرص على طلب الرزق بالطرق الحلال؛ حتى يستغني عن الحاجة إلى أعداء الله.","link":"https://binbaz.org.sa/fatwas/30009/ما-كيفية-مواجهة-اساليب-التنصير-في-بلاد-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatwa 26.mp3","categories":["العالم والمتعلم"]},{"id":5110,"question":"سماحة الشيخ أفيدونا أثابكم الله، من المعلوم أن ديننا وسط، ولكن الإفراط في بعض المسائل، فهل معنى هذا التوسع في الفتيا أو التمسك بسد الذرائع والتوسع في الفتيا والاقتصار على النصوص؟","title":"ما حكم التوسع في الفتيا والتمسك بسد الذرائع؟","answer":"الجواب: هذا مقام عظيم، مقام......؛ فالواجب عدم التوسع في الفتيا، الواجب على المؤمن أن يخاف الله ويراقبه، وألا يفتي إلا عن بصيرة وعن نص عَرَفَه، وإذا لم يكن هناك نص فلا بدّ من اجتهاد عند الضرورة وتحرٍّ للحق إذا كان من أهله، إذا كان عنده علم بالنصوص من الكتاب والسنة والقواعد الشرعية فلا بدّ يتحرّى الحق عند الضرورة ويجتهد في الإفتاء عند الضرورة، كان الصحابة  يتدافعون الفتوى بينهم حرصًا منهم على السلامة وحذرًا من خطر الفتوى. فينبغي للمؤمن ألا يكون حريصًا على الفتوى، ولا سريعًا في الفتوى، وإذا رأى من هو أفضل منه أحال إليه؛ لأنه أقرب إلى الصواب منه كما فعل الصحابة رضي الله عنهم وأرضاهم، فينبغي للمفتي ألا يتوسع في الفتوى، وأن يحرص على تحري الحق بالدليل، وأن يفتي على مقتضى الدليل حسب الطاقة والإمكان؛ إرشادًا للأمة وتوضيحًا للحق، وإذا كان في المقام إشكال توقف ولم يفت حتى يحقق الأمر وحتى يتضح له وجه الصواب، وإن كان من أعلم الناس؛ فالصحابة أعلم الناس بعد الأنبياء وكانوا يتوقّفون في مسائل كثيرة ويحيل بعضهم على بعض؛ حذرًا من خطر الفتوى، وهكذا الأئمة بعدهم،  رضي الله عنهم ورحمهم.","link":"https://binbaz.org.sa/fatwas/30018/ما-حكم-التوسع-في-الفتيا-والتمسك-بسد-الذراىع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 38.mp3","categories":["العالم والمتعلم"]},{"id":5121,"question":"سائلٌ يقول: هناك مَن يُحذِّر من كتب الإمام النووي وابن حجر رحمهما الله تعالى، ويقول: إنَّهم ليسوا من أهل السنة والجماعة، فما الصَّحيح في ذلك؟","title":"ما صحة ما نُسب للنووي وابن حجر من أخطاء؟","answer":"الجواب: لهم أشياء غلطوا فيها في الصِّفات: ابن حجر، والنووي، وجماعة آخرين، ليسوا فيها من أهل السنة، وهم من أهل السنة فيما سلموا فيه ولم يُحرِّفوه، هم وأمثالهم ممن غلط.","link":"https://binbaz.org.sa/fatwas/30034/ما-صحة-ما-نسب-للنووي-وابن-حجر-من-اخطاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 55.mp3","categories":["العالم والمتعلم"]},{"id":5136,"question":"يقول: وهل هذا العصر هو عصر الشح المطاع، والهوى المتبع، وإعجاب كل ذي رأي برأيه؟","title":"هل عصرُنا هو عصر الهوى والشح والعُجْب بالرأي؟","answer":"الجواب: لا، فيه هذا، لكن ما هو معناه أن هذا هو العصر الذي يُترك الإنسان، لا يؤمر ولا ينهى، لأن فيه شحًّا مطاعًا وفيه هوى متبعًا وفيه إعجابًا، لكن ليس العصر الذي يقف فيه الإنسان عن الدعوة وعليه بنفسه، لا، الحمد لله: الدعوة مسموعة ومفيدة ونافعة، وهناك من يستجيب لها. فعليه أن يدعو إلى الله ويحذر شحًّا مطاعًا وهوى متبعًا ويحذر دنياه المؤثرة، ولكن لا يقف عن الدعوة. إلا إذا جاء وقت يُمنع فيه من الدعوة، ويُعاقب عليها، ولا يُسمح له أن يدعو أحدًا من إخوانه، ولا يأمر بالمعروف ولا ينهى عن المنكر؛ حينئذ عليه بنفسه، وليس هذا وقتهم، الحمد لله، بل الأمر بالمعروف، والنهي عن المنكر، والدعاة إلى الله -ولله الحمد- مسموح لهم، يدعون إلى الله، كون بعض الناس قد يخطئ، قد يوقف لأجل خطأه في بعض المسائل، ما يمنع من الدعوة، فالإنسان يلزم الطريق ويستقيم على الطريق السوي ولا يُمنع. وإذا مُنع أحدٌ أو أوقف أحدٌ لأجل أنه حاد عن السبيل في بعض المسائل، أو أخطأ في بعض المسائل، حتى يتأدب وحتى يلتزم، هذا من حق ولاة الأمور أن ينظروا في هذه الأمور، وأن يوقفوا من لا يلتزم بالطريقة التي يجب اتباعها، وعليهم أن يحاسبوا من حاد عن الطريق حتى يستقيم، هذا من باب التعاون على البر والتقوى، وعلى الدولة أن تتقي الله في ذلك، وأن تتحرى الحق في ذلك، وعليها أن تأخذ رأي أهل العلم، وتستشير أهل العلم، عليها أن تقوم بما يلزم، ولا يُترك الحبل على الغارب، كل من جاء يتكلم، لا، قد يتكلم أناس يدعون إلى النار، وقد يتكلم أناس ينشرون الشر والفتن، يفرّقون بين الناس بغير حق. فعلى الدولة أن تراعي الأمور بالطريقة الإسلامية، بالطريقة المحمدية، بمشاورة أهل العلم، حتى يكون العلاج في محله، والدواء في محله، وإذا وقع خطأ أو غلط فلا يُستنكر؛ من يسلم من الغلط؟ لكن الداعية قد يغلط، والآمر والناهي قد يغلط، والدولة قد تغلط، والقاضي قد يغلط، والأمير قد يغلط، كل بني آدم خطاء، لكن المؤمن يتحرى، الدولة تتحرى الحق، والأمير يتحرى، والقاضي يتحرى، والداعي إلى الله يتحرى، والآمر بالمعروف والناهي عن المنكر يتحرى، وليس معصومًا، فإذا غلط يُنبّه على خطئه، ويُوجّه إلى الخير، فإذا عاند فإلى الدولة أن تعمل معه من العلاج أو التأديب أو السجن ما يمنع العناد، إذا عاند الحق وعاند الاستجابة، ومن أجاب وقبل الحق فالحمد لله.","link":"https://binbaz.org.sa/fatwas/30051/هل-عصرنا-هو-عصر-الهوى-والشح-والعجب-بالراي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 72.mp3","categories":["العالم والمتعلم"]},{"id":5280,"question":"أعظم الله مثوباتكم، هذه طالبة: تقول إن المعلمة علّقت أمانة في رقابنا تسألنا عنها يوم القيامة وهي أن لا نعطي طالبة أخرى مجهودنا الشخصي حتى تتعلم كل طالبة حل الواجب بنفسها، وفي اليوم الثاني: حضرت إليّ بعض الزميلات يردن مني أن أكتب لهن تعبيرًا عن الإسلام في مادة اللغة الإنجليزية، وهي الأمانة التي كلّفتنا بها المعلمة فوالله لقد أنساني الشيطان -لعنه الله- تلك الأمانة، وأخذت أكتب لهن، فهل عليّ ذنب، علمًا بأنني كنت ناسية، وإذا أخبرت المعلمة بذلك لم تسامحني، فهل لها حق في ذلك أم ماذا؟","title":"ما الذي يجوز للطلبة التعاون فيه في الدراسة؟","answer":"الجواب: التعاون بين الطالبات حق، التعاون بين الطالبات في الإفادة والبحث والمناقشة، أما شيء سِرِّي كالأسئلة التي يؤمرون بعدم بيان جوابها حتى تجتهد كل طالبة، لا تخبرها، خليها تجتهد وتبحث وتسأل وتجتهد. أما البحث العام بينهن في مسائل العلم ولتحصيل الفائدة فهذا حق، لكن الأسئلة السرية التي معروف عندكن أنها سرية فليس لكل واحدة أن تخبر الأخرى؛ لأنها إذا أخبرتها وتساهلت صارت الطالبة ما تبالي ولا تجتهد ولا تبحث، تقلد غيرها، فالواجب تركها تبحث وتجتهد. أما البحث العام فيما بينهن الدراسة العامة بينهن فكل واحدة تحرص على أن تُفهم أختها ما قد يخفى عليها، وأن تجتهد في نصيحتها، في توجيهها، تعليمها البحث المناسب: في الكتاب الفلاني، في الكتاب الفلاني، وما أشبه ذلك من التعاون. أما شيء سِرِّي الذي أنتم تعرفون أنه سِرِّي وأن المعلّمات أخبرتكن أنه سِرِّي؛ لا تخبريها، وكل واحدة تجتهد. السؤال: هل يترتب عليه إثم يا شيخ؟ الشيخ: ما دام ناسية ما يضرها، ربنا لا تؤاخذنا إن نسينا أو أخطأنا.[1]","link":"https://binbaz.org.sa/fatwas/30918/ما-الذي-يجوز-للطلبة-التعاون-فيه-في-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 000.mp3","categories":["العالم والمتعلم"]},{"id":5309,"question":"رجل حصل على شهادة علمية وقد كان غش في الامتحانات الخاصة بهذه الشهادة، كما أنه قدم شهادة مَرَضِية مزوّرة كي يدخل الامتحان في إحدى سنوات هذه الشهادة، وهو الآن يعمل في إحدى الوظائف بهذه الشهادة، فما حكم راتبه أحلال أم حرام؟ علمًا بأن العمل بهذه الوظيفة قد تم بعد اختبار شفوي ونجح فيه، ولكن من شروط الوظيفة التقدم بهذه الشهادة العلمية؟","title":"ما حكم الغش في الشهادة العلمية والعمل بها؟","answer":"الجواب: هذا مُنكر وغلط، ويجب عليه التوبة إلى الله، وأن لا يقدِّم شهادته من الغش أو المزوَّرة، هذا منكر، عليه التوبة إلى الله جل وعلا، وما دام قُبِل في الوظيفة وقام بواجبها واعتنى بها؛ فلا حرج عليه في ذلك، لا يفضح نفسه، ويستمر، ويقوم بالواجب، إن أدى واجب الوظيفة فالحمد لله، وعليه التوبة إلى الله والندم والعزم على عدم العودة.[1]","link":"https://binbaz.org.sa/fatwas/30965/ما-حكم-الغش-في-الشهادة-العلمية-والعمل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 029.mp3","categories":["العالم والمتعلم"]},{"id":5356,"question":"المقلد إذا قلَّد أحد العلماء في مسألةٍ، وغيره من العلماء يرى قولًا آخر، فقلَّده اتِّباعًا للأهون، هل هذا من الهوى؟","title":"هل من اتباع الهوى الأخذ بالأيْسَر من الفتاوى؟","answer":"الجواب: اتِّباع الهوى ما يجوز، عليه أن يتحرى مَن هو أتقى لله وأورع حتى يُقلده إذا كان عاجزًا. س: مثل بعض الجماعات تبيّن لهم طريق السنة وطريق المنهج لكنه مصمم على اتباع الجماعة؟ ج: الذي يتَّبع الهوى له نصيبه من وعيد الله، لا بدَّ أن يتَّقي الله ويتبع ما يراه أقرب إلى الحقِّ، إذا كان عامِّيًّا يشوف العلماء، والذي في نفسه أنه أقرب إلى الخير وأتقى لله يتبعه.[1]","link":"https://binbaz.org.sa/fatwas/31058/هل-من-اتباع-الهوى-الاخذ-بالايسر-من-الفتاوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 012.mp3","categories":["العالم والمتعلم"]},{"id":5476,"question":"مَن لم تبلغه الحُجَّة متصور في زماننا؟","title":"ما الذي تقوم به الحجة في بلوغ الإسلام للناس؟","answer":"الجواب: نعم متصور؛ قد يكون في بعض الجهات: في الشرق أو الغرب، ليس عنده إذاعة، ولا عنده دعاة، قد يكون الحكم مناطًا بالوجود، فإذا وجد مَن لم تبلغه الدَّعوة فهذا حكمه، يقول جلَّ وعلا: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15]، فإذا كان في جهةٍ من الجهات: في الغرب أو في الشرق أو في الشمال أو في الجنوب، ما سمع قرآنًا ولا سنةً، ولا سمع الدُّعاة إلى الله؛ فهو من جنس البهائم، ممن يُمتحن يوم القيامة.\nس: إذا كان في أطراف الدنيا وسمع بالإسلام سماعًا مُشوشًا أو مغلوطًا لم يتميز له؟ ج: ما تقوم عليه الحُجَّة حتى تبلغه الآيات أو النصوص من الرسول ﷺ، حتى يسمع ما يطمئن إليه، يكون مُطمئنًّا ويثبت عنده.[1]","link":"https://binbaz.org.sa/fatwas/31366/ما-الذي-تقوم-به-الحجة-في-بلوغ-الاسلام-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 001.mp3","categories":["العالم والمتعلم"]},{"id":5493,"question":"إطلاق لفظ \"حُجَّة الإسلام\" على عالم؟","title":"حكم إطلاق كلمة \"حُجَّة الإسلام\" على عالم؟","answer":"الجواب: يُطلق على ناسٍ كثيرين: \"حُجَّة الإسلام\"، كله تَجَوُّز وتسامح في العبارات، يعني أنه إذا تكلم أسوة، إذا استدل ونبَّه الناس فهو حُجَّة في الإسلام؛ لعلمه وفضله. والحُجَّة الحقيقية: القرآن والسنة وإجماع السلف، لكن يُعبرون عن بعض العلماء -لكثرة علمه- حجة الإسلام، يعني: أنه إذا تكلم حُجَّة، يُحتج به؛ لأنه يُقيم الأدلة.[1]","link":"https://binbaz.org.sa/fatwas/31400/حكم-اطلاق-كلمة-حجة-الاسلام-على-عالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 006.mp3","categories":["العالم والمتعلم"]},{"id":5494,"question":"إطلاق كلمة \"مولانا الشيخ\"؟","title":"ما حكم إطلاق كلمة \"مولانا الشيخ\"؟","answer":"الجواب: لا، ما ينبغي، يقول النبي ﷺ: لا يقول أحدكم: مولاي؛ فإنَّ مولاكم الله، إلا في حقِّ العبد المملوك، فيقول المملوك لسيده: مولاي، العبد المملوك لا بأس أن يقولها.[1]","link":"https://binbaz.org.sa/fatwas/31401/ما-حكم-اطلاق-كلمة-مولانا-الشيخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 007.mp3","categories":["العالم والمتعلم"]},{"id":5496,"question":"الاختلاف في مسألة العذر بالجهل من المسائل الخلافية؟","title":"هل مسألة العذر بالجهل من المسائل الخلافية؟","answer":"الجواب: مسألة عظيمة، والأصل فيها أنه لا يُعذر إنْ كان بين المسلمين، مَن بلغه القرآنُ والسنةُ لا يُعذر، الله جلَّ وعلا قال: هَذَا بَلَاغٌ لِلنَّاسِ [إبراهيم:52]، وقال: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنْذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19]، مَن بلغه القرآن والسنة غير معذورٍ، إنما أُتي من تساهله وعدم مُبالاته. س: لكن هل يُقال أنها مسألة خلافية؟ ج: لا، ما هي بخلافية، إلا في الدَّقائق التي قد تخفى، مثل قصة الذي قال لأهله: أحرقوني.[1]","link":"https://binbaz.org.sa/fatwas/31405/هل-مسالة-العذر-بالجهل-من-المساىل-الخلافية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 009.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":5497,"question":"وقوله: \"هو الله المحيي المميت\" الإنسان المتسمِّي: بمحيي الدين، هل فيه شيء؟","title":"ما حكم التسمِّي بمحيي الدين؟","answer":"الجواب: ترك اللَّقب أحسن، وإلا استعمله الكثير من الناس، مثل: النووي؛ لأنه دعا إلى الله، وأرشد الناس إلى الله، سموه: محيي الدين، لأجل هذا. س: الإمام النووي في مُؤلفاته يقول: هو يكره أن يُسمَّى: محيي الدين؟ ج: تركها أولى، ترك اللقب أفضل. س: أنا محيي الدين، أترك اسمي؟ ج: تسمَّ باسمٍ آخر أحسن: عبد الله، أو عبد الرحمن، هكذا.[1]","link":"https://binbaz.org.sa/fatwas/31406/ما-حكم-التسمي-بمحيي-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 010.mp3","categories":["العالم والمتعلم"]},{"id":5535,"question":"بعض الناس يقولون: التوحيد يُنفر الناس؟","title":"حكم مَن يعتقد أن في الدعوة للتوحيد تُنفيرًا للناس","answer":"الجواب: هذا غلط وجهل، الرسول ﷺ بدأ بالتوحيد، ما بدأ بالصلاة، ولا بدأ بالزكاة، ولا بدأ بالصدقات، بدأ بالتوحيد: قولوا: لا إله إلا الله تُفلحوا.[1]","link":"https://binbaz.org.sa/fatwas/31468/حكم-من-يعتقد-ان-في-الدعوة-للتوحيد-تنفيرا-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 050.mp3","categories":["مسائل متفرقة في العقيدة","العالم والمتعلم"]},{"id":5679,"question":"ما الفرق بين المذاهب الأربعة؟ وهل هناك مذهب أحسن من الثاني؟","title":"الفرق بين المذاهب الأربعة","answer":"الجواب: المذاهب الأربعة كلها تريد الحق، الشافعية والمالكية والحنبلية والحنفية كلها مذاهب في اتباع الحق، واتبعوا القرآن، والسنة -رضي الله عنهم ورحمهم- ولكن يعاب على بعض أتباعهم التعصب، وهكذا مذهب الظاهرية وهو مذهب خامس معروف، وهناك مذاهب أخرى كانت موجودة: الجريرية، والليثية، والثورية أتباع سفيان الثوري، وأتباع الليث بن سعد، وأتباع ابن جرير، والراهوية كذلك أتباع إسحاق بن راهويه، ولكنها انقرضت. والمهم هو اتباع الحق، فهؤلاء المذاهب الأربعة، والظاهرية ومن قبلهم من المذاهب التي انقرضت كلهم أهدافهم اتباع الحق، فقد يختلفوا في مسألة، أو مسألتين، أو ثلاث، فيشتهر بها العالم، فيكون له أصحاب، وأتباع، فيشتهر ذلك المذهب بهذا الشيء الذي انفرد به هذا العالم في مسألة، أو مسألتين، أو ثلاث، أو أكثر، وأخيها غير رأي أخيه، بسبب أدلة قد يخفى على هذا، وظهر في هذا، وهي مسائل فرعية ليس لها في الغالب تعلق بالأصول. لكن يعاب على الرجل التعصب للباطل، وعدم الاقتناع بالحق من أتباعهم؛ فهذا هو الذي يعاب عليه، وإلا فالمذاهب معروفة، كلها تريد الحق، وتتبع الكتاب والسنة، وتهدف إلى اتباع الكتاب والسنة، وإلى الثبات على ما جاء به الرسول، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/979/الفرق-بين-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_07.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":5683,"question":"قل من يوجه الشباب حتى من العلماء! عند ذلك يقع الشباب وراء ما يسمعون، ويرون من الأشياء التافهة، فما هو توجيهكم؟","title":"الحث على مجالسة أهل العلم","answer":"الجواب: على كل حال موجود من أهل العلم، وموجود من العلماء -بحمد الله- موجودون، وإن كانوا قليلًا، بالنسبة إلى غالب البلاد قليلين، ولكن -على كل حال- طالب العلم إذا سعى، وطلب أهل العلم وجدهم.  من المصيبة عدم الطلب، وعدم الاتصال بهم، والانزواء بنفسه، والاستغناء بنفسه؛ فقد يغلط كثيرًا، ويخفى عليه كثيرًا، بل يجب عليه أن يسعى بطلب العلم، وأن يعنى بالقرآن، وبطلب العلم، وأن يسأل أهل العلم عما يشكل عليه، ولا يحتقر، ولا يظن بهم السوء، بل عليه أن يحسن الظن بعلماء زمانه الذين لم يظهروا له منهم ما يخالف شرع الله، ولم يخالف له منهم ما يدل على باطلهم، وبعدهم عن الحق. فيتحرى أهل العلم، ويسألهم عما أشكل عليه، ولا يساء بهم الظن؛ هذا من أسباب توفيق الله له، ومن أسباب هداية الله له، وإذا غلط في مسألة قد لا يغلط في مسألة أخرى، قد يغلط في مسألة واحدة، ولكن يصيب في مسائل إلا إذا أشكل عليه، وقال لعله غلط، يسأل العالم الثاني، والعالم الثالث، والعالم الرابع. هكذا كان السلف يسألون حتى يطمئنوا، يسألون العلماء، لا لقصد الامتحان، والتعنت لا، ولكن للطمأنينة حتى يجد منهم ما يطابق ما عنده من الدليل، وما عرف من الدليل الذي أشكل عليه؛ فإذا وجد ما يدل على صحة ما ظهر له من آية، أو حديث استقام على ذلك، وصبر على ذلك، ولا ييأس، ولا يسيئ الظن، ويعمل ما يستطيع من الاتصال بأهل العلم والمطالعة، والمذاكرة مع إخوانه، وزملائه، حتى الزملاء قد يفيدوه لا يسيئ بهم الظن، ولا يقول: إنه أعلم منهم، بل يذاكر مع زملائه، ويبحث معهم، ويناقش من دون غلط؛ حتى يزول الإشكال، وتزول الشبهة. السؤال: العالم عند الناس عندهم عرف أن الذي تخرج من الكلية هو الشيخ، أما إذا تخرج من الثانوية، أو المتوسط فما هو بشيخ؟ الجواب: على كل حال كلما زاد علمه اقترب من الصواب، المتخرج من الجامعة أقرب إلى الصواب من الثانوي، وهكذا، لكن لا يحتقر أهل الثانوي إن شاء... زملاءه ولو من الثانوي، لا يحتقر.","link":"https://binbaz.org.sa/fatwas/974/الحث-على-مجالسة-اهل-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_03.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":5796,"question":"ما هو واجب الشباب المسلم في هذا الزمان بتجنب الوقوع في الإفراط والتفريط؟ وبماذا تنصحون الشباب أن يقرأ من الكتب لتحقيق ذلك؟","title":"نصيحة للشباب لتجنب الإفراط والتفريط","answer":"الجواب: \n\nهذا لا شك موضوع مهم، وينبغي للشباب أولًا: العناية بطلب العلم، والتفرغ لطلب العلم، والحرص على الفهم الصحيح؛ لأن كثيرًا من الناس قد يفهم خلاف الحق بسبب عدم العناية بالفهم، وهذا يسبب مشاكل كثيرة، كما قال الشاعر:\n\n\n\t\n\t\t\n\t\t\tوكم من عائب قولًا صحيحًا\n\t\t\tوآفته من الفهم السقيم\n\t\t\n\t\n\n\nفأنا أنصح الطلاب جميعًا أن يعنوا بطلب العلم، طلب العلم الشرعي، وأن يجتهدوا في فهمه فهم الأحكام الإسلامية، فهم قول الله، وقول رسوله فهمًا جيدًا، وألا يكتفوا بأول بادرة، بل يدرسوا الشيء مرة بعد مرة، ويتذاكروا فيه مع الزملاء، ومع الأساتذة الطيبين حتى يستقر الفهم الصحيح في قلب الطالب، وحتى يكون على بينة من كتاب الله، وسنة رسوله -عليه الصلاة والسلام- وبكل ما يدرسه.\n\nلكن أهم شيء النصوص، أهم شيء ما يتعلق من القرآن، وما يتعلق من السنة، فهذا أهم شيء أن يعنى به، ويفهم الفهم الصحيح، ويطبقه بالعمل، وألا يتساهل في ذلك، فربما زلت قدمه بسبب الفهم الرديء بسبب غلطة في كتاب الله، أو سنة رسوله، عليه الصلاة والسلام.\n\nفالواجب: أن يعنى بالفهم الصحيح، وأن يتشاور مع زملائه في المعنى، ويتدارسون ذلك، ويسأل أهل العلم، ثم للعلوم الأخرى التي يستطيع أن يتعلمها، حتى ينفع أمته، وينفع المسلمين، لا بأس، إذا تيسر له ذلك من طب، أو غيره مما ينفع المسلمين، لكن أهم شيء العلوم الإسلامية البحتة، التي بها يعرف الله، وبها يعبد، وبها تعرف أحكامه  وبها يعرف ما يدعو إليه، وما ينهى عنه، حتى يعمل بذلك، وحتى يبلغه الناس، فما حصل بعد هذا من علوم أخرى فهو خير إلى خير.\n\nوكذلك أوصيه بالعناية بالقرآن، فكتاب الله أهم شيء، أهم شيء القرآن العظيم، يعتني به لحفظه، ويكثر من تلاوته، وتدبر معانيه، وإذا لم يحفظه؛ فليكثر من تلاوته، فإن الإكثار من التلاوة تجعل الإنسان يذكره كثيرًا، ويكون قريبًا من الحافظ، فأنا أوصي بالإكثار من تلاوة كتاب الله، بتدبر، وتعقل في الأوقات المناسبة، كأول النهار، وفي أثناء الليل، ونحو ذلك، وآخر الليل حتى يحصل له حفظ القرآن، أو ما تيسر منه، مع العناية بالمعنى، ومطالعته في التفسير في ذلك كابن كثير، والبغوي، وغيرهم من أهل التفسير، حتى تكون معلوماته جيدة، وحتى يكون على بينة من كتاب الله .\n\nثم السنة، سنة رسول الله ﷺ أوصيه بأن يحفظ منها ما تيسر، مثل: بلوغ المرام كتاب جيد محرر مفيد، كذلك عمدة الأحكام للشيخ عبدالغني المقدسي من الصحيحين كتاب جيد أيضًا، والخمسين النووية، والرحبية يحفظها، ويعتني بها، وإذا تيسر له مزيد علم، وارتفعت همته، ومعلوماته فيعتني بالصحيحين، وينظر في الصحيحين، وكتب السنن، وموطأ مالك، ومسند أحمد، هذا خير إلى خير بعد ذلك، بعدما ينهي دراسته، وبعدما تستقضى معلوماته يرتفع إلى هذه الكتب، ويعتني بها، كالصحيحين، والسنن الأربعة، ومسند أحمد، وموطأ مالك، ونحوها من الكتب العظيمة التي هي ثروة عظمى، وفيها تفسير كتاب الله، وفيها العون على فهم كلام الله، وكلام رسوله، عليه الصلاة والسلام.\n\nثم يعنى بكتب اللغة في مطالعة كتب التفسير، ومطالعة كتب الحديث حتى يستعين بها على فهم القرآن، والسنة، وعلى ترجيح الراجح، وتزييف الزائف.\n\nومن الكتب المفيدة النافعة: منتقى الأخبار أيضًا، لابن تيمية، فإنه كتاب عظيم، جمع فيه خيرًا كثيرًا، وجامع الأصول لابن الأثير أيضًا، كذلك زاد المعاد لابن القيم، كتاب جيد، زاد المعاد في هدي خير العباد كتاب عظيم، وإعلام الموقعين لابن القيم أيضًا كتاب عظيم، وإغاثة اللهفان لابن القيم كتاب عظيم، فأنا أنصح بمطالعة هذه الكتب، والعناية بها، فهي كتب مفيدة.\n\nالسؤال: فقه السنة؟\n\nالجواب: فقه السنة لا بأس به، للشيخ سيد سابق، لا بأس به، وفيه بعض الأغلاط، وطالب العلم إذا تأمله يستفيد، ويعرف الخطأ.","link":"https://binbaz.org.sa/fatwas/1125/نصيحة-للشباب-لتجنب-الافراط-والتفريط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_131.mp3","categories":["نصائح وتوجيهات","العالم والمتعلم"]},{"id":5992,"question":"أنا أعتقد أن المسلمين يريدون الجهاد، ويريدون العلم، ويكرهون الجهل، ويكرهون الوهن، لكن العلماء فيهم تقصير في عدم قول كلمة الحق بكل صراحة، وبكل صدق، ويفتقدون القيادة الصادقة من العلماء، فما رأيكم؟","title":"نصيحة موجهة للعلماء وطلبة العلم للقيام بواجبهم","answer":"الجواب:  هذا قد وقع كثير منه، لا شك أن هذا وقع، كثير من العلماء الآن ليس عندهم العناية التامة بتعليم الناس، وتوجيه الناس إلى الخير. وكما وقع في اليهود، والنصارى ما وقع من انحراف العلماء، وقع في هذه الأمة ما وقع أيضًا من عهد طويل، من انحراف كثير من العلماء، والرضا بالعاجلة، وعدم القيام بالواجب من التعليم، والتوجيه، ولكن هناك بقايا -بحمد الله- يعلمون، ويرشدون.  والعلماء هم ورثة الأنبياء، وهم القادة في كل زمان، ولكننا اليوم في غربة الإسلام، وفي قلة من العلماء، كما قال النبي -عليه الصلاة والسلام-: لا تقوم الساعة، حتى يظهر الجهل، ويقل العلم، ويفشو الزنا، ويشرب الخمر إلى آخره.  وقد وقع هذا الأمر من أزمان متطاولة، فقد قل العلماء، وكثر الجهل، وغلب على أكثر النفوس، تجد البلدان الكثيرة، والقبائل الكثيرة خالية من العلماء، والمتفقهين في دين الله. والعلماء الذين يصح أن يقال علماء: هم الذين تفقهوا في دين الله، وأخذوا علمهم عن كتاب الله، وعن سنة رسوله -عليه الصلاة والسلام- وليس العالم المقلد لفلان، أو فلان الذي يعرف مختصرًا من المختصرات، أو كتابًا من الكتب، فيقلد أربابها، ولا يدري عن كتاب الله، ولا عن سنة رسوله، هذا لا يعد من العلماء بإجماع أهل العلم، وإنما  العالم هو الذي يأخذ علمه عن كتاب الله، وعن سنة رسوله -عليه الصلاة والسلام- وهذا اليوم قليل في الأمصار، والدول، هذا الصنف قليلون جدًا.  وقد ظهر -بحمد الله- حركات في مواطن كثيرة، وبلدان كثيرة إسلامية، تنشد الحق، وتطلب الدليل، وتعنى بالكتاب والسنة، وهذا يبشر بالخير؛ فنسأل الله أن ينمي هذه الحركات الطيبة، وأن يزيدها خيرًا، وأن يبارك في العلماء الموجودين، وأن يرزقهم البصيرة، وأن يعينهم على أداء الواجب، وعلى نشر الحق. وينبغي أن يعلم أنه وإن كان قد وقع التقصير من الكثير من العلماء، وهكذا من الناس، ومن الشعوب، والطلبة، التقصير كثير، فقل من يأتي إلى العالم، ويسأله، ويشجعه على أن يدرس، أو ينشر العالم، فهذا قد يعرض، وهذا قد يعرض.  فالواجب التكاتف، فإن العالم إذا سئل، واتصل به السائلون من طلبة العلم، ومن غيرهم، كان هذا مما يعينه على العناية بالعلم، ومراجعة الآيات، والأحاديث، والاستعداد لإجابة السائلين، ولإظهار العلم، ونشره بين الناس، فإذا غفل غفل هذا، وأقبل هذا على دنياه، وهذا على دنياه، وقل السائلون. فالعالم أيضًا قد يغفل، وقد يعرض، وقد ينشغل بشيء آخر من أمور دنياه، فلا ينبغي للجميع الغفلة عن هذا الأمر، بل يجب على العالم أن يعنى بالقرآن، والحديث، وأن يأخذ علمه منهما، وأن يعنى بذلك، وأن يبذل الكثير من وقته، أو الأغلب من وقته في هذا السبيل العظيم، حتى يكن علمه علمًا شرعيًا نافعًا، ينفع الله به الناس. وعلى المسلمين أن يسألوا، ويتبصروا في دينهم، ويتفقهوا قال الله : فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [النحل:43] وقال النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة فإذا جاء طالب العلم إلى عالم، ويسأل عالمًا آخر؛ أكد عليه، ويسأل من فوقه، أو جاء العامي يسأل العالم، أو طالب العلم، يريد العلم، يريد الفائدة؛ فله الخير العظيم، وله الفضل الكبير، وقد سعى في طريق إلى الجنة.  كذلك إذا حضر حلقات العلم ليستفيد في شرع الله، وقصده، ولو من بعيد، ولو بأسفار، ولو سافر المسافرات؛ ليحضر حلقات العلم، ويسأل العالم؛ فهذا أيضًا من المهمات، ومن الواجبات عند الحاجة. وكذلك طلبة العلم الذين في المدارس، والمعاهد، والكليات يجب عليهم أن يعنوا بالعلم النافع الحقيقي، الذي يؤخذ من كتاب الله، ومن رسوله -عليه الصلاة والسلامج حتى يكون علمهم علمًا حقيقيًا نافعًا؛ موصلًا إلى الآخرة، وإلى الجنة، والكرامة.","link":"https://binbaz.org.sa/fatwas/1397/نصيحة-موجهة-للعلماء-وطلبة-العلم-للقيام-بواجبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_352.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6010,"question":"ما هي كيفية التفقه في الدين؟ وهل يكفي قراءة المؤلفات، واستماع الإذاعات الدينية، أو لا بد من الالتحاق بالمعاهد، أجيبونا، جزاكم الله خيرًا؟","title":"أسباب وطرق التفقه في دين الله","answer":"الجواب:  التفقه في الدين يكون بأنواع، وأسباب، وطرق، التفقه في الدين هو التفقه في كتاب الله، وفي سنة رسوله -عليه الصلاة والسلام- حتى تعرف ما أوجب الله عليك، وما حرم عليك، وما أباح لك، فتكون على بصيرة في دينك من كتاب الله، وسنة رسوله، سواء كان في بيتك على شيخ من الشيوخ العارفين، أو في بيته هو، أو في المسجد، أو في مدرسة، أو في جبل، أو تحت شجرة في أي مكان. التفقه في دين الله المقصود به هو التفقه في الكتاب، والسنة في أي مكان، وعلى أي عالم ممن  عرف الحق، وهو من أهل العلم، والدين، والإيمان.","link":"https://binbaz.org.sa/fatwas/1394/اسباب-وطرق-التفقه-في-دين-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_350.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6107,"question":"كثيرًا ما يركز المشايخ في دعواهم إلى الله على جانب العقيدة، ومعلوم أن ذلك له أهميته الكبرى، ومكانته العظيمة، إذ أن تأسيس العقيدة هو الركيزة الكبرى للإسلام، ولكن نرجو توجيه العناية بالأخلاق الاجتماعية، ومحاربة الرذائل في بناء العقيدة، فلماذا نرى غالبًا العلماء يهملون هذا كثيرًا؟","title":"أهمية العقيدة والدعوة إليها","answer":"الجواب: على كل حال، المعروف عند العلماء أنهم يعتنون بهذا وهذا، العقيدة مثل ما ذكرت أيها السائل هي: الركيزة، وهي الأساس، ولهذا أغلب أهل العلم في بلدان العالم لا يهتمون بالعقيدة ضد ما قلت، فيتكلمون في الأخلاق، وفي أشياء أخرى في الصلاة، في الزكاة في الأوقات، في الصلاة، في أشياء أخرى، والعقيدة مهملة حتى عبدت بينهم القبور من دون الله، وحتى وقع الشرك بالله بينهم، وهم لا يشعرون. وربما وقع ذات العالم في الشرك بالله؛ لأنه عاش على الشرك مع أبيه، ومع عمه، ومع شيخه، فعاشوا على الشرك لأسباب عدم خوضهم في العقيدة، وعدم عنايتهم بالعقيدة، تجده يدرس، ويعبد غير الله، تجده في المسجد يدرس، ثم يدعو البدوي، ويدعو الحسين، ويدعو عبدالقادر؛ لأنه عاش على هذا هو وأبوه، وجده وأصحابه، هذه من نتائج إهمال العقيدة، وعدم العناية بالعقيدة.  وتجده جهبذًا بصيرًا بأحكام الصلاة، في أحكام الأوقات، في أحكام الإجارة، في الزكاة، في وصايا، في أشياء أخرى؛ لأنه درسها، واعتنى بها، أما العقيدة فلا يعتني بها ولا يعرف ... وإن كان جيدًا فهو يعتني بعقيدة المتكلمين، وما يخوض فيه المتكلمون من جهة الكلام، والعقائد التي ساقها أهل الكلام من الأشعرية، والجهمية، والمعتزلة، وغفل عن العقيدة السلفية التي درج عليها أصحاب الرسول ﷺ ودرج عليها سلفنا الصالح في إثبات الأسماء والصفات، ومن الإيمان بالله، وتوحيد العبادة، وعدم الشرك بالله  والعناية بهذا الأمر. فالحاصل أنه يجب وجوبًا عظيمًا وجوبًا مؤكدًا أن يعتنى بالعقيدة، وليعتني العلماء في إيضاحها للناس من عامة، وخاصة، وأن تكون الدروس غالبًا تعتني بها مع العناية بالأخلاق، والأحكام الأخرى، لا يهمل هذا، ولا هذا، ولكن تكون العناية الكبرى بالعقيدة. وكان الشيخ محمد -رحمه الله- في رسائله يقول لبعض خصومه الذين يكتب إليهم، ويخاصمون في العقيدة، يقول: إني أريد منكم أن تدرسوا العقيدة كما تدرسوا كتاب الأوقاف، يعني كما أنكم تعتنوا بالأوقاف -أوقاف الناس- فأرجو منكم أن تدرسوا العقيدة باب حكم المرتد مثل عنايتكم بكتاب الأوقاف.  فلو أنهم درسوا باب حكم المرتد في كتب الفقه التي ألفها العلماء في كل مذهب، لو درسوا باب حكم المرتد، واعتنوا به لظهر لهم ما هم فيه من الباطل، والشرك، ولكنهم يغفلون عن ذاك الباب؛ لأن السؤال ما يجدون السؤال فيه، ولا عناية به، وتجدهم مشغولين بالأوقاف، وأولياء الأوقاف، كيف ينفذ الوقف؟ كيف تصرف غلة الوقف؟ كيف يفعل بالإجارة؟ كيف يؤجر؟ كيف يفعل بمال اليتيم؟ فاشتغلوا بهذه، وضيعوا العقيدة لعدم عنايتهم بها، ولعدم سؤال العامة عنها؛ فلهذا جمدت، وغفل عنها، وصار الناس في غاية من الشرك بالله، وعبادة القبور، والأولياء، بسبب هذه الغفلة تجد البدوي، وغير البدوي، وفلانًا، وفلانًا، في مصر، والشام، والعراق، وفي كل مكان تجده معبودًا مع الله، والعلماء المعممون يدعون إلى ذلك، ويفعلون ذلك مع العامة.  قد لبسوا هذا الأمر، وضيعوه لعدم عنايتهم به، حتى وقعت العامة في الشرك بأسبابهم، وصاروا يعكفون على القبور، ويدعونها مع الله، وبها يستغيثون، ويسألونها قضاء الحاجات، وشفاء المرض، والنصر على الأعداء، هكذا وقع بين الناس، ومن استنكر هذا، وسافر إلى بلاد أخرى؛ فليمر على قبر البدوي، والحسين، وفلان، وفلان، يجد الناس حوله عاكفين، هذا يقول: يا سيدي فلان المدد، اشف مريضي، انصرني على عدوي، افعل بي، افعل بي، حتى آل بهم الأمر، حتى يسألوهم الأولاد، يسألونهم أن تحمل نساءهم أولادًا، وأن يعطوا كذا، ويعطوا كذا، نسأل الله العافية، نسوا الله فنسيهم، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1521/اهمية-العقيدة-والدعوة-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_451.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6404,"question":"مما يشاع بين طلاب العلم، وخاصة في الكليات، والمؤسسات العلمية قولهم: العلم ذهب مع أهله، وأنه لا يوجد أحد يتعلم في المؤسسات العلمية إلا من أجل الشهادات، والدنيا، فبماذا يرد عليهم؟ وما الحكم إذا اجتمع قصد الدنيا، والشهادة مع نية طلب العلم؛ لنفع نفسه، ومجتمعه؟","title":"ما الرد على أنه لا يوجد أحد يتعلم إلا من أجل الشهادات؟","answer":"الجواب: هذا الكلام ليس بصحيح، ولا ينبغي أن يقال هذا الكلام وأمثاله، ومن قال: هلك الناس فهو أهلكهم. ولكن ينبغي التشجيع والتحريض على طلب العلم والتفرغ لذلك، والصبر والمصابرة على ذلك، وحسن الظن بطلبة العلم إلا من علم منه خلاف ذلك. ولما حضرت المنية معاذا - فيما يذكر - أوصى من حوله بطلب العلم، وقال: «إن العلم والإيمان مكانهما من أرادهما وجدهما» يعني: مكانها في كتاب الله العظيم وسنة رسوله ﷺ الأمين، وإنما العالم يقبض بعلمه، فالعلم يقبض بموت العلماء، لكن لا تزال بحمد الله طائفة على الحق منصورة؛ ولهذا قال عليه الصلاة والسلام: إن الله لا يقبض العلم انتزاعا ينتزعه من العباد، ولكن يقبض العلم بقبض العلماء، حتى إذا لم يبق عالم اتخذ الناس رؤوسا جهالا فسئلوا فأفتوا بغير علم فضلوا وأضلوا رواه البخاري في صحيحه.\nوهذا هو الذي يخاف منه، يخاف أن يتقدم للإفتاء والتعليم الجهلة فيَضلون ويُضلون، وهذا الكلام الذي يقال: ذهب العلم ولم يبق إلا كذا وكذا، يخشى منه التثبيط لبعض الناس، وإن كان الحازم والبصير لا يثبطه ذلك، بل يدفعه إلى طلب العلم حتى يسد الثغرة. والفاهم المخلص، والصادق البصير بمثل هذا الكلام لا يثبطه ذلك، بل يتقدم ويجتهد، ويثابر ويتعلم، ويسارع لشدة الحاجة للعلم، وليسد الثغرة التي زعمها هؤلاء القائلون: إنه لم يبق أحد.\nوالحاصل أنه وإن نقص العلم وذهب أكثر أهله، فإنه ولله الحمد لا تزال طائفة على الحق منصورة كما قال النبي ﷺ: لا تزال طائفة من أمتي على الحق منصورة لا يضرهم من خالفهم ولا من خذلهم حتى يأتي أمر الله.\nفعلينا أن نجتهد في طلب العلم، وأن نشجّع عليه، وأن نحرص على سد الثغرة، والقيام بالواجب في مصرنا وغيره، عملا بالأدلة الشرعية المرغبة في ذلك، وحرصا على نفع المسلمين وتعليمهم، كما ينبغي أن نشجع على الإخلاص والصدق في طلب العلم.\nمن أراد الشهادة ليتقوى بها على تبليغ العلم والدعوة إلى الخير فقد أحسن في ذلك، وإن أراد المال ليتقوى به فلا بأس أن يدرس ليتعلم وينال الشهادة التي يستعين بها على نشر العلم، وأن يقبل الناس منه هذا العلم، وأن يأخذ المال الذي يعينه على ذلك، فإنه لولا الله سبحانه ثم المال لم يستطع الكثير من الناس التعلم وتبليغ الدعوة. فالمال يساعد المسلم على طلب العلم وعلى قضاء حاجته وعلى تبليغه للناس، ولما ولي عمر  أعمالا أعطاه رسول الله ﷺ مالا، قال: أعطه من هو أفقر مني، فقال النبي ﷺ: خذ هذا المال فتموله أو تصدق به، وما جاءك من هذا المال وأنت غير مشرف ولا سائل فخذه، وما لا فلا تتبعه نفسك خرجه مسلم في صحيحه.\nوأعطى النبي ﷺ المؤلفة قلوبهم ورغبهم حتى دخلوا في دين الله أفواجا، ولو كان حراما لم يعطهم، بل أعطاهم قبل الفتح وبعده. وفي يوم الفتح أعطى بعض الناس على مائة من الإبل، وكان يعطي عطاء من لا يخشى الفقر عليه الصلاة والسلام ترغيبا في الإسلام ودعوة إليه. وقد جعل الله سبحانه للمؤلفة قلوبهم حقا في الزكاة، وجعل في بيت المال حقا لهم ولغيرهم من المدرسين والقضاة وغيرهم من المسلمين. والله ولي التوفيق[1].","link":"https://binbaz.org.sa/fatwas/2035/ما-الرد-على-انه-لا-يوجد-احد-يتعلم-الا-من-اجل-الشهادات","audio":"undefined","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6476,"question":"صورة من جريدة من مجلات صفحة 16 وتحت موضوع \"حدث في كلية الشريعة: ملخص ما في الأمر: أن أحد أساتذة كلية الشريعة، وهو الدكتور حسن نيتو، حيث يقول: إن من خالف إجماع الأمة الإسلامية؛ فهو كافر، وأن ابن تيمية أحد علماء الشام قد خالف إجماع الأمة، ولولا أنه لم يمت في السجن؛ لأقيم عليه حد الردة، إذاً نرجو من سماحتكم التعليق على هذا الأمر، أو الرد على من يقول بمثل هذا القول، وذلك في وسائل الإعلام الكويتية، وجزاكم الله خير الجزاء؟","title":"الرد على من قال إن ابن تيمية خالف الإجماع","answer":"الجواب: هذا ما سمعناه، ومن قال هذا: فهو أجهل من حمار أهله، من قال هذا الكلام، سواء حسن، أو غير حسن الدكتور، من قال مثل هذا الكلام؛ فهو أضل من بعير أهله، وبقرة أهله، لا شك أنه قال بغير علم، وقال قولًا فاسدًا ضالًا. فإن ابن تيمية لم يخالف إجماع الأمة، وإنما بين ما يجب على الأمة أن يأخذوا به، وحرر المسائل التي اختلف فيها الناس، وأوضح أحد القولين الراجح من القولين، أو من الأقوال بالدلائل، وليس ممن يخالف إجماع الأمة، بل هو ممن يدعو إلى الخير، وينهى عن الشر، رحمه الله.  ولكنه قد خالف في مسائل جمهور الأمة، والعبرة بالدليل، ولو مع القليل، فإذا كان الأكثرون على قول، والقليل من العلماء على قول، والدليل مع القليل، فالحق مع القليل، الحق مع من معه الدليل، ولو كانوا هم القليل من العلماء، فليس الحق مع الكثيرين، الحق مع من معه الدليل، من قام معه الدليل من كتاب، أو سنة، فهو صاحب الحق، وإن كان القائل بذلك ليس هم الأكثرين، بل هم الأقل.  السؤال:.. في الكويت..؟ الجواب: إن شاء الله نبحث الموضوع، وننظر نبحث الموضوع.  السؤال: يعني الموضوع في كلية الشريعة في الكويت، ليس في المملكة، الحمد لله. الجواب: على كل حال الواجب علاج الموضوع، سواء هنا، أو هناك.","link":"https://binbaz.org.sa/fatwas/2220/الرد-على-من-قال-ان-ابن-تيمية-خالف-الاجماع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_840.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6501,"question":"ذهبت من بلدي إلى طلب العلم، ولكن والدي ليسوا موافقين ما أعمل، وما هي التوبة؟الشيخ: أعد ذهبت من بلدي إلى طلب العلم، ولكن والدي غير موافقين، فهم طلبوا مني عدم الذهاب، وأنا ذهبت للإفادة؟","title":"حكم السفر لطلب العلم دون موافقة الوالدين","answer":"الجواب: طلب العلم واجب، فإذا كان في بلدك ما عنده علماء يطلبون العلم عليهم؛ فإن طلب العلم واجب، عليه أن يسافر في طلب العلم الشرعي، ولو لم يرض والداه بقدر الحاجة، يسافر بقدر الحاجة، ويتعلم ما لا يسعه جهله من دين، ثم يرجع إلى والديه، ويستسمحهما بالكلام الطيب، والأسلوب الحسن، أو يتوجهون جميعًا إلى بلد العلم إذا استطاع ذلك؛ لأن هذا أمر لازم، طلب العلم واجب.","link":"https://binbaz.org.sa/fatwas/2250/حكم-السفر-لطلب-العلم-دون-موافقة-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_871.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6523,"question":"ذهبت من بلدي إلى طلب العلم، ولكن والدي ليسوا موافقين ما أعمل، وما هي التوبة؟الشيخ: أعد ذهبت من بلدي إلى طلب العلم، ولكن والدي غير موافقين، فهم طلبوا مني عدم الذهاب، وأنا ذهبت للإفادة؟","title":"حكم السفر لطلب العلم دون موافقة الوالدين","answer":"الجواب: طلب العلم واجب، فإذا كان في بلدك ما عنده علماء يطلبون العلم عليهم؛ فإن طلب العلم واجب، عليه أن يسافر في طلب العلم الشرعي، ولو لم يرض والداه بقدر الحاجة، يسافر بقدر الحاجة، ويتعلم ما لا يسعه جهله من دين، ثم يرجع إلى والديه، ويستسمحهما بالكلام الطيب، والأسلوب الحسن، أو يتوجهون جميعًا إلى بلد العلم إذا استطاع ذلك؛ لأن هذا أمر لازم، طلب العلم واجب.","link":"https://binbaz.org.sa/fatwas/2250/حكم-السفر-لطلب-العلم-دون-موافقة-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_871.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6806,"question":"ما رأيكم في قراءة الكتب التي تعالج مشاكل هذا العصر، والفتن، والمذاهب المعاصرة، والمذاهب الهدامة، مثل القومية، والشيوعية، وغيرها، والكتب مثل كتب سيد قطب، والمودودي، ومحمد قطب، ويوسف العظمة، والندوي؟","title":"حكم القراءة في الكتب التي تعالج مشاكل العصر","answer":"الجواب: طيب، إذا قرأها ليستعين بما فيها من العلم إذا قرأ ما تيسر منها، لكن لا يغفل عن كتب السلف الصالح، يعتني بكتب السلف الصالح مثل: تفسير ابن جرير، والبغوي، وابن كثير، ممن ينقلون عن السلف الصالح، وينقلون علومهم، ويعتنون بها، ويستعين بالكتب الجديدة التي ألفها أهل العلم، يستعين بها حتى يستفيد من علمهم، ومن أساليبهم، ومن طرقهم في الدعوة إلى الله، يستفيد من ذلك، فيضم العلم الجديد إلى العلم القديم.","link":"https://binbaz.org.sa/fatwas/2688/حكم-القراءة-في-الكتب-التي-تعالج-مشاكل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1186.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6818,"question":"ما هي أنسب، وأنفع الطرق -في رأيكم- لتحصيل العلم في هذا الزمان؟ هل هو بالاتجاه إلى حلقات المشايخ في المساجد، أم بالاتجاه إلى الجامعات الإسلامية، أم إلى قراءة الكتب، وسؤال أهل العلم عما استشكل؟","title":"أنفع الطرق لتحصيل العلم","answer":"الجواب: هذا وهذا وهذا، يدرس في الجامعات، وفي المعاهد الدينية، ويعتني بالدراسة؛ حتى يستفيد شهادات تنفعه، وعلوم تنفعه، فالشهادات اليوم تنفع، ويستعان بها على تبليغ الدين، وعلى ما ينفع المسلمين. فيدرس في الجامعات، وفي المعاهد العلمية، ويأخذ الشهادات، ومع ذلك يحضر حلقات العلم حسب الإمكان، ويطالع الكتب الدينية، ويسأل أهل العلم، فيجمع بين هذا، وهذا، هكذا كان السلف، هكذا في الزمن الأول، وفي الزمن الأخير. أهل العلم هكذا يدرسون في المدارس، ويدرسون في حلقات العلم، ويدرسون، ويتذاكرون فيما بينهم، ويطالعون الكتب النافعة، ويقرؤون كتب التفسير، ويعتنون بالقرآن العظيم دراسة، وتدبرًا وتعقلًا، فيجمعون بين هذه الطرق كلها، هكذا طالب العلم لا يشغله شاغل، فهو مع الدارسين في المدارس، وفي الجامعات، وهو مع حلقات العلم، وهو مع المطالعة، والمذاكرة، والعناية بالقرآن، والسنة، والمذاكرة مع الزملاء، ومع العلماء، حتى يستفيد علمًا إلى علمه، وبصيرة إلى بصيرته.","link":"https://binbaz.org.sa/fatwas/2687/انفع-الطرق-لتحصيل-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1185.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6824,"question":"ما رأيكم في قراءة الكتب التي تعالج مشاكل هذا العصر، والفتن، والمذاهب المعاصرة، والمذاهب الهدامة، مثل القومية، والشيوعية، وغيرها، والكتب مثل كتب سيد قطب، والمودودي، ومحمد قطب، ويوسف العظمة، والندوي؟","title":"حكم القراءة في الكتب التي تعالج مشاكل العصر","answer":"الجواب: طيب، إذا قرأها ليستعين بما فيها من العلم إذا قرأ ما تيسر منها، لكن لا يغفل عن كتب السلف الصالح، يعتني بكتب السلف الصالح مثل: تفسير ابن جرير، والبغوي، وابن كثير، ممن ينقلون عن السلف الصالح، وينقلون علومهم، ويعتنون بها، ويستعين بالكتب الجديدة التي ألفها أهل العلم، يستعين بها حتى يستفيد من علمهم، ومن أساليبهم، ومن طرقهم في الدعوة إلى الله، يستفيد من ذلك، فيضم العلم الجديد إلى العلم القديم.","link":"https://binbaz.org.sa/fatwas/2688/حكم-القراءة-في-الكتب-التي-تعالج-مشاكل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1186.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6868,"question":"سمعنا من بعض مشايخنا الفضلاء القول بعدم صحة كتاب انتشر في أوساط الناس على مختلف طبقاته، وهو كتاب: الدعاء المستجاب لمؤلفه أحمد عبدالجواد، وتحذير من قراءته، ولكن المشاهدة في الواقع زيادة انتشاره، وكثرة وجوده في دار الكتب، والمكتبات؛ لذا نود منكم الإيضاح لنا عن أمر هذا الكتاب، وإذا كان الأمر كما سمعنا، فلماذا لا يعمل على جمعه من المكتبات، والأسواق، وتحذير الناس منه، والله يحفظكم ويرعاكم؟","title":"هل كتاب الدعاء المستجاب أحاديثه صحيحة؟","answer":"الجواب: هذا قد اطلعنا عليه، وهو كتاب ردئ، وفيه أحاديث موضوعة، وفيه بدع كثيرة، ومثل هذا صدر من دار الإفتاء لولاة الأمور بيان أنه كتاب غير صالح، وأن الواجب منعه، وعدم دخوله إلى البلاد، وعدم بيعه في المكتبات، هذا هو الذي صدر منا من دار الإفتاء لبيان ما فيه من الباطل، وأنه يجب أن يصادر، وأن يمنع من البلاد. وهناك كتب أخرى قد صدر من دار الإفتاء بيان أنها ضارة، وأن الواجب مصادرتها، وعدم دخولها البلاد، ومع هذا تدخل لأسباب كثيرة.  فنسأل الله أن يوفق ولاة الأمور للعناية بهذا الأمر، وأن يهاجموا هذه المكتبات مرة بعد مرة، وتارة بعد تارة؛ حتى يعرفوا ما فيها من الباطل، وحتى يصادروا ما فيها من الممنوعات، وحتى يعاقبوا المتساهلين، وسوف نفعل إن شاء الله ما نستطيع من المتابعة لهذا الأمر.","link":"https://binbaz.org.sa/fatwas/2756/هل-كتاب-الدعاء-المستجاب-احاديثه-صحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1248.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6871,"question":"أنا حريص على حضور دروس العلم، وأقيم مع زوجتي بمدينة الرياض، وعندما أخرج هي تخاف من الوحشة بالجلوس وحدها، وتريد أن تمنعني، فهل أجلس معها، أم أحضر لمجالسة العلم؟","title":"عدم حضور حلقات العلم بسبب الزوجة","answer":"الجواب: الأقرب -والله أعلم- أنك تجلس معها حتى لا تكون وحشة .. وتأتي في أوقات تحضر فيها العلم في الأوقات التي عندها من يؤنسها، أو تذهب إلى من يؤنسها؛ لأن بعض النساء ما تتحمل، ولأهلك عليك حق، فالأظهر، والأقرب أن تبقى عندها، وتؤنسها، ثم تلتمس وقتًا آخر يكون فيه السلامة من هذا الشيء، أو تحضر عندها في وقت الدرس الذي تريد من يؤنسها، ثم تذهب، ثم ترجع.  السؤال: لو أخذها إلى المسجد؟ الجواب: إذا تيسر أحسن، وأحسن؛ حتى يجمع بين الفائدتين.","link":"https://binbaz.org.sa/fatwas/2759/عدم-حضور-حلقات-العلم-بسبب-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1251.mp3","categories":["العالم والمتعلم","الحقوق الزوجية"]},{"id":6874,"question":"ما رأي سماحتكم في الكتب التالية : تحفة العروس، وكتب الشيخ الندوي، والمودودي، ومحمد قطب وكتاب لطائف المعارف، لابن رجب الحنبلي؟","title":"تقييم كتب الندوي والمودودي ومحمد قطب","answer":"الجواب: كل كتاب في الغالب -ما عدا كتاب ربنا - لا يخلو من شيء، لا يخلو من أشياء تنتقد عليه، وفيه بعض الأغلاط، وطالب العلم لا يأخذ الكتاب مطلقًا، بل يقبل منه ما وافق الحق، ويترك ما خالف الحق.","link":"https://binbaz.org.sa/fatwas/2755/تقييم-كتب-الندوي-والمودودي-ومحمد-قطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1247.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6903,"question":"أنا شاب في متقبل دراستي الجامعية، واتجهت لمعرفة آيات الله في البحار، والجبال، وفي الكواكب، وفي النفس البشرية، هل يجوز أن أتعلم هذا وأنا لم أتعلم بشكل جيد باقي العلوم الشرعية؟ هل اتجاهي هذا جائز، أم أتركه، أفيدونا أفادكم الله؟","title":"حكم الاقتصار على معرفة الآيات الكونية دون الإلمام بالعلوم الشرعية","answer":"الجواب: عليك بالعناية بالعلم الشرعي حتى تعرف أحكام الله، وما أراده الله منك، وما حرم الله عليك، وهذه الأمور تدرك بأدنى عمل، وأنت تدرس تنظر في آيات الله، وأنت تدرس في ليلك ونهارك، آيات الله بارزة: النجوم، الشمس والقمر، والسماء، والأرض كلها بارزة تنظرها، وتراها، وأنت في دراستك وَفِي الْأَرْضِ آيَاتٌ لِلْمُوقِنِينَ [الذاريات:20]، إِنَّ فِي اخْتِلَافِ اللَّيْلِ وَالنَّهَارِ وَمَا خَلَقَ اللَّهُ فِي السَّمَاوَاتِ وَالْأَرْضِ لَآيَاتٍ لِقَوْمٍ يَتَّقُونَ [يونس:6]. المقصود: أن الآيات واضحة، وبينة لمن أرادها، ولا تمنعك من الدراسة التي أنت بها، أهم دراسة العلوم الشرعية، والإقبال عليها، والحرص عليها، ومع ذلك أنت تفكر في هذه الأمور التي تنفعك، وتزيدك إيمانًا بالله، وأنه الحق العظيم، وأنه الخلاق العليم، وأنه المستحق لأن يعبد وحده ويطاع أمره، وينتهى عن نهيه .","link":"https://binbaz.org.sa/fatwas/2832/حكم-الاقتصار-على-معرفة-الايات-الكونية-دون-الالمام-بالعلوم-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1280.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6914,"question":"نحيطكم علمًا بأنه قد ظهر كتاب في معرض الكتاب الواقع في وحدة القادسية التابعة للإسكان الجامعي، في جامعة الإمام، وهذا الكتاب اسمه: \"الغيث المسجم في شرح لامية العجم\" لابن إيدك الصفدي، وهذا الكتاب يذكر فيه مؤلفه أبياتًا، وحكايات في أخبار اللواط، ومتعاطيه، وفي هذا الكتاب كثير من المفاسد، ويجترئ على دعوة صريحة إلى اللواط، وترغيب الناس فيه، وأنت تعلم أيها الشيخ أن هذا قد توعد الله فيه قومًا جعل أعلى ديارهم أسفلها، وإن كان هذا حاصل، فما معنى وجود هذا الكتاب الداعي للواط في بلد التوحيد، نرجو من سماحتكم، وهذا الكتاب مكون من جزئين، والذي ذكرناه عنه موجود في أول الجزء الثاني، وأوسطه تحت عنوان الدبيب، وتحت عنوان حكاية العمياء؟","title":"التحذير من كتاب (الغيث المسجم في شرح لامية العجم)","answer":"الجواب:  نسأل الله العافية، قاتل الله من فعل الشر، أو من دعا إليه، إن شاء الله يعالج الموضوع، وإن شاء الله يمنع، نسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/2839/التحذير-من-كتاب-الغيث-المسجم-في-شرح-لامية-العجم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1287.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6963,"question":"نرى بعضًا من المجالس يحضرها بعض من إخواننا طلاب العلم، لكنهم لا ينتهزون فرصة مجلسهم، ويذكرونهم بالله، بل ينتهزون معهم في خوضهم فيما لا فائدة فيه، فما هي نصيحة سماحتكم لهؤلاء ولأمثالهم؟","title":"توجيه طلبة العلم بعمارة المجالس بالذكر والعلم","answer":"الجواب: نصيحتي لكل طالب علم أن ينتهز الفرص، فإذا كان في أي مجلس يأمرهم بذكر الله، بقراءة القرآن، بقراءة الحديث الشريف؛ حتى ينتفع المجلس، حتى يكون وجوده نافعًا للمجلس، لا يشاركهم في الغيبة، والنميمة، والسواليف التي لا فائدة فيها، بل متى وجد طالب العلم يعمر المجلس إما بقراءة القرآن، والكلام على ما تيسر من الآيات، وإلا بقراءة الأحاديث، مثل رياض الصالحين، وغيره؛ حتى تكون الفائدة للجميع، وحتى يكون المجلس نافعًا من مجالس الآخرة.  وإذا كان  ولا بد من حديث؛ فليكن حديثًا قليلًا فيما أباح الله، لا في الغيبة، والنميمة، ونحوها، بل في الحاجات العادية التي ليس فيها محذور، حتى يعطيهم بعض الفرصة لأحاديثهم التي يريدونها، ولكن مع هذا يعمر الوقت بطاعة الله، وبذكر الله، وبالنصيحة، وبالقراءة، فيكون الوقت مشتركًا بعضه للنصيحة، وبعضه لقراءة القرآن، أو الحديث، وبعضه لحاجاتهم العادية، التي ليس فيها محذور شرعًا؛ حتى لا يملوا. السؤال: الذكر .. أن يسمع الناس على التسبيح، والتحميد، والتكبير؟ الجواب: هذا منها، إن جلس في المجلس قبل الصلاة؛ يذكر الله، أو يقرأ القرآن، ويذكر الله في نفسه، ويسبح، ويهلل هذه من.. أو جلسوا في أي مكان يذكرون الله، ويتباحثون في طاعة الله، حلقة أو اثنين، أو ثلاثة، يتباحثون، يتذاكرون فيما يجب عليهم، فيما حرم الله عليهم، فيما أعطاهم الله من الأرزاق، والخيرات، وخشية الله، هل أدوا حق الله. كما كان الصحابة يفعلون شيئًا من هذا؟! يذكرون حالهم في الجاهلية وما كانوا عليه، وما هداهم الله للإسلام، وهكذا المؤمنون إذا اجتمعوا يتذاكرون في أي مجلس.","link":"https://binbaz.org.sa/fatwas/2896/توجيه-طلبة-العلم-بعمارة-المجالس-بالذكر-والعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1344.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6969,"question":"ما حكم الذي يحلق لحيته بقصد مساواتها؛ لأن بعض وجهه فيه شعر كثيف والبعض الآخر يكاد يخلو من الشعر؟","title":"حكم تخفيف اللحية وتسويتها","answer":"الجواب:\n\nبسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، أما بعد:\n\nفقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين وقال -عليه الصلاة والسلام-: جزوا الشوارب وأرخوا اللحى خالفوا المجوس.\n\nفأمر بجز الشوارب، وقصها، وأمر بإعفاء اللحى، وتوفيرها، وإرخائها -عليه الصلاة والسلام- فهذا هو الواجب على المؤمن أن يعفي اللحية، ويرخيها ويوفرها، وألا يتعرض لها بشيء من القص، والتسوية، بل يتركها، ويعفيها، ويرخيها كما أمره النبي الكريم -عليه الصلاة والسلام-. \n\nأما الشوارب فالواجب قصها، وعدم إطالتها.","link":"https://binbaz.org.sa/fatwas/2903/حكم-تخفيف-اللحية-وتسويتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1351.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6971,"question":"يا سماحة الشيخ حفظ الله علينا، وعلى المسلمين ديننا، فنحن بحاجة إلى الدعوة، والدعاة، وخاصة في أطراف البلاد -أي المملكة- خاصة بالذات الجنوب، وعندهم عدم الاعتناء بالاجتماع في المساجد، وعندهم شعوذة وعدم معرفة بالدين، لقد لاحظنا أنهم يصلون السنة قبل الفجر، وبعده، وما ذاك إلا لعدم العلم بذلك، والمعرفة، نرجو من الله، ثم من سماحتكم الحث على بعث الدعاة، وجزاكم الله، ويحفظكم الله.","title":"الحث على طلب العلم والتفقه في الدين","answer":"الجواب:  هذا الدعاة -بحمد الله- عندهم نشاط في هذا، وهم يوجهون، ويحرصون على هذا الخير في الجنوب، والشمال، ولا شك أن الجهل موجود، لكن نسأل الله أن يعين الدعاة على أداء الواجب، وأن يعين العامة على التفقه، وطلب العلم والسؤال عما أشكل عليهم، وأن يعينهم أيضًا على حضور النصائح، واستماع الفوائد.  بعض الناس يسمع الفائدة .. والندوة، والخطبة، والمحاضرة، ولا يحضرها، يأبى أن يحضرها، وأن يستمع، فنسأل الله أن يوفق المسلمين حتى يحضروا حلقات العلم، وحتى يفرحوا بالندوات، والمحاضرات في أي مكان حتى يطلبوها، ويحضروها، ويستفيدوا. وهنا وأنا قلت كم مرة، وأكرر: أن إذاعة القرآن فيها فوائد يعرفها، ويقرأها، ويسمعها الذي في الجنوب، والذي في الشمال، والذي في خارج المملكة، برنامج نور على الدرب، وإذاعة القرآن، هذه حلقات علم يستفيد منها كل من سمعها، سواء كان في داخل المملكة، أو في خارجها. فأنا أوصي الذي يحب الخير، ويريد الخير أن يسمع حلقات العلم أينما كانت، وأن يحضرها، ويطلب العلم، وأن يسمع هذا البرنامج -برنامج نور على الدرب- في إذاعة القرآن، فيه خير كثير، ويلقي فيه عدة من العلماء، والأخيار بين المغرب، والعشاء في بلاد الإسلام، وفي الساعة التاسعة والنصف ليلًا من كل ليلة، من إذاعة القرآن. فأنا أكرر، وأوصي الحاضرين، وغيرهم أن يوصوا غيرهم بأن يستفيدوا من هذا البرنامج، وأن يستفيدوا من حلقات العلم في كل مكان؛ في الجنوب، وفي غيرها، إذا سمعوا أن هناك ندوة في مسجد كذا، في حارة كذا، يذهبون إليها يسمعونها، يستفيدون منها من أهل العلم في الدمام، في الإحساء، في بريدة، في حائل، في أبها في خميس مشيط، في جيزان، في أي مكان، وهكذا في خارج البلاد في ندوات تكون في خارج البلاد، عند العلماء المعروفين في مصر، أو في الشام، أو في غير ذلك. هكذا يكون طالب العلم، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [النحل:43]، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله به طريقًا إلى الجنة. العلم ما هو يطق الباب عليك وخذ، العلم يحتاج إلى طلب، تطلب العلم، تسمع الفوائد في الإذاعة، وفي غيرها، في خطبة، في ندوة، في محاضرة، في حلقات علم، تطلب تسأل.  الرسول ﷺ يقول: من سلك طريقًا، وسمعتم في الندوة قال الله -جل وعل-ا: فَلَوْلَا نَفَرَ مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ طَائِفَةٌ لِيَتَفَقَّهُوا فِي الدِّينِ نفروا: سافروا هنا وهنا لِيَتَفَقَّهُوا فِي الدِّينِ وَلِيُنْذِرُوا قَوْمَهُمْ إِذَا رَجَعُوا إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ [التوبة:122] لا يجلس ويريد العلم، وأنا جالس عند أمي، وزوجتي، لا، يطلب العلم، يلتمس العلم.  الله يقول: وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] كيف تعبد ربك وأنت ما تطلب العلم؟ّّ! لا بد من طلب العلم، لا بد من حضور حلقات العلم؛ حتى تعرف العبادة، ما هي العبادة التي أنت مخلوق لها؟! مأمور بها من توحيد الله، والإخلاص له، والصلاة، والصوم، والحقوق الأخرى التي عليك لله، ولعباده، فلا بد أن تطلب هذا العلم. وحديث آخر في الصحيحين يقول ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين هذا الحديث العظيم: من يرد الله به خيرًا؛ يفقهه في الدين معنى هذا الحديث: أن الذي ما أراد الله به خيرًا ما يتفقه في الدين، هذا معنى الحديث، مفهومه أن المعرض الغافل الذي ما يهتم، معناه أن الله ما أراد به خيرًا -نسأل الله العافية-. أما الذي يطلب العلم، ويتفقه في الدين، ويسأل، ويحضر ندوات العلم، ويسأل العلماء، ويسمع أيضًا ما يذاع فيما يتعلق بالعلم، فهذا يريد يطلب العلم، ومن طلبه وجده. وعندكم القرآن أعظم كتاب، وأشرف كتاب، عندكم القرآن اسمعوه، تدبروه ممن يقرأه من إخوانكم، خلوه يقرأ يجلس في المجلس بدل السواليف التي ما فيها ثمرة، اقرؤوا جزءًًا من القرآن، صفحة من القرآن، اقرأ عنا، قد نسمع اسمعوا، اسمعوا وعوا ،وتدبروا، واعملوا، هذه إذاعة القرآن عندكم يذاع فيها القرآن بأصوات متنوعة، بقراءات متنوعة، بأصوات طيبة، بقراءات مجودة، اسمعوا لكن ما هو سماع المعرض الغافل لا، سماع الذي يريد الفائدة، يريد أن يعرف مراد الله؛ حتى يعمل، هكذا يكون طالب العلم. فالذي يريد الخيرن ويريد الفقه في الدينن ويريد السعادة؛ عليه بطلب العلم، وحضور حلقات العلمن وسماع العلم، وسماع القرآن، وتدبر القرآن، يقرأه بنفسه، أو يسمعه من أخيه في المسجد، أو في الإذاعة، أو في أي مكان، هكذا يكون طلب العلم.","link":"https://binbaz.org.sa/fatwas/2898/الحث-على-طلب-العلم-والتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1346.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":6979,"question":"كتاب منتشر في الأسواق عند الكثير من الشباب، واسم هذا الكتاب هو \"أنت تسأل والإسلام يجيب\" الذي ألفه محمد متولي الشعراوي، فما مدى صلاحية هذا الكتاب من عدمه؟","title":"تقييم كتاب (أنت تسأل والإسلام يجيب)","answer":"الجواب: هذا اطلعنا عليه، وفيه أجوبة جيدة، وفيه غلط فيما يتعلق بأن الرسول ﷺ خلق من النور، وأنه خلق من نور الله، هذا غلط، بناه على حديث باطل موضوع لا أصل له، فغلط فيه -عفا الله عنا وعنه- ولا بد أن ينبه عليه -إن شاء الله- اطلعت عليه منذ أيام؛ لأن بعض الناس قد يغلط في هذا، ويوجد من بعض الخطباء، وبعض الناس يتكلمون في هذا، ويقولون: إن محمدًا خلق من نور الله، وبعضهم يقول: خلق من نور العرش، كل هذا كلام باطل، لا أساس له، كله باطل، محمد ﷺ خلق من ماء أبيه وأمه، مثل بقية الناس، خلق من ماء عبدالله بن عبدالمطلب، ومن ماء آمنة، فالله خلقه مثل ما خلق بقية البشر كما قال تعالى: قُلْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ يُوحَى إِلَيَّ [الكهف:110] فهو خلق كما خلق بنو آدم جميعًا يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى [الحجرات:13] ما عدا آدم خلقه الله من الطين، وما عدا عيسى خلقه الله من أنثى بلا ذكر، والبقية من ذكر، وأنثى. قال -جل وعلا-: الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ وَبَدَأَ خَلْقَ الْإِنْسَانِ مِنْ طِينٍ ۝ ثُمَّ جَعَلَ نَسْلَهُ مِنْ سُلَالَةٍ مِنْ مَاءٍ مَهِينٍ [السجدة:7-8] فنسل آدم كلهم من ماء مهين، ومحمد ﷺ وبقية الرسل كلهم من نسل آدم -عليه الصلاة والسلام- فهذا هو الحق الذي لا ريب فيه، أما ما يروى عن النبي -عليه السلام- أنه قال: \"إن النبي خلق من نور الله\" فهذا خبر باطل، لا أساس له، بل هو مكذوب على النبي ﷺ وليس له صحة، فينبغي أن يعلم هذا، ويكون على البال؛ لأن هذا من الأخطاء التي سارت على ألسنة بعض الناس -نسأل الله السلامة- يريدون بها أن يرفعوا شأن النبي ﷺ والله قد رفعه بدون كذبهم، الله قد رفعه، ورفع شأنه، وجعله خير البشر، وأفضل عباد الله، ولا حاجة إلى الكذب.","link":"https://binbaz.org.sa/fatwas/2915/تقييم-كتاب-انت-تسال-والاسلام-يجيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1363.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6985,"question":"نرى بعضًا من المجالس يحضرها بعض من إخواننا طلاب العلم، لكنهم لا ينتهزون فرصة مجلسهم، ويذكرونهم بالله، بل ينتهزون معهم في خوضهم فيما لا فائدة فيه، فما هي نصيحة سماحتكم لهؤلاء ولأمثالهم؟","title":"توجيه طلبة العلم بعمارة المجالس بالذكر والعلم","answer":"الجواب: نصيحتي لكل طالب علم أن ينتهز الفرص، فإذا كان في أي مجلس يأمرهم بذكر الله، بقراءة القرآن، بقراءة الحديث الشريف؛ حتى ينتفع المجلس، حتى يكون وجوده نافعًا للمجلس، لا يشاركهم في الغيبة، والنميمة، والسواليف التي لا فائدة فيها، بل متى وجد طالب العلم يعمر المجلس إما بقراءة القرآن، والكلام على ما تيسر من الآيات، وإلا بقراءة الأحاديث، مثل رياض الصالحين، وغيره؛ حتى تكون الفائدة للجميع، وحتى يكون المجلس نافعًا من مجالس الآخرة.  وإذا كان  ولا بد من حديث؛ فليكن حديثًا قليلًا فيما أباح الله، لا في الغيبة، والنميمة، ونحوها، بل في الحاجات العادية التي ليس فيها محذور، حتى يعطيهم بعض الفرصة لأحاديثهم التي يريدونها، ولكن مع هذا يعمر الوقت بطاعة الله، وبذكر الله، وبالنصيحة، وبالقراءة، فيكون الوقت مشتركًا بعضه للنصيحة، وبعضه لقراءة القرآن، أو الحديث، وبعضه لحاجاتهم العادية، التي ليس فيها محذور شرعًا؛ حتى لا يملوا. السؤال: الذكر .. أن يسمع الناس على التسبيح، والتحميد، والتكبير؟ الجواب: هذا منها، إن جلس في المجلس قبل الصلاة؛ يذكر الله، أو يقرأ القرآن، ويذكر الله في نفسه، ويسبح، ويهلل هذه من.. أو جلسوا في أي مكان يذكرون الله، ويتباحثون في طاعة الله، حلقة أو اثنين، أو ثلاثة، يتباحثون، يتذاكرون فيما يجب عليهم، فيما حرم الله عليهم، فيما أعطاهم الله من الأرزاق، والخيرات، وخشية الله، هل أدوا حق الله. كما كان الصحابة يفعلون شيئًا من هذا؟! يذكرون حالهم في الجاهلية وما كانوا عليه، وما هداهم الله للإسلام، وهكذا المؤمنون إذا اجتمعوا يتذاكرون في أي مجلس.","link":"https://binbaz.org.sa/fatwas/2896/توجيه-طلبة-العلم-بعمارة-المجالس-بالذكر-والعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1344.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":7188,"question":"إذا أراد الإنسان أن يقرأ بعض الكتب، ويريد منها الفائدة، قد يقرأ هذا الكتاب حول شيء ثلاث ساعات، أو أكثر، وخلص، ولم يفهم مما قرأ شيئًا، هذه تكون عبادة، أم ضياع للوقت؟ أفيدونا جزاكم الله خيرًا.","title":"لو قرأ كتابا ولم يفهم، هل تكون عبادة، أم ضياعًا للوقت؟","answer":"الجواب:\n\nعلى طالب العلم، وعلى طالب الحق أن يلتمس الحق من طرقه، فأعظم طريق، وأفضل طريق، وأكبر طريق، وأنفع طريق طريق من على كتاب الله القرآن، هذا أعظم شيء، كثير من الناس إذا قلت الكتاب والسنة ما عنده حماس، يدور شيئًا آخر، أعظم طريق، وأعظم سبيل، وأفضل طريق، وأنجح طريق كتاب الله العظيم، ثم سنة الرسول المصطفى -عليه الصلاة والسلام- هذه هي الطرق، هذان الطريقان.\n\nفالمؤمن يقبل على القرآن، يكثر من تلاوته، يتدبر معانيه .. لماذا أنزل إلا لك؟ حتى تستفيد، ما أنزله الله للبهائم، ولا للجمادات، أنزله لك، للثقلين، للجن والإنس؛ ليتفقهوا، ويتعلموا يقول سبحانه: كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ [ص:29] يعني محمد ﷺ إليك يعني وإلى أمتك، أنزل إليه لينتفع به هو وأمته كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ [ص:29].\n\nويقول سبحانه: أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ [محمد:24] من هم؟ أنت، الجن والإنس هم الذين يتدبرون، ما هو البهائم أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]، ويقول سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]. \n\nفعليك يا أخي أن تقبل على القرآن، وأن تكثر من تلاوته، وأن تدبر معانيه وتقف عند الآيات، يقول: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] ما معنى يهدي للتي هي أقوم؟ يعني يدل على الناس على الطريقة التي هي أقوم يرشدهم، فالتمس من هذا الكتاب الهداية، وسل ربك أن يفقهك، وأن يعينك، ويمنح قلبك الفهم الصحيح، ما أنزل عبث قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ [ص:29]. \n\nفعليك بالتدبر، والتعقل، تقف عند الآيات، تستفيد منها، تعرف مراد الله منها، وإذا أشكل عليك عندك كتب التفسير؛ راجع كتب التفسير: ابن جرير، ابن كثير، البغوي، الشوكاني، القرطبي، غيرهم، تنظر ومن أنفعها وأحسنها: ابن جرير، وابن كثير، والبغوي، هذه الكتب ميسرة بحمد الله، موجودة، تراجع كلام أهل العلم عليها تستفيد.\n\nكذلك أحاديث الرسول ﷺ تراجعها، تستفيد منها، عندك إن كنت طالب علم، عندك البخاري، عندك مسلم، عندك مختصرات: مثل المنتقى لابن تيمية، بلوغ المرام للحافظ ابن حجر، عمدة الحديث للحافظ عبدالغني، هذه مختصرات تفيدك تأملها، وانظر ما يتعلق بالصلاة في أبواب الصلاة، ما يتعلق بالزكاة في أبواب الزكاة، ما يتعلق بالتوحيد في أبواب التوحيد، إلى آخره، ثم تسأل أهل العلم.\n\nأما الكتب المجهولة، كتب لا تدري عن حالها، تضيع فيها أوقاتك لا، لا تضيع أوقاتك في كتب ما تدري عنها، دع الأوقات تروح في كتب معلومة للفائدة، عليك بالكتب المعروفة التي فيها الفائدة والخير، أعظمها الكتاب العزيز القرآن، ثم كتب السنة البخاري ومسلم، المختصرات من ذلك: المنتقى، بلوغ المرام، عمدة الحديث، كتاب أبي داود، كتاب الترمذي، سنن النسائي، ابن ماجه، مسند أحمد، إذا كنت طالب علمن وإذا كنت عاميًّا فاسأل أهل العلم، أكثر من القرآن وتدبر القرآن لعلك تستفيد، واسأل أهل العلم عما أشكل عليك.\n\nأما تطلب كتبًا جدت بين الناس، ما تدري ما حالها تضيع أوقاتك فيها لا، أما إذا كانت كتبًا طيبة أثنى عليها العلماء، وأرشدوك إليها؛ فلا بأس أن تجعل لها وقتًا، فتأخذ منها ما وافق الكتاب والسنة، وتحمد الله على ذلك، وما خالف الكتاب والسنة تدعه، فبعض الكتب تفيد، ترشد إلى الكتاب والسنة، تعين على فهم الكتاب والسنة، تعين على فهم الأحاديث الصحيحة والضعيفة، لا بأس.\n\nلكن بعض الناس يضيع أوقاته في مجلات، في جرائد يومية، في كتب لا قيمة لها، حتى أهلها لا يعرفون بالفضل، ولا بالعلم، تذهب أوقاته ليلًا ونهارًا في مجلة من أولها إلى آخرها، في خرافات، وضلالات، أو أشياء لا قيمة لها، أو في كتاب مجهول، أو كتاب ضال مضل، أو في غير ذلك، وعنده كتاب الله فيه الهدى والنور، وعنده سنة الرسول فيها الهدى والنور، عنده كلام أهل العلم المعروفين بالهدى والعلم، يتركهما جانبًا، هذا من طرق الضلال، هذا من العمى فَإِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَكِنْ تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ [الحج:46].\n\nالسؤال:...؟\n\nالجواب: يعني إذا كان طالب علم؛ يكفي، إذا كان ما هو طالب علم؛ لا يقرأ، لكن إذا كان طالب علم، ينتسب إلى العلم، يقرأ ويستفيد من قول النبي ﷺ ويستفيد من كلام الله -جل وعلا- وإذا أشكل عليه شيء؛ يطالع، ما معنى الآية في تفسير ابن كثير، في الجلالين، في البغوي، في ابن جرير، في الشوكاني، ويسأل إخوانه الزملاء الطيبين، يتذاكر معهم، لا يحقرهم، قد يكون زميل له أفضل من شيخ، قد يكون زميل جيد يتفاهم معك أكثر من شيخ، قد لا يعطيك إلا كلمة، أو كلمتين، تفاهم مع الزملاء الطيبين، ومع أستاذك الذي تدرس عليه الطيب، تخير من الأساتذة أطيبهم وأنفعهم وأغيرهم لله وأكثرهم علمًا؛ حتى تستفيد.\n\nالسؤال: يقول هل يؤجر حتى ولو ما استفاد منها إن قرأها؟\n\nالجواب: يؤجر يؤجر، لكن ينبغي له أن يقرأ حسب الاستفادة، إذا أشكل عليه لا يقف عند الجهل، يراجع الكتاب، يراجع التفسير، يراجع زملاءه، يتعاونون، يراجع الأساتذة، لا يرضى بالجهالة التي لم يفهمها، أقول لا يرضى بهذا، يعني يستفيد إذا جهل شيئًا وهو يهمه، يراجع التفسير، يراجع أهل العلم..","link":"https://binbaz.org.sa/fatwas/3239/لو-قرا-كتابا-ولم-يفهم-هل-تكون-عبادة-ام-ضياعا-للوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1580.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":7428,"question":"الحصون المنيعة جمعها محمد علوي المالكي ...؟","title":"تقويم كتاب الحصون المنيعة لمحمد علوي المالكي","answer":"الجواب:  لا، هذه الحصون المنيعة فيها أغلاط، فيها بعض البدع، وكتب العلوي هذا مبتلى بشر كثير من البدع، ومبتلي بأشياء كثيرة من الشرك -نسأل الله العافية- وهو معروف في مكة، وقد نبهه العلماء على أخطائه وأغلاطه، ولكنه أصر على باطله، ونسأل الله أن يهديه ويرده إلى الصواب، فله مؤلفات فيها شر كثير، له الذخائر المحمدية فيها شركات وبدع كبيرة، وله كتاب المفاهيم وفيه أغلاط كثيرة.  فالمقصود: أن الرجل لا يعتمد، محمد بن علوي المالكي لا يعتمد عليه في كتبه؛ لأنه رجل عنده تخريف، وعنده انحراف في العقيدة -نسأل الله لنا وله الهداية- فلا يجوز الاعتماد على كتبه ولا على فتاويه حتى يرجع إلى الصواب، ويعلن توبته، ويعدل ما كتبه من الباطل -نسأل الله لنا وله الهداية-.","link":"https://binbaz.org.sa/fatwas/3513/تقويم-كتاب-الحصون-المنيعة-لمحمد-علوي-المالكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1817.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":7478,"question":"السؤال الثاني: للأخت (ع . ع) من السودان تقول: أنا طالبة في معهد إعداد المعلمات، وفي المعهد تدرس مادة المسرح وهي مادة إجبارية ضمن المواد الأكاديمية التي تدرس بالمعهد، ونمثل على خشبة المسرح، ونقدم الأناشيد والغناء بصحبة فرقة موسيقية، ونقدم أيضاً التراث الشعبي والرقصات، ويشهد الحفل أسرة المعهد والجمهور، وهذا يعتبر نشاط للطالبة وتأخذ عليه درجات، ويرفع من شأن شهادة التخرج، ما موقف الطالبة من كل هذا، علماً بأن الطالبة تجبر ومن غير إرادتها؟","title":"حكم دراسة مادة المسرح والتمثيل والغناء للطالبة","answer":"الجواب:  الذي يظهر من هذا أن هذه المادة لا يجوز للطالبة أن تفعلها ولا أن توافق عليها، لما فيها من الأغاني الخليعة، ولما فيها من إظهار الزينة، وإذا كان يحضرها رجال فالأمر أشد، إذا كان الجمهور يحضرون منهم الرجال فالأمر أشد، فلا يجوز هذا أبداً، بل يجب على القائم على المعهد أن يتقي الله، وأن يدع هذا الشيء، وأن يكون للنساء صفة خاصة في التعليم، ليس فيه إظهار زينتهن ولا جمالهن بين الرجال، بل تكون دروسهن خاصةً بهن ليس فيها ما يفتن الرجال ولا ما يدعو إلى إظهار زينة النساء، هذا الواجب على القائم على المعهد.\nوأما الطالبة نفسها فعليها أن تتحرى ما أباح الله لها، وأن تدع ما حرم الله عليها، وقد قال النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فالشيء الذي فيه معصية؛ من إظهار زينتها بين الرجال، ومن تعلمها آلات الملاهي؛ من الموسيقى والعود والكمان وأشباه ذلك، كل هذه أشياء منكرة لا يطاع فيها المخلوق، إنما الطاعة في المعروف. أما الشيء الذي لا محذور فيه فلا بأس، إذا وجد أشياء رياضية لا محذور فيها فلا بأس، أما أن تتعلم الرقصات الفاتنة بين الرجال، أو تتعلم الموسيقى وآلات الملاهي، أو الأغاني الخليعة فلا، ما يجوز هذا الشيء.  أما الرقصات بين النساء وهن بين النساء الرقصات العادية التي تعمل في الزواجات، أو الأغاني التي تعمل في الزواجات ليس فيها مدح الخمر ولا الزنا ولا كذا بل أغاني خاصة شعبية ليس فيها شيء مما حرم الله تستعمل للزواج والعرس، هذا لا بأس به. نعم.","link":"https://binbaz.org.sa/fatwas/4323/حكم-دراسة-مادة-المسرح-والتمثيل-والغناء-للطالبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_004/00403.mp3","categories":["قضايا المرأة","العالم والمتعلم"]},{"id":7560,"question":"السؤال الخامس يقول: إذا امتلكت مبلغاً من المال عن طريق حلال، فأيهما أفضل: أن أشتري بها كتب علم وأتصدق بجزء من المال، أم أتصدق بالمال جميعاً؟","title":"أفضلية اقتناء كتب العلم على الصدقة","answer":"الجواب: إذا كان عنده مال وهو يحتاج إلى كتب العلم فكتب العلم أولى، يشتري كتب العلم حتى يستفيد منها، أو عنده من يحتاج إليها في بلد، يحطها في مكتبة يستفيد منها طلبة العلم، فكونه يشتري كتباً تنفع الناس مثل الصحيحين، مثل السنن الأربع، مثل المغني، مثل غيرها من الكتب النافعة.. تفسير ابن كثير ، تفسير البغوي ، تفسير ابن جرير .. إلى غير ذلك من الكتب المفيدة، كونه يشتري بها كتب مفيدة في مكتبته يحتاجها هو أو يحتاجها أولاده أو إخوانه طلبة العلم، أو يجعلها في مكتبة المسجد، أو في المكتبات العامة يرد إليها الناس ويستفيدون منها الناس، هذا أولى من الصدقة، وأما إذا كان ما هناك حاجة إلى المكتبة؛ لأن هناك كتب تغني عن شرائه هو، فإذا تصدق بها على الفقراء من أقاربه أو غيرهم فهذا حسن، هذه قربى إلى الله جل وعلا، لكن الكتب إذا كانت لها حاجة أنفع وأفضل؛ لأن نفعها أعظم. نعم.","link":"https://binbaz.org.sa/fatwas/4564/افضلية-اقتناء-كتب-العلم-على-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01405.mp3","categories":["الرضاع","العالم والمتعلم"]},{"id":7561,"question":"سؤاله الأخير يقول: هناك مجلات دينية مشهود لها بالأمانة والإصلاح ولكن عيبها أنها تحتوي على صور، وقد فتح الله علي بمبلغ وفير فأحببت أن أحصل على أعداد وفيرة منها، ولكن تذكرت أن الملائكة لا تدخل بيتاً فيه صورة، وأنا الآن في حيرة من أمري فأرشدوني وفقكم الله؟","title":"حكم شراء المجلات الدينية المحتوية على الصور","answer":"الجواب: الذي يظهر أن المجلات المفيدة ينبغي أن تشترى وتوزع بين الناس لعظم فائدتها، ولا يمنع من ذلك ما فيها من الصور، مثل مجلة المجتمع، مثل مجلة الدعوة.. وأشباهها، مجلة البلاغ، هذه مجلات نافعة ومفيدة، فلا ينبغي أن يتوقف في شرائها من أجل الصور، بل يشريها ويوزعها على المحتاجين لها، ويستفيد منها، والصور لا تمنع دخول الملائكة في مثل هذا فإنها مغطاة، هذه صورة مغطاة تغطى بالأوراق التي عليها، فهي تشبه الصور التي تغطى بخرقة فوقها، وتشبه الصور التي في الفراش الذي يوطأ ويمتهن والوسائد، فلا تمنع إن شاء الله من دخول الملائكة، لكن على سبيل الاحتياط ينبغي له أن يضع على الرءوس البوية، يعني: يمسحها بالبوية حتى تزول أحكام الصور؛ يعني زال الرأس زال حكم الصورة، ولا سيما إذا كانت على الغلاف، هذه مكشوفة، إذا كانت على الغلاف ينبغي طمسها، يجعل فوقها قرطاسة بالشمع، أو فوق الرأس قرطاسة بالشمع، أو يزيل الرأس بالحبر الذي يزيل معالم الرأس، أو بشيء من البوية ويزول الحكم. نعم.\nوفي الحقيقة: أن هذا الشيء الذي ذكره السائل مؤلم، ما كان ينبغي لهذه المجلات الطيبة أن تستعمل الصور؛ لأن التصوير محرم، والرسول ﷺ شدد في ذلك وقال: كل مصور في النار، وقال: أشد الناس عذاباً يوم القيامة المصورون، وقال لـعلي: لا تدع صورة إلا طمستها، فما كان ينبغي لهؤلاء الذين يصدرون هذه المجلات الطيبة ما كان ينبغي لهم أن يضعوا الصور، فنصيحتي لهم جميعاً أن لا يضعوها، وأن يتركوا الصور، فتكون هذه المجلات سليمة طيبة بعيدة عن هذا التيار الذي وقع فيه الناس، هذه نصيحتي لإخواني في الدعوة، وفي مجلة المجتمع، والبلاغ وغيرها، نصيحتي لهم جميعاً أن لا يضعوا فيها صوراً، وكذلك إذا كتبوا فيها مقالاً لأحد أن لا يضعوا صورته إلا بإذنه حتى لو أذن لا ينبغي أن يصوروه على الصحيح، حتى لو أذن لا يصورونه، وأنا أحرج كل من نقل عني مقالاً أن يضع صورتي، أنا لا أسامحه، ولا أبيحه أن يضع صورتي، كل من كتب عني أنا أحرجه أن يضع صورتي، ولا أرضى بذلك؛ لأني أعتقد أنه لا يجوز التصوير مطلقاً، فأنا أقول لكل من نقل عني في أي مجلة أو في أي جريدة: لا أبيحه ولا أسامحه أن يضع صورتي، هذا الذي أقوله لإخواني جميعاً، وأنصح به إخواني جميعاً، وأبلغهم إياه من طريق هذا المنبر أني لا أرضى أن توضع صورتي مع أي مقال أو فتوى تنشر عني، هذا اعتقادي، وإن كان التصوير قد يحتاجه بعض الناس مثل التابعية، والجواز، ورخصة القيادة، هذا شيء آخر، قد يقال: إن صاحبها في ضرورة أو مكره فيعفى عنه إن شاء الله؛ لأنه مضطر إلى التابعية ونحوها، لكن نقل المقالات في الصحف ليس هناك ضرورة إلى وضع صورة صاحبها، صاحب المقال معروف وإن لم توضع صورته. نعم.\nالمقدم: هذه الرسالة من المرسل إبرهيم حسين الحويطي من جدة البريد المركزي، في الحقيقة لم يضمن رسالته أسئلة وإنما هي استشارة، يقول في هذه الرسالة الأخ إبراهيم حسين الحويطي من جدة: هل بالإمكان مراسلة البرنامج وعرض ما لديهم من استفسارات حول ما يهمهم من أمور دينية ويخشى من عدم تمكننا من قراءة خطه، وفعلاً الخط رديء للأسباب التي ذكرها، ولكن على الأخ إبراهيم اختصار السؤال ما أمكن، أو الطلب من أحد أقاربه أو أصدقائه كتابة أسئلته لنتمكن من عرضها على الوجه الذي يريد، ونحن مستعدون ونرحب به وبأسئلته، وفي الحقيقة أنا جلست ليلة كاملة لإخراج هذه الكلمات البسيطة.","link":"https://binbaz.org.sa/fatwas/4565/حكم-شراء-المجلات-الدينية-المحتوية-على-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01406.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":7817,"question":"يقول: ما الكتب التي تنصحونني بالتزود منها في التفسير وفي التوحيد وفي الفقه؟","title":"أهم ما ينصح بقراءته من الكتب","answer":"الجواب: أعظمها القرآن، نوصيك بالقرآن الكريم، الإكثار من قراءة القرآن وتدبر معانيه، وهو أصل كل خير، هو أصدق كتاب، وهو المرجع في كل شيء، نوصيك بالقرآن والعناية به، والإكثار من تلاوته، وتدبر معانيه.\nثم كتب الحديث مثل عمدة الحديث لـعبد الغني بلوغ المرام للحافظ ، المنتقى لـابن تيمية كتب جيدة نافعة على أبواب الفقه تنفعك، كتب العقيدة مثل كتاب التوحيد لشيخ الإسلام : محمد بن عبد الوهاب ، كشف الشبهات ثلاثة الأصول هذه كتب جيدة أيضاً نافعة، ومثل العقيدة الواسطية لشيخ الإسلام: ابن تيمية في العقيدة التدمرية الحموية كلها كتب مفيدة له رحمه الله في العقيدة، وفي الفقه مثل زاد المستقنع للحجاوي عمدة الفقه للموفق ، فهذه كتب مفيدة ....، نسأل الله لنا ولكم التوفيق. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/5199/اهم-ما-ينصح-بقراءته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05117.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":7820,"question":"هذه رسالة طويلة من مستمع للبرنامج (ش. م) مصري ومقيم بتبوك، كتب مجموعة من الأسئلة يقول: سماحة الشيخ حفظكم الله: ما الشروط التي يجب أن تتوفر في الناس الذين يتعرضون للفتيا ويفتون؟ وهل يجوز للإنسان أن يفتي نقلاً من العلماء الموثوق في علمهم، نرجو أن تحدثونا في هذا الموضوع مأجورين يا سماحة الشيخ؟","title":"الشروط الواجب توافرها في المفتي","answer":"الجواب: الفتوى إنما تجوز للعالم الذي يعرف قال الله قال رسوله، وليس له أن يفتي بمجرد رأيه.\nفالواجب على المؤمن أن يفتي عن علم عن بصيرة بما قاله الله ورسوله، فإذا كان ليس عنده علم يسأل أهل العلم الذين يطمئن إليهم ويعرفهم ويسألهم عما أشكل عليه، ولا يتخبط ولا يقل بغير علم؛ لأن الله قال: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] جعله فوق الشرك القول على الله بغير علم.\nوذكر عن الشيطان أنه يأمر بالسوء والفحشاء إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:169].\nفالواجب على المسلم أن لا يقول على الله إلا بعلم، فإذا كان ما عنده علم يسأل أهل العلم، وليس له الكلام في دين الله في حرام أو حلال أو واجب إلا ببصيرة وعلم قال الله قال رسوله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/5196/الشروط-الواجب-توافرها-في-المفتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05114.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":7839,"question":"أخونا يسأل ويقول: بماذا نحارب الجهل والأمية؟ وهل هما شيئان مختلفان، أم أن لكل واحد منهما حد معين، وما هو؟ جزاكم الله خيرا.","title":"وسائل محاربة الجهل والأمية والفرق بينهما","answer":"الجواب: الجهل والأمية يحاربان بالعلم بالتعلم والتفقه في الدين والتدبر للقرآن الكريم، وحضور مجالس العلم، وسؤال أهل العلم، بهذا يحارب الجهل وتحارب الأمية، كون المؤمن والمؤمنة يتدبران القرآن ويكثران من قراءة القرآن بالتدبر والتعقل والاستفادة، وكذلك بمراجعة أحاديث الرسول صلى الله عليه وسلم والعناية بما ذكره أهل العلم في تفسير القرآن، وفي بيان الأحاديث وما دلت عليه، وهكذا بحضور مجالس العلم وحلقات العلم، وهكذا بصحبة الأخيار من أهل العلم، وهكذا بسؤال أهل العلم كما قال الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]، وروي عنه عليه الصلاة والسلام أنه قال لما أفتى قوم بجهل، قال: ألا سألوا إذ لم يعلموا، إنما شفاء العي السؤال، بهذا تحارب الجهالة وتحارب الأمية.\nوالجهل أعم من الأمية، كل أمي قد يكون جاهلاً، ولكن ليس كل جاهل أمياً فالجهل أعم، فقد يكون متعلماً وليس بأمي ولكن يجهل مسائل كثيرة، تخفى عليه مسائل كثيرة، فدواء ذلك التعلم والتفقه في الدين حتى يزول الجهل، وقد يكون عالماً بالصلاة جاهلاً بالزكاة، وقد يكون عالماً بالصلاة والزكاة جاهلاً بأحكام الصيام، وقد يكون عالماً بالعقيدة والصلاة والزكاة والصيام لكنه جاهل بأحكام الحج، وقد يكون عالماً بالعبادات لكنه جاهل بأحكام المعاملات جاهل بأحكام الطلاق والنكاح إلى غير هذا.\nفالعلم يتبعض والجهل يتبعض، فدواء الجهل مطلقاً دواؤه التعلم والتفقه في الدين، ودواء الأمية كذلك التعلم والتفقه في الدين، نعم.\nالمقدم: إذاً وصف أمة الإسلام بأنها أمية يكون ماذا لو تكرمتم شيخ عبد العزيز؟\nالشيخ: هذا هو الأصل فيهم، الأصل في هذه الأمة أنها أمية.\nالمقدم: الأصل الأصل.\nالشيخ: أي عدم العلم، هذا هو الأصل ونبينا صلى الله عليه وسلم أمي؛ لأنه ما كان عنده علم قبل أن يوحى إليه عليه الصلاة والسلام، ما كان يقرأ ولا يكتب، كما قال الله عز وجل: وَمَا كُنْتَ تَتْلُوا مِنْ قَبْلِهِ مِنْ كِتَابٍ وَلا تَخُطُّهُ بِيَمِينِكَ إِذًا لارْتَابَ الْمُبْطِلُونَ [العنكبوت:48]، فما كان قارئاً، وما كان شاعراً، وما كان يخط، حتى علمه الله وأنزل عليه هذا الكتاب العظيم، فالأمي الذي نسب لأمه، يعني: بقي على الجهل ليس عنده علوم وليس عنده كتابة، فإذا تعلم العلم لم يكن أمياً، وإذا كان يكتب العلم وينقل المسائل العلمية ويحسن الكتابة لم يكن أميا، وإنما الأمي الذي لا يحسن القراءة ولا يحسن الكتابة حتى يستفيد من علمه الذي علمه أو مما يكتبه عن العلماء، فكان النبي ﷺ مثلما قال الله: وَوَجَدَكَ ضَالًّا فَهَدَى [الضحى:7]، جاهلاً بالعلوم التي جاء بها الوحي، لم يكن عنده علم بما شرع الله له في كتابه العظيم، ولم يكن عنده علم بعلوم الأولين المرسلين، ولم يكن يكتب ويخط حتى جاءه هذا الخير العظيم والوحي العظيم عليه الصلاة والسلام، فكل إنسان لم يتعلم ولم يكتب يقال له: أمي، والأمة العربية هكذا كان الغالب عليها أنها أمية لا تكتب ولا تقرأ، هذا الغالب على أمة محمد ﷺ، نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/5223/وساىل-محاربة-الجهل-والامية-والفرق-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05204.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":7909,"question":"من مدينة الخرج بعث بهذه الرسالة: سعدون العنزي يقول في رسالته: سماحة الشيخ: عبد العزيز بن عبد الله بن باز الموقر بعد الاحترام والتقدير:السلام عليكم ورحمة الله وبركاته، وبعد:سماحة الشيخ! أرجو إفتائي في السؤال التالي مشكوراً: هل الذي تزوج فاطمة بنت الرسول عليه الصلاة والسلام أبو بكر الصديق أم أنه علي بن أبي طالب رضي الله عنهما جميعاً؟","title":"تزويج فاطمة بنت رسول الله","answer":"الجواب: الذي تزوج فاطمة هو علي بن أبي طالب ، هذا بإجماع المسلمين، ليس في هذا نزاع ولا خلاف، أما أبو بكر الصديق فلم يتزوج بنت النبي ﷺ، ولكن عثمان تزوج ابنتين من النبي ﷺتزوج ابنتيه: رقية وأم كلثوم وماتا في عصمته ، وعلي تزوج الصغيرة وهي فاطمة أم الحسن وأم الحسين رضي الله عن الجميع، وزينب تزوجها أبو العاص بن الربيع ، وهن أربع، وليس في هذا نزاع ولا خلاف.","link":"https://binbaz.org.sa/fatwas/5398/تزويج-فاطمة-بنت-رسول-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06207.mp3","categories":["العالم والمتعلم","التاريخ والسيرة"]},{"id":8109,"question":"بارك الله فيكم. سماحة الشيخ! أخونا يتيح لنا فرصة السؤال عن هذه الأشياء التي لم يعد لها وجود تقريباً -سماحة الشيخ- كالرق مثلاً، وكالسفر على الدواب كالجمال والحمير والخيل وهكذا، ثم عن مثل الإقط وزكاة الفطر، هذه الأشياء تكاد ينعدم التعامل بها سماحة الشيخ، وفقهنا لا زال يذكر هذه الأشياء، ماذا يقول سماحة الشيخ عن مثل هذه الأشياء؟","title":"هل من حاجة إلى الكلام في الرق وركوب الخيل والحمير؟","answer":"","link":"https://binbaz.org.sa/fatwas/5905/هل-من-حاجة-الى-الكلام-في-الرق-وركوب-الخيل-والحمير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10204.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8141,"question":"يقول أيضاً: ما رأيكم في كتاب: \"في فصول الدين والأدب\" من تأليف إبراهيم السليمان؟الشيخ: أيش؟ إبراهيم السليمان الطامي كتاب: في فصول الدين والأدب؟","title":"تقييم كتاب: في فصول الدين والأدب","answer":"الجواب: لم أطلع عليه ولا أعلم عنه شيئاً.","link":"https://binbaz.org.sa/fatwas/5945/تقييم-كتاب-في-فصول-الدين-والادب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_089/08903.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8170,"question":"يقول بعض الناس: إن قراءة الكتب وحدها لا تنفع ولابد أن تقرأ على شيخ فهل هذا صحيح أم لا؟","title":"حكم أخذ العلم من الكتب دون الرجوع إلى العلماء","answer":"الجواب: نعم إذا كان الشخص عامياً وليس عنده أدوات العلم ولم يتعلم ما يؤهله لمطالعة الكتب فإنه لا يستفيد الفائدة المطلوبة قد يستفيد إذا كان يفهم العربية قد يستفيد وإذا كان بلغته قد يستفيد إذا كان يفهم كما يستفيد من كلام الله إذا قرأ القرآن يستفيد باللغة التي يفهمها، لكن ما يستفيد الفائدة الكاملة العظيمة إلا إذا تعلم على أهل العلم المعروفين بالخير والعقيدة الصالحة والطريقة السلفية التي يتبعون فيها السلف الصالح وهم أصحاب النبي ﷺ وأتباعهم بإحسان، هذا العالم يبصرك ويرشدك إلى ما قد يخفى عليك من كتاب الله ومن سنة رسوله عليه الصلاة والسلام ويعينك على الفهم الصواب، أما وحدك فقد تغلط كثيراً ولا سيما إذا كنت لم تتعلم الأصول التي تهتدي بها إلى فهم النصوص ولم تجالس أهل العلم، أما الذي قد جالس العلماء وحضر حلقات العلم واستفاد فإنه يمكن أن يطالع ويستفيد، فنوصيك أن تجمع بين هذا وهذا، تطالع الكتب التي تفهمها تتدبر القرآن وتعتني بقراءة القرآن بالتدبر والتعقل وتسأل أهل العلم عما أشكل عليك، ولا تثق بنفسك بل عليك أن تسأل أهل العلم المعروفين بالاستقامة بالفضل والديانة والعبادة وصحة المعتقد هذا هو الذي ينبغي لك.\nالمقدم: بارك الله فيكم.\nالمقدم: حبذا سماحة الشيخ لو ذكرتم الأشياء التي تؤهله للاستفادة من القراءة دون أن يكون عنده أحد، أو دون أن يكون له شيخ كما يقول؟\nالشيخ: يراجع كتب التفسير، تفسير القرآن الكريم ويعرف أصول أهل العلم وأصول الفقه يطالعها ومصطلح الحديث حتى يستفيد، وبكل حال لا يستفيد الفائدة المطلوبة إلا بعالم يبصره، لابد، لأن هذه أصول وقواعد تحتاج إلى بعض الشرح بعض البيان، فكونه يستقل بنفسه من أول وهلة هذا لا يتم به المطلوب وإن كان حاذقاً وإن كان عربياً لكنه محتاج إلى أن يعرف المصطلحات بواسطة أهلها العارفين بها، لكن لا يمتنع من تدبر القرآن ولا يمتنع من حفظ الأحاديث وقراءة الكتب المفيدة فإنه لابد يستفيد بعض الفائدة، لكن لا يكتفي بهذا، ننصحه أن لا يكتفي بل يطلب العلم في حلقات العلم وفي مدارس العلم الموثوقة الطيبة، ومن طريق زيارة العلماء في بيوتهم ومساجدهم للسؤال والتبصر هكذا يكون طالب العلم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5968/حكم-اخذ-العلم-من-الكتب-دون-الرجوع-الى-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10407.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8171,"question":"ما حكم من يتعلم لكي يأخذ الشهادة أو يصير عالماً إلى غير ذلك؟","title":"وجوب تصحيح النية في طلب العلم","answer":"الجواب: إذا كان يتعلم للدنيا ليتوظف أو ليقال: إنه عالم فهذا خاسر، ما يستفيد من العلم الفائدة التي تنفعه في الآخرة، أما إذا تعلم ليستفيد ويعرف حكم الله ويعرف ما شرع الله له وليتوظف أيضاً وينتفع في أمور دنياه فلا بأس، فإن العلم يجره إلى هذا وهذا، ولكن قد يتعلم ليتوظف أو ليقال له: عالم ثم يهديه الله ويرجع إلى الصواب، مثل ما قال بعض السلف: (تعلمنا العلم لغير الله فأبى أن يكون إلا لله).\nفينبغي له أن يتعلم ولو ساءت نيته لا يترك العلم يتعلم ويجتهد ويحضر مع العلماء ويسأل ربه أن يحسن نيته، يضرع إلى الله أن الله يعينه على إصلاح النية وأن يقصد بعلمه وجه الله ، والله سبحانه وتعالى جواد كريم إذا صدق في الدعاء يجيب الله دعوته ويحسن حاله فتكون النية بعد ذلك صالحة لا ييئس ولا يترك العلم. نعم.","link":"https://binbaz.org.sa/fatwas/5970/وجوب-تصحيح-النية-في-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10408.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8184,"question":"تقول أنا معلمة وقد قمت بواجبي في التعليم ابتغاء رضا الله فلم أقصر فيه أو أتهاون عن بعض ولكن قد تعتريني بعض المشكلات، فمثلاً: الطالبة تكون غير مجتهدة أو لم تؤد واجبها فأنا بطبيعة الحال أقوم بضربها حتى لا تكرر هذا الإهمال فما حكم ضرب الطالبات لتأديبهن؟ وما صحة قول رسول الله ﷺ: العصا لمن عصى، نسبت هذا إلى الرسول صلى الله عليه وسلم! أرجو أن تفيدوها سماحة الشيخ؟","title":"حكم ضرب المعلم للطالب على إهماله","answer":"الجواب: لا شك أن الواجب على المعلمة تحري أسباب نجاح الطالب والطالبة، فإذا كانت الطالبة تقصر وتتساهل في أداء واجبها فعليك أن تنصحيها وتوجيهها وإذا لم ينفع النصح ولم تتأثر بالكلام فلا مانع من تأديبها التأديب الذي يعينها على أداء الواجب من دون خطر تأديب ليس فيه خطر لا جرح ولا كسر ولكنه تأديب يحصل به المقصود من تشجيعها على العمل وتنشيطها على العمل وأنت مأجورة في ذلك كما يؤدب الإنسان ولده على الصلاة قال النبي ﷺ مروا أبناءكم بالصلاة لسبع واضربوهم عليها لعشر.\nفالضرب للتأديب وكما يؤدب الرجل زوجته للقيام بحقه أو بحق الله سبحانه لا بأس بهذا فهذا من هذا الباب تأديب الطالب وتأديب الطالبة عند وجود التقصير منهما أو التساهل أمر مطلوب وهو في مصلحتهما لكن مع مراعاة عدم الخطر في ذلك، وأما قولك في الحديث: «العصا لمن عصى» فهذا فليس بحديث وليس بوارد عن النبي ﷺ وإنما هذا من كلام العامة.\nالمقدم: بارك الله فيكم. سماحة الشيخ عن تربية المعلم للتلاميذ يدور حديث وحديث في الصحافة وفي وسائل الإعلام وكانت نتيجة ذلك الحديث أن ذهبت هيبة المعلم وأصبح في مكان خوف من قبل بعض الطلبة الذين لم يؤدبوا كما يجب لعل لسماحة الشيخ رأي في هذا وفق لشرع الله؟\nالشيخ: وما هو الحديث؟\nالمقدم: الحديث أن تلك الصحافة أو وسائل الإعلام تلك لا ترى أن يقوم المعلم بضرب الطالب إطلاقاً.\nالشيخ: يعني يخوضون في هذا.\nالسائل: يخوضون في هذا حتى أن الطلبة قرأوا هذا فأصبح المعلم بدون شخصية أمام تلاميذه.\nالشيخ: لا، هذا خطأ من الصحافة هذا خطأ من الخائضين بل ينبغي لمن يتكلم في هذا الشأن أن ينصح الطلبة والطالبات وأن يقول لهم عليهم أن يتقوا الله وعليهم أن يؤدوا الواجب وعليهم أن يعينوا الأستاذ ويعينوا المدرسة على ما ينفعهما على ما ينفع الطلبة على هذا ..... ينبغي، وعلى المعلم وعلى المدرسة أن يقوم بالواجب من التأديب عند تمرد الطالب أو الطالبة وعند عدم اكتراث الطالب والطالبة بما يوجهه إليه الأستاذ أو المدرسة هذا هو الواجب على من يتكلم في الصحافة أن يكون مع هؤلاء ومع هؤلاء.\nينصحوا الطلبة والطالبات ويأمروا الجميع بتقوى الله والعناية بالطلب والحرص على أداء الواجب وأن يقوم بما وكل إليه وأن يعد ما ينبغي أن يعده وأن يحرص ويبذل بوسعه وعلى المعلم وعلى المعلمة أن ينظرا في ذلك فإذا ظهر لهما من الطالب أو من الطالبة أنهما مقصران وأنهما لم يبذلا الواجب فإنهما يؤدبان أما لو كان الأمر بخلاف ذلك يعني كان الطالب مغفل ما فيه حيله أو المطلوب يعجز عنه مثله لصغر سنه وعدم تحمل هذا الشيء فينبغي لهم أن يقدروا ذلك وأن ينصحوا الجهات المختصة بأن تخفف هذا المقرر وتعوض عنه مقرراً آخر أو تحذف ما يشق على الطالب ولا يتحمله الطالب لأن الطالب له قدرة محدودة فلابد من كون المعلم أو المعلمة ينظران في هذا الأمر فلا يحملان الطالب ما لا يحتمل ولا يحملا الطالبة ما لا تحتمل ولكن يكونان مع الطالبة في الأمر الموافق ومع الطالب في الأمر الموافق ويقومان عليه في الأمر الذي يريان أنه مقصر فيه هذا هو الواجب لا هذا ولا هذا، لا الغلو في الأمر حتى يؤدب كل أحد ولا التقصير حتى لا يؤدب كل أحد ولكن من استحق التأديب يؤدب.\nومن كان لا يقوى وليس مثله يقوى فهو يعني يعامل بطرق أخرى من النصيحة أو العناية بالجهات المختصة حتى تخفف وتزيل العقبة التي لا يتحملها هذا الطالب أو هذه الطالبة المقصود المعلم طبيب والمعلمة طبيبة لابد أن ينظرا في الأمر فيؤدبا حيث يكون التأديب في محله ويتوقفا عن التأديب حيث لا يكون في محله. نعم.","link":"https://binbaz.org.sa/fatwas/5991/حكم-ضرب-المعلم-للطالب-على-اهماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_106/10607.mp3","categories":["العالم والمتعلم","تربية الأولاد","الدعوة والدعاة"]},{"id":8223,"question":"أختنا تقول: إنها تقتني بعض الكتب، وذكرت منها: الإسراء والمعراج، ورياض الصالحين، ورجال حول الرسول ﷺ، وترغب أن تتفضلوا بدلالتها على كتب أخرى تفيدها في شئون دينها لو تكرمتم سماحة الشيخ؟","title":"كتب ينصح باقتنائها","answer":"الجواب: أما رياض الصالحين فهو كتاب نفيس وطيب، ونوصي بأن يقتنيه كل أحد لما فيه من الفائدة العظيمة، أما الإسراء والمعراج فهو كتاب ليس بشيء ولا ينبغي اقتناؤه ولا يعتمد عليه، وأما ما يتعلق برجال حول الرسول ﷺ فلم أقرأه ولا أستطيع أن أحكم عليه، ولكن نوصي أختنا المرأة السائلة نوصيها بكتب أخرى.. كتاب الصحيحين، صحيح البخاري ومسلم يكونان عندها؛ لأنهما كتابان عظيمان وهما أصح الكتب بعد كتاب الله، ونوصيها بتفسير ابن كثير ؛ فإنه كتاب عظيم مفيد، ونوصيها بزاد المعاد لـابن القيم في هدي خير العباد كتاب عظيم ومفيد، ونوصيها بفتح المجيد للشيخ عبد الرحمن بن حسن حفيد الشيخ محمد بن عبد الوهاب ، مع كتاب التوحيد مع العقيدة الواسطية وشرحها للهراس أو غيره، كل هذه كتب مفيدة. نعم.\nالمقدم: طيب. بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6035/كتب-ينصح-باقتناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09608.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8304,"question":"سؤاله الثاني يقول: إن والدتي عندما تقرأ آيات من كتاب الله غيباً؛ لأنها لا تعرف القراءة ولا الكتابة إنما حفظت بعض الآيات من القرآن الكريم في صغرها، وعندما تقرأ الآن تخطئ في كثير من المرات، فمثلاً: في آية الكرسي تقول: وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ فتزيد الواو، وفي قوله تعالى: وَلاَ يَؤُودُهُ حِفْظُهُمَا فتزيد فيها واو، فنعلمها ولكن بدون جدوى، هل تمتنع من القراءة أم ماذا نفعل؟","title":"هل تمتنع من القراءة من لا تحسن الحفظ؟","answer":"الجواب: لا تمتنع، لكن علموها علموها واجتهدوا واصبروا، كونوا صابرين معلمين مرشدين معينين لها على الخير، فهي مجتهدة وطالبة للخير، وقد قال النبي ﷺ في الحديث الصحيح: الماهر في القرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق ويتتعتع فيه وهو عليه شاق له أجران فالمتتعتع قد يغير حرفاً، وقد يبدل حرفاً، يريد الخير، فعليك أن تعلمها وأن تحسن إليها، وأن تصبر وتكرر عليها الألفاظ بأسلوب حسن برفق وتواضع حتى تقتنع وحتى يذل لسانها لهذا الأمر، وحتى تدع زيادة الواو، هذه الزيادة سهلة سقوطها سهل، لكن عليك أن تصبر لا تعنف ولا تشدد، فعليك بالحلم والصبر وعند ذلك يزول الخطأ إن شاء الله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6123/هل-تمتنع-من-القراءة-من-لا-تحسن-الحفظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/201006.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8333,"question":"لدي كتاب يسمى (ضياء الصالحين) فيه جميع الصلوات والتسابيح والأدعية.. إلى آخره لجميع الأيام والشهور، ولكل يوم توجد صلاة اليوم والليلة وأنا أصليها جميعها دون استثناء، فهل ما جاء في هذا الكتاب صحيح؟ وهل صلاتي صحيحة، أفيدونا أفادكم الله؟","title":"تقييم كتاب: ضياء الصالحين","answer":"الجواب: لا أعرف هذا الكتاب، ولا أدري عما فيه، والذي فيه يعرض على ما جاءت به الشريعة، يعرض على أحاديث النبي ﷺ فإن وافق ما جاء في الأحاديث من صفة الصلوات فلا بأس، فإن كثيراً من الناس قد يجمع أحاديث لا تصح عن النبي صلى الله عليه وسلم، إما موضوعة وإما ضعيفة.\nفإذا رأيت إرساله نظرنا فيه، والآن أقول لك: إن هذا الكتاب وأشباهه يعرض على الكتب الصحيحة كـالبخاري ومسلم صحيح البخاري وصحيح مسلم ، والكتب الأخرى الصحيحة كـأبي داود والنسائي والترمذي وابن ماجة يعني ما صح فيها، وهكذا رياض الصالحين فيه الأحاديث الصحيحة والضعيف فيه قليل، فهذا الكتاب الذي لديك تعرض الأحاديث التي فيه على الأحاديث الصحيحة، وما أشكل عليك تبينينه لأهل العلم حتى يجيبوك عنه، الحديث الفلاني والحديث الفلاني حتى يستطيع أهل العلم أن يجيبوك على سؤالك. نعم.","link":"https://binbaz.org.sa/fatwas/6146/تقييم-كتاب-ضياء-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11104.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8340,"question":"سماحة الشيخ! لعله من تحصيل الحاصل أن أنبه إلى السنة الحسنة التي اتبعتها الرئاسة العامة لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد في المملكة وهي: إعلان التلفونات حتى يتصل الناس بمن يريدون استفتاءه عن أمر من الأمور.","title":"حكم استحباب الإعلان عن هواتف العلماء والإدارات العلمية للاستفتاء","answer":"الشيخ: صحيح هذا طيب.\nالمقدم: لعل استحسان هذا في الرئاسة أيضاً يجعله معمولاً به في جهات أخرى؟\nالشيخ: إعلام التلفون طيب، لأن الناس يحتاجون إلى هذا في أوقات لا يتيسر لهم سماع مثل برنامج نور على الدرب، أو ما تيسر لهم إرسال السؤال أو ما أشبه ذلك.\nفالحاصل أنه يعرض للناس حاجات يحتاجون فيها إلى تلفونات العلماء حتى يسألوهم وهذا طيب.\nالمقدم: بارك الله فيكم، إذاً هذا تدعون إلى أن يكون سنة في كل بلدان المسلمين؟\nالشيخ: نعم، ونحن نعلن بهذا أيضاً؛ لأنه ينبغي أن تعلنوه للناس ونعلن الآن تلفون المنزل: (4534444).\nالمقدم: طيب.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم، هذا بالنسبة لبيت سماحة الشيخ عبد العزيز بن باز في الرياض؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيراً.\nالشيخ: ويوجد تلفون آخر: (4351421) هذا التلفون الآخر: (4351421).\nالمقدم: حزاكم الله خيراً.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6157/حكم-استحباب-الاعلان-عن-هواتف-العلماء-والادارات-العلمية-للاستفتاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_112/11203.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8394,"question":"الواقع سماحة الشيخ، تعددت الفتاوى، وتعدد المفتون في كثير من المجلات والصحف في الداخل والخارج، ولابد لسماحة الشيخ من كلمة توجيهية حول هذا الموضوع، بالنسبة للقراء، وبالنسبة لأولئك الذين يتعاطون الفتوى؟","title":"نصائح قيمة للمفتي والمستفتي","answer":"الجواب: نصيحتي للقراء أن لا ينجرفوا مع كل مفت، وأن يعرضوا فتاوى الناس على كلام الله، وكلام رسوله عليه الصلاة والسلام، وأن يعظموا ما عظمه الله ورسوله، وأن ينتهوا عما نهى الله عنه ورسوله، وأن يسألوا أهل العلم المعروفين بالاستقامة والغيرة الإسلامية والعلم الشرعي، وأن لا ينجرفوا مع كل فتوى، بل عليهم أن يتثبتوا وأن يحذروا؛ حتى لا يقعوا في الباطل.\nأما وصيتي ونصيحتي للمفتين، فعلينا جميعاً تقوى الله، وأن لا نفتي إلا بما يوافق الحق، وأن نحذر التساهل أو الميل إلى أهواء الناس وما يرضيهم، فإن الناس أكثرهم لا يرضيه إلا الباطل، فالواجب على المفتي أن يتقي الله، وأن يخاف الله، وأن يراقب الله، وأن لا يفتي إلا بما يظهر له من كلام الله وكلام رسوله عليه الصلاة والسلام، بعد التثبت، وبعد النظر والعناية، وبعد مراجعة أهل العلم، والاستعانة بما ذكروه في كتبهم، حتى تكون الفتوى على بينة، وعلى بصيرة، نسأل الله للجميع الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/6260/نصاىح-قيمة-للمفتي-والمستفتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11613.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":8395,"question":"سؤال أخير في هذه الحلقة، سماحة الشيخ! بالنسبة لاختلاف المفتين، هل من تعليق عليه؟","title":"اختلاف المفتين وكيفية معالجة هذا الخلاف","answer":"الشيخ: نعم، اختلاف المفتين لا بد منه، ..... من قديم الزمان، الفتوى لا بد من وقوع الاختلاف فيها، كما هو موجود في كتب أهل العلم، لكن الواجب على من ابتلي بأن يفتي الناس، أن ينظر في هذه الفتاوى، وأن يحرص على التماس الدليل الواضح، وأن يحذر التساهل بالفتوى، وإذا استطاع أن ينصح المفتين، وأن يقرب بينهم إذا كانوا في بلاده أو يستطيع مكاتبتهم، حتى تكون الفتوى متقاربة، وحتى تضيق شقة الخلاف، فهذا من أهم المهمات، ونسأل الله للجميع الهداية والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/6261/اختلاف-المفتين-وكيفية-معالجة-هذا-الخلاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11614.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":8406,"question":"منعاً للأحاديث الدنيوية في المساجد، هل يصح أن نستمع إلى برنامج نور على الدرب بدلاً من أحاديث بعض المصلين الفارغة؟","title":"حكم استماع برنامج نور على الدرب في المسجد","answer":"الجواب: الاستماع لهذا البرنامج فيه خير عظيم، وفيه مصالح جمة، وقد يسر الله للمسلمين هذا البرنامج يستفيدون منه حلقة علمية عظيمة، يستفيد منها الرجال والنساء وهم في بيوتهم، وفي مجالسهم، وعلى أسرتهم، فهي من نعم الله العظيمة، وهي حجة قائمة على الناس، هذا البرنامج حجة قائمة وصل إليهم في بيوتهم، وفي سياراتهم، وفي طائراتهم، وفي كل مكان، فالواجب على المسلمين أن يستفيدوا من هذا البرنامج، وأن يحمدوا الله ويشكروه على ما يسره لهم سبحانه وتعالى، وكان الناس يسعون للعلم من أماكن بعيدة إلى المساجد، وإلى العلماء في بيوتهم يطلبون العلم، وربما سافر الرجل من بلاد بعيدة إلى العالم يطلب منه فائدة، وسافر جابر بن عبد الله إلى الشام في حديث واحد، وسافر غيره إلى مصر في حديث واحد، وهم أصحاب النبي عليه الصلاة والسلام، فأنت يا عبد الله! وأنت يا أمة الله! يسر الله لكما هذا البرنامج من الأثير وأنتم في بيوتكم، أنتم في فرشكم، أنتم في مساجدكم، في أي مكان، هذه نعمة من الله عظيمة، فأنا أوصي وأنصح كل مسلم وكل مسلمة أن يستفيد من هذا البرنامج، وأن يسأل عما أشكل عليه، من طريق هذا البرنامج، وهذه نعمة من الله عظيمة يسرها للمسلمين، فأسأل الله أن يوفق القائمين على هذا البرنامج لإصابة الحق، وأن يعينهم على إبلاغ رسالة الله وأمره ونهيه للأمة في كل مكان، وأن يوفق المسلمين في كل مكان إلى أن يستمعوا هذا البرنامج ويستفيدوا منه، وإذا أشكل على أحد من ذلك شيء وتوقف في شيء فليعد السؤال، ويسأل أهل العلم في أي مكان حتى يطمئن، رزق الله الجميع التوفيق والهداية. نعم.\nالمقدم: سؤال أخينا لو تكرمتم سماحة الشيخ بالنسبة للاستماع إلى البرنامج في المساجد؟\nالشيخ: لا بأس الفتح، بالراديو في المسجد لسماع هذا البرنامج، أو لسماع العلم غير هذا البرنامج لا بأس به، فإذا جاءت الموسيقى أو جاء شيء لا يرضى يقفل، يقفل عما لا يرضى، ويفتح عن أهل العلم والقرآن ونحو ذلك.\nالمقدم: طيب، طيب.","link":"https://binbaz.org.sa/fatwas/6290/حكم-استماع-برنامج-نور-على-الدرب-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11712.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8477,"question":"أختنا أم الحسن تسأل مع المعلمات سماحة الشيخ اللائي يسألن عن ضرب الطالبات لغرض التعليم، ولغرض الحث على أداء الواجبات، وتقول: سبب الضرب هو حث الطالب أو الطالبة على أداء واجباتهم المطلوبة منهم، وتعويدهم على عدم التهاون فيها؟","title":"حكم ضرب الصغير للتعليم","answer":"الجواب: لا بأس في ذلك، المعلم والمعلمة والوالد كل منهم عليه أن يلاحظ الأولاد وأن يؤدب من يستحق التأديب إذا قصر في واجبه، حتى يعتاد الأخلاق الفاضلة وحتى يستقيم على ما ينبغي من العمل الصالح، ولهذا ثبت عنه ﷺ أنه قال: مروا أولادكم بالصلاة لسبعع واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع فالولد إذا كان يضرب وهكذا الأنثى تضرب إذا بلغ كل منهما العشر وقصر في الصلاة يؤدب حتى يستقيم على الصلاة، وهكذا الواجبات الأخرى في التعليم وفي شئون البيت وفي غير ذلك الواجب على أولياء الصغار من الذكور والإناث أن يعنوا بتوجيههم وتأديبهم لكن يكون ضرباً لا خطر فيه، ضرباً خفيفاً يحصل به المقصود من دون مضرة على الذكر والأنثى جميعاً. نعم.","link":"https://binbaz.org.sa/fatwas/6514/حكم-ضرب-الصغير-للتعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12504.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":8490,"question":"تسأل سماحة الشيخ عن الطالبات في الصف الأول والثاني والثالث وتقول: إنهن لا يؤدين الصلاة كما ينبغي؟","title":"ضرورة التوجيه والإرشاد عند تعليم الطلاب","answer":"الجواب: لا بد من التعليم لا بد من التوجيه للطالبات والطلبة جميعاً، .. على المعلم وعلى المعلمة التوجيه والإرشاد ليس المقصود التعليم فقط، مع التعليم أمر آخر، وهو التوجيه والإرشاد والتربية الصالحة فالمعلم يعلم الأولاد الصلاة ويعلمهم الأخلاق الفاضلة، ويحذرهم من الأخلاق الذميمة كالكذب والرياء والغيبة والنميمة والسب والشتم ونحو ذلك، فهكذا المعلمة تعلم الطالبات الأخلاق الفاضلة، وتحثهن على الصلاة وتحثهن على الأمانة وعلى حفظ اللسان عما لا ينبغي، هكذا ينبغي للمعلمة وهكذا ينبغي للمعلم، أن يكون تعليم معه إرشاد ومعه توجيه قولي وعملي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6549/ضرورة-التوجيه-والارشاد-عند-تعليم-الطلاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8565,"question":"يسأل ثانياً فيقول: عندما أقرأ القرآن أخطئ ولا أجيد القراءة في بعض الكلمات الصعبة، فما الحكم في ذلك؟","title":"حكم من يقرأ القرآن ويخطئ في بعض الكلمات","answer":"الجواب: يتعلم، عليك -أيها السائل- أن تتعلم وتجتهد، تقرأ على من هو أعلم منك، وتتهجى الكلمات، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق ويتتعتع فيه له أجران، يعني: لا يجيده جداً، بل يتتعتع، له أجران هذا فضل من الله عز وجل، إذا اجتهدت في تعلم القرآن وحرصت على ذلك، فأنت لك أجران، ولكن من الحرص ومن أسباب الإجادة للقرآن أن تقرأه على من هو أعلم منك، وأن تجتهد في ذلك، وأن تذاكر فيه مع زملائك الطيبين حتى تقوى قراءتك، وحتى تمهر فيه.\nوبكل حال فأنت مأجور، لكن ينبغي لك أن لا تبقى على الجهالة، بل ينبغي لك أن تتعلم من إخوانك الطيبين، من بعض القراء الجيدين، تدرس عليهم وتقرأ عليهم حتى تستفيد وحتى تزول العلة التي بك، وعدم إتقان القراءة. نعم.","link":"https://binbaz.org.sa/fatwas/6651/حكم-من-يقرا-القران-ويخطى-في-بعض-الكلمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20713.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8569,"question":"يسأل ثانياً فيقول: عندما أقرأ القرآن أخطئ ولا أجيد القراءة في بعض الكلمات الصعبة، فما الحكم في ذلك؟","title":"حكم من يقرأ القرآن ويخطئ في بعض الكلمات","answer":"الجواب: يتعلم، عليك -أيها السائل- أن تتعلم وتجتهد، تقرأ على من هو أعلم منك، وتتهجى الكلمات، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق ويتتعتع فيه له أجران، يعني: لا يجيده جداً، بل يتتعتع، له أجران هذا فضل من الله عز وجل، إذا اجتهدت في تعلم القرآن وحرصت على ذلك، فأنت لك أجران، ولكن من الحرص ومن أسباب الإجادة للقرآن أن تقرأه على من هو أعلم منك، وأن تجتهد في ذلك، وأن تذاكر فيه مع زملائك الطيبين حتى تقوى قراءتك، وحتى تمهر فيه.\nوبكل حال فأنت مأجور، لكن ينبغي لك أن لا تبقى على الجهالة، بل ينبغي لك أن تتعلم من إخوانك الطيبين، من بعض القراء الجيدين، تدرس عليهم وتقرأ عليهم حتى تستفيد وحتى تزول العلة التي بك، وعدم إتقان القراءة. نعم.","link":"https://binbaz.org.sa/fatwas/6651/حكم-من-يقرا-القران-ويخطى-في-بعض-الكلمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20713.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8629,"question":"هذه رسالة وردتنا من السائل: نفيع نافع الصحفي من وادي غران، يقول: أسأل عن تنوير المقباس من تفسير ابن عباس، ما صحة نسبته إليه ؟","title":"ما صحة نسبة كتاب: تنوير المقباس لابن عباس؟","answer":"الجواب: لم أقرؤه ولم يحصل لي دراسة له، فلا أحكم عليه بشيء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6768/ما-صحة-نسبة-كتاب-تنوير-المقباس-لابن-عباس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21109.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8729,"question":"إذا كان الفرقة بين الأبناء يسبب هذا سماحة الشيخ فما بالكم إذا ابتعدت المرأة عن بيتها وتركت أطفالها للخدم أو ما أشبه ذلك؟","title":"نصيحة حول ضرر ابتعاد الأم عن تربية الأولاد وتركهم للخادمة","answer":"الجواب: لاشك أن هذا يضر كثيراً ويجعل الولد ينشأ نشأة فيها نظر ولاسيما إذا كانت الخادمة ليست ذات دين فإن الأولاد ينشئون نشأة غير دينية وعليهم خطر من ذلك، فمن الأهم أن تتولى الأم تربية الأولاد التربية الإسلامية وأن تعطف عليهم وتحن عليهم وتواسيهم وتنظر في حاجاتهم وشئونهم وتقدم ذلك على الوظيفة ما دام الزوج يقوم بحالها وحاجاتها فلا حاجة إلى الوظيفة، قيامها بأولادها وتربية أولادها والإحسان إليهم وتوجيههم إلى الخير أهم وأهم وأهم من الوظائف التي تدر مالاً ليست في حاجة إليه ولا في ضرورة إليه، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/6881/نصيحة-حول-ضرر-ابتعاد-الام-عن-تربية-الاولاد-وتركهم-للخادمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_135/13502.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":8747,"question":"له سؤال ثالث وأخير يقول فيه: يسمي بعض الناس عندنا العلماء في المملكة العربية السعودية بالوهابية، فهل ترضون بهذه التسمية؟ وما هو الرد على من يسميكم بهذا الاسم؟","title":"التعريف بدعوة الشيخ محمد بن عبد الوهاب رحمه الله","answer":"الجواب: نعم هذا لقب مشهور هذا اللقب مشهور لعلماء التوحيد لعلماء نجد، ينسبونهم إلى الشيخ الإمام محمد بن عبد الوهاب رحمة الله عليه؛ لأنه دعا إلى الله  في النصف الثاني من القرن الثاني عشر واجتهد في إيضاح التوحيد وبيان الشرك للناس، حتى هدى الله به الجم الغفير، ودخل الناس في توحيد الله وتركوا ما هم عليه من أنواع الشرك الأكبر، من عبادة أهل القبور ومن البناء على القبور وعبادة الأشجار والأحجار والغلو في الصالحين، فصارت دعوته دعوة تجديدية إسلامية عظيمة نفع الله بها المسلمين في الجزيرة العربية وفي غيرها، رحمه الله رحمة واسعة، وصار أتباعه ومن دعا بدعوته ونشأ على هذه الدعوة في نجد يسمى بالوهابي، وكان هذا اللقب علماً على أهل التوحيد، كل من دعا إلى توحيد الله ونهى عن الشرك وعن التعلق بالقبور أو التعلق بالأشجار والأحجار وأمر بالإخلاص لله سموه وهابياً، فهو لقب شريف عظيم يدل على أن من لقب به من أهل التوحيد ومن أهل الإخلاص لله، وممن ينهى عن الشرك بالله وعن عبادة القبور والأشجار والأحجار والأصنام والأوثان. هذا هو أصل هذه التسمية وهذا اللقب.\nهو نسبة إلى الشيخ الإمام محمد بن عبد الوهاب بن سليمان بن علي التميمي الحنبلي الداعي إلى الله  رحمه الله رحمة واسعة، فقد نشأ في نجد وتعلم في نجد ثم سافر إلى مكة والمدينة وأخذ عن علمائها من أهل السنة ثم رجع إلى نجد فرأى ما الناس فيه من الجهل وعبادة القبور والغلو فيها والشرك بالله  ودعاء الأموات والاستغاثة بهم والبناء على قبورهم، فدعا إلى الله وأرشد الناس ونهاهم عن الشرك، وبين لهم أن التوحيد هو حق الله جل وعلا على عباده وأنه الذي دعت إليه الرسل عليهم الصلاة والسلام، وبين لهم معنى، لا إله إلا الله وأن معناها: لا معبود حق إلا الله، فهي نفي وإثبات تنفي الإلهية عن غير الله وتثبت العبادة لله وحده سبحانه وتعالى، كما قال : ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62].\nقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] قال : وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ [الأنبياء:25] قال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] قال : فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14] قال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]\nفالشيخ رحمه الله محمد بن عبد الوهاب قام بهذه الدعوة في النصف الثاني من القرن الثاني عشر وكان ذلك في العيينة وهي بلدة قريبة من الرياض دعا إلى الله فيها ونشر التوحيد وصارت عنده حلقة عظيمة في التعليم، ثم انتقل لأسباب معروفة إلى الدرعية وتلقاه أميرها محمد بن سعود وبايعه على الدعوة إلى الله عز وجل وعلى نشر الإسلام في الدرعية وما حولها، فنفع الله بذلك وتعاون الشخصان الشيخ محمد بن عبد الوهاب والشيخ محمد بن سعود جد العائلة المالكة الآن، فتعاونا في سبيل الدعوة وكان ذلك في عام ثمان وخمسين ومائة وألف في عام ألف ومائة وثمان وخمسين، هذا بدء الدعوة في الدرعية بعد أن انتقل من العيينة فانتشر الإسلام هناك وأزيلت القباب التي على القبور وانتشر التوحيد بين الناس وعرفوا حقيقة معنى: لا إله إلا الله، ثم قامت دولة آل سعود في بقية الجزيرة وانتشر أمر التوحيد في أطراف الجزيرة، فنفع الله بهذه الدعوة نفعاً عظيماً وظهر بها الحق وانتصر بها أهل التوحيد وصارت علماً لأهل التوحيد في كل مكان، ثم انتشر هذه الدعوة أيضاً في اليمن وفي جهات كثيرة من الهند وغير الهند والشام والعراق ومصر، وتلقاها أئمة الهدى وعلماء الحق بالقبول، وساعدوا الشيخ محمد رحمه الله ودعوا بدعوته وخالفه آخرون ممن غلب عليهم الجهل أو غلب عليهم التقليد لآبائهم وأسلافهم أو غلب عليهم الهوى والتعصب لما هم عليه، لئلا يقول الناس: ليش ما علمتونا ليش ما نبهتمونا؟ فعادوا هذه الدعوة وكتبوا كتابات باطلة، ولكن نصر الله الدعوة وأهلها واستقام أمر التوحيد في الجزيرة وانتشر أمر الله بحمد الله، فصار أتباع هذه الدعوة ومن يدعو إلى توحيد الله من علماء التوحيد من علماء نجد يلقب بالوهابي، فهو لقب معروف شريف وليس بالمستنكر بل هو لقب لأهل التوحيد والإيمان، لأهل الدعوة إلى الله عز وجل وهكذا انتشر هذا اللقب.\nإذا رأوا من يدعو إلى الله ويبين حقيقة التوحيد وينهى عن الشرك في أفريقيا أو في الشام أو في اليمن أو في جهات أخرى، إذا رآه بعض الغلاة وبعض المنحرفين، قالوا: هذا وهابي حتى ينفروا الناس عن دعوته وحتى يظن الناس أن هذه الدعوة دعوة باطلة أو دعوة مخالفة لشرع وهو غلط قبيح ومنكر بل هي حقيقة ما دعا إليه الرسول ﷺ، فإن الرسول ﷺ دعا إلى توحيد الله، وهكذا الرسل جميعاً كلهم دعوا إلى توحيد الله ونشروا دين الله عليهم الصلاة والسلام، كما قال تعالى: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36].\nفهذه دعوة الرسل عليهم الصلاة والسلام جميعاً وهي دعوة نبينا وإمامنا وسيدنا محمد بن عبد الله عليه الصلاة والسلام، هو دعا إلى توحيد الله وقام في مكة بالدعوة، وصار المشركون يسمون من أجاب دعوته صابي كما يقال للموحد الآن وهابي.\nفمن أجاب دعوة محمد ﷺ في مكة قال له: صابي، وهكذا بعد ما هاجر لكن الله نصر الدعوة وأيد نبيه محمد ﷺ، وانتشرت الدعوة في مكة وفيما حولها ثم هاجر عليه الصلاة والسلام إلى المدينة وانتصرت الدعوة وقام سوق الجهاد وصارت المدينة معقل الإسلام ومدينة الإسلام والعاصمة الأولى للإسلام والحمد لله.\nوالمقصود من هذا كله أن هذه الدعوة وهذا اللقب لقب لمن دعا إلى توحيد الله، من دعا إلى توحيد الله وأنكر الشرك يسميه بعض الجهلة وهابي لجهلهم بالحقيقة وعدم علمهم بالحقيقة، والحقيقة هي ما ذكرنا أنها دعوة عظيمة إلى توحيد الله وإلى اتباع رسول الله ﷺ وعدم التقليد الأعمى والتعصب الأعمى وعدم البدع والخرافات وعدم الشرك والتعلق بالأموات والأشجار والأحجار أو بالأنبياء والصالحين أو بالأصنام فهذه الدعوة تحارب هذا الشرك، وتدعو إلى توحيد الله والإخلاص له والإيمان بمعنى: لا إله إلا الله وتحقيقها، وتحقيق اتباع الرسول ﷺ والتمسك بسنته وطريقه والاستقامة على ذلك.\nهذه هي دعوة الشيخ محمد رحمه الله. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6899/التعريف-بدعوة-الشيخ-محمد-بن-عبد-الوهاب-رحمه-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8748,"question":"هذه رسالة من المرسل: (م. ق. ل) من جيزان يقول: هناك رجل طالب علم يصلي ويصوم ويتصدق، لكن مع الأسف قد هجر أمه فهل صلاته وصومه وصدقته تنفعه، وهو هاجر لأمه لا يلتفت إليها وهي مؤمنة تصلي وتصوم ونحن نعرفها بذلك؟","title":"نصيحة لطالب علم عاق لوالدته","answer":"الجواب: على كل حال هجره لأمه منكر وعقوق عظيم يجب عليه التوبة إلى الله من ذلك، وعليه أن يرجع إلى برها والإحسان إليها والأخذ بخاطرها واستسماحها، هذا الواجب عليه، وليس له أن يبقى على الهجر وعلى العقوق بل هذا منكر عظيم وكبيرة عظيمة، يجب عليه تركها واستسماح والدته وطلب رضاها والتوبة إلى الله من ذلك ﷺ.\nأما صلاته وصومه وعباداته فلا تبطل بل عباداته صحيحة وأعماله صحيحة، إذا أداها على الوجه الشرعي ولكن يكون إيمانه ضعيفاً، يكون إيمانه ناقصاً بهذه المعصية، فإن المعاصي عند أهل السنة تنقص الإيمان وتضعف الإيمان ولكن لا تكفر صاحبها، إنما يكفر عند الخوارج ، الذين يكفرون بالذنوب وهم ظلمة فجرة في هذا قد أخطئوا وغلطوا عند أهل السنة والجماعة .\nوأما أهل السنة فيقولون: لا، المعصية تنقص الإيمان ولكن لا يكون صاحبها كافراً ولا مخلداً في النار، بل هو عاصي ومعصيته تنقص إيمانه تضعف إيمانه، تسبب غضب الله عليه وعلى خطر منها من دخول النار، ولكن لا يكون كافراً حتى ولو دخل النار لا يخلد فيها، هكذا أهل التوحيد -عند أهل السنة والجماعة - لا يخلدون في النار إذا دخلوها بمعاصيهم.\nفالحاصل أن هجر أمه معصية وكبيرة وعقوق، ولكن لا يكون ذلك من أسباب كفره ولا بطلان عمله، إلا إذا استحل ذلك، ورأى أن عقوق الوالدين حلال هذا يكون كافر -نعوذ بالله- من استحل عقوق الوالدين وأنه حلال أو استحل الربا ورأى أنه حلال أو استحل الزنا ورأى أنه حلال، هذا يكون كافر مرتد عن الإسلام إلا أن يكون مثله يجهل كالبعيد عن الإسلام الذي نشأ في بلاد بعيدة عن الإسلام يعلم فإذا بين له أن هذا مما فرضه الله بر الوالدين مما فرضه الله، وأن عقوقهما مما حرم الله إذا علم وبين له ثم أصر يكون كافراً نعوذ بالله.\nالمقدم: هذا طالب علم يا شيخ!\nالشيخ: إذا كان طالب علم على كل حال تكون كبيرته أشد، نسأل الله العافية.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6902/نصيحة-لطالب-علم-عاق-لوالدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21607.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8752,"question":"له سؤال ثالث يقول فيه: ورد في الحديث: اتقوا الله واعدلوا بين أولادكم فهل المقصود المساواة المطلقة أو أن للذكر مثل حظ الأنثيين أسوة بالميراث، فالحديث على ما أظن يقول: أكلهم أعطيته مثل فكلمة: (مثل) إن صحت توحي بالمساواة المطلقة، اللهم إن كان يتكلم عن الذكور فقط أفيدونا أفادكم الله؟","title":"العدل بين الأولاد وحكم تفضيل بعضهم على بعض","answer":"الجواب: الحديث صحيح رواه الشيخان عن النعمان بن بشير رضي الله تعالى عنه: أن أباه أعطاه غلاماً فقالت أمه: لا أرضى حتى يشهد رسول الله عليه الصلاة والسلام، فذهب بشير بن سعد إلى النبي ﷺ، وأخبره بما فعل فقال: أكل ولدك أعطيته مثل ما أعطيت النعمان؟ قال: لا، فقال: اتقوا الله واعدلوا بين أولادكم.\nفدل ذلك على أنه لا يجوز تفضيل بعض الأولاد على بعض بالعطايا كلهم ولده وكلهم يرجى بره فلا يجوز أن يخص بعضهم بالعطية، واختلف العلماء رحمة الله عليهم هل يسوى بينهم ويكون الذكر كالأنثى أم يفضل الذكر على الأنثى كالميراث؟ على قولين لأهل العلم: والأرجح أن العطية تكون كالميراث وأن التسوية تكون بجعل الذكر كالأنثيين، فإن هذا هو الذي جعله الله له في الميراث، وهو سبحانه الحكم العدل، فيكون المؤمن في عطيته لأولاده كذلك، كما لو خلفه لهم بعد موته للذكر مثل حظ الأنثيين فهكذا إذا أعطاهم في حال حياته يعطى الذكر مثل حظ الأنثيين، هذا هو العدل بالنسبة إليهم وبالنسبة إلى أمهم وأبيهم، وهذا هو الواجب على الأب والأم أن يعطوا الأولاد هكذا للذكر مثل حظ الأنثيين، وبذلك يحصل العدل والتسوية كما جعل الله ذلك عدلاً في إرثهم من أبيهم وأمهم والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6905/العدل-بين-الاولاد-وحكم-تفضيل-بعضهم-على-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21703.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":8847,"question":"من حائل هذه هي الرسالة الثانية لأحد الإخوة من هناك يقول: (ع.ش.ح) أخونا مهتم ببعض الفتاوى التي تطبعها بعض المجلات، والواقع أخذ صورة من تلك المجلة وبعث بها، ويرجو أن تتفضلوا بمناقشة ما ورد من فتاوى في تلك المجلة، رأي سماحة الشيخ في هذا؟","title":"الفتاوى التي تطبعها بعض المجلات","answer":"الشيخ: لا مانع، نطلع عليها إن شاء الله ونجيبه.\nالمقدم: بارك الله فيكم، إذًا: لا داعي لعرضها في البرنامج هنا؟\nالشيخ: لا داعي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7002/الفتاوى-التي-تطبعها-بعض-المجلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16504_02.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8854,"question":"من جمهورية تشاد رسالة وصلت إلى البرنامج من الأخ فيزاني محمد من مدينة أبشا فيما يبدو، أخونا رسالته كلها ثناء وتقدير على هذا البرنامج، ويسأل عدة أسئلة عن البرنامج الذاتي من بينها أسئلة حول طباعة البرنامج، هل أخذتم بذلك أو لا؟","title":"مقترح بطباعة برنامج نور على الدرب","answer":"الجواب: سيطبع إن شاء الله، ستطبع الجوابات التي فيه من جميع المشايخ وسوف تنظم إن شاء الله وتوزع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7009/مقترح-بطباعة-برنامج-نور-على-الدرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16611.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8883,"question":"إذا أراد الوالد أو الوالدة أو الوالدان جميعاً لأبنائهما الفرح والسرور بم ينصحونهم لو تكرمتم سماحة الشيخ؟","title":"سبل إسعاد الأبناء","answer":"الجواب: يستعملون ما يسرهم من الأحاديث الطيبة، من الذهاب بهم إلى البساتين الطيبة، إلى الأرض الطيبة إذا كان عندهم بستان طيب، إذا كان في محل طيب يذهبون إليه ليس فيه منكر، يشترون لهم حاجات تسرهم مثل أشرطة إسلامية تنفعهم يعني فيها الخطب الطيبة والمواعظ الطيبة، والأشعار المفيدة الداعية إلى الخير وإلى ترك الشر، وما أشبه ذلك مما يسر أولادهم وينفع أولادهم من دون أن يوقعهم في المحرمات، أهل الخير يلتمسون طرق الخير التي تشرح الصدور وتنير القلوب، ويحصل بها المتعة الحسنة ويحصل بها الأنس دون ما حرم الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7039/سبل-اسعاد-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13909.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":8900,"question":"من البصرة الأخت سميحة عمار تسأل مجموعة من الأسئلة من بينها سؤال عن أخت لها تقول: إنها في العقد الخامس من عمرها، ولها ابن لشدة حبها له تتغاضى كثيرًا عن مخالفاته لأمر دينه ولأمور تتعلق بالأخلاق، وتقول: إن ذلك شأن كثير من الوالدات وبعض الآباء وترجو التوجيه في هذا لو تكرمتم؟","title":"وجوب الأمر بالمعروف والنهي عن المنكر للقريب والبعيد","answer":"الجواب: الواجب على المسلم أن يتقي الله في نفسه وفي أهل بيته وفي جيرانه وفي كل المسلمين، وذلك بدعوتهم إلى الله وأمرهم بالمعروف ونهيهم عن المنكر وأن لا تأخذه في الله لومة لائم ، هذا هو الواجب على كل مسلم، فلا يدع الأمر بالمعروف والنهي عن المنكر من أجل قرابة قريب أو محبة شخص بل من حبه له ومن صلته له الحقيقية التي يؤجر عليها أن يأمره بالمعروف وينهاه عن المنكر، كما قال : وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَى [الأنعام:152] فالواجب على المؤمن أن يتقي الله ويؤدي الحق الذي عليه وإن كان مع القريب، يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَى أَنفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالأَقْرَبِينَ إِنْ يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَاللَّهُ أَوْلَى بِهِمَا [النساء:135].\nفالواجب على المؤمن أن ينكر المنكر وأن يأمر بالمعروف مع الأقرباء وغيرهم، وأن ينصح قريبه وغير قريبه، وإذا كان قريبًا له فمن أهم المهمات أن ينصحه وأن يوجهه هذا أعظم من صلته بالمال فإذا كان يصله بالمال ويؤجر على صلة الرحم فكونه يصله بتوجيهه إلى الخير وتعليمه الخير وأمره بالمعروف ونهيه عن المنكر هذا أهم من صلة المال، وهذا ينفعه في الدنيا والآخرة، فليس لهذه المرأة ولا لغيرها أن تدع الأمر بالمعروف والنهي عن المنكر لحبها لولدها أو ابن أخيها أو ابن أختها أو غيرهم بل يجب أن تأمر بالمعروف وتنهى عن المنكر بالطرق التي تراها مفيدة ومجدية، وبالأساليب الحسنة حتى تنجح إن شاء الله في عملها.\nالمقدم: إذًا: من التربية الحسنة من الرأفة بالأبناء إنكار المنكر عليهم ..؟\nالشيخ: نعم.. نعم، لكن بالأساليب التي تراها مفيدة لا بالعنف والشدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7056/وجوب-الامر-بالمعروف-والنهي-عن-المنكر-للقريب-والبعيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_168/16802.mp3","categories":["العالم والمتعلم","تربية الأولاد","الدعوة والدعاة"]},{"id":8935,"question":"حياكم الله، شيخ عبدالعزيز! أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من دولة الكويت الديوان الأميري وباعثها أخونا: فايز موسى أبو شيخة أخونا نص رسالته كما يلي: فضيلة الشيخ: عبد العزيز بن باز المحترم. السلام عليكم ورحمة الله وبركاته.بعد حمد الله الحمد الكثير، والصلاة والسلام على حبيبنا محمد صلى الله عليه وسلم أضع بين يديكم ما يلي:إنني أستمع إلى برنامجكم نور على الدرب من فترة ليست بالقليلة ثم وجدت نفسي متابعاً له بشكل منتظم، ثم وجدت ما فيه من علم نافع لا حدود له في شتى مجالات العلوم الشرعية التي لا يستغني عنها أحد، واتضح لي أن عدداً قليلاً جداً هو من يتابع هذا البرنامج في الإذاعة أو يجد الحماس للاستماع إلى الأشرطة لأسباب متعددة، بينما يمكنه إذا توفر ذلك في كتاب أن يعود إليه بسهولة وفي أي وقت وعلى أي موضوع.وعليه: فقد بادرت بكتابة الفتاوى بعد تسجيلها بدقة وأمانة وتكون لدي الآن مجموعة كبيرة من الفتاوى للعلماء الأفاضل في السعودية، وحرصاً مني على أن لا تبقى هذه الفتاوى على أوراق دفاتري فإني على استعداد لطبعها وتوزيعها بحيث تصل إلى كثيرين وبسعر رمزي، وإنني على ثقة بعون من الله من صحة ما كتبته ودقته؛ لأنها أمانة علمية في النقل وعلى استعداد لعرضه على فضيلتكم الآن وقبل الطبع النهائي، أو عرضها على أحد العلماء الموثوق بهم هنا في الكويت.المهم: أن هذه المعلومات القيمة والفتاوى الشرعية التي تحوي الفائدة العظيمة تتوزع إلى مناطق تنتشر فيها البدع والمحدثات البعيدة عن السنة فتعمل بها إلى ما يعيدها للحق إن شاء الله وبعونه.إن لنا أملًا كبيرًا في الله ثم بكم للموافقة على طبع هذه الفتاوى حتى يعم العلم وتتوسع المعرفة ويكون لكم إن شاء الله ولبقية العلماء الثواب الكبير ولنا ولمن يساهم بالنشر والتوزيع.كما أكرر عهدي بأن يكون ما يطبع هو ما قيل على ألسنة فضيلتكم موضوعاً متكاملاً وفتاوى دقيقة، إنني أخشى الله سبحانه وتعالى وأعلم عاقبة الأخطاء في هذا العمل؛ ولذلك سأكون حريصاً على تعدد المراجعة.أكرر دعائي لله  كما دعوته من قبل أن يتم هذا العمل وأن يمنحكم الصحة والعافية، ويوفقنا لمتابعة هذه الفتاوى والقدرة على إتمامها حتى نلقى الله تعالى بعلم ينتفع به، والله يجعل فيكم الخير الدائم والبركة. إن أملي بالله ثم بكم أن تتكرموا بالرد كتابة وفي البرنامج حتى يكون عملنا صحيحاً مع العلم بأنني لن أقدم على طباعة شيء إذا رفضتم ذلك ولم توافقوا عليه؟","title":"طلب الإذن بطبع فتاوى نور على الدرب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإني أشكر السائل على همته العالية ورغبته في العلم، وأسأل الله لك يا أخي المزيد من كل خير وأن يمنحنا وإياك العلم النافع والعمل الصالح، ثم أخبرك أنه ليس عندي مانع من طبع ما يتعلق بي من الفتاوى التي تنشر من طريق هذا البرنامج؛ لأن في ذلك منفعة إن شاء الله للجميع، ولكني أقول: إنه لابد من إرسالها إلي حتى تراجع حذراً من شيء من الخطأ، فإذا رأيتم إرسالها إلي قبل الطبع فهذا هو الذي أرى وبعد ذلك نعيدها إليكم إن شاء الله في وقت قريب، حتى نطمئن إلى صحة الموجود وعدم الخطأ، مع العلم أيضاً بأني عازم على طبع جميع الفتاوى التي تصدر من طريق هذا البرنامج والفتاوى الأخرى التي قد صدرت وتصدر منا في جهات أخرى ومن طرق أخرى، كالفتاوى التي تصدر منا كتابياً في الصحف وغيرها أو للسائلين من طريق الكتابة، وهكذا ما يصدر منا من المؤلفات الصغيرة التي نكتبها في بعض المواضيع، كل هذا سوف يجمع وسوف ينشر إن شاء الله للمسلمين، والآن نحن ساعون في ذلك والمجلد الأول سوف يصدر قريباً ويوزع إن شاء الله، والمجلد الثاني في الطريق إن شاء الله، وهكذا بقية الفتاوى سوف تصدر إن شاء الله تباعاً مطبوعة توزع على المسلمين من طريق دار الإفتاء ومن طريق البيت جميعاً، ولكن لا مانع عندي من طبع أيضاً ما يصدر من هذا البرنامج بواسطة إخواننا في الله، لكن بعد العناية وبعد إرساله إلي لمراجعته، وفق الله الجميع. نعم.","link":"https://binbaz.org.sa/fatwas/7093/طلب-الاذن-بطبع-فتاوى-نور-على-الدرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_144/14401.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8971,"question":"أخت لنا من الخبر رمزت إلى اسمها بالحروف (م. م. س) لم تسأل إلا عشرة أسئلة فقط، تسأل في سؤال لها وتقول: قال رسول الله ﷺ: من كانت له ثلاث بنات فصبر عليهن وسقاهن وكساهن كن له حجاباً من النار،  هل يكن حجاباً من النار لوالدهن فقط أم حتى الأم شريكة في ذلك، وإن عندي ولله الحمد ثلاث بنات؟","title":"فضل البنات والصبر على تربيتهن","answer":"الجواب: هذا عام، يقول ﷺ: من ولي ابنتين فأحسن إليهن كن له ستراً من النار، وهكذا لو كن أخوات أو عمات أو خالات ونحو ذلك المعنى واحد، فإذا كان ابنتان أو أختان أو عمتان أو نحو ذلك فإن المعنى واحد إذا أحسن إليهما أو كانوا أكثر من ثنتين كالثلاث والأربع ونحو ذلك من باب أولى، فإنه متى أحسن إليهن فإنه بذلك يستحق الأجر العظيم، وأن يحجب من النار ويحال بينه وبين النار لعمله الطيب، وهذا في المسلمين، هذه من أعمال المسلمين، فالمسلم الذي يعمل هذه الخيرات يكون قد تسبب في نجاته من النار، والنجاة من النار ودخول الجنة لها أسباب كثيرة فينبغي للمؤمن أن يستكثر منها، فالإسلام نفسه هو السبب الوحيد هو الأصل هو الأساس في دخول الجنة والنجاة من النار.\nوهناك أعمال إذا عملها المسلم موعود بالجنة والنجاة من النار، مثل من رزق بنات أو أخوات فأحسن إليهن كن له ستراً من النار، مثل من مات له أفراط لم يبلغوا الحنث كانوا له حجاباً من النار، قال النبي ﷺ: من مات له ثلاثة أفراط كانوا له حجاباً من النار، قالوا: يا رسول الله! أو اثنين؟ قال: أو اثنين، ولم يسألوه عن الواحد، وجاء عنه ﷺ أنه قال: يقول الله : ما لعبدي المؤمن جزاء إذا أخذت صفيه من أهل الدنيا فاحتسبه إلا الجنة.\nفبين سبحانه وتعالى أن ليس لعبده المؤمن عنده جزاء إذا أخذ صفيه يعني: محبوبه من أهل الدنيا فصبر واحتسب إلا الجنة، فالواحد من ذلك يدخل في هذا، الواحد من أولاده إذا أخذه الله قبضه فاحتسب وصبر فله الجنة، فهذا فضل عظيم، هكذا زوجته وهكذا أخوه وهكذا أبوه إلى غير ذلك. نعم.\nالمقدم: بارك الله فيكم، وجه هذا الإحسان، أو وجوه هذا الإحسان لو تكرمتم؟\nالشيخ: الوجوه كثيرة، فيكون من ذلك: الإحسان إلى البنات بتربيتهن التربية الإسلامية وتعليمهن وإرشادهن، والحرص على عفتهن أو بعدهن عما حرم الله من التبرج وغيره، تربية الأخوات كذلك، أو الأولاد الذكور كذلك إلى غير ذلك من وجوه الإحسان حتى يتربى الجميع على طاعة الله ورسوله والبعد عن محارم الله والقيام بحق الله سبحانه وتعالى.\nالمقدم: بارك الله فيكم، إذاً ليس هو المقصود الأكل والشرب والكسوة فقط؟\nالشيخ: الدين أعظم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7129/فضل-البنات-والصبر-على-تربيتهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_146/14604.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":9024,"question":"يوجد عندي كتاب اسمه: نصيحة المسلمين بأحاديث سيد المرسلين، ما رأي سماحتكم في هذا الكتاب؟","title":"حكم كتاب: (نصيحة المسلمين بأحاديث سيد المرسلين)","answer":"","link":"https://binbaz.org.sa/fatwas/7182/حكم-كتاب-نصيحة-المسلمين-باحاديث-سيد-المرسلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14717.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9027,"question":"عندي كتيب صغير اسمه: تعليم الصلاة من تأليف الشيخ: محمد محمود الصواف أخذت منه بعض الأدعية في السجود وبعد التشهد وكذلك بعد الصلاة، فهل هذا الكتيب من الكتب الموثوق بها؟ أفتونا جزاكم الله خيراً.","title":"تقييم كتاب (تعليم الصلاة) للصواف","answer":"الجواب: الكتاب هذا قرأت بعضه وجملة منه، وهو كتاب فيما اطلعت عليه منه كتاب جيد ومفيد، ودار الإفتاء توزعه؛ لأن مؤلفه معروف لدينا بالعلم والفضل والنصح، فهو كتاب إن شاء الله مفيد ولهذا وزعناه لما بلغنا عنه من الفائدة الكبيرة للرجال والنساء. نعم.","link":"https://binbaz.org.sa/fatwas/7185/تقييم-كتاب-تعليم-الصلاة-للصواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14720.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9093,"question":"الأخت جوهرة عبدالرحمن أيضاً تقول: أرجو من سماحتكم أن تدلوني على الكتب المفيدة النافعة في الدين والدنيا، وأن تدلوني على المكتبة الموجود فيها هذه الكتب أو ترسلوا لي إذا تكرمتم شيئاً من هذه الكتب جزاكم الله خيراً؟","title":"الدلالة على الكتب النافعة","answer":"الجواب: الكتب النافعة كثيرة؛ ومنها بل أعظمها وأهمها: كتاب الله سبحانه، هو أهم الكتب وأعظمها، فيه الهدى والنور، وفيه الدعوة إلى كل خير، وفيه بيان مكارم الأخلاق ومحاسن الأعمال، وفيه بيان ما أوجب الله وبيان ما أعد الله لأهله من الخير، وبيان ما حرم الله وما أعد لأهله من العقوبة، فأعظم كتاب وأشرف كتاب وأنفع كتاب هو كتاب الله العظيم القرآن، ثم كتب السنة الصحيحة كـالبخاري ومسلم وما بعدهما من كتب السنن المعروفة كـأبي داود والترمذي والنسائي وابن ماجة وسنن الدارمي ، ومسند أحمد رحمه الله، وموطأ مالك ، هذه الكتب من أنفع الكتب، لكن بالنسبة إلى طلبة العلم الذين لم يتمكنوا من العلم وطالبات العلم في المتوسط والثانوي هؤلاء لهم كتب ينبغي أن يحفظوها أولاً حتى تكثر علومهم وحتى يتأهلوا للكتب العظيمة الكبيرة التي تحتاج إلى مزيد عناية وعلم بما قاله أهل العلم في شأنها، مثل كتاب التوحيد للشيخ الإمام محمد بن عبد الوهاب رحمه الله هذا كتاب عظيم في العقيدة، ومثل الثلاثة الأصول ينبغي أن يحفظ من الطلبة والطالبات طلبة المتوسطة والابتدائي كذلك حتى يكون عندهم أساس في العقيدة، كذلك العقيدة الواسطية لشيخ الإسلام ابن تيمية كتاب عظيم مختصر لكنه مهم في العقيدة، كتاب بلوغ المرام للحافظ ابن حجر في الحديث، كتاب عمدة الحديث للشيخ عبد الغني بن سرور المقدسي في الحديث مهم، الأربعون النووية وتكميلها لـابن رجب الجميع خمسون حديثاً كتاب جيد ومهم نافع، في الفقه عمدة الفقه للموفق ابن قدامة كتاب جيد في الفقه الشرعي في الفقه الإسلامي، وهو في الفقه الحنبلي لكنه يعين على معرفة الفقه الإسلامي بالأدلة الشرعية، دليل الطالب للشيخ مرعي بن يوسف الحنبلي ، مختصر المقنع المسمى: زاد المستقنع للحجاوي ، هذه الكتب في الفقه مختصرة، ومن الكتب النافعة المفيدة لطلبة العلم وللعامة جميعاً: رياض الصالحين للنووي رحمه الله، الوابل الصيب لـابن القيم رحمه الله، هذه كتب مفيدة، زاد المعاد في هدي خير العباد لـابن القيم رحمه الله، هذه الكتب وأشباهها فيها نفع كبير. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7253/الدلالة-على-الكتب-النافعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15004.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9171,"question":"هذه رسالة وصلت إلى البرنامج من المستمع عمر الأمين الشيخ، سوداني مقيم بالقصيم، يقول في رسالته: بسم الله الرحمن الرحيم، أرجو الإجابة على سؤالي هذا، عندما كنت أدرس بالمرحلة المتوسطة طرح لنا أحد الأساتذة سؤالاً، وقال فيه: من هو أول رائد للفضاء؟ فأجبنا على سؤاله بأنه سوفييتي الجنسية، وقال لنا الأستاذ: الإجابة خطأ؛ إن أول رائد للفضاء هو: نبينا محمد صلوات الله وسلامه عليه، عندما عرج به إلى السماوات، وكانت مركبتهم البراق، هل هذا صحيح، أفيدونا أفادكم الله؟","title":"ما صحة القول بأن النبي أول رائد فضاء؟","answer":"الجواب: لا نعلم شيئاً في الموضوع غير ما ذكره المجيب، فإنا لا نعلم أحداً عرج به إلى السماء وفرضت عليه الصلوات الخمس سوى نبينا عليه الصلاة والسلام، فإنه عرج به إلى السماء السابعة، حتى كان فوقها؛ وحتى سمع كلام الرب ، فهذا إذا عبر عنه بأنه رائد فضاء؛ فهذا له بعض الوجاهة؛ لكن ليس بصحيح أنه رائد فضاء، بل إنما عرج به إلى السماء إلى ربه عز وجل، ليفرض عليه ما يشاء سبحانه وتعالى، وليس المقصود من هذه الرحلة أن يجوب الفضاء، وأن ينظر في الفضاء، المقصود من هذه الرحلة مع الملك جبرائيل عليه الصلاة والسلام هو أن يرتفع إلى الله، ويجوب السموات، حتى يصل إلى ما فوق السماء السابعة، وحتى يسمع كلام ربه، وليس المقصود أن يجوب الفضاء، فهذا الذي قاله .... له بعض الوجاهة من جهة أن الرسول ﷺ شق الفضاء كله، حتى جاوز السبع الطباق له وجه، لكن ليس هو المعنى المقصود عند الدول الموجودة اليوم؛ أمريكا والسوفيت وغيرهما، مقصودهم: اختبار الفضاء، واختبار ما فيه من العجائب، وليس المقصود هذا المعنى الذي حصل للنبي ﷺ، فالمجيب الذي قال: السوفييتي له وجه، والسائل الذي سألكم لقصده وجه، ولكن ليس منطبقاً على مراد الناس اليوم، وعلى مقصود الناس اليوم، لأن الرسول ﷺ لم يرتحل ليجوب الفضاء، وإنما ارتحل بأمر ربه، ليتصل بالله  فوق السماء السابعة، ويسمع كلامه سبحانه، وليمتثل أمره جل وعلا، فالرسول ﷺ مأمور بأن يرتحل هذه الرحلة العظيمة، ويسمع كلام ربه، وليفرض الله عليه هذه الصلوات العظيمة؛ التي هي أعظم أركان الإسلام بعد الشهادتين، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/7331/ما-صحة-القول-بان-النبي-اول-راىد-فضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23213.mp3","categories":["العالم والمتعلم","التاريخ والسيرة"]},{"id":9199,"question":"رسالة مطولة باعثها أحد الإخوة المستمعين من السودان يقول: إنه مقيم في ليبيا، أخونا يقول: إن له رغبة شديدة في التفقه في الدين، وأن يتعلم التفسير وتجويد القرآن الكريم، ويرجو من سماحة الشيخ التوجيه حيال هذه الأمور جزاكم الله خيرا.","title":"نصيحة لمن أراد التفقه في الدين","answer":"الشيخ: وهو في ليبيا؟\nالمقدم: نعم، هو مقيم في ليبيا وسوداني الأصل واسمه علي أحمد آدم.\nالشيخ: هذا عمل طيب ورغبة طيبة، ينبغي له أن يسارع إلى ذلك ويبادر بذلك وإذا وجد في ليبيا من علماء السلف الصالح المعروفين بالخير من يتفقه عليهم فالحمد لله، فإن لم يجد في ليبيا من يقوم بذلك شرع له أن ينتقل عنها إلى محل آخر يجد فيه علماء الشرع حتى يتفقه عليهم، وحتى يتعلم عليهم كتاب الله وتجويده.\nفالحاصل: إنه إن وجد في ليبيا من يحصل به المقصود فالحمد لله يبادر ويقرأ عليهم ويتعلم ويستفيد ويتفقه، فإن لم يجد انتقل إلى غير ليبيا حتى يجد من يتعلم عليهم علوم الشرع المطهر ويتعلم عليهم علوم القرآن وتجويد القرآن ويقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة، فطلب العلم من أهم الأمور، ومن أفضل العبادات وهو واجب على كل مسلم أن يتعلم ما لا يسعه جهله كل مسلم عليه أن يتعلم ما لا يسعه جهله فيما أوجب الله عليه وما حرم عليه. نعم.\nالمقدم: هل تنصحونه بكتب معينة سماحة الشيخ؟\nالشيخ: نعم، ننصحه أولًا بكتاب الله، ننصحه أن يتعلم كتاب الله ويتحفظه ويكثر من تلاوته وتدبر معانيه مع من تيسر من إخوانه الطيبين هناك، فإن كتاب الله هو أصل كل خير، هو ينبوع الهدى كما قال الله : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، وقال سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، قال : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، وقال سبحانه: أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]، وقال جل وعلا: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155].\nفنوصي جميع المسلمين بالعناية بكتاب الله والإقبال عليه والإكثار من تلاوته والعناية بحفظه وتدبر معانيه والعمل بذلك، هذا هو المشروع للجميع وتعلمه وتعليمه فرض كفاية على المسلمين.\nثم يشرع للمؤمن أن يلتمس أهل العلم والبصيرة حتى يتفقه عليهم، وحتى يسألهم عما أشكل عليه من كتاب الله وسنة رسوله عليه الصلاة والسلام.\nثم ننصح بعد ذلك بكتب الحديث الصحيح، كالصحيحين فإنهما أعظم كتاب بعد كتاب الله عز وجل.\nثم السنن الأربع: سنن أبي داود و الترمذي و النسائي و ابن ماجه فإنها كتب عظيمة وهي كتب السنة وإن كان فيها بعض الأحاديث الضعيفة لكنها كتب عظيمة وغالب ما فيها أحاديث صحيحة وفي إمكان طالب العلم أن يعرف ما فيها من الضعيف بالطرق التي رسمها أهل هذا العلم، أو بسؤال أهل العلم العارفين بهذا، ومثل: رياض الصالحين كتاب جيد مفيد غالبه أحاديث صحيحة، ومثل منتقى الأخبار للمجد ابن تيمية كتاب جليل، ومثل: بلوغ المرام للحافظ ابن حجر كتاب جيد مفيد، ومثل: عمدة الحديث للشيخ عبدالغني المقدسي ، هذه كتب عظيمة في الحديث ينبغي للمؤمن أن يعتني بها حسب طاقته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7359/نصيحة-لمن-اراد-التفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18108.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9211,"question":"صدرت فتوى من سماحة الشيخ عبدالعزيز بن عبدالله بن باز، أيضًا هذا السؤال من أخينا الطالب في الثانوية عمر ماجد محمد سعيد من الأردن، يقول أيضًا في سؤاله الثاني: صدرت فتوى من سماحة الشيخ عبدالعزيز بن عبدالله بن باز حفظه الله وبارك فيه، وكان معنى تلك الفتوى بأن من كان عنده شرائط ما يسمى بالفيديو وعليها مواد خليعة خبيثة وتاب إلى الله تعالى فإنه يسجل عليها الطيب الجيد وذلك يزيل ما بها من الخبث، والاستفسار هو: ما المقصود بالطيب، هل هو حلقات العلم والدروس الشرعية وتلاوة القرآن، فإن كان هذا هو المقصود، فهل يدخل ذلك في نطاق التصوير المحرم أم لا؟ فإن كان داخلًا في هذا النطاق فكيف يجوز استعماله؟ وإن لم يكن داخلًا فما الأدلة الشرعية على ذلك؟وأخيرًا: أرجو من سماحة الشيخ عبدالعزيز أن يتفضل بإيضاح عنوانه كاملًا لعلنا نسأله عن أمور أخرى.","title":"حكم تسجيل المحاضرات والدروس على أشرطة الفيديو","answer":"الجواب: المقصود: أن الأشرطة التي فيها شيء لا ينبغي.. قد سجل فيها شيء لا ينبغي لا حاجة إلى إتلافها، بل يسجل عليها الشيء الطيب حتى لا تتلف هذا المال بغير فائدة والنبي نهى عن إضاعة المال عليه الصلاة والسلام، فيسجل عليها ما ينفع الناس، الأشرطة التي تحتاج إلى تصوير الشريط الفيديو إذا دعت الحاجة إلى ذلك وسجل عليها من الندوات النافعة والمحاضرات النافعة ما ينفع الناس فلا حرج في ذلك من باب تقديم المصلحة العظيمة على ما في التصوير من المضرة والمنكر.\nفالمقصود من هذا كله: أن إيجاد فيديو ينفع الناس قد سجل فيه وقد جعل فيه من العلوم النافعة والمحاضرات المفيدة والندوات الصالحة خير من تركه وإتلافه بدون فائدة، هذا المقصود: أن يسجل عليه بدل الشيء الرديء ما ينفع الناس من محاضرات صالحة وندوات صالحة وأشباه ذلك مما ينفع الناس، هذا هو المقصود.\nوأما العنوان: فالعنوان معروف: الرياض .. الرئاسة العامة لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد، هذا هو العنوان، الرئيس العام لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد.. الرياض. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7371/حكم-تسجيل-المحاضرات-والدروس-على-اشرطة-الفيديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18203.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9331,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من أحد الإخوة يقول: صلاح عبدالرحيم أحمد سوداني، أخونا يقول: إذا كان لدي أخ أصم وأبكم وهو لا يسمع ولا يتكلم كما هو معلوم، وطبعاً لا يعرف شيئاً عن الصلاة ولا الصوم ولا الزكاة ولا يعرف شيئاً عن أحكام الإسلام، ولا يعرف شيئاً من القرآن كيف يكون التوجيه والحالة هذه؟","title":"كيفية تعليم الأصم الأبكم أحكام الإسلام","answer":"الجواب: هذا لابد، يعني: يفعل معه ما يعلم به عقله من إشارة إذا كان يبصر ...... الناس وقت الصلاة حتى ينظر أعمالهم، ويكتب له إن كان يكتب، يعلم الكتابة لعله يستفيد من الكتابة حتى يعرف عقله أنه يعي أو يفهم، فإذا كان يعي ويفهم بالكتابة والإشارة فهو مكلف بحسب ما وصل إلى علمه، إذا كان لا ينطق ولا يسمع فقد يفهم بالإشارة أو بالكتابة إن تيسرت الكتابة حتى يعمل بما أوجب الله ويترك ما حرم الله من طريق الكتابة أو من طريق الإشارة هذا إذا كان يعقل، أما إذا كان ما يعقل ظهر من حاله أنه لا يعقل فلا حرج عليه؛ لأنه غير مكلف، رفع القلم عن ثلاثة منهم: الصغير حتى يبلغ، والمعتوه حتى يفيق، فإذا كان معتوهاً لا عقل له فلا شيء عليه. نعم.\nالمقدم: إذاً يكفي من مثل هذا التقليد، يعلمونه التقليد وهو كافي؟\nالشيخ: يعلمونه حسب الإمكان، بالمكاتبة، بالإشارة، بالشيء الذي يستطيعون، وقد يعوض هذا الجنس فهماً عظيماً بالإشارات، إذا فقد حاسة السمع وحاسة الكلام قد يعوض بإذن الله هذا مشاهد معروف من أولئك الذين يبتلون بهذا عندهم فهم عظيم للإشارات، ونحن نعرف من هذا ناساً يعملون ويكدحون ويحصلون أموالاً بالإشارة ويصلوا مع الناس ويصوموا مع الناس وكانوا من خيرة الناس كله بالإشارة أو بالكتابة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7484/كيفية-تعليم-الاصم-الابكم-احكام-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_155/15505.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9356,"question":"أختنا تقول: إنها قادرة على شراء الكتب وتوزيعها في سبيل الله، فهل هناك قائمة تنصحونها بشرائها لتقوم بتوزيعها؟","title":"كتب ينصح بتوزيعها","answer":"الجواب: نعم، الكتب من أهم القربات، توزيعها من أهم القربات، الكتب النافعة المفيدة وهي داخلة في قول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له وهو حديث صحيح، فإذا اشترى الإنسان الكتب الطيبة ووزعها أو جعلها في المكتبات العامة للمسلمين فهذا عمل صالح وصدقة جارية.\nومن أحسنها فيما نعلم: كتاب التوحيد للشيخ محمد بن عبد الوهاب، كتاب الثلاثة الأصول، وكشف الشبهات، وآداب المشي إلى الصلاة، وزاد المعاد لـابن القيم في هدي خير العباد، فتح المجيد للشيخ عبد الرحمن بن حسن، تيسير العزيز الحميد للشيخ سليمان بن عبد الله، وكلاهما حفيد للشيخ محمد بن عبد الوهاب، الصحيحان البخاري ومسلم، سنن أبي داود، سنن الترمذي، سنن النسائي، سنن ابن ماجة، سنن الدارمي ، موطأ مالك ، مسند أحمد، كل هذه كتب عظيمة شراؤها وتسبيلها للمسلمين في المكتبات العامة أو توزيعها على طلبة العلم كل ذلك نافع، كله طيب، ....فتاوى شيخ الإسلام ابن تيمية ، الدرر السنية فتاوى أئمة الدعوة الإسلامية في نجد، كل هذه كتب عظيمة نافعة، اقتضاء الصراط المستقيم مخالفة أصحاب الجحيم لشيخ الإسلام ابن تيمية ، العقيدة الواسطية لشيخ الإسلام ابن تيمية ، الرسالة الحموية لشيخ الإسلام ابن تيمية ، الرسالات النورية لشيخ الإسلام ابن تيمية ، كلها كتب عظيمة مفيدة نافعة، فهذه الكتب وأشباهها شراؤها وتوزيعها طيب، هكذا شرح الطحاوية لـابن أبي العز كتاب مفيد نافع. نعم.\nالمقدم: من كتب التفسير لو تكرمتم؟\nالشيخ: من كتب التفسير تفسير ابن كثير ، تفسير ابن جرير ، تفسير البغوي ، تفسير الشوكاني ، تفسير القرطبي ، كل هذه كتب مفيدة نافعة، شراؤها وتوقيفها وتسبيلها أمر مهم ونافع للمسلمين. نعم.\nالمقدم: من المؤلفات في العصر الحديث مثلاً؟\nالشيخ: فيه مؤلفات في العصر الحديث كذلك فيه مؤلفات نافعة منها: مؤلفات أخينا العلامة الشيخ عبد الله بن حميد رحمه الله ..........وأخينا الشيخ حمود التويجري وبعض المؤلفات التي لنا يعرفها الناس.\nفيه كتب أخرى قد لا تحضرني الآن من إخواننا المعروفين مثل بعض مؤلفات الشيخ صالح بن فوزان كذلك مفيدة ونافعة، والذي يريد أن يشتري ويوزع ينبغي له أن يستشير بعض العلماء حتى يعني: يكون على بصيرة فيما يشتري وفيما يوزع أو يكتب عليه وقف في المكتبات، يعني: ينبغي له أن يستشير حتى يكون على بينة فيه؛ لأن بعضها الآن قد غاب عني. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7520/كتب-ينصح-بتوزيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9373,"question":"الواقع سماحة الشيخ المبتدئ في القراءة قد يقع على شيء من هذا، فبما تنصحونه والحالة هذه؟","title":"نصيحة للمبتدئ في طلب العلم إذا أشكل عليه شيء","answer":"الشيخ: نعم.\nالمقدم: المبتدئ في الاطلاع على كتب أهل العلم قد يقع على شيء من هذا، وربما يقع في حيرة.\nالشيخ: يسأل أهل العلم إذا اشتبه عليه القارئ، وطالب العلم المبتدي إذا مر عليه شيء من الأحاديث واشتبه عليه أمرها أو بعض الآيات يسأل أهل العلم الذين عنده ولو سافر إليهم، يسأل أهل العلم الذين بلغه عنهم أنهم أهل علم وأهل بصيرة، ويطمئن إليهم يسألهم، بالمكاتبة.. بالمشافهة.. بالهاتف.. بغير هذا من طرق الاتصال، والمقام يحتاج إلى عناية، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]. نعم. \nالمقدم: ذكرتم السفر وهذا دليل على أهمية التوضيح فيما يتعلق بأمور ديننا؟\nالشيخ: نعم، ولو بالسفر، قد سافر جمع من الصحابة من بلد إلى بلد من المدينة إلى مصر وإلى الشام من أجل بعض الأحاديث رضي الله عنهم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7537/نصيحة-للمبتدى-في-طلب-العلم-اذا-اشكل-عليه-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18611.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9390,"question":"بارك الله فيكم. هل من كتب معينة ينصح بها سماحة الشيخ عبدالعزيز كل من يود أن يعمل في مجال الدعوة إلى الله؟","title":"كتب ينصح بها للداعية إلى الله","answer":"","link":"https://binbaz.org.sa/fatwas/7554/كتب-ينصح-بها-للداعية-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_158/15802.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9616,"question":"الرسالة التالية وصلت من المستمع عبدالله سلام العمراني من المنطقة الشمالية لمدينة البدع يقول الأخ عبدالله في رسالته:هل يقصد بقول الله تعالى: هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لا يَعْلَمُونَ [الزمر:9] وقوله ﷺ: العلماء ورثة الأنبياء علماء الطب أو الكيمياء أو غيرهم أم يقصد فقط علماء الشريعة أفيدونا حفظكم الله ورعاكم؟","title":"علماء الشريعة هم المعنيون بكلام الله ورسوله","answer":"الجواب: المقصود بالآيات التي في العلم أو الأحاديث التي في العلم كلها عند أهل العلم كتب الشريعة؛ علوم الكتاب والسنة هي التي فيها الفضل العظيم والخير الكثير، وأما ما يتعلق بعلوم الطب والهندسة والاختراع والجيولوجيا وأشباه ذلك علوم لها أهلها وعلى حسب مقاصدهم تكون حكمهم؛ فمن تعلم الهندسة أو الطب لينفع المسلمين وأن يغنيهم عن أعدائهم فهذا مأجور على حسب نيته، وهكذا من تعلم اختراع شيء من آلات الحرب لينفع المسلمين أو تعلم الجيولوجيا أو شبه ذلك لينفع المسلمين قصده نفع المسلمين فهذا له أجره، ولا يكون حكمه حكم علماء الشريعة لكن يكون له أجر على نيته، أما من تعلمه للدنيا ومقاصد الدنيا؛ ليأكل يتوظف يعيش فهذا مباح لا له ولا عليه، لأنه مأمور بالكسب مأمور بطلب الرزق لكن ما يكون كمن تعلمها ليأكل الحلال ويستغني عن الحاجة إلى الناس أو ينفع المسلمين ليغنيهم عن أعدائهم هذه النية تختلف، فمن تعلمها لنفع المسلمين فله أجر ومن تعلمها ليستغني بها عن الحرام ويكسب الحلال فله أجر، ومن تعلمها لا لقصد إلا لمجرد ليعيش ويأكل ويشرب ما همه حلال ولا غيره ولا همه نفع المسلمين ولا غيرهم وإنما تعلمها لمصالحه الدنيوية فقط الدنيوية فقط فهذا ...... أنه مباح فقط. نعم.","link":"https://binbaz.org.sa/fatwas/7774/علماء-الشريعة-هم-المعنيون-بكلام-الله-ورسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19312.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9731,"question":"السائلة أم مريم تقول: لي مجموعة من الأولاد الصغار ويكثرون من اللعب، هل يجوز الدعاء على الأولاد في مثل هذه الحالة؟","title":"واجب الأم تجاه أولادها","answer":"الجواب: إذا كان أولادك فيهم بعض الشر كاللعن والشتم والمخاصمة ... بينهن، هذا جاهديهم بالتوجيه والإرشاد والنصيحة والتأديب واسألي الله أن الله يهديهم، اسألي الله أن الله يهديهم جل وعلا، ولا تقنطي ولا تيئسي، اسألي الله لهم الهداية وعلميهم وهكذا أبوهم وهكذا أخوهم الكبير وهكذا جدهم ينصحهم ويؤدبهم إذا رأى التأديب حتى يستقيموا، لا تقنطي أبداً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7886/واجب-الام-تجاه-اولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27220.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":9777,"question":"يقول أيضاً نفس السائل: في نفس الكتاب يذكر المؤلف أن أحد كتاب الوحي ارتد عن الإسلام، والسبب أنه كان يكتب ما ينزل عليه من الآيات كقوله تعالى: الْعَزِيزُ الْحَكِيمُ [البقرة:129] يكتبها: العليم الحكيم، أو نحو ذلك، وفي الحقيقة لم أفهم مقصود المؤلف أرجو الإيضاح؟","title":"هل ارتد أحد من كتاب الوحي؟","answer":"الجواب: أنا لا أذكر بحث المؤلف، ويمكن أن نطالعه في وقت مستقبل إن شاء الله لا نذكر بحثه، لكن ارتداد بعض كتاب الوحي واقع هو عبد الله بن سعد بن أبي سرح ارتد عن الإسلام ثم دخل في الإسلام وهداه الله يوم الفتح، أما الأسباب أسباب الردة فلا أذكرها حالياً، ولكن يمكن أن نراجع كلام ابن القيم وأن أذكر ذلك في حلقة أخرى إن شاء الله.\nوأما قوله: إن بعض كتاب الوحي ارتد فهذا معروف هو عبد الله بن سعد بن أبي سرح ارتد عن الإسلام ثم بعدما فتح الله على رسوله مكة هداه الله وجاء وأسلم، والحمد لله. نعم.\nالمقدم: بارك الله فيكم. وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7946/هل-ارتد-احد-من-كتاب-الوحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25807.mp3","categories":["العالم والمتعلم","التاريخ والسيرة"]},{"id":9879,"question":"يقول أيضاً قرأت في كتيب صغير اسمه: الحصن الحصين من كلام رب العالمين، أن من يقرأ هذه الآية لا يموت في يومه وفيه سبع آيات يقول عنها إنها المنجيات ثم ذكر بسم الله الرحمن الرحيم: لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُمْ بِالْمُؤْمِنِينَ رَءُوفٌ رَحِيمٌ [التوبة:128] إلى آخر الآية، فما حكم ذلك؟","title":"التعريف بما يحويه كتيب الحصن الحصين","answer":"الجواب: ليس بصحيح، هذا ليس بصحيح، والحصن الحصين يجمع أحاديث ضعيفة وأحاديث غير صحيحة، فلا يعتمد على ما يذكر بل لا بد من المراجعة، مراجعة الأحاديث في كتب الأصول ومراجعة كلام أهل العلم فيها، حتى يعلم طالب العلم صحتها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8053/التعريف-بما-يحويه-كتيب-الحصن-الحصين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26410.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9911,"question":"هذه رسالة رمز السائل بـ (ع. ع. ع) المنصورة يقول: والدي قد بلغ من العمر ما يقارب من اثنين وخمسين عام، يحافظ على الصلوات المكتوبة في أوقاتهن.الشيخ: أعد أعد.المقدم: يقول هذا السائل: والدي بلغ من العمر ما يقارب من الثانية والخمسين يحافظ على الصلوات المكتوبة في أوقاتهن ولكنه كثير المزاح مع الناس ومع الغير صالحين والفاسدين بالفواحش والمنكر، فهذا يغضبني ويجعلني لا أملك نفسي فأقوم بتوجيهه في نفس الوقت وأمام هؤلاء الناس وهؤلاء الفاسدين بأسلوب متشدد جدًا، فمثلًا أقول له: بأن هذا الكلام لا يقوله إلا الفاسد والفاسق ولو مت يا أبي على هذه الحالة ستلقى الله وهو عليك غضبان، ولا أطيل عليكم فقد كنت متشدد معه مع خوفي عليه من غضب الله؟ فماذا أفعل لو كان أسلوبي هذا يغضب الله وجهوني مأجورين؟","title":"مشروعية الرفق بالوالد عند توجيهه ونصيحته","answer":"الجواب: المشروع لك -يا أخي- الرفق والدعوة إلى الله بالحكمة والأسلوب الحسن، ولا سيما مع والدك، الله يقول جل وعلا: فَقُولا لَهُ قَوْلًا لَيِّنًا [طه:44] لما أرسل موسى وهارون إلى فرعون لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] ويقول الله سبحانه لنبيه محمد ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] ويقول الله سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكََ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] فنوصيك بالرفق بوالدك ومخاطبته بالأسلوب الحسن بينك وبينه حتى يهديه الله، عليك بالكلام الطيب والأسلوب الحسن والرفق في نصيحته وتوجيهه إلى الخير، سواء كان عند الناس أو بينك وبينه نسأل الله أن يهديه وأن يعيذه من الشيطان.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8079/مشروعية-الرفق-بالوالد-عند-توجيهه-ونصيحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27323.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":9989,"question":"له سؤال ثالث أيضًا يقول فيه: وردت الأدلة على الأجر في قراءة القرآن الكريم، فهل هناك أجر في قراءة الأحاديث النبوية أفيدونا بارك الله فيكم؟","title":"فضل تعلم كتاب الله وسنة رسوله","answer":"الجواب: نعم، قراءة العلم كلها فيها أجر، تعلم العلم وطلب العلم من طريق القرآن من طريق السنة فيها أجر عظيم، فالعلم يؤخذ من الكتاب ويؤخذ من السنة، يقول النبي ﷺ: خيركم من تعلم القرآن وعلمه، وجاء في قراءة القرآن أحاديث كثيرة، منها قوله ﷺ: اقرءوا القرآن فإنه يأتي شفيعاً لأصحابه يوم القيامة رواه مسلم ، وقال ذات يوم عليه الصلاة والسلام: أيحب أحدكم أنن يذهب إلى بطحان -وادٍ في المدينة يقال له: بطحان- فيأتي بناقتين عظيمتين في غير إثم ولا قطيعة رحم؟ فقالوا: كلنا يحب ذلك يا رسولل الله! قال: لأن يذهب أحدكم إلى المسجد فيتعلم آيتين من كتاب الله خير له من ناقتين عظيمتين وثلاث خير من ثلاث، ومن أربع ومن أعدادهن من الإبل أو كما قال عليه الصلاة والسلام، فهذا يدل على فضل تعلم القرآن وقراءة القرآن، حديث ابن مسعود: من قرأ حرفًا من القرآن فله حسنة والحسنة بعشر أمثالها، هكذا السنة إذا تعلمها المؤمن، قرأ الأحاديث ودرسها يكون له أجر عظيم لأن هذا من تعلم العلم، يقول النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة، فهذا يدل على أن دراسة العلم وحفظ الأحاديث والمذاكرة فيها من أسباب دخول الجنة والنجاة من النار، هكذا قوله ﷺ: من يرد الله به خيرًا يفقهه في الدين متفق عليه، فالتفقه في الدين يكون من طريق الكتاب ويكون من طريق السنة، فالتفقه في السنة من الدلائل على أن الله أراد بالعبد خيراً، كما أن التفقه في القرآن دليل على ذلك، والأدلة في هذا كثيرة والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8157/فضل-تعلم-كتاب-الله-وسنة-رسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_275/27503.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9991,"question":"تسأل أختنا مع من يسأل عن كتاب رياض الصالحين؟","title":"التعريف بكتاب رياض الصالحين","answer":"الجواب: رياض الصالحين كتاب عظيم نفع الله به الأمة، والظاهر -والله أعلم- أن مؤلفه ألفه عن نية صالحة رحمة الله عليه، وعن قصد صالح ولعله سأل الله  فأجاب الله دعوته أن ينفع به العباد فنفع الله به العباد، فكل بلاد تستعمل هذا الكتاب فيما بلغنا يدرسونه في البيوت وفي المساجد وينتفع به الناس، فهو كتاب عظيم والحديث الضعيف فيه قليل، فهو كتاب ننصح بقرءاته في المساجد وفي المجالس لما فيه من الفائدة الكبيرة، نسأل الله أن يعفو عن مؤلفه وأن يضاعف مثوبته وأن ينفع بهذا الكتاب المسلمين كما نفع به سابقاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8170/التعريف-بكتاب-رياض-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30007.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9994,"question":"أيضاً تسأل عن كتاب الدعاء المستجاب ودعاء الرسول ﷺ؟","title":"التعريف بكتاب الدعاء المستجاب","answer":"الجواب: كتاب الدعاء المستجاب كتاب فيه أحاديث ضعيفة وموضوعة لا ننصح به، بل ننصح بتركه وعدم الاعتماد عليه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8171/التعريف-بكتاب-الدعاء-المستجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30008.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10042,"question":"أرجو من سماحتكم إرشادي إلى الكتب الموثوق بها في كل من الموضوعات التالية: العقيدة؟","title":"كتب ينصح بقراءتها في العقيدة","answer":"الجواب: أعظم كتاب وأشرف كتاب وأصدق كتاب في العقيدة وغيرها كتاب الله القرآن، فعليك بكتاب الله أكثر من تلاوته تدبر معانيه وحفظ ما تيسر منه والمذاكرة مع زملائك ومع أستاذك في ذلك حتى تستفيد العلم العظيم، قال تعالى في كتابه العظيم: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قال سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] وقال: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] فهو كتاب الله العظيم فيه الهدى والنور والشفاء، فالزم كتاب ربك وأكثر من تلاوته وتدبر معانيه أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24].\nثم كتب الحديث الشريف كالصحيحين فإنهما أعظم كتاب بعد القرآن، إذا كنت طالب علم تعتني بالصحيحين تطالعهما وتقرأ فيهما وتذاكر فيهما مع الأساتذة ومع الزملاء وهكذا بقية السنن الأربع كـأبي داود والترمذي والنسائي وابن ماجة ومسند أحمد وسنن الدارمي، هذه كتب مفيدة عظيمة إذا كنت تستطيع أن تقرأ فيها وأن تستفيد منها، ولكن أعظمها الصحيحان، ومثل رياض الصالحين كتاب مفيد جيد، بلوغ المرام تستفيد منه تحفظه إذا تيسر للحافظ ابن حجر، عمدة الحديث للعلامة الحافظ عبدالغني بن عبدالواحد المقدسي كتاب عظيم مفيد في الحديث.\nوفي العقيدة: العقيدة الواسطية.. التدمرية.. الحموية.. كتاب التوحيد للشيخ محمد بن عبدالوهاب رحمه الله ثلاثة الأصول، كشف الشبهات، كل هذه كتب مفيدة، لمعة الاعتقاد للموفق ابن قدامة رحمه الله، الطحاوية كتاب جيد وإن كان فيه مواضع قليلة قد علقنا عليها ووضح أيضًا ما فيها شارح الطحاوية ابن أبي العز كل هذه كتب طيبة وشرح ابن أبي العز للطحاوية كتاب جيد أيضًا، وهكذا كتب ابن القيم الصواعق المرسلة، اجتماع الجيوش الإسلامية، زاد المعاد، حادي الأرواح.. كل هذه كتب مفيدة في العقيدة وغيرها.\nوهكذا كتب شيخ الإسلام ابن تيمية رحمه الله الفتاوى المعروفة وهكذا كتاب الإيمان له أيضًا مع ما تقدم من كتبه الثلاثة التدمرية.. الحموية.. العقيدة الواسطية.. كل هذه كتب عظيمة مفيدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8211/كتب-ينصح-بقراءتها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33210.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10051,"question":"أرجو إرشادي إلى أسماء كتب طيبة تتحدث عن قصص الأنبياء وعن قصص الصحابة ؟","title":"الكتب التي تتحدث عن سير الأنبياء والصحابة","answer":"الجواب: أرشدك أولاً إلى أن تهتمي بالقرآن العظيم فهو أعظم القصص وأحسن القصص، قال فيه جل وعلا: نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ [يوسف:3]، فيه قصص عن الأنبياء وأممهم وعن أهل الخير والشر، فهو أعظم كتاب وأحسن كتاب وأصدق كتاب فأوصيك بالقرآن كثيراً وأن تعتني بالإكثار من تلاوته وتدبر معانيه، ثم بعد ذلك من أحسن الكتب في هذا الباب (زاد المعاد) لـابن القيم في هدي خير العباد، والمجلدات الأولى من تاريخ ابن كثير في قصص النبي ﷺ وأخباره وأخبار الصحابة وكتابه كله طيب (البداية والنهاية) كله طيب، وهناك كتاب مختصر للسيوطي سماه تاريخ الخلفاء فيه فائدة طيبة، وأوصيك أيضاً بحفظ كتاب \"التوحيد\" للشيخ محمد عبد الوهاب (والعقيدة الواسطية) لشيخ الإسلام ابن تيمية، وثلاثة الأصول للشيخ محمد، كشف الشبهات، وآداب المشي إلى الصلاة، كلها كتب مفيدة، كذلك أوصيك بمطالعة فتح المجيد شرح كتاب التوحيد فهو كتاب جيد مفيد، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8221/الكتب-التي-تتحدث-عن-سير-الانبياء-والصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30305.mp3","categories":["التاريخ والسيرة","العالم والمتعلم"]},{"id":10058,"question":"أرجو إرشادي إلى أسماء كتب طيبة تتحدث عن قصص الأنبياء وعن قصص الصحابة ؟","title":"الكتب التي تتحدث عن سير الأنبياء والصحابة","answer":"الجواب: أرشدك أولاً إلى أن تهتمي بالقرآن العظيم فهو أعظم القصص وأحسن القصص، قال فيه جل وعلا: نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ [يوسف:3]، فيه قصص عن الأنبياء وأممهم وعن أهل الخير والشر، فهو أعظم كتاب وأحسن كتاب وأصدق كتاب فأوصيك بالقرآن كثيراً وأن تعتني بالإكثار من تلاوته وتدبر معانيه، ثم بعد ذلك من أحسن الكتب في هذا الباب (زاد المعاد) لـابن القيم في هدي خير العباد، والمجلدات الأولى من تاريخ ابن كثير في قصص النبي ﷺ وأخباره وأخبار الصحابة وكتابه كله طيب (البداية والنهاية) كله طيب، وهناك كتاب مختصر للسيوطي سماه تاريخ الخلفاء فيه فائدة طيبة، وأوصيك أيضاً بحفظ كتاب \"التوحيد\" للشيخ محمد عبد الوهاب (والعقيدة الواسطية) لشيخ الإسلام ابن تيمية، وثلاثة الأصول للشيخ محمد، كشف الشبهات، وآداب المشي إلى الصلاة، كلها كتب مفيدة، كذلك أوصيك بمطالعة فتح المجيد شرح كتاب التوحيد فهو كتاب جيد مفيد، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8221/الكتب-التي-تتحدث-عن-سير-الانبياء-والصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30305.mp3","categories":["التاريخ والسيرة","العالم والمتعلم"]},{"id":10185,"question":"مستمع بعث برسالة مطولة بعض الشيء هو مهيوب أحمد حسن، يقول: أفيدكم أنني أتابع هذا البرنامج من عام ستة وسبعين للميلاد، وقد استفدت منه كثيراً، وأسألكم في هذه الرسالة سؤالين:الأول: ما هو رأيكم في السيرة لـابن هشام ؟","title":"تقييم كتاب سيرة ابن هشام","answer":"الجواب: كتاب جيد ومفيد، كتاب عظيم ومفيد، لكن في أخباره ما هو صحيح وما هو ضعيف، ولكنه كتاب مفيد، وهو مختصر السيرة لابن إسحاق رحمه الله، وفيه فوائد كثيرة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8365/تقييم-كتاب-سيرة-ابن-هشام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30907.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10239,"question":"أخيرًا يسأل ويقول: ما هي أفضل كتب الفقه التي يمكن الاعتماد عليها؟","title":"أفضل كتب الفقه المعتمدة","answer":"الجواب: كتب الفقه كثيرة، ولكن من أحسنها: المغني لـابن قدامة لـموفق الدين ابن قدامة عبدالله بن أحمد بن قدامة ، ... كتاب جيد مفيد يذكر فيه الخلاف والأدلة، شرح المهذب للنووي وتتمته، الفروع لـابن مفلح في المذهب الحنبلي، والإقناع والمنتهى في المذهب الحنبلي، والروض المربع في المذهب الحنبلي وحاشيته .. له حاشية جيدة للشيخ عبدالرحمن بن قاسم رحمه الله، وفي كتب أخرى في المذاهب الأخرى؛ كالمدونة في مذهب مالك رحمه الله، ومثل فتح القدير في المذهب الحنفي، كل هذه كتب مفيدة، لكن ينبغي للمؤمن أن يعتني بالدليل ويحرص على الكتب التي فيها الدليل، وبيان الراجح من الخلاف، وإذا كان طالب علم لا يستطيع أن يفهم هذه الأمور فيسأل أهل العلم عما أشكل عليه، ويحفظ الكتب المختصرة مثل: عمدة الحبيب في الحديث، ومثل بلوغ المرام حتى يستعين بذلك على معرفة الدليل، ومتن الزاد .... الحنابلة، أو متن الدليل أو العمدة أو العمدة للموفق في الفقه، أو ما أشبهها من الكتب المختصرة من كتب المذاهب الأخرى، حتى يستعين بها على معرفة المسائل الفقهية ومراجعة أدلتها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8410/افضل-كتب-الفقه-المعتمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33511.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10337,"question":"أخيراً يسأل ويقول: كيف يستطيع المرء أن يتعلم تفسير الأحلام، وهل توجد كتب صحيحة في هذا المجال؟","title":"مصادر تعلم تفسير الأحلام","answer":"الجواب: يتعلمها من كتب العلماء التي ذكرت الأحاديث عن النبي ﷺ في الرؤيا وتفسيرها، مثل كتاب ابن القيم في إعلام الموقعين ذكر جملة من ذلك رحمه الله في الرؤيا، وفي كتب أخرى مؤلفة في الرؤيا يستفيد منها، وأكثر ما يفيد ذلك تدبر الأحاديث التي جاءت في الرؤيا عن النبي ﷺ وتفسير النبي ﷺ لها، تفسير الصحابة، يستفيد منها إذا كان عنده علم وعنده بصيرة يستفيد.\nولا ينبغي أن يقدم على التأويل إلا عن بصيرة وعن علم حتى لا يكذب على الله ولا على رسوله عليه الصلاة والسلام، فينبغي لمن أراد التفسير -تفسير الرؤيا وتعبيرها- أن يعتني بما جاء في السنة عن النبي ﷺ في تفسير الرؤيا، وما جاء عن الصحابة والسلف الصالح، وما ذكره العلماء المعتمدون كـابن القيم، شيخ الإسلام ابن تيمية وغيرهم من أهل العلم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8508/مصادر-تعلم-تفسير-الاحلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31508.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10340,"question":"أخيراً يسأل ويقول: كيف يستطيع المرء أن يتعلم تفسير الأحلام، وهل توجد كتب صحيحة في هذا المجال؟","title":"مصادر تعلم تفسير الأحلام","answer":"الجواب: يتعلمها من كتب العلماء التي ذكرت الأحاديث عن النبي ﷺ في الرؤيا وتفسيرها، مثل كتاب ابن القيم في إعلام الموقعين ذكر جملة من ذلك رحمه الله في الرؤيا، وفي كتب أخرى مؤلفة في الرؤيا يستفيد منها، وأكثر ما يفيد ذلك تدبر الأحاديث التي جاءت في الرؤيا عن النبي ﷺ وتفسير النبي ﷺ لها، تفسير الصحابة، يستفيد منها إذا كان عنده علم وعنده بصيرة يستفيد.\nولا ينبغي أن يقدم على التأويل إلا عن بصيرة وعن علم حتى لا يكذب على الله ولا على رسوله عليه الصلاة والسلام، فينبغي لمن أراد التفسير -تفسير الرؤيا وتعبيرها- أن يعتني بما جاء في السنة عن النبي ﷺ في تفسير الرؤيا، وما جاء عن الصحابة والسلف الصالح، وما ذكره العلماء المعتمدون كـابن القيم، شيخ الإسلام ابن تيمية وغيرهم من أهل العلم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8508/مصادر-تعلم-تفسير-الاحلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31508.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10382,"question":"يسأل سماحتكم فيقول: ما هي الكتب المفيدة والتي تعين على ترسيخ العقيدة الإسلامية الصحيحة في نفوس الناس؟","title":"أهم الكتب التي ينصح بها في العقيدة","answer":"الجواب: أعظمها وأنفعها وأصدقها كتاب الله، فيه الهدى والنور، فأنا أنصح كل مسلم وكل مسلمة أن يعتني بالقرآن، وأن يكثر من تلاوته، فإنه هو الدواء الناجع لجميع الذنوب، وجميع ما يخالف الشرع؛ لأن الله سبحانه يقول: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] .. قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] .. وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] ويقول سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89].\nفالوصية العناية بالقرآن تلاوة وتدبرًا وتعقلًا وعملًا، هذا هو العلاج هذا هو الدواء النافع، ثم كتب الحديث الصحيح، مراجعة الأحاديث الصحيحة، حتى يستفيد منها، مثل صحيح البخاري ، صحيح مسلم ، سنن أبي داود ، الترمذي ، النسائي ، ابن ماجة ، رياض الصالحين، الترغيب والترهيب، يسمع الأحاديث يستفيد، يعالج أمراض قلبه بما يسمع من أقوال النبي عليه الصلاة والسلام مع القرآن الكريم، ثم حضور المواعظ والمحاضرات المفيدة من العلماء المعروفين، والإصغاء إلى خطب الجمعة والاستفادة منها، كل هذا مما يعين على التوبة وعلى ترك الذنوب، كون المؤمن يعتني بسماع المحاضرات من أهل العلم، والندوات العلمية، وخطب الجمعة، يكون حاضر القلب، يستفيد مع العناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، والعناية بمراجعة الأحاديث الصحيحة، والاستفادة منها، هذا هو العلاج، مع الضراعة إلى الله وسؤاله أن الله يهديه وأن الله يصلح قلبه وعمله، وأن الله يرزقه البطانة الصالحة، والجلساء الصالحين، فإن الجلساء الصالحين من أعظم العون على الخير، كونه يتحرى الجلساء الصالحين والأصحاب الطيبين، ويتباعد جدًا عن أصحاب السوء، وعن أصحاب الشر. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8554/اهم-الكتب-التي-ينصح-بها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28007.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10461,"question":"يقول: نسأل سماحتكم عن أسماء الكتب المفيدة التي تقوي ديننا وتجعلنا نحافظ عليه، جزاكم الله خيراً؟","title":"أسماء بعض الكتب المفيدة التي تعين المسلم في دينه","answer":"الجواب: الكتب كثيرة، لكن أعظمها وأشرفها وأصدقها وأنفعها كتاب الله القرآن العظيم، نوصي الجميع بكتاب الله، هو أحسن كتاب وأصدق كتاب، وفيه الدلالة على كل خير، وفيه التوجيه إلى أسباب النجاة والسعادة، وفيه الترهيب من أسباب الهلاك.\nفنوصيك أيها السائل وجميع المسلمين والمسلمات بالعناية بالقرآن العظيم والإقبال عليه، والإكثار من تلاوته وتدبر معانيه والعمل بما فيه من الأوامر والنواهي، فهو كتاب الله فيه الهدى والنور، لا يَأْتِيهِ الْبَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلا مِنْ خَلْفِهِ تَنزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ [فصلت:42] يقول الله فيه : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] ويقول سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] فهذا الكتاب العظيم فيه الهدى والنور، فيه الدلالة على الخير كله والتحذير من الشر كله، فالوصية لكل مسلم ولكل مسلمة العناية بالقرآن والإكثار من تلاوته وحفظه إذا تيسر ذلك، فهو أصل كل خير وينبوع كل خير.\nثم سنة الرسول ﷺ مثل البخاري و مسلم ، الإكثار من قراءتهما وتدبر معاني الأحاديث ومراجعة كلام أهل العلم في تفسيرها وشرحها، ثم السنن الأربعة: أبو داود و الترمذي و النسائي و ابن ماجة ، هذه الكتب من أحسن الكتب بعد الصحيحين، فالعناية بها والاستفادة منها مهم جداً في حق طلبة العلم، الاستفادة من السنن الأربع والعناية بها والإكثار من مراجعتها كل ذلك فيه خير عظيم، ثم بكتب العلماء مثل زاد المعاد لـابن القيم في هدي خير العباد، ومثل الفتاوى لشيخ الإسلام ابن تيمية ومثل في العقيدة: فتح المجيد شرح كتاب التوحيد .. مثل مجموعة التوحيد.. مثل تيسير العزيز الحميد للشيخ سليمان بن عبد الله شرح كتاب التوحيد.. مثل نفس كتاب التوحيد.. مثل كشف الشبهات.. ثلاثة الأصول.. العقيدة الواسطية لشيخ الإسلام ابن تيمية .. التدمرية والحموية كلاهما لشيخ الإسلام ابن تيمية ، هذه كتب مفيدة وعظيمة نافعة، ومثل شرح الطحاوية لـابن أبي العز أيضاً كتاب مفيد في العقيدة، مثل المنتقى في الحديث.. بلوغ المرام في الحديث، الأول: للمجد ابن تيمية والثاني للحافظ ابن حجر ، هذه الكتب أيضاً مفيدة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8645/اسماء-بعض-الكتب-المفيدة-التي-تعين-المسلم-في-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32011.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10531,"question":"السائل: حمدي مصري يقول في هذا  هناك رجل لا يجيد القراءة ولا الكتابة ولا يتفقه في الدين، هل يعذر بجهله أم لا، وإذا كان يعذر فما الدليل جزاكم الله خيرًا؟","title":"وجوب التفقه في الدين فيما لا يسع المسلم جهله","answer":"الجواب: الواجب عليه أن يتعلم، الواجب عليه أن يتعلم ويتبصر ويسأل أهل الذكر ويحضر حلقات العلم حتى يتعلم دينه؛ لأن الله سبحانه خلقه ليعبده: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وهذه العبادة يجب أن يتفقه فيها وأن يعرفها من طريق أهل العلم، من طريق حلقات العلم، من طريق سماع خطب الجمعة والمحاضرات المفيدة، ويسأل أهل العلم حتى يعرف دينه، ما هي العبادة التي خلق لها، يسأل حتى يتبصر وحتى يتعلم وحتى يؤدي ما أوجب الله عليه على بصيرة، وليس له السكوت والإعراض، بل يجب أن يسأل ويتعلم ويتفقه حتى يعبد الله على بصيرة.\nيقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين والله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8706/وجوب-التفقه-في-الدين-فيما-لا-يسع-المسلم-جهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28403.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10723,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الكويت، باعثها المستمع خالد صالح محمد المهيني مستشار، أخونا خالد يقول: عندما أقوم بتدريس مادة التربية الإسلامية للمرحلة الثانوية، وخلال عملي أحتاج إلى وسائل تقنيات للشرح مثال جهاز العرض العلوي، وهذا الجهاز أعرض عليه الآيات القرآنية ليتم شرحها للطلبة، ولكن إعداد هذه الشرائح يتطلب مني قطع صفحات من المصحف لإدخالها في الجهاز، ولا يمكن الاستغناء عن تلك الطريقة؛ لأنها تسهل عملي، فهل هناك إثم في هذه الناحية؟","title":"حكم تقطيع ورق المصحف وإدخالها في جهاز العرض للتعليم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفهذا الإجراء الذي ذكره السائل فيه احتمال وليس بواضح، ونرى أن يرسل السائل رسالة موضحة لعمله أكثر من هذا، حتى ينظر في ذلك ويجاب على ضوء ذلك، نعم.\nالمقدم: يقول: طلب مني العامل الذي يعمل في القسم أن أقدم له المصحف الذي تنقصه بعض الصفحات، فقدمته له، ولكن بعد ذلك أحسست أنني أخطأت بذلك؛ لأن المصحف تنقصه بعض الصفحات، فكيف أعمل؟ هل أستعيده منه مع أن رسول الله ﷺ نهى عمر بن الخطاب رضي الله عنه أن يستعيد أعطيته، فقال عليه الصلاة والسلام: العائد في أعطيته كالكلب يعود في قيئه، أو كما قال ﷺ، فما الحل جزاكم الله خيراً؟\nالجواب: الواجب عليك أن تنبهه على الأخطاء حتى يسدد النقص، عليك أن تنبه الشخص العامل على مواضع الخطأ حتى يكتب ما سقط من المصحف، ويلحق في محله، وبذلك تبرأ الذمة إن شاء الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8898/حكم-تقطيع-ورق-المصحف-وادخالها-في-جهاز-العرض-للتعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34401.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10753,"question":"رسالة مطولة بعض الشيء من إحدى الأخوات المستمعات، تقول أختكم في الله الحائرة (أم عبد الله . س. ج) تقول: تزوجت من رجل يصلي ولله الحمد وأخلاقه طيبة ولله الحمد، ولكنني أرغب من زوجي أن يكون لديه حماس شديد بالنسبة للصلاة وأن يقوم الليل، وأن يكون حافظاً للقرآن الكريم أو بعضاً منه، وأن يكون مجاهداً في سبيل الله، وأن يكون عالماً بشعائر الدين، لكي يخبرني عن الحلال والحرام، ويكون رجلاً مثقفاً، حيث أنني أكثر منه علماً في ديني ولا أمدح نفسي، وَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلَّا قَلِيلًا [الإسراء:85] وهذه الأسباب جعلتني أكره زوجي، ومنذ أن تزوجته وأنا أطلب منه الطلاق، وكراهيتي له تزيد يوماً بعد يوم، فهل يحق لي ذلك يا سماحة الشيخ! مع العلم أنني صليت صلاة الاستخارة عدة مرات قبل الزواج، ولكنني لم أعرف نتيجة الاستخارة فتزوجته، وأنا الآن نادمة على زواجي ذلك، فما هو الحل يا سماحة الشيخ! حيث إن الإنسان يعرف مع من يعاشر، وأنا أريد زوجي أن يكون معي في الجنة يوم القيامة، وأنا أعامله معاملة سيئة لكراهيتي له، فأنا خائفة من الله بالنسبة لهذه المعاملة، وهل أكون من الذين لم يصبروا على قضاء الله وقدره، أرجو إفادتي حول هذه القضايا؟ جزاكم الله خيراً.","title":"نصحية الزوجة لزوجها ضعيف الهمة في طلب العلم","answer":"الجواب: الواجب عليك أيها الأخت في الله الواجب عليك الصبر، وأن تنصحيه وترشديه بالكلام الطيب وترغبيه في التعلم والتفقه في الدين، كما أشرت إلى ذلك، أما عصيانه أو كراهته لكونه لم يجتهد فيما ذكرت من التعلم والتفقه وأن يكون من المسارعين ومن المبادرين إلى الصلاة ونحو ذلك، هذا لا يوجب بغضه أو طلب الطلاق، فلا يجوز لك طلب الطلاق، ما دام الرجل يصلي وليس هناك ما يوجب كفره من نواقض الإسلام، ولكنه ليس عنده المعلومات التي عندك وليس عنده التحمس إلى المسارعة والمسابقة إلى الصلاة، ولكنه يصلي والحمد لله.\nفالواجب عليك السمع والطاعة في المعروف، وعدم طلب الطلاق، والتعاون معه على الخير، من جهة حثه على المطالعة والمذاكرة وحضور حلقات العلم، وسماع هذا البرنامج نور على الدرب حتى يستفيد وحضور حلقات العلم إذا وجدت عندكم من علماء السنة وأهل الخير حتى يستفيد، أما طلب الطلاق فلا وجه له، وليس من اللازم أن يكون زوجك مثلك في العلم، قد يكون الزوج دون المرأة وقد تكون فوقها في العلم، وإذا من الله عليك بالعلم فأحسني إليه ووجهيه بالكلام الطيب والأسلوب الحسن، ورغبيه في الخير وساعديه بكل ما تستطيعين وشجعي أقاربه كأبيه أو أخيه حتى يرغبوه وحتى يساعدوه في التفقه في الدين والتعلم، ولا أنصحك أبداً أن تطلبي الطلاق بل لا يجوز لك ذلك، طلب الطلاق ليس هنا ما يوجب طلبه، ولا يسبب طلبه، وفي الحديث: أيما امرأة طلبت الطلاق من غيرما بأس لم ترح رائحة الجنة.\nفالواجب عليك الصبر والاحتساب والتعاون معه على الخير وإرشاده إلى الخير واحتساب الأجر في كل ما تبذلين في طريق تثقيفه وتفقيهه حتى يكون إن شاء الله كما طلبت وكما رغبت في العلم والفضل، وفق الله الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيرا، النقص في الإنسان شيء وارد سماحة الشيخ، وقد يسيء الإنسان من حيث يعتقد أنه يحسن، أختنا طلبت ما طلبت من زوجها وربما طلبت منه فوق طاقته، أن يحفظ القرآن أن يقوم الليل أن يجاهد في سبيل الله، ربما أنه لا يستطيع هذا، أطمع بكلمة زائدة في هذا الموضوع؟\nالشيخ: على كل حال مثل هذه المطالب هو مخير فيها، حفظ القرآن ليس بواجب، والتهجد بالليل ليس بواجب، ولكن يسن له أن يحفظ ما تيسر من القرآن إذا أمكنه ذلك، يسن له التهجد بالليل والوتر ولو في أول الليل، كل هذا أمر مشروع، والجهاد في سبيل الله فيه تفصيل، إذا استطاع الجهاد وتمكن من الجهاد فالجهاد من أعظم القربات ومن أفضل الطاعات، وقد يكون فرض كفاية، وقد يكون فرض عين، وقد يكون سنة، ففيه تفصيل.\nفالمشروع لها أن تشجعه على الخير وأن تحثه على الخير، ولكن لا تطلب الطلاق من أجل هذا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8919/نصحية-الزوجة-لزوجها-ضعيف-الهمة-في-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34602.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10791,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين هو: (خ. ن. ج) أخونا يقول: ألاحظ يا سماحة الشيخ! أن هناك كثيراً من الآباء قد أهملوا تربية أبنائهم مما أعاد عليهم بأمور سيئة للغاية، لذلك فإني أطلب من سماحتكم أن تتفضلوا بتوجيه الآباء كيما يهتموا كثيراً بأبنائهم ولا سيما في هذا الزمان جزاكم الله خيراً؟","title":"نصيحة وتوجيه للآباء وبيان واجبهم في تربية أبنائهم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الذي ذكره السائل جدير بالعناية؛ لأن مراعاة الأولاد ذكوراً وإناثاً والعناية بهم وتربيتهم الإسلامية أمر من أهم المهمات، يقول النبي الكريم عليه الصلاة والسلام: كلكم راع وكلكم مسئول عن رعيته، فالرجل راع في أهل بيته ومسئول عن رعيته، والأمير -الذي على الناس- راع ومسئول عن رعيته، والمرأة راعية في بيت زوجها ومسئولة عن رعيتها، والخادم راع في مال سيده ومسئول عن رعيته، ثم قال: ألا فكلكم راع وكلكم مسئول عن رعيته خرجه الإمام البخاري في الصحيح وغيره.\nفهذا الحديث العظيم يدل على وجوب العناية بالرعية، وأعظم مسئول في ذلك الإمام الذي على الناس، وهو أمير المسلمين وسلطانهم، يجب عليه أن يرعاهم من كل ما فيه صلاحهم، وسلامة دينهم ودنياهم، والعناية بكل ما ينفعهم في الدنيا والآخرة، حسب الطاقة والإمكان، وأعظم ذلك العناية في الدين، حتى يستقيموا عليه، وحتى يلتزموا به، وذلك بأداء الواجبات وترك المحارم، كما يجب على كل وال على الناس أن يحكم فيهم شريعة الله، وأن يلزمهم بشرع الله، وألا يحكم فيهم غير شرع الله، وهو مسئول عن ذلك كما قال جل وعلا: فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ [الحجر:92] عَمَّا كَانُوا يَعْمَلُونَ [الحجر:93]، وكما في هذا الحديث الصحيح: كلكم راع وكلكم مسئول عن رعيته، فالأمير الذي على الناس راع ومسئول عن رعيته نسأل الله أن يوفق ولاة أمر المسلمين لكل ما فيه صلاحهم وصلاح المسلمين جميعاً.\nوهكذا كل إنسان مسئول عن أهل بيته، فالأب مسئول عن أولاده، والأم مسئولة عن أولادها، من جهة تربيتهم الإسلامية، وأمرهم بالمعروف، ونهيهم عن المنكر وإلزامهم بالحق، وتركهم ما خالف شرع الله ومن ذلك أمر الصلاة، فإنها عمود الإسلام، فالواجب على الأب أن يعتني بأولاده وهكذا الأم، حتى يستقيموا على الصلاة وحتى يحافظوا عليها في بيوت الله مع المسلمين، يقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] ويقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6] والوالدان داخلان في هذا يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6].\nوالعناية بأمر الصلاة من أسباب الوقاية من النار، للوالد والولد جميعاً، وقال تعالى يخاطب نبيه عليه الصلاة والسلام: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132] ويقول عليه الصلاة والسلام: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع.\nفالولد ذكراً كان أو أنثى يؤمر بالصلاة إذا بلغ سبعاً، ويضرب عليها إذا بلغ عشراً؛ لأنه بهذا قد ناهز الاحتلام وقارب، وإذا بلغ وجبت عليه عيناً وفرضاً واستحق بذلك إذا تركها أن يستتاب فإن تاب وإلا قتل من جهة ولي الأمر، فالأمر عظيم، فالواجب على الآباء والأمهات وإخوان الأولاد الكبار وأعمامهم التعاون في هذا الأمر، وأن يجتهدوا في إصلاح الأولاد وتربيتهم التربية الإسلامية، ومن ذلك إلزامهم بالصلاة، وأمرهم بها إذا بلغوا سبعاً، وضربهم عليها إذا بلغوا عشراً وقصروا في ذلك.\nوهكذا يؤمرون بما أمر الله به من بر الوالدين، وحفظ اللسان عن السب والشتم والكذب، وعن غير هذا من المعاصي، وعن غير هذا مما حرم الله ، وهكذا يمنعون من شرب المسكرات والتدخين، حتى لا ينشئوا على هذا الباطل، فيجب على الآباء والأمهات العناية بالأولاد لما ينفعهم في الدنيا والآخرة وعليهم أن يمنعوهم مما حرم الله  حتى ينشئوا نشأة صالحة وحتى يستقيموا على دين الله، فإذا بلغوا فإذا هم قد عرفوا ما يجب عليهم وما يحرم عليهم، وقد تربوا على الخير وعلى ترك الشر، ولأبيهم وأخيهم وأمهم ومن سعى في هذا الخير له مثل أجورهم، كما قال النبي الكريم عليه الصلاة والسلام: من دل على خير فله مثل أجر فاعله وهذا من فضل الله ، نسأل الله للجميع التوفيق والهداية، نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8964/نصيحة-وتوجيه-للاباء-وبيان-واجبهم-في-تربية-ابناىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_351/35101.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":10809,"question":"رسالة وصلت إلى البرنامج من المستمعة (أ. أ. الزاوي) من طرابلس في ليبيا، أختنا لها عدد من الأسئلة، من بينها سؤال تقول فيه: أرجو من سماحتكم أن تتفضلوا بإبداء رأيكم حول مؤلفات أبي الأعلى المودودي، وأبي الحسن الندوي، وسيد قطب.","title":"تقييم كتب أبي الأعلى المودودي وأبي الحسن الندوي وسيد قطب","answer":"الجواب:  كلها كتب مفيدة، كتب، هؤلاء الثلاثة -رحمهم الله- كلها كتب مفيدة، فيها خير كثير، ولا تخلو من بعض الأغلاط، كل إنسان يؤخذ من قوله ويترك، ليسوا معصومين، فطالب العلم إذا تأملها عرف ما فيها من الأخطاء، وما فيها من الحق، وهم -رحمهم الله- قد اجتهدوا إلى الخير، ودعوا إلى الخير، وصبروا على المشقة في ذلك، وأبو الحسن موجود -بحمد الله- وفيه الخير الكثير، ولكن ليس معصومًا، ولا غيره من العلماء، العصمة للرسل -عليهم الصلاة والسلام- فيما يبلغون عن الله، الرسل عصمهم الله في كل ما يبلغون عن الله، وهكذا الأنبياء، أما العلماء كل عالم يخطئ ويصيب، ولكن -بحمد الله- صوابهم أكثر، وقد أفادوا وأجادوا ونفعوا الناس. يقول مالك -رحمه الله- ابن أنس، إمام دار الهجرة في زمانه: ما منا إلا راد ومردود عليه إلا صاحب هذا القبر، يعني: الرسول، عليه الصلاة والسلام. فالمؤمن يطلب العلم، وهكذا المؤمنة تطلب العلم، وكل واحد يتفقه في الدين، ويتبصر، ويسأل عما أشكل عليه، يقرأ القرآن، يقرأ السنة، يعتني حتى يعرف الحق بأدلته، وحتى يعرف الغلط إذا غلط العالم، ولا يجوز أن يقال: هذا فلان العالم الجليل يؤخذ قوله كله من دون نظر! لا، بل لابد من النظر والعناية، وعرضها على الأدلة الشرعية، فما وافقها قبل، وما خالف الأدلة الشرعية ترك، وإن كان عظيمًا، وإن كان له أجر عظيم، وإن كان مجتهدًا في الخير، وإن كان مشهورًا. نعم.","link":"https://binbaz.org.sa/fatwas/8989/تقييم-كتب-ابي-الاعلى-المودودي-وابي-الحسن-الندوي-وسيد-قطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35311.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10870,"question":"يقولان أيضًا -في سؤال مهم فيما أتصور سماحة الشيخ-: نحن نحب التزود من معين الدين الإسلامي، لكننا نجهل الكتب المفيدة في هذا المجال، نرجو من سماحتكم ترشيح بعض الكتب الموثوقة التي تساعد على التفقه في الدين، جزاكم الله خيرًا.","title":"أفضل الكتب التي ينصح بها للتفقه في الدين","answer":"الجواب:  أعظم كتاب، وأشرف كتاب، وأصدق كتاب يعلم الدين، ويرشد إلى أحكام الله، ويحصل به الفقه في الدين كتاب الله القرآن، هو أعظم كتاب، وهو أصدق كتاب، وأشرف كتاب، أنزل على أشرف نبي -عليه الصلاة والسلام- وفي أشرف بقعة في مكة والمدينة، وفي أفضل ليلة -ليلة القدر- فنوصي السائلة وغير السائلة بالعناية بكتاب الله  نوصي جميع المسلمين رجالًا ونساءً بالعناية بالقرآن، والتفقه فيه، والإكثار من تلاوته، ومراجعة كتب التفسير لمعرفة ما أشكل من ذلك، وسؤال أهل العلم عما أشكل أيضًا هذا هو أعظم كتاب، وأنفع كتاب، وأصدق كتاب، يقول سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، ويقول -جل وعلا-: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، ويقول سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89]. فالواجب على المسلمين العناية بهذا الكتاب، والإقبال عليه والإكثار من تلاوته، وتدبر معانيه، والاستفادة مما بينه ربنا سبحانه من أوامر ونواهي وقصص عمن مضى من الأمم حتى يستفيد المؤمن والمؤمنة من كلام ربنا . ومن أحسن الكتب التي تعين على فهم الكتاب كتب التفسير المعروفة المأمونة، مثل: كتاب تفسير ابن جرير، تفسير البغوي، تفسير ابن كثير -رحمة الله عليهم- تفسير الشوكاني، تفسير القرطبي، كلها كتب مفيدة، لكن أحسنها هذه الثلاثة: تفسير ابن جرير، والبغوي، وابن كثير، وكتب أخرى مفيدة، مثل: القرطبي، والشوكاني، وكتب أخرى تفيد المؤمن مع التحرز مما فيها من الغلط. كذلك كتب الحديث فيها الخير العظيم، فليس بعد القرآن خير وأصح من أحاديث الرسول ﷺ هو المعلم، والمرشد، والمبين لما بينه الله -جل وعلا- كما قال سبحانه: وَالنَّجْمِ إِذَا هَوَى ۝ مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى [النجم:1-2] يعني محمد -عليه الصلاة والسلام- وَمَا يَنْطِقُ عَنِ الْهَوَى ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:3-4]، فهو -عليه الصلاة والسلام- مفسر لكتاب الله، ومبين لمعانيه، وخير الهدي هديه، عليه الصلاة والسلام. فالمشروع للمؤمن والمؤمنة العناية بالسنة أيضًا مع القرآن، والحرص على فهم الأحاديث الصحيحة مثل صحيح البخاري، صحيح مسلم، وهكذا بقية الكتب التي ألفها أئمة الحديث، كـأبي داود والترمذي والنسائي وابن ماجة وموطأ مالك وغيرها من كتب السنة، لكن أصح الكتب وأعظمها وأنفعها صحيحا البخاري ومسلم. فينبغي أن تكون العناية بهما أكثر، والإقبال عليهما أكمل، ولا سيما طالب العلم، وطالبة العلم الذي يميز بين الصحيح والضعيف، ويفهم المعاني، فينبغي أن يعتني طالب العلم وطالبة العلم بهذين الكتابين العظيمين أكثر من غيرهما، صحيح البخاري، وصحيح مسلم . ومن الكتب المختصرة بلوغ المرام، كتاب مفيد نافع محرر للحافظ ابن حجر، وكتاب عمدة الحديث للحافظ عبدالغني بن عبدالواحد المقدسي، كتاب مفيد عظيم، كتاب المنتقى للمجد ابن تيمية، كتاب مفيد أيضًا وعظيم، يستفيد من هذه الكتب طالب العلم، وطالبة العلم، وما أشكل من ذلك يسأل عنه الطالب أهل العلم، ويراجع الكتب التي فيها بيان الصحيح من الضعيف، وفيها بيان مسائل الخلاف، كالمغني لـابن قدامة هو كتاب عظيم الفائدة. المقدم: هذا بالنسبة للفقه. الشيخ: الفقه... وبيان الراجح من كلام العلماء فيما اختلفوا فيه؛ لأنه كتاب عظيم يبين مسائل الخلاف والأدلة والمرجح والراجح، ومثل الفروع لـابن مفلح، شرح المهذب للنووي وأشباهه من الكتب التي تذكر خلاف العلماء، وتبين الراجح، وهذا بالنسبة إلى أهل العلم بالنسبة إلى من يميز بين الأقوال، ويعرف الأدلة؛ لأنه صاحب علم، وقد تفقه في الدين، وتبصر، وعرف كلام أهل العلم في الحديث الصحيح والضعيف، ومما يرجح به الخلاف في مسائل الخلاف. أما العامي وشبه العامي فيسألون أهل العلم الذين يثقون بهم من أهل السنة، يسألونهم عما أشكل عليه، ويعمل بما يرشدونه إليه إذا لم يكن عنده بصيرة وعلم يستطيع أخذ المسائل بأدلتها من كتب أهل العلم. ومن أحسن الكتب زاد المعاد لـابن القيم وهو كتاب جامع بين الحديث والفقه جميعًا، كتاب جامع زاد المعاد لـابن القيم -رحمه الله- وإغاثة اللهفان له أيضًا، إعلام الموقعين له أيضًا، كتب عظيمة فيها أحكام، وفيها علم عظيم، وفي العقيدة كتاب التوحيد، وفتح المجيد، والعقيدة الواسطية، كتاب التدمرية لشيخ الإسلام ابن تيمية، كتاب الحموية له أيضًا، هذه كتب عظيمة في العقيدة، شرح الطحاوية لـابن أبي العز كتاب عظيم، نسأل الله للجميع التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ! ذكرتم بعض كتب التفسير، وهي من الكتب ذات العصر القديم، هل تتفضلون بذكر شيء من الكتب التي عنيت بدراسة القرآن وتفسيره، مما ألف في العصر الحديث؟ الشيخ: منها مثل ما تقدم فإن عهده قريب، الشوكاني عهده قريب في القرن الثالث عشر، في كتب مؤلفة أخيرًا فيها مثل (في ظلال القرآن) ومثل تفسير ابن سعدي -رحمه الله- هذه كتب مفيدة، وينبغي للمؤمن بخصوص تفسير السيد قطب ينبغي للمؤمن أن يتحرز مما فيه من الأغلاط، ويأخذ ما فيه من الخير والفائدة. وهكذا بقية التفاسير التي فيها، كل كتاب في الغالب لا يخلو من شيء، مثل الجلالين تفسير الجلالين، ومثل تفسير القرطبي، ومثل غيره من الكتب التي يقع فيها بعض التأويل، ينبغي للمؤمن أن يحذر ما فيها من الأخطاء ليسأل أهل العلم عما أشكل عليه، ويستفيد منها فيما وافقت الصواب فيه. المقدم: طيب طيب.. جزاكم الله خيرًا، بعد أن ذكرتم بعض التفاسير هل تتفضلون بذكر بعض الشروح للسنة؟ الشيخ: نعم فيه شروح كثيرة مثل فتح الباري على البخاري، وشرح النووي لـمسلم، ومثل نيل الأوطار للشوكاني، هذه كتب جيدة ومفيدة، فتح المجيد في العقيدة للشيخ عبدالرحمن بن حسن لكتاب التوحيد، شرح ابن أبي العز على العقيدة الطحاوية، كلها كتب مفيدة، وشروح جيدة، ولا يخلو بعضها من شيء، مثل فتح الباري، ومثل شرح مسلم لا يخلو من بعض الأغلاط في العقيدة على مذهب الأشاعرة، لكن طالب العلم ينبذ الخطأ، ويحذر الخطأ. وهكذا ما قد يقع في نيل الأوطار، وسبل السلام شرح بلوغ المرام وغيرها من الكتب، يأخذ ما فيها من الصواب، ويستعين بها على الفقه في الدين، وما فيها من خطأ يتركه إذا بان له، وإذا أشكل عليه يسأل أهل العلم، ويتذاكر مع أهل العلم، ومع زملائه الذين لهم بصيرة، ولهم فهم حتى يتجنب الخطأ، يستفيد مما وافق الصواب، نعم. المقدم: جزاكم الله خيرًا، هذه الكتب التي تفضلتم بذكرها سماحة الشيخ يبدو أنها لفئة معينة من المتعلمين، لكن ماذا عن المبتدئ الكتب التي تنصحون المبتدئ بقراءتها؟ الشيخ: المبتدئ ينبغي له أن يقرأ الكتب المعروفة التي ألفها المعروفون بالعقيدة الطيبة، والسلامة من الأخطاء في مؤلفاتهم حتى لا يقع في شيء من الخطأ، مثل العقيدة الواسطية لشيخ الإسلام ابن تيمية، مثل كتاب التوحيد للشيخ محمد بن عبدالوهاب، مثل ثلاثة الأصول كشف الشبهات، كتب مفيدة جيدة ينبغي لطالب العلم المبتدئ يحفظها، ومثل الأربعين النووية مع تتمتها لـابن رجب خمسين حديثًا يحفظها، هذه مفيدة ومختصرة، وعمدة الحديث كذلك للطلبة يحفظونها مختصرة أربعمائة حديث وكسور، وحاجة قليلة زيادة عن أربع، يحفظها طالب العلم، حفظناها في الصغر، ينبغي أن يحفظها طالب العلم في الثانوي والمتوسط. نعم. المقدم: جزاكم الله خيرًا، وبالنسبة للفقه؟ الجواب: مثل العمدة للموفق، العمدة للموفق في الفقه. المقدم: موفق ابن قدامة؟ الشيخ: ... مختصرة وجيدة مفيدة. نعم. المقدم: بالنسبة للمذاهب الأخرى يبدو أن هذا على المذهب الحنبلي بالنسبة للمذاهب الأخرى؟ الشيخ: والله ما تأملت يعني الكتب المختصرة للمذاهب الأخرى ما حصل لي تأمل لها، فيه أشياء نسمع عنها، لكن ما أستطيع أقول فيها شيئًا،  نعم؛ لأني لم أتأملها كثيرًا. نعم. المقدم: جزاكم الله خيرًا، شيء مهم بالنسبة للناس سماحة الشيخ! قد يقولون: إن هذه الكتب لا يسهل وصولها إلينا حول نشر مثل هذه الكتب القيمة؟ الشيخ: الذي نعلم أنها الكتب كلها تباع، كلها موجودة، وكلها تباع، كلها تباع، وكلها موجودة يمكن شراؤها من المكتبات، ما نعلم شيئًا من هذه مفقود، كلها موجودة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9051/افضل-الكتب-التي-ينصح-بها-للتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35805.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10876,"question":"هل كتاب الطب النبوي لـابن قيم الجوزية كتاب نافع ومفيد؟","title":"تقييم كتاب الطب النبوي لابن القيم","answer":"الجواب:  نعم، كتاب الطب لـابن القيم والذهبي كلها كتب طيبة، كذلك لـابن مفلح في الآداب الشرعية كلها كتب مفيدة فيها أشياء كثيرة عن النبي ﷺ نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9049/تقييم-كتاب-الطب-النبوي-لابن-القيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35803.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10974,"question":"يقول هذا السائل: أسأل عن كتاب الأذكار المنتخبة من كلام سيد الأبرار للنووي سماحة الشيخ؟","title":"تقييم كتاب الأذكار للنووي","answer":"الجواب:  كتاب جيد مفيد، وفيه بعض الأشياء الضعيفة، لكنه مفيد في الجملة، يستفاد منه في الجملة نعم.","link":"https://binbaz.org.sa/fatwas/9152/تقييم-كتاب-الاذكار-للنووي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28618.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11042,"question":"ما حكم وجود الكتب الشرعية من تفسير القرآن الكريم، أو خلاف ذلك من الأحاديث في مكتبتي في المنزل، علمًا بأنني أقتني هذه الكتب رغبة مني في بعض الكتب القيمة المفيدة لي ولأبنائي، لكن أبنائي صغار، وأنا أنشغل كثيرًا عنها، فهل علي شيء في هجر هذه الكتب؟","title":"حكم اقتناء الكتب وعدم قراءتها","answer":"الجواب:  ليس عليك شيء تحفظ لمصلحتها، إذا جاء أحد يطالع، يستفيد منها، أولادك يستفيدون منها -إن شاء الله- أنت على خير -إن شاء الله- لا بأس بذلك، نعم.","link":"https://binbaz.org.sa/fatwas/9220/حكم-اقتناء-الكتب-وعدم-قراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28724.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11058,"question":"بعد هذا ننتقل إلى المملكة المغربية لنستعرض رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من هناك، يقول: باسم عبدالله، الأخ باسم أول سؤال له يقول: ما هي الكتب التي تنصحون بقراءتها؟","title":"التعريف بأهم ما ينصح بقراءته من الكتب","answer":"الجواب:  أعظم كتاب أنصحك وأنصح غيرك بقراءته القرآن العظيم، هو أعظم كتاب وأشرف كتاب، وأصدق كتاب كتاب الله العظيم، نوصيك ونوصي الإخوان جميعًا والأخوات بالإكثار من قراءته، تدبر معانيه، كل حرف بحسنة، والحسنة بعشر أمثالها، وفيه العلم العظيم، والدعوة إلى الخير، وإلى الأخلاق الفاضلة، والأعمال الصالحة، وفيه الترهيب والتحذير من كل ما نهى الله عنه، فنوصي الجميع بالإكثار من قراءة القرآن بالتدبر، والتعقل كما قال الله سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]. ثم الكتب التي فيها الأحاديث الصحيحة عن النبي ﷺ إذا كنت من أهل العلم مثل كتاب البخاري ومسلم، والكتب التي ألفت في الصحيح تستفيد منها، مثل عمدة الحديث للشيخ: عبدالغني بن عبدالواحد المقدسي، ومثل بلوغ المرام فيه خير كثير، وإن كان فيه أحاديث ضعيفة، ولكنها مبينة، كتاب جيد مفيد، بلوغ المرام، منتقى الأخبار لابن تيمية المجد.  هذه كتب مفيدة وإن كان فيها بعض الضعيف، لكن يعرف الضعيف بالتنبيه عليه من المؤلف ومن الشوكاني في نيله الذي هو شرح المنتقى، وبلوغ المرام قد بين المؤلف الأحاديث الضعيفة. وتسأل أهل العلم عما أشكل عليك، ومثل رياض الصالحين كتاب جيد مفيد، تقرؤه في بيتك، وعلى إخوانك، وعلى بيتك، وبينك وبين زملائك تستفيدون. وفي العقيدة مثل فتح المجيد للشيخ: عبدالرحمن بن حسن، كتاب التوحيد للشيخ: محمد بن عبدالوهاب، كشف الشبهات له أيضًا -رحمه الله- ثلاثة الأصول كتاب جيد للشيخ: محمد بن عبدالوهاب -رحمه الله- العقيدة الواسطية لشيخ الإسلام ابن تيمية، الكتب مفيدة للطالب والطالبة، ينبغي حفظها والاستفادة منها، فتح المجيد كتاب جيد شرح كتاب التوحيد، ينبغي الاستفادة منه، هكذا كتب العقيدة المعروفة السليمة، مثل شرح ابن أبي العز على متن الطحاوية، مثل الحموية لـشيخ الإسلام، التدمرية لـشيخ الإسلام، لمعة الاعتقاد للموفق، هذه كتب جيدة في العقيدة مثل تفسير ابن كثير، كتاب مفيد في التفسير، تفسير ابن كثير -رحمه الله- والبغوي، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9236/التعريف-باهم-ما-ينصح-بقراءته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36709.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11188,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من خميس مشيط، باعث الرسالة مستمع يقول: أخوكم في الله علي القحطاني الأخ علي له قضية يقول فيها: إن لي إخوانًا ولله الحمد متعلمين، ولكنهم عند الصلاة لا يهتمون بها، ويصلون وهم يلعبون بالصلاة، وعندما أفرغ من الصلاة آمرهم بإعادة الصلاة فيرفضون ويهربون، وعندما أضربهم على ذلك تغضب الوالدة، فبماذا أتخلص من هذه المشكلة، علمًا بأن أصغرهم عمره عشر سنوات، وأكبرهم خمس عشرة سنة؟","title":"كيفية تربية الصغار الذين يلعبون في الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه أما بعد.  فالواجب عليك هو ما فعلت من تأديبهم والقيام عليهم؛ لقول النبي ﷺ: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر فإذا كان الوالد غير موجود فأنت في محل الوالد، وإن كان الوالد موجودًا.  فالواجب عليه أن يقوم بهذه المهمة، وعلى الوالدة أن تساعد في ذلك ولا تغضب، عليها أن تساعد في ذلك، وأن تعينك على هذا الأمر، وأن تتكلم عليهم وتزجرهم عن ذلك، حتى تكون معك في هذا الأمر؛ لأن الله جل وعلا يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] فلا بد من التعاون بينك وبين الوالدة على البر والتقوى، وعليك أن تشرح لها الأمر بالعبارة الحسنة، والأسلوب الحسن، وأن هذا شيء واجب، حتى تعلم الحق وتستجيب للحق إن شاء الله. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ! هل تنصحونه باصطحابهم إلى المسجد حتى يتأدبوا بآداب المصلين أيضًا؟ الشيخ: إذا تيسر اصطحابهم هذا طيب، وإلا فالواجب سوقهم إلى المسجد سواء معه وإلا قبله وإلا بعده، لا بد من حضورهم صلاة الجماعة، يصلون مع الناس في المساجد ولو بالضرب، ولو بالرفع إلى الهيئة إذا دعت الحاجة إلى الهيئة، حتى يساعدوه على ذلك؛ لأن هذا أمر لازم، أما الصلاة في البيت فلا، لا يصلون في البيت، بل يجب أن يصلوا مع الناس ويجب عليه أن يقوم عليهم بما يستطيع، من الضرب والتوبيخ وغير ذلك. نعم. المقدم: جزاكم الله خيرًا من كان له أبناء لكنهم لا يهتمون بالصلاة في المساجد، وتعب مع أولاده والحال كما ذكر، هل تنصحونه أيضًا بمراجعة الجهات المختصة؟ الشيخ: مثل ما تقدم، مثل ما تقدم إذا عجز يرفع الأمر للهيئة، تساعده الهيئة في ذلك.  المقدم: بارك الله فيكم، جزاكم الله خيرًا. الشيخ: نسأل الله السلامة. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/9356/كيفية-تربية-الصغار-الذين-يلعبون-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37201.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":11230,"question":"أختنا تقول: لدي رغبة شديدة في سلوك الطريقة المثلى للتفقه في الدين، فكيف أسلكها؟ وماذا أقرأ؟ وكيف أتفقه في الدين؟","title":"الطريقة المثلى للتفقه في الدين","answer":"الجواب:  نوصيك بالعناية بالقرآن الكريم، فهو أصل كل خير، وهو أصل العلم، نوصيك بالإكثار من تلاوة القرآن، والتدبر والتعقل لمعانيه، وقراءة الأحاديث الصحيحة مثل: عمدة الحديث للشيخ العلامة عبدالغني بن عبدالواحد المقدسي ، ففيها أحاديث عظيمة صحيحة، مثل: بلوغ المرام للحافظ ابن حجر كتاب جيد، قد أوضح فيه الأحاديث الصحيحة والضعيفة، فهما كتابان عظيمان، ونوصيك أيضًا باستماع برنامج نور على الدرب الذي يذاع من إذاعة القرآن كل ليلة، نوصيك باستماع هذا البرنامج فهو مفيد جدًا، ونوصيك بسؤال أهل العلم من طريق الهاتف، من طريق المكاتبة عما أشكل عليك، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9421/الطريقة-المثلى-للتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37318.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11306,"question":"تقول: إخوتي ثلاثة الصغير عمره ستة عشر عامًا، ووالدنا متوفى، وإخوتي لا يصلون ووالدتي تعبت منهم، فقد عملت معهم الكثير.الشيخ: أعد، لا حول ولا قوة إلا بالله.المقدم: إخوتي ثلاثة الصغير عمره ستة عشر عامًا، ووالدنا متوفى، وإخوتي لا يصلون، ووالدتي تعبت منهم، فقد عملت معهم الكثير لنصحهم، ماذا تفعل والدتي أرجو أن تدعو لإخواني ولجميع شباب المسلمين بالهداية؟ جزاكم الله خيرًا.","title":"موقف أم توفي زوجها تجاه أبناء لا يصلون","answer":"الجواب:  نسأل الله لهم الهداية والصلاح، نسأل الله أن يهديهم ويعيذهم من الشيطان، نسأل الله أن يعينك وأمك على جهادهم، والواجب نصيحتهم والحرص على إقامتهم الصلاة، والواجب ... منهم ولو أن ضربتهم الوالدة، أو ترفع بأمرهم إلى الهيئة هيئة الأمر بالمعروف حتى يساعدوها في ذلك، لأن هذا الأمر لا يسكت عنه هذا الأمر خطير. فالواجب أن ينصحوا ويوجهوا من الوالدة وغير الوالدة فإن استقاموا وإلا يرفع بأمرهم إلى الهيئة حتى يعاقبوا العقوبة الرادعة، نسأل الله لنا ولهم الهداية، نسأل الله أن يهديهم ويردهم إلى الصواب. نعم.  المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9484/موقف-ام-توفي-زوجها-تجاه-ابناء-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37616.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":11353,"question":"أيضًا المستمع محمد عبدالعزيز محمد من المملكة الأردنية الهاشمية إربد، يسأل ويقول: ما رأي سماحتكم في درس يلقى في كل يوم جمعة وبالتحديد قبل الأذان ويمتد إلى أن يرفع الأذان، هل هذا الدرس من سنة نبينا محمد ﷺ؟","title":"حكم إقامة درس قبل أذان الجمعة","answer":"الجواب:  لا أعلم أن فيه بأسًا، لا أعلم فيه بأسًا ويروى عن أبي هريرة  أنه كان يقوم بذلك، يروى عن أبي هريرة  أنه ... يقوم بهذا الدرس قبل دخول الخطيب وإذا أذن ترك ذلك، وإن ترك الناس يقرؤون القرآن ويذكرون الله ويدعون فهذا حسن -إن شاء الله- وإن فعله بعض الأحيان فهذا أيضًا أسهل، أما الاستمرار عليه كل يوم كل يوم فلعل تركه أولى؛ لأنه قد يشغل الناس عن قراءة القرآن وعن الدعاء والضراعة إلى الله والتسبيح والتهليل ونحو ذلك، قد يملون، قد يضعفون عن سماع الخطبة أيضًا خطبة الجمعة فلعل ذلك أولى، وإذا فعله بعض الأحيان فأرجو أن لا حرج فيه كما روي هذا عن أبي هريرة . نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9528/حكم-اقامة-درس-قبل-اذان-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37805.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11397,"question":"جزاكم الله خيرًا يا سماحة الشيخ، (أ. أ. أ) يقول: أيهما أفضل لطالب علم الدعوة إلى الله، أو التفرغ لطلب العلم؟ جزاكم الله خيرًا.","title":"الأفضلية لطالب العلم","answer":"الجواب:  إذا كان من أهل العلم وعنده القدرة على الدعوة، عنده علم وبصيرة؛ فالأفضل له الدعوة. أما إن كان حتى الآن ليس عنده العلم الذي يعينه على الدعوة، عنده حاجة، يتفرغ لطلب العلم، ويتفقه في الدين؛ حتى يكون أهلًا للدعوة، وإقامة الأدلة الشرعية، أما إذا كان قد رزقه الله العلم، وقد تفقه في الدين، وعنده الأدلة الشرعية، فكونه يتفرغ للدعوة مع تعليم الناس العلم في المسجد، أو في بيته؛ يجمع بين الأمرين، فهذا خير عظيم، يقرأ في الأوقات المناسبة، أو يعلم الناس، أو يقرأ على العلماء، ويقوم بالدعوة في الأوقات الأخرى، نعم.","link":"https://binbaz.org.sa/fatwas/9575/الافضلية-لطالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29317.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11439,"question":"ما هي نصيحتكم للأب والأم والمدرسة في تربية الأبناء؟","title":"نصيحة للآباء والأمهات والمدرسين حول تربية الأبناء","answer":"الجواب:  النصيحة للجميع أن يوجه الأبناء إلى طاعة الله، وأن يعلموا الأخلاق الفاضلة، والكلمات الطيبة، وأن ينصحوا في طلب العلم والتفقه في الدين، والمحافظة على الصلاة، وعلى حسن الخلق مع الوالدين، ومع الأقارب، ومع الزوار والضيوف، وعلى الوالد والوالدة أيضًا أن يكونا مثالًا صالحًا لأولادهم في الأخلاق الفاضلة، والمحافظة على الصلاة في الجماعة، والحذر من المحرمات كالمسكرات، والدخان، وحلق اللحية، وأشباه ذلك. على الوالد أن يكون مثالًا طيبًا لأولاده في سيرته الطيبة، وفي محافظته على الصلاة في الجماعة، وفي توفير لحيته، وفي اجتنابه المعاصي، وهكذا الأم، كل منهما عليه أن يكون مثالًا طيبًا في الأخلاق الفاضلة، والأعمال الصالحة، والحذر من المعاصي، نسأل الله للمسلمين الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9621/نصيحة-للاباء-والامهات-والمدرسين-حول-تربية-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29416.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":11609,"question":"من سوريا رسالة بتوقيع مستمع يقول: (ع. أ. و) أخونا يسأل عن كتاب (حياة الصحابة) وأورد جملة من الآثار الموجودة في ذلكم الكتاب، يسأل عن صحتها، ما هو رأي سماحة الشيخ أولًا في الكتاب؟","title":"تقييم كتاب حياة الصحابة","answer":"الجواب:  الكتاب يجمع بين الغث والسمين، بين الصحيح والضعيف، فيستفاد منه فيما صح، وتراجع الكتب الأخرى، مثل صحيح البخاري، صحيح مسلم، رياض الصالحين، الترغيب والترهيب، منتقى الأخبار، بلوغ المرام، حتى يستفيد المؤمن من هذه الكتب، وقَلَّ كتاب غير كتاب الله إلا وقد يقع فيه بعض الشيء الضعيف والغلط.  فالحاصل أن المؤمن يستفيد من هذا الكتاب ما صح وثبت. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9792/تقييم-كتاب-حياة-الصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38803.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11718,"question":"سماحة الشيخ لو تكرمتم بنصيحة لأولئك الذين يستمعون إلى الأشرطة والندوات بحيث يكون هناك تركيز حتى لا يكون الفهم مقلوبًا؟","title":"ضرورة الرجوع إلى أهل العلم لتصحيح المفاهيم المغلوطة","answer":"الجواب:  نعم على كل من يسمع الأشرطة، ويشك في شيء من معناها أن يسأل أهل العلم، بالكتابة بالهاتف، لا يسكت على شيء يجهله، أو كان صاحب الشريط غير معروف، قد يغلط صاحب الشريط، قد يكون ليس معروفًا من أهل العلم، قد يكون من الطلبة الذين ما عندهم بصيرة في العلم، فإذا سمع الرجل، أو المرأة ما يشكل عليه، أو يظن أنه خطأ، أو من إنسان غير معروف من أهل العلم يسأل، يسأل المعروفين من أهل العلم، بالمكاتبة، أو بالهاتف بالتلفون عما أشكل عليه؛ لأن الله سبحانه يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]، وروي عنه ﷺ: أن قومًا أفتوا بغير علم، فقال -عليه الصلاة والسلام-: ألا سألوا إذ لم يعلموا؟! إنما شفاء العي السؤال. فالواجب على الرجل والمرأة، وعلى طالب العلم أن يتثبت في الأمور، وأن يسأل عما أشكل عليه بالمشافهة، بالمكاتبة، من طريق التلفون، لا يتأخر عن السؤال ولا يستحي (إن الله لا يستحي من الحق) فالسؤال مطلوب، والفائدة مطلوبة، والتعلم واجب حتى يعلم الإنسان ما أوجب الله عليه، وما حرم الله عليه بالأدلة الشرعية، والعامي يسأل أهل العلم، ويستفصل عما أشكل عليه من أهل العلم، ويتحرى أهل العلم المعروفين بالعلم والفضل والورع، ولا يسأل من هب ودب ممن لا يعرفهم، ولا يعلم ورعهم ولا علمهم، ولكن يتحرى سؤال أهل العلم المعروفين، إما بالسفر إليهم وسؤالهم مشافهة، أو بالمكاتبة، أو بالهاتف (التلفون) أو بالإبراق، أو بالفاكس أي طريق يمكنه أن يستعمله في هذا الباب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9901/ضرورة-الرجوع-الى-اهل-العلم-لتصحيح-المفاهيم-المغلوطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29907.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11749,"question":"يقول: أنا شاب في الخامسة والعشرين، وبعد بلوغي هذا السن وفقني الله إلى حفظ أكثر من نصف القرآن، وأجد في نفسي الرغبة في إلقاء الخطبة يوم الجمعة، أرجو التوجيه من فضيلتكم، وأسماء المراجع التي أستعين بها، جزاكم الله خيرًا.","title":"كتب ينتفع بها الخطيب","answer":"الجواب:  إذا كان لديك القدرة، وسمحت لك الجهات المختصة؛ فلا بأس بذلك، لكن أنصحك أن تأخذ بعض الكتب التي ألفها العلماء، وتستعين بها في ذلك، مثل فقه الخطب للشيخ: محمد بن صالح بن عثيمين، والخطب للشيخ: محمد بن عبدالوهاب -رحمه الله- والشيخ: عبدالعزيز بن عبدالله بن الشيخ، وخطب أخرى للمشايخ لا بأس تستفيد منها إذا سمحت لك الجهة المختصة، وعينتك خطيبًا، أو سمحت لك أن تخطب في أي مسجد؛ فلا بأس أن تستعين بالكتب المؤلفة في هذا الباب، وإن كان لديك قدرة، وجمعت أحاديث في الباب، وكلمات طيبة تعرضها على بعض العلماء حتى يساعدوك في هذا الشيء، وتستعين برأيهم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9931/كتب-ينتفع-بها-الخطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39312.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11779,"question":"يسأل أيضًا ويقول: شخص سئل عن شيء يعرفه، فحلف بالله العظيم أنه لا يدري عن ذلكم الشيء، وهو الآن نادم أشد الندم على ما فعل، ما كفارة ذلك؟ وما الشيء الذي يجب عليه فعله؟ جزاكم الله خيرًا.","title":"حكم من كتم علماً","answer":"الجواب:  عليه التوبة إلى الله من .. عليه التوبة من كتمانه العلم، قد قال النبي ﷺ: من سئل عن علم، فكتمه؛ ألجمه الله يوم القيامة بلجام من نار إلا إذا كان ذلك الشيء يخشى من الإخبار به فتنة وشرًا عظيمًا، هو معذور، فإن كتم العلم إذا كان في كتمه مصلحة أكبر من إظهاره فلا بأس، مثلما قال النبي ﷺ لـمعاذ لما أخبره بحق الله على العباد، وحق العباد على الله، قال معاذ: أفلا أبشر الناس؟ قال: لا تبشرهم فيتكلوا ثم بشر بها معاذ، والنبي ﷺ بشر بذلك، وأخبر الأمة بذلك إبلاغًا للحجة، وإقامة للحجة. فالمقصود: إذا كان إخبارك بما سئلت عنه يترتب عليه شر تراه عظيمًا، وخطيرًا؛ فأنت معذور.","link":"https://binbaz.org.sa/fatwas/9965/حكم-من-كتم-علما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39503.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11787,"question":"بعد هذا رسالة مطولة بعث بها أحد الإخوة يقول: أخوكم في الله (ب. ع. ز)، أخونا رسالته مطولة جدًا، ملخص ما في هذه الرسالة أن والده تزوج، وأنجب من الزوجة الجديدة، وحينئذ أصبح لا يعاملهم معاملة الأب الحنون على أبنائه.الشيخ: أعد.المقدم: يقول: إن أباه تزوج، وأنجب من المرأة الجديدة، وحينئذ تغيرت مشاعره نحو أبنائه القدامى، وأصبح لا ينظر إليهم نظرة الأب الحنون، ويرجو من سماحة الشيخ توجيه هذا الأب بالذات وتوجيه أمثاله، ولاسيما أنهم يصفونه بالإهمال حتى لبنت معوقة عمرها ثنتا عشرة سنة، جزاكم الله خيرًا؟","title":"حكم إهمال الوالد لأولاده بعذر زواجه من ثانية","answer":"الجواب: الواجب على الوالد والوالدة العدل بين أولادهم في كل شيء؛ لقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم فالواجب على الأب أن يعدل في عطيته، وفي ملاحظته، وفي إنفاقه، وفي حسن خلقه، عليه أن يعدل في الجميع ذكورًا وإناثًا، والأم كذلك، هذا هو الواجب على الجميع؛ لقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم وهذا عام يعم العدل في النفقة والعطية، وغير ذلك؛ ولأن عدم العدل يسبب الشحناء والعداوة والبغضاء، وتلك عواقبها وخيمة، نسأل الله للجميع الهداية.  المقدم: اللهم آمين، سماحة الشيخ! لو تفضلتم.. في الواقع أن مما أساء إلى تعدد الزوجات تصرف بعض الناس مثل هذا التصرف أطمع في هذا البرنامج بكلمة من سماحة الشيخ حتى لا يسيء الناس إلى شريعة الله بسوء تصرفاتهم. جزاكم الله خيرًا؟ الشيخ: الواجب على من تزوج زوجتين، أو ثلاثًا، أو أربعًا أن يعدل، وأن يتحرى العدل بين زوجاته، وبين أولاده جميعًا، فالله سبحانه حين شرع التعدد شرع أيضًا العدل، وأمر بالعدل، يقول النبي ﷺ لما كان يقسم بين نسائه: اللهم هذا قسمي فيما أملك؛ فلا تلمني فيما تملكك، ولا أملك. وكان يقسم، ويعدل -عليه الصلاة والسلام- فهذا هو الواجب على الرجل أن يعدل بين زوجاته، وبين أولاده، ويتحرى العدل في ذلك، وما عجز عنه، ولم يستطعه؛ فالله لا يكلف نفسًا إلا وسعها فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9971/حكم-اهمال-الوالد-لاولاده-بعذر-زواجه-من-ثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42204.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":11809,"question":"إحدى الأخوات المستمعات من ليبيا تقول المرسلة (منى . م. ع) من بني غازي، تسأل وتقول: في الفترة المسائية، وخاصة بعد صلاة العشاء أقوم بقراءة كتابًا من الكتب التي تعنى بالأمور الدينية، كالعبادات والسيرة والمعاملات وغيرها، هذه القراءة قد تأخذ من وقتي ساعات، وأحيانًا أقرأ حتى بعد منتصف الليل، وسؤالي: هل هذه القراءة في الكتب الدينية هي من مجالس الذكر، أم أن قراءة القرآن، والتسبيح والاستغفار أفضل، كذكر الله، وخاصة في الليل؟ جزاكم الله خيرًا.","title":"الجمع بين قراءة القرآن وكتب العلم الشرعي","answer":"الجواب:  المؤمن والمؤمنة يجمع بين هذا كله، يقرأ القرآن في وقت يتدبر ويتعقل، ويقرأ كتب العلم، وكتب الحديث الشريف، وكتب الفقه للتعلم والتفقه في الدين، فلا يكفي هذا عن هذا، ولا هذا عن هذا، فإذا قرأت في الليل قراءة لا تضرك، ولا تمنعك من قيام الليل، ولا تسبب نومك عن صلاة الفجر؛ فكل هذا طيب. وإذا كان لك زوج؛ فلابد من مراعاة خاطره ورضاه، لا تشتغلي بشيء عنه، إلا بالفريضة التي فرضها الله، والرواتب التي شرعها الله، فإذا كنت لا زوج لك؛ فالحمد لله اجتهدي في الخير، تارة في القرآن، وتارة في كتب العلم المعتمدة، مثل صحيح البخاري، وصحيح مسلم، كتب أهل العلم المعروفة مثل كتب شيخ الإسلام ابن تيمية، ابن القيم، كتب الشروح الصالحة المعروفة، السنن الأربع، موطأ مالك، سنن الدارمي، وأشباه ذلك للاستفادة إذا كان عندك علم، وإذا كان عندك نقص؛ فاسألي أهل العلم أيضًا، لا تستقلي برأيك، اسألي عما أشكل عليك، وأنت على خير عظيم، وهذا من العلم، ومن الذكر الذي شرعه الله لعباده، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9993/الجمع-بين-قراءة-القران-وكتب-العلم-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42311.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11964,"question":"ما هي الطريقة الصحيحة لحفظ القرآن الكريم حتى لا ينساه المسلم، وخاصة المسلمة عندما تتركه لفترة عذرها؟","title":"وسائل تعين على حفظ القرآن الكريم","answer":"الجواب:  الطريقة التي يحفظ بها كتاب الله هي العناية بقراءته، وعدم الغفلة، بحيث يجعل الرجل، أو المرأة وقتًا مناسبًا يقرأ فيه كتاب الله، ويكرر فيه محفوظه؛ حتى لا ينساه، في الليل، أو في النهار في الوقت المناسب، فهذا هو السبب الذي يعينه الله به على حفظه، أما إذا أعرض وغفل؛ هذا من أسباب النسيان، لكن يجب على المرء أن يحرص على أسباب السعادة التي شرعها الله، وأوجبها عليه، وهذا من أسباب توفيق الله له في حفظ القرآن وغيره، إذا حرص على أداء الواجبات التي فرضها الله عليه، وحرص على ترك المحارم، ثم تحرى بعد ذلك ما يعينه على حفظ القرآن، وما يعينه على الاستكثار من النوافل، وما يعينه على قضاء حقوقه، وحقوق أهله، فإن الله يعينه بذلك؛ لأنه قدم حقه، واعتنى بحقه سبحانه من أداء الفرائض وترك المحارم. فإذا رتب جزءًا من الوقت؛ ليحفظ كتاب الله، وليدرسه كثيرًا؛ فإن الله يعينه بذلك على حفظ كتابه -جل وعلا- فهو  قد رتب المسببات على أسبابها، وإنما يؤتى العبد من غفلته وإعراضه وتساهله، فإذا جد في الطلب، واجتهد فيما يسبب حفظ كتاب الله من تكرار الدراسة، وحفظ الوقت، وعدم الإعراض والغفلة، فإن الله يعينه على ذلك، مع الضراعة إلى الله وسؤاله أن يعينه، وأن يوفقه لحفظ كتابه، وأن يكفيه شر العوارض، يعني يجتهد في الدعاء، يسأل ربه أن الله يوفقه ويعينه، وأن الله يقيه شر أسباب عدم الحفظ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10149/وساىل-تعين-على-حفظ-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42905.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11991,"question":"يقول: إن كثيرًا من الآباء لا ينصحون أبناءهم لتأدية الصلاة، فهل يأثم الأب؟","title":"حكم الوالد الذي لا يأمر أولاده بالصلاة","answer":"الجواب:  نعم يأثم الأب الذي لا يأمر أولاده بالصلاة؛ يأثم، وهكذا أخوهم، وهكذا عمهم وخالهم وأمهم، كلهم يأثمون إذا تركوا الأمر بالمعروف والنهي عن المنكر واجب، فيجب عليهم الأمر بالمعروف والنهي عن المنكر، وهو من واجب المؤمنين، والله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول النبي ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه وهم يقدرون الكلام، يعني: يقدرون الإنكار بالكلام، فالأم تنكر، والأب والأخ الكبير والعم والخال وغيرهم، فهذا من باب التعاون على البر والتقوى، الله يقول -سبحانه-: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَىى [المائدة:2] ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] لابد من التعاون على البر والتقوى، ولاشك أن الإنكار على من ترك الصلاة؛ من باب التعاون على البر والتقوى، من باب الدعوة إلى الله  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ؛ إذا تعب الأب في هذا الموضوع، ولم يستجب الأبناء الاستجابة المرجوة، فهل يطردهم من البيت؟ الشيخ: يطردهم وإلا يرفع أمرهم إلى ولاة الأمور حتى يأدبوا، فإذا لم يتيسر ذلك؛ يطردهم من بيته، يطردهم حتى تسلم ذمته، تبرأ ذمته -نسأل الله العافية- إلا إذا استطاع تأديبهم من جهة ولاة الأمور، نعم. المقدم: إذا خشي أن يقعوا في مصائب أخرى، سماحة الشيخ؟ الشيخ: ما عاد أكبر من الكفر، الكفر هو أعظم الذنوب الكفر، نسأل الله العافية. المقدم: الله المستعان، نسأل الله العافية، إذًا ليس بعد الكفر ذنب؟ الشيخ: نعم هو أعظم الذنوب. المقدم: نسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/10176/حكم-الوالد-الذي-لا-يامر-اولاده-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43105.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12003,"question":"يقول: أرجو إرشادي إلى بعض الكتب المفيدة في مجال العقيدة؟","title":"أهم كتب العقيدة","answer":"الجواب:  أعظم كتاب القرآن العظيم هو أصل الخير كله، نوصيك بالقرآن، أكثر من تلاوته، وفيه بيان العقيدة الصحيحة، بيان أسماء الله وصفاته، وبيان توحيده، وحقه على عباده، فالقرآن هو أفضل الكتب، وأصدقها، وخيرها، وفيه الهدى والنور، فعليك بكتاب الله أكثر من تلاوته، وحفظه، وتدبر معانيه، وفيه الشفاء والكفاية. ومن الكتب الطيبة: كتاب التوحيد للشيخ: محمد بن عبدالوهاب، فتح المجيد، العقيدة الواسطية لشيخ الإسلام: ابن تيمية، كشف الشبهات للشيخ: محمد بن عبدالوهاب، ثلاثة الأصول كل هذه طيبة، إذا اقتنيتها طيبة، منهاج السنة لشيخ الإسلام: ابن تيمية، كتاب الإيمان لشيخ الإسلام ابن تيمية ، كلها كتب مفيدة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10188/اهم-كتب-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43117.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12050,"question":"هل يجوز للرجل أن يدرس البنات الصغار دون السابعة؟","title":"حكم تدريس الرجل للبنات دون سن السابعة","answer":"الجواب:  لا حرج في ذلك؛ لأنهن لسن من أهل العورة، لكن جعلهن عند النساء أولى وأحرى؛ لأنه قد يفضي إلى التساهل، قد يوجد فيهن من تجاوز السبع، أو وصل إلى التسع، فالذي ينبغي سد هذا الباب، وألا يتولى تدريس البنات إلا النساء، وإن كن صغارًا، حتى لا يتوصل بذلك إلى تدريس الكبيرات، والفتنة، وهكذا الصغار من الرجال يتولى تدريسهم الرجال، ولا يتساهل في ذلك مع النساء؛ لأنه إذا فتح الباب؛ تساهل الناس في هذا الأمر، فالأولاد الصغار يدرسهم الرجال كالكبار، والبنات الصغيرات يدرسهن النساء كالكبيرات؛ سداً للباب، وحسمًا لأسباب الفتنة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10235/حكم-تدريس-الرجل-للبنات-دون-سن-السابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43319.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":12096,"question":"المستمع (م. م) من الرياض بعث يسأل سماحتكم ويقول: إذا كنت من المتابعين لهذا البرنامج، وأقرأ كتبا فقهية كثيرة، وأتعرض لأسئلة فقهية من الناس، وأكون أعرف الإجابة عليها، فما هو الأفضل كتمان ما أعرفه؛ خوفًا من عدم الدقة في النقل، أم الإجابة حسب ما سمعت؟ جزاكم الله خيرًا.","title":"واجب الشخص إذا سئل عن مسألة يعلمها","answer":"الجواب:  الواجب أن تجيب حسب ما سمعت لا تزيد، ولا تنقص، إذا كنت ضابطًا للفتوى، تقول: سمعت فلانًا أفتى بكذا وكذا، تنسب الفتوى إلى العالم الذي صدرت منه، إلا إذا كان المستفتي يستطيع أن يذهب إلى العالم، وهو منه قريب، وأنت تخشى أن يكون في كلامك شيء من الزيادة، أو النقص؛ فلا مانع أن تحتاط، وأن ترشده إلى العالم حتى يسأله. أما إذا كنت ما عندك شك، بل عندك يقين في الفتوى؛ تخبره بها إخبارًا أنك سمعت المفتي فلانًا قال كذا وكذا، أو العالم الفلاني قال: كذا وكذا، لأجل التعاون مع أخيك على الخير، والله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] فأنت إذا أخبرته؛ فقد أعنته على الخير، وكفيته المؤونة، لاسيما وقد يكون العالم بعيدًا عنه، وقد يكون عليه مشقة في الذهاب إليه. فالحاصل: أنه لا بأس أن تخبره بالفتوى التي أتقنتها وضبطتها وحفظتها بنصها وتنسبها إلى صاحبها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10281/واجب-الشخص-اذا-سىل-عن-مسالة-يعلمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43610.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12280,"question":"سماحة الشيخ! يتعب كثير من المسلمين فيأتون إلى الديار المقدسة لأداء العمرة، أو لأداء الحج، لكنهم لا يستعدون لمعرفة الأحكام قبل التحرك من أماكنهم، هل تنصحون بشيء نحو هذا؟","title":"نصيحة في وجوب معرفة أحكام الحج والعمرة قبل النسك","answer":"الجواب: نعم الواجب على المؤمن إذا أراد الحج والعمرة أن يسأل أهل العلم في بلاده، أو في طريقه، يسألهم أهل العلم المعروفين المشهورين بالعلم والفضل ماذا يفعل، وإذا كان هناك منسك قد عرف أنه طيب، وأنه من مناسك أهل العلم؛ يستفيد منه، قد كتبنا في هذا منسكًا مختصرًا سميناه: التحقيق والإيضاح لكثير من مسائل الحج والعمرة والزيارة على ضوء الكتاب والسنة، وهو موجود مطبوع بالعربية، وغيرها يستفاد منه في هذا الباب، وهكذا المناسك الطيبة التي ألفها العلماء يستفاد منها. المقصود: أن على من أراد الحج والعمرة وهو ليس عنده علم أن يسأل أهل العلم؛ حتى تكون عنده يعني: حصيلة علمية يستفيد منها في حجه وعمرته قبل السفر، وإذا وصل إلى مكة كذلك يسأل أهل العلم ويأتي محل التوعية في الحج التابعة لنا يأخذ منهم المناسك منسكًا يستفيد منه، ويسأل الدعاة هناك عما أشكل عليه موجود في مكة الحمد لله وقت الحج، وهم جماعات كثيرة للدعوة في إمكانه أن يأتي محل التوعية في العزيزية، أو في منى، أو في عرفات يسألهم، عليه أن يأتيهم، ويسألهم عما أشكل عليه، ويطلب المنسك أيضًا حتى يعطى إياه، ويستفيد منه، نسأل الله للجميع الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/10480/نصيحة-في-وجوب-معرفة-احكام-الحج-والعمرة-قبل-النسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_451/45105.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12299,"question":"رسالة وصلت إلى البرنامج من تبوك وقعت إحدى الأخوات في نهايتها بقولها: أختكم في الله أم هديل، أم هديل تقول: أرجو من سماحة الشيخ أن يذكر لنا أهم الكتب التي تتحدث عن العقيدة والتوحيد، حيث لنا أمل في أن تكون شاملة وافية، حتى نكون على بينة ويقين؛ لأننا في حياتنا اليومية نردد كثيرًا من الألفاظ، أو الأفعال والمعتقدات التي تنقض التوحيد دون أن نشعر بذلك، مثلًا: الحلف بغير الله، وكذلك: التمائم، والاعتقاد بالأولياء، وما رأيكم في كتاب التوحيد الذي هو حق الله على العبيد، هل تنصحوننا بشرائه؟ جزاكم الله خيرًا.","title":"أهم كتب العقيدة الإسلامية الصحيحة","answer":"الجواب:  نعم، ننصح كل مسلم بشرائه، وكل مسلمة أيضًا كتاب (التوحيد) للشيخ الإمام محمد بن عبدالوهاب -رحمة الله عليه- وهو كتاب جيد مفيد، جمع فيه الأدلة من الكتاب والسنة على أشياء كثيرة من أمور الشرك، وأمور البدع والأشياء المحرمة، فهو كتاب مفيد جيد، ننصح باقتنائه وبحفظه. وهكذا شرحه المسمى: (فتح المجيد) لحفيده الشيخ عبدالرحمن بن حسن نوصي أيضًا باقتنائه وهو شرح مفيد. وهكذا شرحه الثاني: (تيسير العزيز الحميد) لحفيده الشيخ سليمان بن عبدالله بن محمد، فهو أيضًا شرح مفيد. وننصح أيضًا بكتاب: (كشف الشبهات) للشيخ محمد بن عبدالوهاب -رحمه الله- وهو كتاب مفيد أيضًا. وهكذا: (ثلاثة الأصول)، و(القواعد الأربع) للشيخ محمد، وهو كتاب مفيد ومختصر. وهكذا (القاعدة الجليلة في التوسل والوسيلة) لشيخ الإسلام ابن تيمية كتاب مفيد، وهكذا: (العقيدة الواسطية) له أيضًا كتاب مفيد في العقيدة الإسلامية السنية.  وننصح أيضًا بكتاب: (زاد المعاد في هدي خير العباد) للعلامة ابن القيم -رحمه الله- وهو كتاب عظيم، قد اشتمل على بيان العقيدة الصحيحة، والسيرة النبوية، وأحكامًا كثيرة في الصلاة وغيرها، وهو كتاب جيد ومفيد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10499/اهم-كتب-العقيدة-الاسلامية-الصحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45305.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12455,"question":"من ليبيا رسالة بتوقيع إحدى الأخوات المستمعات تقول: المرسلة فائزة أحمد. الأخت فائزة تسأل وتقول: أمي لا تعرف القراءة، ولا تحفظ شيئًا من القرآن الكريم، وأنا حاولت تعليمها شيئًا من القرآن، لكنها تنسى، فما هو توجيهكم؟","title":"الحث على تعليم من لا يحسن قراءة الفاتحة","answer":"الجواب:  توجيهي لك أن تجتهدي في تعليمها، وإرشادها حتى تتعلم -إن شاء الله- ويكون لك مثل أجرها، فإن لم يتيسر ذلك؛ صحت صلاتها، والحمد لله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وإذا تيسر تعليمها بدل القراءة: (سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله) كفى ذلك عند العجز عن تعلم الفاتحة، ولكن اجتهدي أنت ومن عندك من الأخوات الطيبات في تعليمها، وإرشادها؛ لعلها تستفيد، ويكون لكن مثل أجرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10679/الحث-على-تعليم-من-لا-يحسن-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40420.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12511,"question":"يسأل عن الأسلوب الذي يلتزمه المسلم حتى يسهل عليه حفظ القرآن الكريم؟","title":"الطرق والوسائل الميسرة لحفظ القرآن","answer":"الجواب:  أولًا: إخلاص النية لله، يكون قصده وجه الله... بتعلم القرآن، وبحفظ القرآن، يخلص لله في ذلك حتى يعينه مولاه : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فنوصي كل مؤمن ومؤمنة بالإخلاص في حفظ القرآن، وفي تعلم القرآن، وفي تعلم العلم، وفي جميع الأعمال الشرعية، نوصي الجميع بالإخلاص لله، وأن يكون القصد وجه الله، والدار الآخرة، ثم نوصيه بالجد والمثابرة في حفظ القرآن، وتحري الأوقات المناسبة في الليل، أو في النهار؛ لأن كل إنسان له ظروفه، فنوصي كل واحد يريد حفظ القرآن الكريم، أو الإكثار من تلاوته، نوصي كل واحد أن يتحرى الأوقات المناسبة، التي يكون فيها قلبه فارغًا يستطيع التدبر والتعقل، حتى يكون حفظه، وحتى تكون قراءته مثمرة، فينظر في ليله، وفي نهاره، ويختار الوقت المناسب لحفظ ما تيسر، أو لقراءة ما تيسر، بقلب حاضر، مقبل على الله، يريد الله، والدار الآخرة، يتدبر ويتعقل، كما قال الله سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] وقال : أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]. فالمؤمن والمؤمنة يتحريان الأوقات المناسبة لحفظ القرآن، ولتلاوة القرآن حتى تكون القلوب حاضرة، وحتى يستفيد المؤمن والمؤمنة من قراءته، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10719/الطرق-والوساىل-الميسرة-لحفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40713.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12513,"question":"يسأل سماحتكم فيقول: ما هي الكتب المفيدة التي إذا اعتمد عليها طالب العلم كفته عن البقية من الكتب؟","title":"الكتب الواجب على طالب العلم الاهتمام بها واقتناؤها","answer":"الجواب:  أعظم كتاب، وأهم كتاب: القرآن العظيم، هو أعظم الكتب، القرآن العظيم هو أهم كتاب، وأعظم كتاب، وأنفع كتاب، كتاب الله فيه الهدى والنور، كما قال الله سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] وقال -جل وعلا-: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89] وقال سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] فأعظم الكتب، وأصدقها، وأنفعها، وأنفسها، وأكملها كتاب الله، فنوصي كل مسلم، وكل مسلمة في جميع الدنيا، نوصيهم بالعناية بالقرآن، نوصي الجميع بالعناية بكتاب الله حفظًا، وتدبرًا، وتعقلًا وعملًا، وسؤال أهل العلم عما أشكل في ذلك، وإذا كان طالب علم ينظر كتب التفسير حتى يستفيد مثل كتاب ابن جرير تفسير ابن جرير، تفسير ابن كثير، تفسير البغوي، تفسير الشوكاني، تفسير القرطبي، حتى يستفيد من هذه التفاسير من معاني كلام الله -عز وجل- يتعلم، ويستفيد من هذه الكتب. وكذلك كتب الحديث، كـالبخاري ومسلم والسنن الأربع، هذه الكتب العظيمة يستفيد منها، مثل منتقى الأخبار لابن تيمية، بلوغ المرام للحافظ ابن حجر، عمدة الحديث للشيخ عبدالغني بن عبدالواحد المقدسي، هذه كتب الحديث المهمة، وهكذا موطأ مالك، ومسند أحمد، وسنن الدارمي، كلها كتب مفيدة عظيمة. ولكن إذا كان ليس عنده علم يسأل أهل العلم، لا يعتمد على رأيه، بل طالب العلم الذي عنده فقه في الدين، وعنده علم يستفيد من هذه الكتب، وإذا كان عاميًا ليس عنده علم يتوصل به إلى معرفة الحديث الصحيح، والضعيف؛ فإنه يسأل أهل العلم، يسأل أهل العلم عما أشكل عليه، ويعتني بالقرآن، ويكثر من تلاوة القرآن بالتدبر والتعقل، ويسأل ربه التوفيق والهداية، والإعانة.  أما أهل العلم فإنهم ينظرون في هذه الكتب، ويستفيدون منها في تفسير كتاب الله، وفي معرفة الصحيح عن رسول الله ﷺ من الأحاديث، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10709/الكتب-الواجب-على-طالب-العلم-الاهتمام-بها-واقتناوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40716.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12514,"question":"يسأل سماحتكم فيقول: ما هي الكتب المفيدة التي إذا اعتمد عليها طالب العلم كفته عن البقية من الكتب؟","title":"الكتب الواجب على طالب العلم الاهتمام بها واقتناؤها","answer":"الجواب:  أعظم كتاب، وأهم كتاب: القرآن العظيم، هو أعظم الكتب، القرآن العظيم هو أهم كتاب، وأعظم كتاب، وأنفع كتاب، كتاب الله فيه الهدى والنور، كما قال الله سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] وقال -جل وعلا-: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89] وقال سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] فأعظم الكتب، وأصدقها، وأنفعها، وأنفسها، وأكملها كتاب الله، فنوصي كل مسلم، وكل مسلمة في جميع الدنيا، نوصيهم بالعناية بالقرآن، نوصي الجميع بالعناية بكتاب الله حفظًا، وتدبرًا، وتعقلًا وعملًا، وسؤال أهل العلم عما أشكل في ذلك، وإذا كان طالب علم ينظر كتب التفسير حتى يستفيد مثل كتاب ابن جرير تفسير ابن جرير، تفسير ابن كثير، تفسير البغوي، تفسير الشوكاني، تفسير القرطبي، حتى يستفيد من هذه التفاسير من معاني كلام الله -عز وجل- يتعلم، ويستفيد من هذه الكتب. وكذلك كتب الحديث، كـالبخاري ومسلم والسنن الأربع، هذه الكتب العظيمة يستفيد منها، مثل منتقى الأخبار لابن تيمية، بلوغ المرام للحافظ ابن حجر، عمدة الحديث للشيخ عبدالغني بن عبدالواحد المقدسي، هذه كتب الحديث المهمة، وهكذا موطأ مالك، ومسند أحمد، وسنن الدارمي، كلها كتب مفيدة عظيمة. ولكن إذا كان ليس عنده علم يسأل أهل العلم، لا يعتمد على رأيه، بل طالب العلم الذي عنده فقه في الدين، وعنده علم يستفيد من هذه الكتب، وإذا كان عاميًا ليس عنده علم يتوصل به إلى معرفة الحديث الصحيح، والضعيف؛ فإنه يسأل أهل العلم، يسأل أهل العلم عما أشكل عليه، ويعتني بالقرآن، ويكثر من تلاوة القرآن بالتدبر والتعقل، ويسأل ربه التوفيق والهداية، والإعانة.  أما أهل العلم فإنهم ينظرون في هذه الكتب، ويستفيدون منها في تفسير كتاب الله، وفي معرفة الصحيح عن رسول الله ﷺ من الأحاديث، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10709/الكتب-الواجب-على-طالب-العلم-الاهتمام-بها-واقتناوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40716.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12515,"question":"يسأل عن الآداب التي يجب أن يلتزم بها حامل القرآن؟","title":"آداب حملة القرآن","answer":"الجواب:  يجب عليه أن يلتزم بالحكمة، وترك الخوض فيما لا يعنيه، وأن يكون كلامه مضبوطًا، إذا خاض الناس في الباطل؛ يحفظ لسانه، وإذا أكثر الناس الضحك؛ لزم الصمت، والحشمة حتى يكون معروفًا بسمته الحسن، وبأخلاقه الفاضلة، والبعد عن المشاركة في الباطل من الغيبة، أو النميمة، أو الخوض فيما لا يعني، تكون أوقاته محفوظة، ولسانه محفوظًا، إلا من الخير. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10720/اداب-حملة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40714.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12523,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع محمد خضير من مدينة حائل، الأخ محمد له جمع من الأسئلة في أحدها يقول: سماحة الشيخ! إنني قريب من التخرج من المرحلة الثانوية، فبماذا تنصحونني؟ وما هي نصيحتكم بالتوجه بعد التخرج؟ جزاكم الله خيرًا.","title":"توجيه بالالتحاق بكلية الشريعة بعد الثانوية","answer":"الجواب:  ننصحك بالالتحاق بكلية الشريعة، نوصيك بأن تجتهد في الالتحاق بكلية الشريعة، حتى تكمل الدراسة الجامعية، ثم التخصص بعدها، إن شاء الله، نسأل الله لك التوفيق والعون. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10734/توجيه-بالالتحاق-بكلية-الشريعة-بعد-الثانوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40813.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12688,"question":"بعد هذا رسالة وصلت إلى البرنامج من ليبيا بتوقيع إحدى الأخوات المستمعات، تقول المرسلة سلمى، الأخت سلمى لها سؤال تقول فيه: بالنسبة لخروج المرأة خارج بيتها لضرورة، حول هذا الموضوع المهم، أقول: بأننا مجموعة من بنات مسلمات، وأننا نذهب إلى أحد المساجد في مدينتنا، وهو يبعد عن البيت حوالي ربع ساعة مشيًا على الأقدام، ونذهب في الأسبوع أربعة أيام، ونتعلم الفقه والسيرة، فهل هذا يعتبر من الضرورة، جزاكم الله خيرًا؟","title":"حكم ذهاب المرأة للمسجد من أجل تعلم أمور دينها","answer":"الجواب:  هذا كله طيب، مثل هذا يؤدي إلى التفقه في الدين، هذا أمر مطلوب إلا إذا تيسر في مدرسة عندكم من يفقهكن، ويعلمكن طيب، وإذا دعت الحاجة إلى حضور حلقات العلم في المساجد حتى تسمعن الفائدة والعلم؛ فهذا أمر مطلوب، قد يجب، وقد يتأكد، إذا دعت الحاجة إليه وجب. فالحاصل: أن الخروج إلى المساجد لطلب العلم، والتفقه في الدين، أمر مطلوب شرعًا ما بين مستحب، أو واجب، على الرجال والنساء جميعًا. أما إذا تيسر للنساء التفقه في بيوتهن، أو في مدارس خاصة؛ كفى ذلك، والحمد لله، وإلا فعليهن أن يتفقهن في الدين، وأن يتعلمن شرع الله، ولو بالخروج إلى مسجد بعيد ساعة، كربع ساعة، أو أكثر للتفقه في الدين، ويكون معها من أخواتها من يساعدها على ذلك؛ حتى لا تستوحش من الطريق، أو لا تفتن في الطريق، أو يكون معها زوجها أو أخوها، إذا كان هناك حاجة إلى ذلك، وإن كان الطريق آمنًا، ولا خوف؛ فلا بأس أن تخرج وحدها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10898/حكم-ذهاب-المراة-للمسجد-من-اجل-تعلم-امور-دينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41716.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12759,"question":"هل ترون تقديم قراءة التفسير على حفظ القرآن؟","title":"الجمع بين حفظ القرآن ودراسة تفسيره","answer":"الجواب:  كله خير، كونه يتعاهد القرآن ولو نظرًا؛ هذا مطلوب، وإذا تيسر له الحفظ؛ فهذا مطلوب، مع التفقه في القرآن، وقراءة التفسير، وكتب الحديث، وحضور حلقات العلم، يجمع بين هذا وهذا؛ لأن حفظ القرآن وحده لا يكفي، بل لا بد من حضور حلقات العلم، ومراجعة التفسير لمعرفة معنى الآيات؛ حتى يستفيد بالقراءة. فالمؤمن مطلوب منه العناية بالقرآن، والعلم، والتفقه في الدين، مع العناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، وإذا تيسر له حفظه؛ فهذا خير إلى خير، أو حفظ بعضه، لكن ليس بواجب الحفظ إنما هو مستحب مطلوب إذا تيسر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10973/الجمع-بين-حفظ-القران-ودراسة-تفسيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41908.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12760,"question":"هل يجوز لي أن أترك إلقاء الدروس في المسجد، وذلك لعدم حضور أحد إلي، مع تكرار ذلك لعدة مرات، والسؤال لا زال للمستمع (م. ص. ع) من الأردن -؟","title":"دعوة المرأة لبنات جنسها وتعليمهن","answer":"الجواب:  إذا تيسر لك إلقاء الدرس على الجماعة بعد العصر، أو بعد المغرب، أو بعد العشاء.  المقدم: هذه سائلة جزاكم الله خيرًا.  الشيخ: امرأة؟ المقدم: امرأة نعم. الشيخ: تعلمين من حضرك من النساء في بيتك، ومن يزورك في البيت، وإذا كنت في المدرسة كذلك إن كنت مدرسة تعلمين الطالبات، وتبحثين مع المدرسات إذا كن دونك في العلم، أو مذاكرة معهن إذا كن مثلك، أو أعلم منك حتى تستفيدي ويستفيدوا. المقصود: أنك تبذلين ما تستطيعين في توجيه الناس إلى الخير، الطالبات، ومن يجالسك في البيت، ومن يزورك، ومع المدرسات بالمذاكرة، تستفيدين منهن إن كن أعلم منك، وتفيدينهن إن كنت أعلم منهن. المقصود: التعاون على البر والتقوى بالمذاكرة بينك وبين المدرسات، وبتوجيه الطالبات وتعليمهن، وهكذا في البيت مع من يزورك من أخواتك في الله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، حول تدريس النساء في المساجد سماحة الشيخ لبعض إخوانكم طلبة العلم رأي آخر، إذ لا يرى ذلك، ما هو توجيه سماحة الشيخ؟! الشيخ: هذا فيه تفصيل: إذا أمكن أن تدرس النساء في المسجد على رجل لا فتنة فيه، مع التحجب، أو مع كونهن في محل خاص لا يأتيه الرجال، فهذا لا بأس به، ولا حرج فيه، المهم إيصال العلم إلى الرجال والنساء، فإذا كان في المسجد محل خاص، أو في مدرسة، أو في البيت، المهم أن تعمل ما تستطيع في إيصال العلم إلى أخواتها في الله، أو إلى الطالبات في المسجد، أو في المدرسة، أو في بيتها، أو في بيت إحدى أخواتها، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10974/دعوة-المراة-لبنات-جنسها-وتعليمهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41909.mp3","categories":["العالم والمتعلم","المساجد ومواضع السجود"]},{"id":12761,"question":"إذا كان يستمع إلى هذا الدرس عبر مكبرات الصوت رجال، فهل ترون في ذلك شيئًا، أم أنه جائز؟","title":"سماع الرجال لصوت المعلمة وهي تعلم الفتيات","answer":"الجواب:  لا حرج في ذلك، قد ينفع الله به الرجال أيضًا، الحمد لله، قد ينفع الله به الرجال وإن كان صوتها قد يعني يسبب فتنة، لكن ليس المقصود هذا، إنما تدرس النساء، فإذا سمع صوتها بعض الرجال؛ فلا يضر ذلك، نعم. الجواب: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10975/سماع-الرجال-لصوت-المعلمة-وهي-تعلم-الفتيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41910.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":12777,"question":"يقول: سماحة الشيخ أرجو أن توجهوني إلى بعض الكتب التي أقرؤها كيما أستفيد منها، وتفيدني في أمور ديني ودنياي؟ جزاكم الله خيرًا.","title":"الكتب التي ينصح بها طالب العلم","answer":"الجواب:  أنصحك بالعناية بكتاب الله القرآن، فهو أعظم كتاب، وأشرف كتاب وأصدق كتاب، فأوصيك وجميع المسلمين من الرجال والنساء بالعناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، والسؤال عما أشكل عليك، قال الله : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] وقال ﷺ: اقرؤوا القرآن؛ فإنه يأتي شفيعًا لأصحابه يوم القيامة ويقول ﷺ: خيركم من تعلم القرآن وعلمه فنوصي جميع إخواني المسلمين بالعناية بالقرآن تلاوة، وتدبرًا وعملًا به، إذ المقصود العمل، التلاوة والتدبر وسيلة للعمل، والمقصود العمل، فنوصي الجميع بالإكثار من تلاوته بالتدبر، والتعقل، والعمل، والسؤال عما أشكل عليك من أهل العلم، ومراجعة كتب التفسير المعروفة الطيبة إذا كنت تستطيع ذلك مثل تفسير ابن جرير والبغوي وابن كثير والشوكاني ، كتب مفيدة. ومن الكتب النافعة الصحيحان: البخاري ومسلم، إذا كنت تستطيع ذلك، عندك علم عندك بصيرة، ومن الكتب المفيدة -أيضًا- كتب أهل السنة، كتب أهل السنة فيها الخير الكثير، مثل موطأ مالك -رحمه الله- السنن الأربع، كل هذه.. كتب الحديث، كتب أهل السنة. كذلك كتب أهل العلم المعروفين بالخير، والعلم النافع، مثل المغني لابن قدامة -رحمه الله- والمقنع له أيضًا، شرح المهذب للنووي ، الروضة للنووي، كتب مفيدة.. البداية لابن رشد، وما أشبه ذلك من الكتب المفيدة.  ومن كتب العقيدة، كتب السلف أيضًا منها كتب شيخ الإسلام ابن تيمية -رحمه الله- فهي كتب مفيدة كالحموية، والتدمرية، والواسطية، كتب الشيخ محمد بن عبدالوهاب -رحمه الله- مفيدة، مثل كتاب التوحيد، كشف الشبهات، ثلاثة الأصول، وهكذا شرح التوحيد لحفيده الشيخ عبدالرحمن بن حسن، وحفيده الثاني الشيخ سليمان بن عبدالله، فتح المجيد للشيخ عبدالرحمن ، وتيسير العزيز الحميد للشيخ سليمان، هذه كتب عظيمة ومفيدة، فنوصي العناية بها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10991/الكتب-التي-ينصح-بها-طالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42004.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12828,"question":"هل من يعطي الأولاد مبلغًا من المال من أجل أن يواظبوا على الصلوات والتهليل والتكبير لله سبحانه، هل هذا العمل جيد ومشروع؟","title":"حكم إعطاء الأولاد النقود لأجل المواظبة على الصلوات وغيرها","answer":"الجواب:  لا حرج في ذلك إذا كان ليس حيلة لتفضيل بعضهم على بعض، إنما هو لأجل تشجيعهم على الخير، فهذا في الغالب يكون.. شيء يسير ويعفى عنه؛ لأن هذا من باب التشجيع على الخير والمعاونة عليه، أما إذا كان عطايا لها أهمية يفضل بعضها على بعض لا، أما إذا كان أشياء طفيفة للتشجيع؛ فلا بأس -إن شاء الله- نعم. المقدم: إن شاء الله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11042/حكم-اعطاء-الاولاد-النقود-لاجل-المواظبة-على-الصلوات-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46316.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12849,"question":"الأخت (ل. ع. ف) من مدينة القصب بعثت تقول: ما رأيكم يا سماحة الشيخ في الأب الذي يربي أولاده وهم صغار تربية جيدة، ولكن إذا نضجوا، وبلغوا سن الرجولة، وتزوجوا، فإنه يهملهم، ولا يبدي لهم النصح، ولا يتابع أحوالهم، ولا سيما ما يتعلق بحياتهم الإسلامية، هل تنقطع تربية الوالد إلى أن يبلغ الأبناء سن النضج، ويتزوجوا، أم هي متصلة؟","title":"حكم إهمال الأب توجيه أولاده بعد تزويجهم","answer":"الجواب:  بل هي متصلة، والواجب عليه أن يتقي الله في ذلك، وأن يلاحظهم، وأن يوجههم إلى الخير إذا استطاع ذلك، أما إذا لم يستطع بأن كانوا في بلاد أخرى، وهو عاجز لا يصلونه، ولا يتصلون به؛ فإنه يعمل ما يستطيع ولو بالهاتف، ولو بالمكاتبة حسب الطاقة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ولا يجوز له أن يهملهم أبدًا، بل يجب عليه أن يرشدهم ولو بطريق الهاتف، ولو بطريق المكاتبة، ولو بطريق البرقية، أي طريق يستطيعه يفعله، ولا يجوز له إهمالهم؛ لأنهم أولاده، وهو مسؤول عنهم يوم القيامة. لكن إذا كانوا صغارًا، المسؤولية تكون أشد، وإذا كبروا وانفصلوا عنه، كانت المسؤولية أخف: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] عليه أن يتقي الله ما استطاع في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11064/حكم-اهمال-الاب-توجيه-اولاده-بعد-تزويجهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46415.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12881,"question":"الأخت: آمنة عشيلي من اللاذقية في سوريا بعثت برسالة مطولة كلها ثناء وتقدير ومحبة لسماحة الشيخ، وتنتهي رسالتها بسؤال تقول فيه: ما هو رأي سماحتكم في كتاب صفة صلاة النبي ﷺ للشيخ: محمد ناصر الدين الألباني؟","title":"تقييم في كتاب صفة صلاة النبي للألباني","answer":"الجواب:  هذا كتاب طيب مفيد، والشيخ: ناصر الدين الألباني رجل علامة فاضل، وله اجتهاد عظيم في إحياء السنة، وبيان الصحيح من الضعيف، فهو مشكور على جهوده، جزاه الله خيرًا، وضاعف مثوبته، وكل أحد قد يخطئ، ليس أحد معصومًا من الخطأ من العلماء، قد يقع له بعض الأخطاء، وبعض الغلط في بعض المؤلفات، وهكذا غيره من العلماء الذين هم أكبر منه قد يقع له بعض الأخطاء، ومما وقع في صفة صلاة النبي ﷺ من الخطأ قوله: إن الإنسان بعد الرفع من الركوع يسدل يديه، هذا خطأ، والصواب: أنه يضمهما على صدره كما فعل قبل الركوع؛ لأن هذا هو المحفوظ في الأحاديث الصحيحة عن النبي -عليه الصلاة والسلام-: أنه كان إذا صلى وضع يمينه على شماله حال قيامه في الصلاة وهذا يعم ما قبل الركوع وما بعد الركوع، وكذلك حديث سهل بن سعد عن النبي ﷺ أنه قال: كنا نؤمر أن يضع الرجل يده اليمنى على ذراعه اليسرى في الصلاة. ومعلوم أن في الصلاة في حال الركوع يضع يديه على ركبتيه، وفي حال السجود على الأرض، وفي حال الجلوس على فخذيه، أو ركبتيه، ما بقي إلا حال الوقوف، وهو في حال الوقوف يضع يمنيه على شماله، على الكف والرسغ والساعد، والساعد هو الذراع. هذا هو مما يؤخذ على المؤلف وفقه الله، ومثلما تقدم كل أحد يقع منه بعض الزلل، والرجل مشكور على أعماله الطيبة، وعلى جهوده الطيبة، وعلى عنايته بالسنة، فجزاه الله خيرًا، وزادنا وإياكم وإياه من الخير والهدى، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11096/تقييم-في-كتاب-صفة-صلاة-النبي-للالباني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46613.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12895,"question":"يقول: فتاة غير متزوجة، لا تصلي يقول لها والدها: صلي فلا تطيعه، ولا تعمل بما يقول: فعلى من تقع مسؤولية هذه الفتاة، جزاكم الله خيرًا؟","title":"كيفية تصرف الوالد مع ابنة تاركة للصلاة","answer":"الجواب: على والدها وعلى إخوتها، عليهم أن يقوموا عليها ولو بالضرب، حتى تستقيم، وحتى تصلي، فإن لم تستقم؛ يرفع بأمرها إلى المحكمة، تستتاب، فإن تابت وإلا قتلت، يرفع أمرها إلى المحكمة الشرعية، فإن تابت، وهداها الله؛ فالحمد لله، وإلا وجب قتلها؛ لأن من ترك الصلاة؛ يستتاب، فإن تاب؛ وإلا قتل من جهة ولي الأمر، والمحكمة تنوب عن ولي الأمر. ولا يجوز لأبيها السكوت عنها، ولا لإخوتها، ولا لأعمامها، على الجميع أن يقوموا عليها؛ لعل الله أن يهديها بأسبابهم، مع الضرب لا مانع أن يضربها أبوها، يضربها إخوتها ضربًا يسبب رجوعها عن الباطل، ولعل الله أن يهديها بذلك، فإن لم يجد ذلك؛ وجب أن يرفع أمرها إلى المحكمة حتى تجري عليها الحكم الشرعي، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11110/كيفية-تصرف-الوالد-مع-ابنة-تاركة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46710.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12927,"question":"في سؤاله الثاني يقول يا سماحة الشيخ: إذا كان بعض من إخواني -سواء كانوا ذكورًا أو إناثًا- يقصرون في بعض الصلوات، هل هذا يؤثر على والدي المتوفى، علمًا بأن بعض الإناث متزوجات؟","title":"حكم الأب الذي لم ينصح أبناءه في أمور دينهم","answer":"الجواب:  إن كان قصر في حياته لم يأمر أبناءه وبناته، ولم يعلمهم؛ فهو على خطر من ذلك، والدعاء له، تدعو له أن الله يسامحه ويعفو عنه. أما إن كان لم يقصر، بل اجتهد في تربيتهم وتعليمهم، وأمرهم بالخير، ولكن قصروا بعد وفاته هم؛ فالإثم عليهم، وليس عليه من ذلك شيء. إذا قصروا بعد وفاته في الصلاة، أو غيرها؛ فالإثم عليهم، لكن في حياته إذا كان قد تساهل في حقهم؛ فهو على خطر، تدعون له بالمغفرة والرحمة والعفو، إذا كان تساهل معهم، ولم يعلمهم، ولم يؤدبهم؛ فقد ترك الواجب عليه، فهو مسؤول عن هذا، وهو خطر من هذا الشيء، لكن تدعون له بالمغفرة والرحمة والعفو. وعليكم أيضًا أن تتواصوا بالخير فيما بينكم، وأن تناصحوا، وأن تجتهدوا في أداء حق الله، وأن تحافظوا على الصلاة في الجماعة، وأن تجتهد مع أخواتك أيضًا بنصيحة أخواتك، وتوجيههن إلى الخير، وأمرهن بالصلاة والمحافظة عليها في أوقاتهاـ وغير هذا من وجوه الخير، كأداء الزكاة، وصوم رمضان، والمحافظة عليه، صلة الرحم، إكرام الجار، حفظ اللسان عما لا ينبغي، توصي جميع إخوتك من ذكور وإناث بتقوى الله، توصيهم بطاعة الله ورسوله، توصيهم بفعل الخير، وترك الشر، توصيهم بكثرة التسبيح والتهليل والتحميد والتكبير والذكر وقراءة القرآن، توصيهم بإكرام جيرانهم، وإكرام أقاربهم، وصلة أرحامهم، وأنت على خير. يقول الله : وَالْعَصْرِ  ۝  إِنَّ الإِنسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] من أفضل خصال الإيمان التواصي بالحق والتناصح، ويقول -جل وعلا-: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ[النحل:125] ويقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ[المائدة:2]. فأنت -أيها السائل- عليك أن تتعاون مع إخوانك، ومع أقربائك، ومع جيرانك على البر والتقوى، على طاعة الله ورسوله، على الصلاة في الجماعة، على بر الوالدين، على صلة الرحم، على حفظ اللسان عما لا ينبغي، كل هذا من التناصح والتواصي بالحق، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11143/حكم-الاب-الذي-لم-ينصح-ابناءه-في-امور-دينهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50102.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12995,"question":"هذه السائلة تذكر بأنها فتاة تصلي وتصوم وتحفظ من كتاب الله ثلاثة عشر جزءًا، تقول: وأنا أتابع لكي أحفظه -إن شاء الله- ولكن أشعر بأنني أنسى، ولكنني -إن شاء الله- سأعيد الحفظ والمراجعة مرة ثانية بعد حفظه لأول مرة، فهل إذا مت قبل المراجعة، أو قبل مراجعة القرآن مرة ثانية، هل أتذكره يوم القيامة، يوم يقول الله  للعبد: اقرأ وارتق، ورتل كما كنت ترتل في الدنيا وهل أجازى على حفظي إياه لأول مرة إن نسيته، علمًا بأنني مواظبة على تلاوة القرآن الكريم، جزاكم الله خيرًا؟","title":"الحرص على عدم نسيان القرآن الكريم بعد حفظه","answer":"الجواب:  إذا حرصت على الحفظ، واجتهدت في ذلك، وبذلت الوسع؛ فنرجو لك التوفيق في الآخرة، أما إذا حصل التساهل، وعدم المبالاة؛ فهذا خطر عظيم، لكن إذا بذل المؤمن والمؤمنة الوسع في حفظ كتاب الله، واجتهد كل منهما في ذلك؛ فالله سبحانه هو الجواد الكريم الذي يعين عبده، ويوفق عبده، ويجازيه على عمله الطيب . فالوصية الجد في ذلك، والحرص على ذلك، والله سبحانه هو الموفق الهادي، جل وعلا. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11212/الحرص-على-عدم-نسيان-القران-الكريم-بعد-حفظه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50408.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13022,"question":"يسألن عن الكتب التالية لو تكرمتم سماحة الشيخ: أولًا: فقه المرأة المسلمة؟","title":"تقييم كتاب (فقه المرأة المسلمة)","answer":"الجواب:  لا أعلم عن هذا الكتاب شيئًا، من ألفه؟ المقدم: الدكتور إبراهيم الجمل . الشيخ: ما أعرف عنه شيئًا. نعم.","link":"https://binbaz.org.sa/fatwas/11239/تقييم-كتاب-فقه-المراة-المسلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47202.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13023,"question":"عجائب وغرائب الجن لبدر الدين عبدالله .","title":"تقييم كتاب (عجائب وغرائب الجن)","answer":"الجواب: لا أعلم عنه شيئًا، أقول: لا أعرف عنه شيئًا، نعم.","link":"https://binbaz.org.sa/fatwas/11240/تقييم-كتاب-عجاىب-وغراىب-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47203.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13024,"question":"عقيدة المؤمن للشيخ: أبو بكر جابر الجزائري .","title":"تقييم كتاب (عقيدة المؤمن) لأبي بكر الجزائري","answer":"الجواب:  هذا كتاب لا بأس به، جيد. نعم. المقدم: بارك الله فيكم، إذًا تنصحون الأخوات بقراءته. الشيخ: .... عقيدة المؤمن طيب، وهكذا ننصح الأخوات بقراءة كتب شيخ الإسلام ابن تيمية وابن القيم ، وأعظم من ذلك، وأكبر، أنصحهن بالقرآن، العناية بالقرآن الكريم، والإكثار من تلاوة القرآن، فهو كتاب الله العظيم، وهو أصل كل خير، وهو ينبوع السعادة. فأنصح كل مؤمن، وكل مؤمنة بالعناية بكتاب الله، والإكثار من تلاوة كتاب الله أكثر من كل شيء، مع التدبر والتعقل والاستفادة، وسؤال الله التفقه في معانيه، وأن يبصر القاري في معانيه، ويعلمه ما ينفعه، مع سؤال أهل العلم عما أشكل، ومطالعة كتب التفسير؛ حتى يستفيد المؤمن والمؤمنة. وهكذا السنة سنة الرسول ﷺ فهي الوحي الثاني، وهي المفسرة للقرآن، فهي مقدمة بعد القرآن على كل شيء، مثل البخاري صحيح البخاري صحيح مسلم، والكتب المختصرة من ذلك، مثل بلوغ المرام، مثل عمدة الحديث، مثل منتقى الأخبار، كل هذه كتب مفيدة وعظيمة تنفع المؤمن، والمؤمن والمؤمنة إذا أشكل عليهما شيء؛ يسألان أهل العلم، ويراجعان كتب الشروح التي تكلمت على الأحاديث الضعيفة؛ حتى يستفيد الجميع. ولا مانع من قراءة كتب أهل العلم المفيدة التي عرف أهلها بحسن العقيدة، مثل كتب شيخ الإسلام ابن تيمية وابن القيم، كتب أئمة الدعوة كالشيخ: محمد بن عبدالوهاب، وتلاميذه، وأنصاره، مثل كتاب التوحيد، مثل كشف الشبهات، ثلاثة الأصول، آداب المشي إلى الصلاة، مختصر السيرة النبوية، كل هذه للشيخ: محمد -رحمه الله- مثل العقيدة الواسطية لـشيخ الإسلام ، التدمرية، الحموية لشيخ الإسلام ابن تيمية، مثل كتاب الإيمان له أيضًا، منهاج السنة له أيضًا، الفتاوى المعروفة، مثل زاد المعاد لابن القيم -رحمه الله- شفاء العليل لابن القيم -رحمه الله- إعلام الموقعين لابن القيم -رحمه الله- حادي الأرواح له أيضًا، وهكذا كتبه الأخرى كلها مفيدة وجيدة. وهكذا كتب أهل العلم المعروفين بالعقيدة الطيبة، مراجعتها والاستفادة منها أمر طيب مطلوب، ولكن تكون العناية بالقرآن، وبالأحاديث أكثر وأكبر وأعظم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11241/تقييم-كتاب-عقيدة-المومن-لابي-بكر-الجزاىري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47204.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13062,"question":"تقول السائلة في آخر أسئلتها: أحيانًا أقوم بالدعاء على أبنائي الصغار، وذلك لكثرة مشاغبتهم داخل المنزل، فهل دعاء الأم مستجاب؟ مع العلم بأنني أندم فورًا، والسلام عليكم.","title":"حكم الدعاء على الأبناء","answer":"الجواب:  يخشى من الاستجابة، ينبغي الحذر، ينبغي أن لا تدعي عليهم إلا بالخير، فاحذري الدعاء عليهم بالشر، جاهدي النفس، لا بد من جهاد حتى يكون الدعاء طيبًا لا سيئًا، وأبشري بالخير، لا بد من الصبر، ولا بد من جهاد النفس حتى يكون الدعاء طيبًا لا ضارًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11279/حكم-الدعاء-على-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50522.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13100,"question":"السائل يقول: ما هي الآداب التي ينبغي لطالب العلم أن يتحلى بها؟","title":"من آداب طالب العلم","answer":"الجواب:  الآداب الشرعية، التحلي بالتواضع، وبذل السلام، ورد السلام، والتوجيه إلى الخير، والنصيحة، والأمر بالمعروف، والنهي عن المنكر .. صلة الرحم .. إكرام الجار .. كف الأذى عن الجار.. هكذا.. هذه الصفات هي علامات الخير، وعلامات السعادة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11317/من-اداب-طالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50810.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13375,"question":"يقول السائل: يهتم البعض من الآباء والأمهات بغذاء أبنائهم وبناتهم، ويغفلون عن تربيتهم التربية الإيمانية السليمة القائمة على حب الله ورسوله، وقراءة القرآن، والتأدب بآداب الإسلام، ما كلمتكم يا سماحة الشيخ؟","title":"وجوب الاهتمام بالتربية الإيمانية للأولاد","answer":"الجواب: الواجب على كل مؤمن ومؤمنة العناية بالآداب الشرعية، والغذاء الشرعي، أما الغذاء البدني هذا شأن البهائم، الواجب أن تكون العناية بتوجيه الأولاد إلى الخير، وإرشادهم إلى أسباب النجاة، وتعليمهم الأخلاق الفاضلة، والسيرة الحميدة، وترغيبهم في قراءة القرآن الكريم، والاستفادة من القرآن والتدبر، وترغيبهم في صحبة الأخيار، ومجالسة الأخيار، هذا أهم شيء، إصلاح دينهم أهم شيء من إصلاح أبدانهم، فالغذاء يتعلق بصلاح الأبدان، وتعليمهم ما ينفعهم في الدنيا والآخرة، وتوجيههم إلى الخير، وإرشادهم إلى أسباب النجاة، هذا يتعلق بنجاتهم في الدنيا والآخرة، ويتعلق بصلاح القلوب وهذا أهم. فالواجب على الأقارب جميعًا أن يهتموا بما فيه صلاح القلوب، والاستقامة على شرع الله، وأن يعلموا أولادهم، وأيتامهم، وقراباتهم ما ينفعهم في الدنيا والآخرة، وما يرضي الله عنهم، ويشجعوهم على تعلم القرآن الكريم، والعناية بالقرآن وحفظه، والإكثار من تلاوته، وحضور مجالس الذكر وحلقات العلم، وعليهم أن يوصوهم أيضًا بصحبة الأخيار، والبعد عن صحبة الأشرار، كل هذه أمور تتعلق بصلاح القلوب، وصلاح الدين، وصلاح أمر الآخرة. أما ما يتعلق بالغذاء البدني، والكسوة، ونحوها هذا أمر ثانوي، لا مانع من العناية به، ولكنه أمر ثانوي، أمر الدين أهم وأعظم، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11665/وجوب-الاهتمام-بالتربية-الايمانية-للاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52502.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13430,"question":"تقول السائلة في آخر أسئلتها (ب. ع. ش) من الإسكندرية من مصر: أبي يمنعنا من زيارة أقاربنا مثل: الخال، والخالة، والعمة، والأصدقاء، ويكاد يكون يحاسبنا في المنزل، ويسمح لنا بالذهاب لدور العلم فقط، ما رأيكم بذلك سماحة الشيخ؟","title":"توجيه لمن يمنعهن والدهن من زيارة أقاربهن","answer":"الجواب: الوالد قد يكون له رأي سديد في منعكم من الزيارة من الخالة والخال ونحو ذلك؛ لأن زيارتهم قد تجر عليكم شرًا، قد يكون الخال غير مضبوط، قد تكون الخالة غير مضبوطة، يخاف عليكم من شر هذه الزيارات، والدليل على هذا أنه يسمح لكم بزيارة دور العلم حتى تستفيدوا، فهذا يدل على أنه إنما منعكم خوفًا عليكم من هذه الزيارات، فإذا كان الخال، أو الخالة، أو العم، والعمة من أهل الصلاح والخير؛ فهو سوف لا يمنعكم، فأنتم تبحثون معه الموضوع الذي يمنعكم منه، واعرفوا أسباب المنع. فالوالد لا يتهم، يحب لأولاده الخير، فإذا منعكم من شيء؛ فالأصل وجوب طاعته؛ لأنه ناصح لولده، محب لولده الخير، فطاعته من طاعة الله، فإذا اتضح أنه نهاكم عن شيء فيه مصلحة لكم، وفيه خير، فالتفاوض معه، والبحث معه بالكلام طيب، والأسلوب الحسن؛ حتى يتضح الأمر، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11726/توجيه-لمن-يمنعهن-والدهن-من-زيارة-اقاربهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51611.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13447,"question":"من الأردن السائل محمد أحمد القرارعة يقول في هذا  كيف للأب أن يعلم ابنه المعاق سمعيًا، ونطقيًا للصلاة سماحة الشيخ؟","title":"كيفية تعليم الولد الأصم الأبكم الصلاة","answer":"الجواب: يعلمه بالطريقة التي يفهمها، إذا كان لا يسمع فإنه يريه إياه بالعمل، يصلي وهو معه، يركع معه، ويسجد معه، ويرفع معه، وإن كان لا يبصر، ولكنه يسمع يصلي معه، ويسمعه التكبير الركوع والرفع من الركوع، وهكذا حتى يفهمه كيف السجود، كيف الركوع، كيف الرفع.. إلى آخر الصلاة. المقصود: يفهمه بالطريقة التي يفهمها.. بالسمع.. بالفعل.. باللمس، الشيء الذي يستطاع. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11744/كيفية-تعليم-الولد-الاصم-الابكم-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52716.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13506,"question":"السائل (م. ع. ع) من حلب يقول في هذا  أنا طالب في المرحلة الثانوية الفرع العلمي، وقد شغلني تحصيل العلوم الدنيوية عن التفقه في دين الله، فهل أنا آثم على ذلك يا سماحة الشيخ؟","title":"حكم الانشغال بالعلوم الدنيوية وترك التفقه في الدين","answer":"الجواب: نعم، يجب عليك أن تتفقه في دينك، يجب أن تتعلم، ولا تشغل بالعلوم الدنيوية عن العلوم الدينية، الله أوجب عليك أن تعبده ولا طريق إلى العبادة إلا بالفهم والعلم، فعليك أن تتعلم ما تعرف به دينك، والعبادة التي خلقت لها؛ لقوله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ الذاريات:56] عليك أن تعرف هذه العبادة، وأن تؤديها كما أمر الله، يقول النبي ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين. فلا بد من أن تتعلم ما تحصل لك به الفقه في الدين حتى تؤدي ما أوجب الله عليك عن بصيرة، وحتى تترك ما حرم الله عليك على بصيرة، هذا هو الواجب، الواجب أن تعرف من دينك ما لا يسعك جهله، تعرف ما أوجب الله عليك، وما حرم عليك؛ حتى تؤدي الواجب؛ وحتى تبتعد عن المحرم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11827/حكم-الانشغال-بالعلوم-الدنيوية-وترك-التفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53109.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13658,"question":"السائلة (م. م) اليمن من حضرموت تقول في هذا  كيف يمكن تلقي العلم الشرعي الحق بالنسبة للفتاة، وهل تلقي المرأة للعلم الشرعي في بيتها من خلال الاستماع لبعض الأشرطة، وقراءة الكتب كافٍ، وذلك عند قلة وجود العلماء في بلادها؟ وجهونا بذلك يا سماحة الشيخ.","title":"كيفية تلَقي المرأة للعلم الشرعي","answer":"الجواب: بسم الله الرحمن الرحيم الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن العلم يتلقى بطرق كثيرة، منها تلقيه من طريق سماع الإذاعة عن نور على الدرب، وعن إذاعة القرآن، وعن المحاضرات، وخطب الجمعة، والخطب الأخرى من أهل العلم، والبصيرة، وأهل العقيدة الطيبة، هذه طرق لتلقي العلم للمرأة وغير المرأة، يسمع الإنسان في بيته، وتسمع المرأة في بيتها إذاعة القرآن الكريم من المملكة العربية السعودية، فيها علم كثير، ومحاضرات كثيرة، وفيها برنامج نور على الدرب، فيه خير كثير، وعلم جم. وهناك طريق آخر عام وهو العناية بالقرآن الكريم، فهو أحسن الطرق، وأعظمها، وأنفعها، العناية بالقرآن، والإكثار من تلاوته بالتدبر، والتعقل، وسؤال أهل العلم عما أشكل من طريق الهاتف، أهل العلم المعروفين بالعقيدة الطيبة، والعلم، والفضل وحسن السيرة، ومراجعة كتب التفسير، مثل تفسير ابن كثير، تفسير ابن جرير، تفسير البغوي فيما أشكل، تفسير الشوكاني، الإنسان يراجع القرآن، ويتدبر القرآن، وما أشكل عليه يراجع كتب التفسير، أو يسأل أهل العلم الذين يعرفهم بالعلم، والبصيرة، والعقيدة الطيبة. وهناك طريق آخر وهو طريق حلقات العلم في المساجد إذا كان طالب العلم يحضر حلقات العلم في المسجد، أو المرأة تحضر حلقات العلم من بعيد تسمع في محلات مناسبة لها، تستطيع سماع كلام المعلم، والمرشد في حلقات العلم، كما أنها تسمع خطبة الجمعة في المساجد التي تقام فيها الجمعة، كل هذه من طرق العلم. كذلك السؤال من طريق الهاتف كونها تسأل من طريق التلفون، تسأل أهل العلم عما أشكل عليها، وتحرص على أهل العلم المعروفين بالعقيدة الطيبة، والسمعة الحسنة حتى تسألهم عما أشكل عليها. وهكذا الرجال أيضًا يسألون من طريق الهاتف، من طريق التلفون عما أشكل عليهم، ويحضرون حلقات العلم عند أهل العلم في بلدهم، وفي غير بلدهم، ولو بالرحيل إلى بلد أخرى؛ لأجل طلب العلم، والتفقه في الدين، يقول النبي ﷺ في الحديث الصحيح: من يرد الله به خيرًا؛ يفقهه في الدين ويقول -عليه الصلاة والسلام-: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله به طريقًا إلى الجنة وكان السلف يرتحلون في طلب العلم؛ الصحابة ومن بعدهم، من بلاد إلى بلاد؛ لأجل طلب العلم، والتفقه في الدين، ولابد مع هذا من الإخلاص في ذلك، والنية الصالحة، وسؤال الله التوفيق، والإعانة، فهو سبحانه الموفق الهادي. فإذا صدق المؤمن والمؤمنة في طلب العلم، والتفقه في الدين، وأخلص كل منهما لله في ذلك؛ وجد واجتهد بسماع إذاعة القرآن الكريم من المملكة العربية السعودية، وما فيها من الخطب العظيمة، والفوائد الكثيرة، والمحاضرات، وبرنامج نور على الدرب. كذلك سماع خطب الجمعة التي تذاع، سماع المحاضرات التي تذاع، سماع خطبة الجمعة في بلدها إذا كان الخطيب ممن يوثق بعلمه وفضله، كل هذا طريق، كل هذه طرق من طرق العلم، نسأل الله للجميع التوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11990/كيفية-تلقي-المراة-للعلم-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52901.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":13661,"question":"في سؤال لها تقول هذه السائلة: هل هناك شرح موجز، ومبسط لكتاب عمدة الأحكام، وما هي الكتب الفقهية التي تنصحوننا بقراءتها؟ وجزاكم الله خيرًا.","title":"كتب ينصح بحفظها وقراءتها","answer":"الجواب: عمدة الحديث لها شروح لابن دقيق العيد، ولغيره من العلماء، الشيخ عبدالعزيز بن فيصل -رحمه الله- الشيخ عبدالله بن بسام، لها شروح طيبة مفيدة، وهي أحاديث واضحة بحمد الله، فالذي يحفظها يعلم معانيها بسهولة، أحاديث واضحة، عربية واضحة، ولها شروح -بحمد الله- مفيدة، ونفس الأحاديث مشروحة في مسلم، وفي البخاري؛ لأنها من أحاديث الصحيحين. فأنا أوصي بحفظ عمدة الحديث كتاب جيد، للشيخ عبدالغني بن عبدالواحد المقدسي، حفظ هذا الكتاب مهم جدًا ومفيد، هكذا بلوغ المرام للحافظ ابن حجر ، هكذا الأربعون النووية، وتكميلها لابن رجب كلها خمسون حديثًا مفيدة من جوامع الكلم أوصي بحفظها، كذلك عمدة الفقه للموفق مختصرة، وكذلك زاد المستقنع للشيخ موسى الحجاوي، كتاب مفيد في الفقه مختصر. ومن الكتب التي ينبغي أن يهتم بها في العقيدة: كتاب التوحيد، وكشف الشبهات، وثلاثة الأصول، والقواعد الأربع، كلها للشيخ محمد بن عبدالوهاب -رحمه الله- مفيدة في العقيدة، كذلك العقيدة الواسطية لشيخ الإسلام ابن تيمية في العقيدة كتاب مهم، نوصي بحفظ هذه الكتب، والعناية بها، والمذاكرة فيها مع الرجال والنساء؛ لأنها مفيدة وواضحة ليس فيها تعقيد. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11995/كتب-ينصح-بحفظها-وقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52904.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13695,"question":"السائلة سمية محمد من اليمن لها مجموعة من الأسئلة تقول سماحة الشيخ: هل يحرم على المؤمن أن يقرأ كتبًا غير إسلامية، وغيرها من الكتب التي ليس فيها شيء عن الإسلام؟","title":"حكم قراءة الكتب غير الإسلامية","answer":"الجواب: إذا كانت الكتب فيها شيء ينفع؛ لا بأس بقراءتها، ولو في أمور الدنيا، إن كان من الطب، والكتب الأخرى في معادن، في أشياء تنفع؛ فلا بأس، إذا كانت في شيء مباح. أما الكتب التي في أشياء تضل الناس، وتلبس على الناس دينهم، مثل كتب أهل الكلام؛ هذه لا يجوز النظر فيها، ولا قراءتها؛ لأن كتب أهل الكلام تدعو إلى الشر والبدعة، والتحلل من الدين، والشك في دين الله، فالواجب الحذر منها.  أما كتب تتكلم عن مصالح الذهب، فوائد الفضة، فوائد البترول، فوائد كذا، فوائد كذا.. من المباحات هذه تنفع الأطباء وتنفع غيرهم؛ فلا حرج في ذلك، وهكذا الكتب التي تتكلم عن الزراعة، عن مصالح الزراعة، عن فوائد لحم الإبل.. لحم الغنم، الشيء الذي فيه فائدة؛ لا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12066/حكم-قراءة-الكتب-غير-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54502.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13781,"question":"رسالة وصلت إلى البرنامج من المستمع هنداوي إبراهيم مقيم في العراق حاليًا، أخونا يقول: ما هي كتب الفقه التي ترون أن نقرأها؟ وأرشدوني لو تكرمتم إلى بعض كتب السيرة الصحيحة.","title":"كتب ينصح بقراءتها في الفقه","answer":"الجواب: كتب الفقه كثيرة، ولكن من أحسنها فيما نعلم: المغني للموفق ابن قدامة، وهو كتاب عظيم مطول، وشرح المهذب للنووي وتكملته هذان كتابان عظيمان، ومن المختصرات زاد المستقنع للحجاوي في مذهب الحنابلة، وهو كتاب مفيد وعليه شرح حواشي مفيدة، والعمدة للموفق كتاب مختصر في الفقه الموفق ابن قدامة. أما كتب المذاهب الثلاثة المالكية الحنفية الشافعية المختصرة فلا أذكر الآن شيئاً من مختصراتها التي أحول عليها، وفي إمكانك سؤال بعض أهل العلم الذين يعرفون شيئاً منها ليرشدوك إلى ما تريد، ولكن أنصحك بأن تعتني بكتب الحديث المختصرة مثل عمدة الحديث للشيخ عبد الغني بن عبد الواحد المقدسي، ومثل بلوغ المرام للحافظ ابن حجر، والأربعين النووية وتتمتها للحافظ ابن رجب، هذه كتب مفيدة وعظيمة النفع، وإذا حفظت معها العمدة للموفق في الفقه لتعينك على بعض المسائل أو ما يماثلها من كتب الفقه من المذاهب الأخرى المختصرة المفيدة فهذا حسن تستعين بها على معرفة المسائل ثم على معرفة حكمها في الدليل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12143/كتب-ينصح-بقراءتها-في-الفقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60104.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13801,"question":"أختنا تقول: تركت الدراسة ووالدتي غير راضية هل أكون آثمة؟","title":"حكم ترك الدراسة بغير رضا الوالدين","answer":"الجواب: الدراسة فيها خير عظيم وفائدة كبيرة، والواجب على المسلم والمسلمة التعلم والتفقه في الدين؛ لأنه يجب على المسلم أن يتفقه في دينه وأن يتعلم ما لا يسعه جهله، ومن أسباب السعادة التفقه في الدين، كما قال النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين متفق على صحته. فمن علامات الخير والسعادة التفقه في دين الله، التفقه في الإسلام في أحكام الشريعة حتى يعرف المؤمن والمؤمنة ما يجب عليه ما يحرم عليه، وحتى يعبد الله على بصيرة، ويقول النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة.\nفالواجب عليك التعلم والتفقه في الدين إذا تيسر ذلك في مدارس إسلامية طيبة أمينة، وإذا أكدت عليك أمك كان هذا مما يوجب مزيد العناية والحرص على التفقه في الدين؛ لأنها تريد لك الخير والمصلحة العاجلة والآجلة، فلا ينبغي منك أن تعصيها في ذلك إلا إذا كانت المدرسة فيها اختلاط أو فيها أمور أخرى تضرك في دينك فلا حرج عليك إذا تركت الدراسة ولو لم ترض أمك؛ لأن الرسول عليه السلام يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق، نسأل الله أن يمنحك التوفيق. نعم.\nالمقدم: أثابكم الله وسدد خطاكم، وكتب لكم الأجر والثواب.","link":"https://binbaz.org.sa/fatwas/12209/حكم-ترك-الدراسة-بغير-رضا-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60210.mp3","categories":["بر الوالدين","العالم والمتعلم"]},{"id":13807,"question":"أختنا تقول: تركت الدراسة ووالدتي غير راضية هل أكون آثمة؟","title":"حكم ترك الدراسة بغير رضا الوالدين","answer":"الجواب: الدراسة فيها خير عظيم وفائدة كبيرة، والواجب على المسلم والمسلمة التعلم والتفقه في الدين؛ لأنه يجب على المسلم أن يتفقه في دينه وأن يتعلم ما لا يسعه جهله، ومن أسباب السعادة التفقه في الدين، كما قال النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين متفق على صحته. فمن علامات الخير والسعادة التفقه في دين الله، التفقه في الإسلام في أحكام الشريعة حتى يعرف المؤمن والمؤمنة ما يجب عليه ما يحرم عليه، وحتى يعبد الله على بصيرة، ويقول النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة.\nفالواجب عليك التعلم والتفقه في الدين إذا تيسر ذلك في مدارس إسلامية طيبة أمينة، وإذا أكدت عليك أمك كان هذا مما يوجب مزيد العناية والحرص على التفقه في الدين؛ لأنها تريد لك الخير والمصلحة العاجلة والآجلة، فلا ينبغي منك أن تعصيها في ذلك إلا إذا كانت المدرسة فيها اختلاط أو فيها أمور أخرى تضرك في دينك فلا حرج عليك إذا تركت الدراسة ولو لم ترض أمك؛ لأن الرسول عليه السلام يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق، نسأل الله أن يمنحك التوفيق. نعم.\nالمقدم: أثابكم الله وسدد خطاكم، وكتب لكم الأجر والثواب.","link":"https://binbaz.org.sa/fatwas/12209/حكم-ترك-الدراسة-بغير-رضا-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60210.mp3","categories":["بر الوالدين","العالم والمتعلم"]},{"id":13819,"question":"هذا سائل للبرنامج يقول في هذا  هناك شخص يحدث ويقرأ في كتاب بعد أذان العشاء حتى إقامة الصلاة، فعندما يقرأ الحديث يشرح بعض ألفاظه ويأتي ببعض الكلام العامي، وقد يضحك الجلوس أو المستمعين في المسجد من خلال هذا الكلام، وإن لم يكن قصده ذلك، وإنما قصده أن يفهم المستمعين الحديث، فهل في ذلك شيء؟ يا سماحة الشيخ.","title":"حكم شرح الحديث النبوي بالألفاظ العامية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن المشروع للمدرس والمذكر أن يوضح للمخاطبين ما يريد بالأساليب الواضحة التي يفهمونها؛ لأن المقصود نصيحتهم وتوجيههم إلى الخير، فيحدثهم بما يعرفون، مثل ما قال علي : \"حدثوا الناس بما يعرفون أتحبون أن يكذب الله ورسوله؟\"، ويشرع له تجنب الألفاظ التي قد تضحك الناس ويأتي بألفاظ أخرى توضح المراد من دون أن تسبب إضحاكًا أو لعبًا أو ما أشبه ذلك مما يخالف المطلوب في هذا المقام العظيم.\nالمقصود: أن المحاضر أو المدرس أو الواعظ يتحرى الألفاظ الواضحة التي يعرفها الناس ويفهمونها؛ لأن المقصود وعظهم وتذكيرهم وتفهيمهم ودعوتهم إلى الخير، أما الألفاظ التي قد تسبب ضحكًا أو استغرابًا فالمشروع له تجنبها.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12182/حكم-شرح-الحديث-النبوي-بالالفاظ-العامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53701.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13867,"question":"أخيرًا يسأل الأخ عن الكتب التي تنصحون طلبة المتوسطة بقراءتها من كتب السنة؟","title":"كتب ينصح بقراءتها لطلبة المرحلة المتوسطة","answer":"الجواب: نوصي طلبة المرحلة المتوسطة بالعناية بمقرراتهم والإقبال عليها والحرص على الاستفادة منها؛ لأنهم مشغلون بها ولينجحوا فيها أيضاً ولأنها مفيدة، المقررات الدراسية فيما يتعلق بالتوحيد والعبادات مهمة ومفيدة، فإذا كان عنده وقت فنوصيه بمثل: كتاب التوحيد يدرسه، ومثل: كشف الشبهات يحفظه ويتأمل هذين الكتابين فهما مفيدان، ومثل: الأربعين النووية يحفظها خمسين حديث اثنين وأربعين للنووي وثمانية للحافظ ابن رجب خمسون حديثًا من جوامع الكلم يحفظها، فهذه المرحلة ....... جيدة يحفظها وفي هذا كفاية حتى ينتقل للثانوي إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/12239/كتب-ينصح-بقراءتها-لطلبة-المرحلة-المتوسطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60310.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":13900,"question":"السائل عبدالله عبدالرحمن من ليبيا له مجموعة من الأسئلة يقول: أريد أن أتفقه في الدين وأنا طالب علم شرعي، فحبذا لو ذكر لنا سماحة الشيخ عبد العزيز بعض الكتب في الفقه التي توصونني بقراءتها؟","title":"كتب يُنصح طالب العلم بها","answer":"الجواب: نوصيك بالقرآن الكريم، والإكثار من تلاوته، فهو أعظم كتاب وأشرف كتاب، وفيه العلم العظيم؛ يعلمك أصول دينك، ويعلمك الأحكام الشرعية في صلاتك وغيرها، فنوصيك بالقرآن الكريم والإكثار من تلاوته، وتدبر معانيه، ثم نوصيك أيضًا بالسنة؛ حفظ ما تيسر من السنة مثل: بلوغ المرام ... مثل: عمدة الحديث، فهذان كتابان عظيمان مختصران وفائدتهما عظيمة؛ فنوصيك بحفظ ما تيسر منهما، أو بحفظهما جميعًا، مع الأربعين النووية وتتمتها لابن رجب خمسين حديثًا من جوامع الكلم فائدتها عظيمة، ونوصيك بكتب العقيدة مثل كتاب التوحيد .. كشف الشبهات للشيخ محمد بن عبد الوهاب رحمه الله، ثلاثة الأصول، والأربع القواعد له أيضًا، العقيدة الواسطية لشيخ الإسلام ابن تيمية كتاب عظيم مفيد في العقيدة، نوصي جميع الطلبة بهذه الكتب؛ لأنها مفيدة جدًا والحاجة إليها ماسة، ونوصي الجميع أيضًا بكتب شيخ الإسلام ابن تيمية الأخرى مثل: التدمرية والحموية، ومثل كتب ابن القيم رحمه الله فإنه من أهل السنة والجماعة، ومثل: شرح الطحاوية لابن أبي العز كتاب عظيم مفيد، كتاب التوحيد لابن خزيمة. وأما الفقه فكتبه كثيرة فإذا حفظ مثل زاد المستقنع للحجاوي مثل: كتاب الفقه للموفق أو دليل الطالب، المقصود: إذا تيسر له أحد الكتب المؤلفة في الفقه للأئمة المعروفين من أهل السنة فلا بأس يستعين بها على فهم النصوص يستعين بهذا الكتاب لكن لا يقلد ولا يتعصب وإنما يستعين به على فهم النصوص فهذا لا بأس به، زاد المستقنع .. دليل الطالب وما أشبه ذلك من الكتب التي ألفت في الفقه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12282/كتب-ينصح-طالب-العلم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53813.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13913,"question":"في آخر أسئلة هذا السائل من الأردن يقول: نحن ثلاث إخوان من أم وأب، أنا وأختان، الأخت الكبيرة متزوجة ولله الحمد ومتعلمة، أما الأخت الثانية فهي غير متزوجة ولديها مشكلة ألا وهي أنها لا تعرف أن تقرأ ولا تعرف أن تكتب، فقد خرجت من المدرسة في صغرها فأنا أعطيها أشرطة قرآن من السور القصيرة لتحفظها مع تكرار التلاوة، فهل هذا يكفي يا سماحة الشيخ؟","title":"مشروعية تعليم الأمي أمور دينه","answer":"الجواب: هذا طيب جزاك الله خير، ويشرع لك أن تعلمها أنت، وأختك الكبيرة تعلمها أيضًا حتى تحفظ ما تيسر من القرآن، وعليكما أن تعلماها أحكام الدين.. أحكام الصلاة.. أحكام الصيام.. أحكام الحيض حتى تكون على بصيرة، علموها، هكذا المؤمن يعلم أقاربه في الذمة، ويقول النبي ﷺ: خيركم من تعلم القرآن وعلمه ويقول ﷺ: من يرد الله به خيرًا يفقهه في الدين، ويقول عليه الصلاة والسلام: والله في عون العبد ما كان العبد في عون أخيه، ويقول عليه الصلاة والسلام: من كان في حاجة أخيه كان الله في حاجته.\nفالواجب تعليمها وإرشادها منك ومن أختها بكل ما قد تجهل من صلاة أو أحكام حيض أو أحكام نفاس أو أحكام صيام أو غير هذا، مع تعليمها ما تيسر من القرآن الكريم ومن أحكام الصلاة وأنتم على خير ولكم أجر عظيم، يقول النبي ﷺ: من دل على خير فله مثل أجر فاعله ويقول ﷺ: خيركم من تعلم القرآن وعلمه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12317/مشروعية-تعليم-الامي-امور-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54408.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":13938,"question":"أفيدوني لو تكرمتم عن كتاب البداية والنهاية، ثم رشحوا لي بعضًا من الكتب لتكون نواة لمكتبتي؟ جزاكم الله خيرًا.","title":"التعريف بكتاب البداية والنهاية وكتب يُنصح باقتنائها","answer":"الجواب: البداية والنهاية كتاب عظيم للحافظ ابن كثير رحمه الله، وتاريخ عظيم إسلامي ذكر فيه أخبار الأنبياء الماضين، ثم ذكر فيه خبر نبينا ﷺ وسيرته، ثم ذكر مغازيه عليه الصلاة والسلام، ثم ذكر ما بعده إلى القرن الثامن إلى نصف القرن الثامن، فينبغي اقتناءه والاستفادة منه، فهو كتاب عظيم ذكر فيه الأحاديث والآثار وكلام أهل العلم في التاريخ وهو كتاب جيد. وننصحك باقتناء الكتب المفيدة مثل: المغني لـموفق الدين ابن قدامة، مثل: شرح المهذب للنووي، مثل: مجموع الرسائل لشيخ الإسلام ابن تيمية، مثل: مجموعة رسائل أئمة الدعوة، مثل: فتح المجيد، مثل: تيسير العزيز الحميد شرح كتاب التوحيد، كتاب التوحيد، كتب الشيخ محمد رحمه الله، كتاب مختصر السيرة النبوية، والسيرة أيضًا لابنه عبد الله، كلها كتب جيدة، بلوغ المرام تحفظ ما تيسر منه، عمدة الحديث، منتقى الأخبار، نيل الأوطار شرح المنتقى، تفسير الشوكاني، تفسير البغوي، تفسير ابن كثير كلها كتب مفيدة جيدة. نعم.\nالمقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12339/التعريف-بكتاب-البداية-والنهاية-وكتب-ينصح-باقتناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48211.mp3","categories":["العالم والمتعلم","التاريخ والسيرة"]},{"id":14018,"question":"رسالة وصلت إلى البرنامج من المستمع السيد حسن أحمد مصري مقيم في العراق، أخونا يسأل عن كتاب بدائع الزهور في وقائع الدهور، هل ما جاء في هذا الكتاب يعتبر من الصحيح؟","title":"تقييم كتاب: بدائع الزهور في وقائع الدهور","answer":"الجواب: لا، لا يعتمد، هذا الكتاب خرافي لا يعتمد ولا يعول عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12436/تقييم-كتاب-بداىع-الزهور-في-وقاىع-الدهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61106.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14033,"question":"شيخ عبد العزيز! ما أشد حاجتنا إلى السؤال عن أمور ديننا، ألا ترون أنه يجب أن يكون هناك أشخاص متفرغون، همهم إفتاء الناس فيما يرد إليهم من أسئلة ولو عبر الهاتف.","title":"حاجة الأمة إلى من يبصرها بأمور دينها","answer":"الجواب: هذا من أهم المهمات، وهذا البرنامج من هذا القبيل، هذا البرنامج والحمد لله برنامج (نور على الدرب) هو قائم بهذه المهمة، وإذا تيسر من العلماء من يقوم بذلك أيضًا؛ كالعون لهذا البرنامج، فهذا خير عظيم.\nوالمقصود أن هذا البرنامج بحمد الله فيه خير عظيم، وقد يكون أدى فرض الكفاية، وإذا تيسر من العلماء -في المساجد وفي بيوتهم- من يفتي الناس -إذا كان عنده علم وبصيرة- بما قاله الله ورسوله؛ فهذا خير إلى خير، ومما يخفف على هذا البرنامج أيضًا.\nفالحاصل: أن هذا البرنامج فيه خير عظيم والحمد لله، وقد قام بواجب كبير في إفتاء الناس من الداخل والخارج، وفي حل المشاكل بالأدلة الشرعية؛ فنسأل الله أن يوفق القائمين عليه وأن يعينهم، وأن يمنحهم البصيرة والإخلاص والصدق، وأن يوفق المسلمين جميعًا في كل مكان لما فيه رضاه، ولما فيه صلاحهم ونجاتهم، وأن يوفق علماء المسلمين في كل مكان وفي كل بلد لأداء الواجب، وتوجيه الناس إلى الخير، وتعليمهم ما ينفعهم في دينهم، مع العناية بما قاله الله ورسوله، وأن تكون الفتوى على ضوء كلام الله وكلام رسوله عليه الصلاة والسلام، لا بالآراء المجردة، والله المستعان.\nالمقدم: الله المستعان، جزاكم الله خيرًا، إنما لا ترون أن يتفرغ شخص لهذا الموضوع أيضًا شيخ عبد العزيز ، دعمًا لهذا البرنامج؟\nالشيخ: إذا تيسر هذا طيب، إذا تيسر من هو أهل لذلك من أهل العلم والبصيرة في بيته أو في أي مكان؛ فجزاه الله خيرًا، طيب، الناس في حاجة إلى آلاف المفتين والموجهين، وفي حاجة في كل مكان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12456/حاجة-الامة-الى-من-يبصرها-بامور-دينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60703.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14157,"question":"هذه السائلة أم خالد لها مجموعة من الأسئلة تذكر بأنها مدرسة لمادة الدين، وأحيانًا تقول: أطلب من التلميذة الإجابة على السؤال وأطلب الدليل من القرآن والسنة، ويكون لفظ الطالبة للآية خطأ، هل أعطي الطالبة الدرجة الكاملة حتى وإن كان لفظها للآية خطأ؟","title":"حكم إعطاء الدرجة كاملة لمن يلحن في قراءة الآية","answer":"الجواب: هذا العمل طيب، المطالبة بالأدلة الشرعية والسؤال عن أمور الدين هذا تلقين طيب للطالبات حتى يعتدن ذلك، وأنت مأجورة في هذا الخير العظيم، وإذا غلطت في الآية ما يضر تعطى الدرجة التي فهمتها وعرفتها بالدليل والخطأ يعدل، إذا لحنت في الآية أو شبه ذلك لا يضر لا يمنعها من أخذ الدرجة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12598/حكم-اعطاء-الدرجة-كاملة-لمن-يلحن-في-قراءة-الاية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54620.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":14242,"question":"يقول هذا السائل: لي جدة لا تصلي وهي جاهلة لا تعرف تقرأ ولا تكتب، كيف أعلمها الصلاة وأعلمها الطهارة، فأنا ألاحظ عليها أنها لا تعرف حتى الطهارة الشرعية لجهلها، وضحوا لنا ذلك، وهل تبرأ ذمتنا؟","title":"حكم تعليم الجاهل كيفية الطهارة والصلاة وغيرهما","answer":"الجواب: علمها أنت، علمها أنت أو أحد أولادها أو غيركم، علموها كيف تصلي وكيف تتوضأ، العلم بالتعلم هذا واجب عليكم، إذا كانت جاهلة علموها، الله أخذ على من عنده علم أن يعلم، وهذا من برها أيضًا، فيجب عليكم تعليمها وإرشادها بالكلام الطيب والرفق والحلم لا بالشدة والعنف، بل عليكم الرفق بها وتعليمها وتوجيهها إلى الخير هذا شيء لازم لكم، نعم. الله المستعان.\nالمقدم: الله المستعان جزاكم الله خيرًا سماحة الشيخ! يتساهل الكثير من الناس حيث يرون أهلهم وذويهم يخطئون في العبادات، فكيف توجهون مثل هؤلاء يا سماحة الشيخ؟\nالشيخ: الواجب عليهم أن يعلموا جميع من تحت أيديهم، وألا يتساهلوا في هذا الأمر، يعلم بنته، ويعلم أخته، يعلم جدته وأمه، يعلم خالته، يعلم جميع من تحت يده، حتى الخدم الذي عنده يعلمهم ويرشدهم إلى الحق، الله أخذ على أهل العلم أن يعلموا، كل من كان عنده علم عليه العهد والميثاق أن يعلم ويتقي الله، ولو كان ليس بعالم لكن يعلم مما علمه الله، فهو يعرف الصلاة ويعرف كيفيتها .... يعلم الناس يعلم بنته وأخته وجدته وأمه، يعرف أن الغيبة حرام يعلمهم أن هذا لا يجوز، يعرف أن الزنا حرام يعلمهم أن الزنا محرم، يعرف أن المسكر حرام فيعلمهم أنه محرم، وهكذا يعلمهم مما علمه الله؛ لأن ..... قسمان: قسم يحتاج إلى أهل العلم لأنه يخفى دليله، وقسم لا يحتاج إلى أهل العلم بل هو واضح، الصلاة واضحة يعرفها الخاص والعام من أهل الإسلام الذين تعلموا وتبصروا، تحريم الخمر، تحريم الزنا، تحريم العقوق للوالدين أو أحدهما، وهكذا، نعم الشيء الواضح يعلمه واللي ما هو بواضح يسأل أهل العلم ثم يعلم أهل بيته.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12707/حكم-تعليم-الجاهل-كيفية-الطهارة-والصلاة-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53018.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14259,"question":"أحد الإخوة المستمعين بعث يسأل ويرجو رأيكم شيخ عبد العزيز في كتاب روح الصلاة في الإسلام للمؤلف عفيف عبد الفتاح طبارة؟","title":"استفسار حول كتاب روح الصلاة في الإسلام","answer":"الجواب: لا أعلم حال الكتاب المذكور؛ لأني لم أقرأه، قد سمعت عنه ولكن لم أقرأه فلا أستطيع أن أحكم عليه بشيء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12759/استفسار-حول-كتاب-روح-الصلاة-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62108.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14265,"question":"رسالة وصلت إلى البرنامج من المستمع وحيد خليفي مصطفى عنيو مصري ومقيم في المملكة، أخونا له جمع من الأسئلة في أحد أسئلته يقول: أرجو أن تفيدوني أفادكم الله عن الطريقة المثلى والسهلة التي يمكن أن تحبب إلينا القرآن وتجعلني أحفظه بأسرع وقت، وكيف أبدأ، كما أريد حفظ الأحاديث فهل أبدأ أولًا بحفظ القرآن الكريم؟ أم أبدأ بحفظ الاثنين معًا، وما هي الكتب التي تشتمل على الأحاديث الصحيحة؟","title":"كيفية حفظ القرآن والكتب التي ينصح بحفظها","answer":"الجواب: حفظ القرآن من أفضل القربات والطاعات، وهكذا حفظ ما تيسر من السنة الصحيحة من أفضل القربات والطاعات، والأفضل أن تبدأ بحفظ ما تيسر من القرآن وأنت مخير إن شئت بدأت بالمفصل ق وَالْقُرْآنِ الْمَجِيدِ [ق:1]، وما بعدها حتى تكمل تحفظ الأجزاء الأخيرة الأربعة، وإن شئت بدأت بالبقرة ورتبت لك جزءًا معلومًا كل ليلة أو كل صباح صفحة صفحتين ثلاث صفحات ترتب شيئًا معلومًا وتستمر عليه، تسأل ربك العون والتوفيق، وتتحرى الأوقات المناسبة التي ليس فيها مشاغل.\nوإذا جمعت بين الأمرين وجعلت وقتًا لحفظ ما تيسر من القرآن، ووقتًا لحفظ ما تيسر من السنة فهذا حسن؛ لأن حفظ القرآن قد يطول وتطول مدته، فإذا جمعت بين هذا وهذا فهذا شيء طيب.\nونوصيك بحفظ عمدة الحديث للشيخ عبد الغني بن عبد الواحد المقدسي فإنها أحاديث صحيحة ومختصرة، أربعمائة حديث وزيادة يسيرة، فإذا حفظت هذا الكتاب فهو كتاب جيد عظيم مفيد، وإن كان عندك قدرة على حفظ بلوغ المرام للحافظ ابن حجر فهو كتاب أيضًا محرر وجيد، وفيه بعض الأحاديث ضعيفة التي بينها المؤلف رحمه الله. ونوصيك أيضًا بحفظ بعض كتب العقيدة، مثل: كتاب التوحيد، وثلاثة الأصول، وكشف الشبهات للإمام العلامة شيخ الإسلام في زمانه محمد بن عبد الوهاب رحمه الله فهي كتب مفيدة في العقيدة، ومثل: كتاب العقيدة الواسطية لشيخ الإسلام ابن تيمية، ولمعة الاعتقاد للموفق بن قدامة رحمه الله، وهذه كتب جيدة في العقيدة نوصي بحفظها أيضًا؛ لأنها مفيدة وكلها مأخوذة من كتاب الله العظيم وسنة رسوله الأمين عليه الصلاة والسلام، فهي كتب مفيدة مختصرة في العقيدة. نعم.\nالمقدم: جزاكم الله خيرًا، يسأل عن الكتب التي تشتمل على الأحاديث الصحيحة شيخ عبد العزيز؟\nالشيخ: ذكرنا عمدة الحديث كلها من الصحيحين من البخاري ومسلم سوى أفراد قليلة من أحدهما، فالعمدة للشيخ عبد الغني بن عبد الواحد بن سرور المقدسي هي في الحقيقة كتاب مفيد جدًا، سماها العمدة لما فيها من الأحاديث الصحيحة، فإذا حفظها طالب العلم أو حفظتها طالبة العلم فذلك مناسب جدًا، وإن تيسر مع هذا حفظ بلوغ المرام فهو كتاب أوسع ومحرر وفيه علم جم، وفيه أحاديث يسيرة ضعيفة قد بينها المؤلف رحمه الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12768/كيفية-حفظ-القران-والكتب-التي-ينصح-بحفظها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62112.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14271,"question":"من الجمهورية العراقية ذي قار رسالة بعث بها مستمع من هناك هو (ع. ع. ناصر منصور الخلاوي) أخونا له جمع من الأسئلة فيسأل مثلًا ويقول: أرجو أن تنصحوني لقراءة بعض الكتب بعد كتاب الله وبعض كتب السنة لنبينا محمد ﷺ؟","title":"أرجو أن تنصحوني ببعض الكتب بعد الكتاب والسنة","answer":"الجواب: اللهم صل عليه وآله، ننصحك بقراءة الكتب المعتمدة المعروفة لأهل العلم والبصيرة والسنة والعقيدة الصالحة مثل كتب شيخ الإسلام ابن تيمية كتب ابن القيم رحمه الله كتب الحافظ ابن رجب كتب ابن كثير وأشباههم من أهل العلم والبصيرة، فإذا راجعت مثل كتاب اقتضاء الصراط المستقيم لشيخ الإسلام ابن تيمية الفتاوى لشيخ الإسلام ابن تيمية، زاد المعاد في هدي خير العباد لابن القيم، جامع العلوم والحكم في شرح الأربعين النووية للحافظ ابن رجب، تفسير ابن كثير، تفسير البغوي، تفسير ابن جرير، تفسير الشوكاني، فتح المجيد في شرح كتاب التوحيد للشيخ عبد الرحمن بن حسن، المجموعة المهمة: المجموعة النجدية في التوحيد ومسائل الدين والعقيدة، كل هذه كتب عظيمة ومفيدة، رياض الصالحين من كتب السنة كتاب مفيد، الوابل الصيب لابن القيم في الكلم الطيب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12725/ارجو-ان-تنصحوني-ببعض-الكتب-بعد-الكتاب-والسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61713.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14273,"question":"السائل (ح. أ. أ) يقول: يذكر بأنه شاب موظف في إحدى الشركات ويحفظ من كتاب الله كثيرًا والحمد لله، يقول: ما بقي لي إلا جزءًا وكنت أحفظ نصف صفحة في اليوم تقريبًا، ومشكلتي الآن: إذا بدأت بالحفظ أو المراجعة يأتيني نوم ولا أستطيع أن أملك نفسي عن النوم، ولي أكثر من شهرين في سورة الصافات، ما نصيحتكم لي يا سماحة الشيخ؟","title":"نصيحة لمن يأتيه النوم عند حفظ القرآن","answer":"الجواب: نصيحتي لك أنك تسأل ربك أن يعينك، تضرع إليه جل وعلا أن الله يعينك على حفظه وأن يعيذك من الشيطان وأن يمنحك النشاط والقوة، مع أني أنصحك أيضًا أن تنظر في الأوقات المناسبة، تتحرى الأوقات المناسبة التي أنت فيها نشيط، بعد صلاة الفجر بعد صلاة العشاء، في أي وقت ترى نفسك نشيطًا تقرأ فيه، مع التعوذ بالله من الشيطان؛ لأن الشيطان حريص على تكسيل الإنسان عن عمل الخير، فقد يكون يأتي بأسباب النوم، تعوذ بالله من الشيطان الرجيم، تسأل ربك العون والتوفيق، وتلتمس الأوقات المناسبة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12728/نصيحة-لمن-ياتيه-النوم-عند-حفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54912.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14285,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (م. ج. محمد عبد السيد) مصري ومقيم في المملكة، أخونا له قضية يقول فيها: إذا حفظ إنسان علمًا من علوم الدين لكي يقوم بدوره في القرية التي يسكنها، وحفظ القرآن لكي يصلي بالشباب صلاة قيام رمضان في اليوم بجزء، هل يكون هناك شيء من الشرك الأصغر؟ مع العلم أنني عندما كنت في قريتي أقوم بالخطبة والوعظ في القرى المجاورة، وأصلي بالشباب صلاة القيام بالمصحف، وأريد من ذلك أن أتوسع في العلوم ولكي أستغني عن المصحف في القراءة، أرجو توجيهي، جزاكم الله خيرًا.","title":"توجيه لمن يدعو إلى الله ويصلي بالناس ويخاف الرياء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فمن المعلوم بالأدلة الشرعية أن طلب العلم والتفقه في الدين من أفضل القربات، ومن أفضل الطاعات، وهكذا دراسة القرآن الكريم والعناية بالإكثار من تلاوته، والحرص على حفظه أو ما تيسر منه، كل ذلك من أفضل القربات، وإذا قمت بما ينبغي من تعليم أهل قريتك وتوجيههم والصلاة بهم، والصلاة بالشباب وغيرهم من أهل القرية في رمضان فكل هذا عمل صالح تشكر عليه وتؤجر عليه، وليس ذلك من الرياء وليس من الشرك، إذا كان قصدك وجه الله والدار الآخرة ولم ترد رياء الناس ولا حمدهم ولا ثناءهم، وإنما أردت بذلك أن تنفعهم وأن تتزود من العلم والفقه في الدين، وإنما يكون شركًا أصغر إذا فعلت ذلك رياءً للناس وطلبًا لثنائهم، كما قال النبي الكريم عليه الصلاة والسلام: أخوف ما أخاف عليكم الشرك الأصغر، فسئل عنه؟ فقال: الرياء يقول الله يوم القيامة للمرائين: اذهبوا إلى من كنتم تراءون في الدنيا فانظروا هل تجدون عندهم من جزاء.\nفالرياء: هو أن تعمل العمل من أجل رياء الناس حتى يشاهدوك ويثنوا عليك ويمدحوك، ومن ذلك: السمعة، كأن تقرأ ليثنوا عليك ويقولوا: إنه جيد القراءة، ويحسن القراءة، أو تكثر من ذكر الله ليثنوا عليك ويقولوا: إنه يكثر من الذكر، أو تأمر بالمعروف وتنهى عن منكر بقولك، لتمدح ويثنى عليك، هذا هو الرياء، وهذا هو الشرك الأصغر.\nفالواجب الحذر من ذلك وأن تعمل أعمالك لله وحده لا لأجل مراءاة الناس وحمدهم وثنائهم، ولكن تعلم إخوانك وتصلي بهم، ترجو ما عند الله من المثوبة، وتقصد بذلك نفعهم، لا رياءً ولا سمعة، وإذا قرأت من المصحف فلا بأس، كونك تصلي بإخوانك من المصحف في رمضان، كان مولى عائشة رضي الله عنها يصلي بها من المصحف.\nفالحاصل أنه لا بأس أن يقرأ المصلي القرآن من المصحف في قيام رمضان إذا كان لا يحفظ، وإن حفظه وقرأه عن ظهر قلب فهو أفضل وأحسن ولكن لا حرج في القراءة من المصحف عند الحاجة إلى ذلك، هذا هو الصواب، وفق الله الجميع لما يرضيه. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، فهمت جانبًا آخر سماحة الشيخ من رسالة أخينا هو أنه يريد الاستفادة من صلاته بالناس كقراءته للقرآن ومذاكرته، وأيضًا أن يكسب أجر إمامته للناس؟\nالشيخ: كل ذلك طيب، كونه يقصد نفعهم ويقصد الصلاة بهم وإعانتهم على الخير، ويقصد مع هذا أن يستفيد وأن يقوى حفظه للقرآن وأن تكثر معلوماته، كل هذا طيب، وكلها مقاصد حسنة ليس فيها رياء.\nالمقدم: ليس فيها رياء.\nالشيخ: نعم.\nالمقدم: وهذا هو المقصود، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12750/توجيه-لمن-يدعو-الى-الله-ويصلي-بالناس-ويخاف-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61801.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14331,"question":"هذا سائل للبرنامج عبد الحليم عثمان من الجمهورية اليمنية يقول في هذا  هل يجوز قراءة الفاتحة عقب كل صلاة على روح النبي ﷺ أم أن هذا بدعة؟ وكيف نعرف البدع يا سماحة الشيخ؟","title":"حكم قراءة الفاتحة بعد الصلاة على روح النبي ﷺ","answer":"الجواب: هذا بدعة، القراءة على روح النبي ﷺ من البدع ليس له أصل في الشرع، والبدعة: هي فعل شيء ما شرعه الله، هذه البدعة التعبد بشيء ما شرعه الله؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، وقال أيضًا عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد، وقال عليه الصلاة والسلام: كل محدثة بدعة وكل بدعة ضلالة فالتعبد بشيء ما شرعه الله يسمى ضلالة.\nومن هذا القراءة للنبي ﷺ قراءة مخصوصة، أو مطلقة، هذا ما شرعه الله، لكن تصلي عليه تقول: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم صل وسلم على نبينا محمد، اللهم صل وسلم على خاتم أنبيائك، اللهم صل وسلم على رسولنا محمد.. وما أشبه ذلك.\nوتقول: اللهم اجزه عنا خيرًا كما أحسن إلينا، تقول: اللهم صل على محمد وعلى أزواجه وذريته كما صليت على إبراهيم .. إلى آخره، هكذا، تكثر من الصلاة عليه، عليه الصلاة والسلام، وتدعو له وتثني عليه وتتبع سنته، تحرص على اتباع السنة والاستقامة على دينه والعمل بشرعه.\nأما القراءة له ما شرع الله القراءة له، لا تقرأ للنبي ﷺ، ولكن تصلي عليه وتسلم عليه وتدعو له، تقول: جزاه الله عنا خيرًا، وضاعف الله مثوبته وأكثر حسناته.. إلى غير هذا من الدعوات الطيبة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12806/حكم-قراءة-الفاتحة-بعد-الصلاة-على-روح-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55014.mp3","categories":["البدع والمحدثات","العالم والمتعلم","نصائح وتوجيهات"]},{"id":14386,"question":"في آخر أسئلة هذا السائل يقول: سماحة الشيخ، كيف يكون للرجل المسؤولية تجاه أسرته بتعليم أولاده التعاليم الإسلامية؟ وإذا كانت المرأة جاهلة بالدين هل يجوز له أن يضع اللوم عليها في التربية؟","title":"حكم تعليم المرأة أمور دينها","answer":"الجواب: الواجب عليه أن يعلمها ما تجهل، عليه وعلى أبيها وعلى أخيها أن يعلمها ويبصرها ما تجهل، وعليها أن تتعلم، وأن تحضر مجالس العلم حتى تستفيد وهي متحجبة إذا دعت الحاجة إلى ذلك، تسمع القرآن من نور على الدرب، والتعليم في نور على الدرب، فيه علم عظيم نور على الدرب، فيه تعليم، وفيه سؤالات مفيدة من جماعة من العلماء، فيه محاضرات وندوات طيبة، وعلى زوجها أن يعلمها إذا كان عنده علم، وهكذا أبوها وأخوها وعمها وخالها يعلمونها، وهي تسمع في مجالس العلم تسمع من إذاعة القرآن ما يكون فيها من الخير العظيم، وإذا ذهبت إلى المسجد بإذن زوجها، وسمعت العلم إذا كان فيه محاضرات فيه ندوات، وهي متحجبة، أو تسمع خطبة الجمعة كل هذا خير عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12868/حكم-تعليم-المراة-امور-دينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55210.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":14411,"question":"السائل إبراهيم أبو حامد، يقول في هذا  سماحة الشيخ ما هو واجب المربين والمعلمين تجاه طلابهم؟ وهل هم أمانة يسألون عنها يوم القيامة؟","title":"واجب المربين والمعلمين تجاه طلابهم","answer":"الجواب: نعم، المربي والمعلم يجب عليه أن ينصح للمتعلم، والمربى يجب أن ينصح له ويوجهه إلى الخير، ويتقي الله فيه؛ لأنه أمانة، فالواجب على المربي والمعلم تقوى الله، وأن يجتهد في تربية الأولاد والأيتام والأطفال، وأن يحسن تعليمهم، وأن يتقي الله في ذلك، وأن يعلمهم مما علمه الله بالطريقة الشرعية، ومن ذلك تفقيههم في الصلاة وأمرهم بالصلاة إذا بلغوا سبعًا، وضربهم عليها إذا بلغوا عشرًا، كل هذا مما يجب على الولي وعلى المعلم أن يوجه الطلبة إلى هذا الخير، وإذا كان لم يؤذن له في الضرب يضربهم وليهم، إذا بلغوا عشرًا ولم يصلوا. فالحاصل: أن على الولي وعلى المعلم توجيه الطلبة من الرجال والنساء الطالبات والطلبة، وعليه تعليم الجميع، وتثقيف الجميع في الدين، حتى يتعلموا ما أوجب الله عليهم، وما حرم عليهم، الله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12893/واجب-المربين-والمعلمين-تجاه-طلابهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55308.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14549,"question":"هناك كتيب صغير، باسم (إنا نحن نزلنا الذكر وإنا له لحافظون) يشتمل على بعض السور القرآنية والأدلة بالأحاديث النبوية، مع فضل قراءتهما ومنزلتهما، مثل سورة الملك والواقعة والدخان وياسين والكهف والسجدة، والحاقة، فهل يركز القارئ عليها دون غيرها من السور القرآنية؟","title":"تقييم كتاب (إنا نحن نزلنا الذكر...)","answer":"الجواب: لا، هذا يحتاج إلى نظر؛ لأن كثير من هذه الأحاديث غير صحيح، التي أشار إليها صاحب الكتيب، لا بد ينظر فيها، فما ثبت عن النبي ﷺ أنه كان يستعمله في الليل أو في النهار فعله المؤمن، وما لم يثبت فلا يستحب، يقرأ كبقية القرآن، يقرأ مع القرآن كبقية القرآن.  أما أن يخص سورة، أو آية بشيء فلا إلا بدليل، مثل آية الكرسي بعد الصلاة تستحب، ومثل قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين بعد كل صلاة مستحبة، وتكرر في المغرب والفجر ثلاث مرات بعد الفجر، وبعد المغرب؛ لأنه ثبت عن النبي هذا -عليه الصلاة والسلام-. أما شيء يأتي به الإنسان من نفسه، لا، مثل أن يقول: أريد أكرر سورة كذا، سورة الأعراف، سورة مثلًا الأنعام لا يكرر، إلا بدليل، يقرأها مثل بقية القرآن، إلا ما ثبت فيه الدليل، ما صح عن النبي ﷺ أنه خصه بشيء يخص، وهذا الكتاب يحتاج إلى نظر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13047/تقييم-كتاب-انا-نحن-نزلنا-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48906.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":14556,"question":"هناك كثير من الكتب تروي أحاديث وتقول: إنها عن الرسول ﷺ وتذكر فضائل بعض السور، كالسور التي ذكرها صاحب السؤال، رأيكم في مثل هذا الكتب سماحة الشيخ؟","title":"توجيه حول بعض الكتب التي تروي فضائل السور","answer":"الجواب: الواجب على طالب العلم أنه يبين الصحيح من الضعيف، إذا صنف كتابًا يبين، أما أنه يذكر الغث والسمين والصحيح والضعيف ولا يبين، ما يستقيم، لا بد من بيان؛ لأن العامة لا يعرفون الصحيح من السقيم، فلا بد في حق المؤلف أن يحسن في جمعه، ويبين الصحيح، ويترك الضعيف، حتى يستفيد المؤمن من كتابه، وينتفع المؤمن بكتابه، ويستريح من التعب في الضعيف. المقصود: أن أهل العلم يجب على طالب العلم، بل يشرع له لا الوجوب لا يجب، لكن يشرع له أن يعتني بالصحيح حتى يكون العامة على بصيرة، ولا يجعل لهم الضعيف والصحيح، فإنهم لا يميزون، لكن أهل العلم جمهور أهل العلم ذكروا إنه يجوز ذكر الضعيف للترغيب والترهيب، كما فعل صاحب الترغيب والترهيب المنذري -رحمه الله-، ذكر جملة من أحاديث الترغيب والترهيب على هذه القاعدة، أنه من باب الترغيب والترهيب، وذكر غيره من أهل العلم، مثل صاحب بلوغ المرام، والمنتقى وغيرهم ذكروا أحاديث ضعيفة، للفائدة لتعرف أو ليضمها طالب العلم إلى غيرها مما يتقوى بها. فالحاصل: أنه ينبغي لمن ألف كتابًا أنه يوضح الصحيح، ولا سيما الكتب التي فيها بيان خصوصية بعض السور، أو خصوصية بعض الأذكار، يبين أنها صحيحة، ثبت عن النبي ﷺ أنه قال كذا في كذا، حتى يكون المطالع للكتاب على بينة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13054/توجيه-حول-بعض-الكتب-التي-تروي-فضاىل-السور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48907.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14642,"question":"يسأل -سماحة الشيخ- عن كتاب الروح لـابن القيم؟","title":"توجيه عن كتاب الروح لابن القيم","answer":"الجواب: كتاب مفيد عظيم الفائدة، فيه علم جم، ومسائل مفيدة، وفيه بعض الأشياء المرجوحة، طالب العلم إذا قرأه يعرف الراجح من المرجوح، ولكنه كتاب مفيد جدًا في بابه، وفيه علم كثير، وتحقيقات كثيرة، ينتفع بها طالب العلم، ولكن ليس كل ما في الكتاب صحيحًا؛ لأن كل عالم يخطئ ويصيب، وكل عالم يؤخذ من قوله ويترك إلا الرسول -عليه الصلاة والسلام-، فهناك مرائي وأشياء ذكرها قد لا يتابع عليها، وكذلك ترجيحه لبعض المسائل قد لا يتابع عليه  ورحمه، ولكن هذا يحتاج إلى علم. فالذي يراجع الكتاب، ويقرأ الكتاب إذا كان ذا علم، وذا بصيرة، سوف يفهم ما يقوم عليه الدليل، وما لا يقوم عليه الدليل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13152/توجيه-عن-كتاب-الروح-لابن-القيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62708.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14729,"question":"تسأل أختنا عن قراءة المجلات، هل هي حرام؟علمًا أنني أقضي معظم الوقت في قراءة القرآن الكريم.","title":"حكم قراءة المجلات","answer":"الجواب: قد أحسنت في قراءة القرآن، فهو كتاب الله فيه الهدى والنور، والعناية بقراءته من أعظم القربات، ومن أفضل الطاعات، قال الله تعالى: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ[الإسراء:9] ويقول سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44] ويقول الرسول ﷺ: اقرؤوا هذا القرآن فإنه يأتي شفيعًا لأصحابه يوم القيامة ويقول ﷺ: من قرأ حرفًا من القرآن فله حسنة والحسنة بعشرة أمثالها في أحاديث كثيرة، فلقد أحسنت جدًا. أما المجلات ففيها تفصيل: المجلات الطيبة الدينية المفيدة يشرع قراءتها، والاستفادة منها، مثل الكتب، مثل كتب العلم المفيدة: كتب الحديث الشريف، كتب العقيدة الصحيحة، كتب الفقه الإسلامي.  أما المجلات الخليعة والصحف الخليعة فلا تجوز قراءتها، ولا الاشتغال بها، بل يجب أن تحارب، وأن يحذر منها؛ لعظم شرها وضررها.  أسأل الله أن يوفقك وسائر المسلمين لما فيه رضاه؛ ولما فيه الصلاح والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13226/حكم-قراءة-المجلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63713.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":14745,"question":"أريد أن أسأل عن التوسع في عدد حلقات طلب العلم في المساجد سماحة الشيخ، في القرى، في المدن الصغيرة، وفي المدن الكبيرة أيضًا.","title":"مشروعية التوسع في حلقات العلم في المدن","answer":"الجواب: ينبغي إذا تيسر العلماء، ينبغي التوسع في ذلك، ولو كان في كل مسجد؛ لأن كل مسجد جماعته في حاجة إلى التعلم والفائدة، فإذا وجد في البلد علماء فالمشروع لهم أن يعلموا الناس من طريق الحلقات، ومن طريق الدروس بعد العصر، أو بعد المغرب، أو بعد العشاء؛ حتى يستفيدوا، وكلٌ على حسب طاقته، الذي يستطيع الحلقة يقيم الحلقة، والذي لا يستطيعها ولو بالدرس بعد صلاة العصر أو غيرها، ولو درسًا مختصرًا؛ فإنه مع الدوام ينفع الله به ولو قليلًا، والذي لا يستطيع يتوسط في حق من يستطيع، ويشير عليه، وينصحه أن يقوم بهذا الدرس، أو بهذه الحلقة، إذا كان أهلًا لذلك، عنده من علم الكتاب والسنة ما يؤهله لذلك، وإذا كان في البلد عالمان، صار كل واحد في ناحية من البلد، وإذا كانوا ثلاثة هكذا، أو أربعة، أو أكثر، كلٌ إنسان يكون في حيٍ من الأحياء، وفي مسجدٍ واسع، حتى يعلم الناس، وحتى يفقه الناس، نعم. المقدم: جزاكم الله خيرًا.\nالواقع هذا الموضوع يحتاج إلى مزيدٍ من الطرح، ومزيدٍ من العناية، ولا سيما وأن الناس -سماحة الشيخ- يشكون أحيانًا كيف يقضون أوقات فراغهم؟ الشيخ: لا شك أن هذا موضوعٌ جديرٌ بالعناية، من الدولة، ومن العلماء، ومن الناس، فعلى الدولة أن تقوم بذلك، وأن تؤكد على العلماء أن يقوموا بهذا، ولو بالإلزام، ولو بفرض مرتبات لمن ليس له راتب يقوم بحاله، ويحتاج إلى راتب حتى يقوم بهذه المهمة، في القرى والأمصار، وعلى العلماء فيما بينهم أن يقوموا بهذا الواجب حسب طاقتهم، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] في الأوقات التي يستطيعونها، ولو في وقتٍ قصير، فإن التكرار ينفع الله به، ولو كانت المدة غير طويلة، في الوقت المناسب، بعد العصر، أو بعد المغرب، أو بعد العشاء، أو بعد الفجر، فإن الجلسة ولو كانت غير طويلة، بالتعليم والتوجيه ينفع الله بها الناس، عملاً بقوله تعالى: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، نعم. المقدم: جزاكم الله خيرًا، آمل أن نتمكن من العودة إلى هذا الموضوع في حلقاتٍ قادمة سماحة الشيخ.\nالشيخ: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/13298/مشروعية-التوسع-في-حلقات-العلم-في-المدن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64110.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14772,"question":"سماحة الشيخ التجربة لها تأثير، نحن في الرياض نعيش هذه النعمة، ولله الحمد، ويتوجها حضوركم باستمرار، كيف تصورون هذه التجربة للإخوة المسلمين حتى يستفيدوا منها؟","title":"نصيحة بالحرص على التعليم وحلق العلم","answer":"الجواب: لا ريب أن حلقات العلم لها شأنٌ عظيم، وكان الرسول ﷺ يفعلها، ويجلس لأصحابه يعلمهم، ويذكرهم بين وقتٍ وآخر، ويتحلقون حوله، ويجتمعون ، وهكذا الصحابة بعده كانوا يستعملون الحلقات للعلم والتعليم، وهكذا العلماء إلى زماننا هذا. فالفائدة من الحلقات عظيمة، فطالب العلم يحضر ويستمع، والعامة يحضرون، ويستمعون، وطالب العلم يحضر بكتابه الذي فيه الدرس، حتى يستفيد، وحتى يكتب بعض الفوائد؛ ولهذا فائدة عظيمة، فإنه إذا استمع وكتب ما قد يفوته لولا الكتابة، يكون هذا عملًا طيبًا، وهكذا العامة يحضرون ويستفيدون، ويسألون عما أشكل عليهم، كل هذا مما يحبه الله، وفي الحديث يقول ﷺ: إذا مررتم برياض الجنة فارتعوا قالوا: يا رسول الله، وما رياض الجنة؟ قال: حلق الذكر وفي الصحيحين أنه كان -عليه الصلاة والسلام- كان ذات يوم في المسجد، وحوله أصحابه يذكرهم -عليه الصلاة والسلام-، فدخل ثلاثة والنبي ﷺ يعلم الناس وحوله الحلقة، فجاء أحدهم فدخل في الحلقة، والثاني جلس خلف الحلقة، والثالث خرج، فلما فرغ النبي من حديثه -عليه الصلاة والسلام-، قال: ألا أنبئكم بشأن الثلاثة؟ قالوا: بلى يا رسول الله، قال: أما أحدهم فآوى، فآواه الله وهو الذي دخل في الحلقة  وأما الثاني فاستحيا، فاستحيا الله منه، وأما الثالث فأعرض، فأعرض الله عنه.\nالمقدم: الذي استحيا الذي بقي في...\nالشيخ: الذي خلف الحلقة، ما زاحم، ولا دخل في الحلقة، وأما الثالث: فأعرض، فأعرض الله عنه وهذا وعيد شديد، يفيد الحذر من الإعراض عن حلقات العلم، وعن طلب العلم.  وفي الصحيحين عن معاوية  عن النبي -عليه الصلاة والسلام- أنه قال: من يرد الله به خيرًا يفقهه في الدين وهذا حديثٌ عظيم، يدل على أن من علامات السعادة، وأن الله أراد بالعبد خيرًا أن يفقه في الدين، وأن يتبصر في الدين، كما يدل على أن من علامات الهلاك، وعدم الخير، أن لا يتفقه في الدين، وأن يعرض، ويغفل. وفي صحيح مسلم عن النبي ﷺ أنه قال: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة فطلب العلم من أفضل القربات، ومن أهم المهمات، فنصيحتي لكل مسلم، ولكل مسلمة الحرص على التفقه في الدين، والتعلم، وعلى طلب العلم بكل وسيلة، ومن ذلك سماع هذا البرنامج: نور على الدرب، سماعه من طلب العلم، ومن العناية بالعلم، فهو برنامج مفيد، يصل إليك وأنت على فراشك، وفي مجلسك، وفي سيارتك، فنصيحتي لكل مسلم ولكل مسلمة العناية بهذا البرنامج للاستفادة. وهكذا نصيحتي للجميع سؤال أهل العلم عما أشكل، وعدم الحياء، بالبرقية، بالهاتف، بالمكاتبة، بالمشافهة إذا كان طالب العلم قريبًا، ولا ينبغي لأحد أن يسكت على الجهل، لا رجل، ولا امرأة، الواجب السؤال عما أشكل، قال الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنتُمْ لا تَعْلَمُونَ [الأنبياء:7] ويروى عنه -عليه الصلاة والسلام- أنه قال لقومٍ أفتوا بغير علم: ألا سألوا إذ لم يعلموا، إنما شفاء العي السؤال. فالنصيحة أكررها: الحرص على طلب العلم، والتفقه في الدين، من طريق المكاتبة، من طريق الهاتف -التلفون- من طريق سماع هذا البرنامج في كل مكان، من طريق حضور حلقات العلم في المساجد، إلى غير ذلك، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13296/نصيحة-بالحرص-على-التعليم-وحلق-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64109.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14777,"question":"أخونا يسأل ويقول: هل حلقات العلم بعد العشاء تعتبر قيام ليل؟","title":"هل حلقات العلم بعد العشاء من قيام الليل؟","answer":"الجواب: الحلقات في العلم بعد العشاء قربة وطاعة، ولكنها لا تغني عن قيام الليل، ولكنها أفضل من قيام الليل. المقدم: أفضل؟ الشيخ: طلب العلم أفضل من قيام الليل، كونه يطلب العلم، ولو فاته قيام الليل، أفضل له من قيام الليل، مع بقائه في الجهل، فحلقات العلم أمرها عظيم، وفوائدها كبيرة، لا تعدلها بقية التطوعات، لكن إذا تيسر له الجمع بين الأمرين، يحضر حلقات العلم، أو ما تيسر منها، ويقوم من الليل ما تيسر، ولو بثلاث ركعات، أو خمس ركعات، كان هذا أفضل، جمعًا بين المصلحتين، كفعل النبي ﷺ، وفعل الصحابة -رضي الله عنهم-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13292/هل-حلقات-العلم-بعد-العشاء-من-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64107.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14914,"question":"نبدأ برسالة محمد بن ناصر الصالح من القصيم، يقول محمد في رسالته: سمعنا في حلقة من حلقات البرنامج (برنامج نور على الدرب) وأعتقد أنها الماضية لفضيلة الشيخ عبدالعزيز بن عبدالله بن باز، وكثير من هذه الأسئلة كان من المفروض للحجاج أن يرسلوها أو للمسلمين أن يرسلوها قبل أن يتلبسوا بالعبادة، لا أن يرسلوها بعدما يتلبسون بالعبادة، ويخطؤون، فما موقف الإسلام من ذلك؟وما رأي الشيخ جزاه الله عنا خيرًا؟","title":"توجيه بأن يتفقه المسلم قبل أن يتلبس بالعبادة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: هذا هو الواجب، الواجب على المسلم أن يسأل قبل التلبس بالعبادة يسأل عن أمور دينه، ويتفقه في دينه قبل أن يتلبس بالعبادة، يسأل عن أمور الحج قبل أن يحرم، يسأل عن أمور الصلاة قبل أن يشرع في الصلاة، يسأل عن أمور الصيام قبل الشروع في الصيام إذا تيسر ذلك، يعني: لا يغفل، بل يبادر ويسارع إلى السؤال قبل الشغل في العبادات، لكن لو قدر أنه فرط وتساهل، ولم يسأل إلا بعد ذلك فلا حرج، المهم أنه تعلم، مثلما قال النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة وقال -عليه الصلاة والسلام-: من يرد الله به خيرًا يفقهه في الدين. فالواجب على أهل الإسلام أن يتعلموا ويتفقهوا قبل أن يقعوا في الخطأ في عباداتهم، في صلاتهم، في صومهم، في حجهم، في جهادهم، في جميع أمورهم، لكن لو قدر أنه غفل وسأل بعدما صلى يعني عما جرى له في صلاته، أو عما جرى في صيامه، كل هذا طلب علم، كله واجب متعين، الله قال: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] قبل العبادة وبعدها، قبل التلبس، وبعد التلبس، لكن كونه يتأهب، كونه يسأل قبل أن يتلبس، كونه يعد نفسه إعدادًا كاملًا، حتى إذا شرع في العبادة، إذا هو يؤديها عن علم وعن بصيرة، هذا هو الواجب، وهذا هو الطريق السليم، نعم.","link":"https://binbaz.org.sa/fatwas/13413/توجيه-بان-يتفقه-المسلم-قبل-ان-يتلبس-بالعبادة","audio":"","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14974,"question":"هذا سائل للبرنامج أرسل الحقيقة بمجموعة من الأسئلة، يبدأ هذه الصفحة بالسؤال الأول، ويقول: هل يجوز للعالم أن يفتي ويستدل بالأحاديث الضعيفة؟","title":"حكم الاستدلال بالأحاديث الضعيفة","answer":"الجواب: نعم، يجوز للعالم أن يفتي بالأدلة الشرعية، وإذا استشهد بالأحاديث الضعيفة التي تعددت طرقها، وصارت من قبيل الحسن لغيره فلا بأس، لكن عليه أن يجتهد، ويتحرى الحق بالدليل من القرآن والسنة، وإذا استشهد بعض الأحيان ببعض الأحاديث الضعيفة التي ليست موضوعة، بل ضعيفة غير موضوعة فلا بأس، يقول الحافظ العراقي -رحمه الله- في ألفيته: وسهلوا -يعني: أهل العلم، أهل الحديث-:","link":"https://binbaz.org.sa/fatwas/13474/حكم-الاستدلال-بالاحاديث-الضعيفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56217.mp3","categories":["الحديث وعلومه","العالم والمتعلم"]},{"id":15065,"question":"بعض المعلمات -هداهن الله- لا يبالين بتحضير الدروس في دفاترهن، أي: دفتر التحضير، فما حكم التهاون بتحضير الدروس؟ علمًا بأننا لا نستفيد منها شيئًا أثناء شرح الدرس، أفتونا مأجورين.","title":"حكم تهاون المعلمات في تحضير الدروس","answer":"الجواب: الواجب عليها أن تعتني بهذا، وأن تحضر الدرس؛ حتى يستفيد الطلبة والطالبات إن كانت معلمة، يستفيد منها الطالبات، وإن كان معلمًا كذلك، الواجب العناية بالتحضير ومراجعة الدرس، ومراجعة ما قد يشكل، ومراجعة الدليل الذي فيه؛ حتى يعرف صحته من الأحاديث، يعتني ولا يتساهل في هذا الأمر؛ حتى يستفيد منه الطلبة والطالبات، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13552/حكم-تهاون-المعلمات-في-تحضير-الدروس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56314.mp3","categories":["قضايا المرأة","العالم والمتعلم"]},{"id":15070,"question":"سماحة الشيخ ما هي أشهر كتب التفسير التي تنصحون المسلم بالرجوع إليها، والتزود منها؟","title":"أهم كتب التفسير التي ينصح بقراءتها","answer":"الجواب: أشهر كتب التفسير وأحسنها: تفسير ابن جرير -رحمه الله-، تفسير عظيم ومفيد، تفسير ابن أبي حاتم، تفسير الحافظ ابن كثير -رحمه الله-، هذه الكتب أشهر التفاسير؛ وكذلك البغوي -رحمه الله- تفسير عظيم، تفسيره تفسير عظيم، فنوصي بها كثيرًا، فإنها من الكتب العظيمة المعتنية بالكتاب والسنة. وهناك كتب أخرى مفيدة، مثل: تفسير الشوكاني، وتفسير الشيخ صديق، وتفاسير أخرى، لكن هذه الكتب الأولى هي الإمام في هذا المقام، تفسير ابن جرير -رحمه الله-، تفسير ابن أبي حاتم، والبغوي وابن كثير، هذه الكتب لها الأهمية والتقدمة، نعم. والكل يخطئ ويصيب ما أحد معصوم، قد يقع في بعضها أشياء من الخطأ والغلط، ولكن المعول على الأدلة الشرعية، ليس ابن جرير، ولا ابن كثير، ولا البغوي، ولا ابن أبي حاتم ولا غيرهم، ليس واحد معصومًا من الخطأ، لكن على طالب العلم، وعلى من يراجع كتب التفسير أن يعتني بالأدلة الشرعية، وإذا أشكل عليه شيء يعرض ذلك على القرآن العظيم، والسنة المطهرة الصحيحة، أو يسأل أهل العلم إن كان ما عنده علم، يسأل أهل العلم من أهل السنة والجماعة من علماء السنة، يسألهم عما أشكل عليه، نعم. ومن كتب التفسير المهمة كما تقدم، تفسير أيضًا الشنقيطي -رحمه الله-، الشيخ: محمد أمين الشنقيطي أيضًا هو من التفاسير المهمة، وقد اعتنى به -رحمه الله-، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13561/اهم-كتب-التفسير-التي-ينصح-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56402.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":15144,"question":"السؤال الآن الذي بين أيدينا، وردنا من المستمع المرسل (أ. م. س) يقول فيه: هل يجوز الغش في الامتحان؛ نظرًا لأننا بدأنا سنةً دراسية جديدة؟وفقكم الله، وأثابكم.","title":"ما حكم الغش في الامتحانات؟","answer":"الجواب: الغش في الامتحان لا يجوز، هذا غلط؛ لأنه يتظاهر بأنه ناجح وهو غير ناجح؛ فيضر المسلمين.  ثم أيضًا هو خيانة للأمانة، ثم قد يفوق غيره بالكذب، فهذا كله لا يجوز، الغش في الامتحان مطلقًا لا يجوز، لا في مادة أساسية، ولا في مادة أخرى فرعية، ولا في مادة اللغة، ولا في مادة الدين، ولا في مادة اللغة الإنجليزية، ولا غير ذلك، لا يجوز الغش أبدًا، بل يجب أن يجتهد، ويحرص حتى ينجح، وليس له أن يغش.  وليس للأساتذة أن يتساهلوا معه في هذا، أو يسمحوا له بالغش، كما يفعل بعض الناس فيما بلغنا، ليس للأستاذ ذلك، بل يجب أن ينصح الطالب بأن يجتهد حتى ينجح في الاختبار نجاحًا صحيحًا لا مغشوشًا، والله المستعان.","link":"https://binbaz.org.sa/fatwas/13654/ما-حكم-الغش-في-الامتحانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65807.mp3","categories":["الأخلاق المذمومة","العالم والمتعلم"]},{"id":15313,"question":"في آخر أسئلة هذه السائلة تقول: هل يجوز لنا أن نقرأ في كتب الأديان الأخرى غير الإسلام من باب حب الاستطلاع والتعرف على الديانات الأخرى؟","title":"حكم القراءة في كتب الأديان","answer":"الجواب: لا ينبغي لا، لا ينبغي قراءة التوراة، ولا الإنجيل، ولا غيرها؛ لأنها قد تورث شكًا وشبهة، والرسول روي عنه ﷺ أنه لما رأى عمر يقرأ في شيء من التوراة، قال: أفي شك يا ابن الخطاب؟ لقد جئتكم بها بيضاء نقية، لو كان موسى حيًا ما وسعه إلا اتباعي. المقصود: أنه لا ينبغي للمسلم أن يقرأ الكتب الأخرى من التوراة والإنجيل وغيرها، إلا من تدعو الحاجة إلى قراءته كالعلماء الذين يريدون أن يردوا على اليهود والنصارى من كتبهم، فإذا دعت الحاجة للعالم الذي يرد عليهم، ويبين أباطيلهم أن يراجع كتبهم حتى يرد عليهم منها فلا بأس عند الحاجة لأهل العلم والبصيرة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13812/حكم-القراءة-في-كتب-الاديان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56608.mp3","categories":["مسائل متفرقة في العقيدة","العالم والمتعلم"]},{"id":15346,"question":"هل من توجيه كريم -سماحة الشيخ- للذين قد يؤدون مناسك الحج سؤال أهل العلم والعلماء وأهل الذكر؟","title":"توجيه للحجاج بسؤال أهل العلم عما يجهلونه","answer":"الجواب: نعم، الواجب على كل مؤمن ومؤمنة السؤال عما أشكل عليه في الحج وغيره، في حجه، في صلاته، في زكاته، في صيامه، في معاملاته يسأل، الله يقول سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] ويروى عنه -عليه الصلاة والسلام- أنه قال: ألا سألوا إذ لم يعلموا؟ إنما شفاء العي السؤال فالواجب على من جهل أن يسأل في صلاته، في صومه، في حجه، في جهاده، في زكاته، في معاملاته، لا يجوز السكوت والسير على الجهل، بل يجب أن يسأل أهل العلم، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13847/توجيه-للحجاج-بسوال-اهل-العلم-عما-يجهلونه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56619.mp3","categories":["مسائل متفرقة في الحج والعمرة","العالم والمتعلم"]},{"id":15381,"question":"هذه السائلة أم حسين، أرسلت بمجموعة من الأسئلة تقول: سماحة الشيخ عبدالعزيز، يقوم بعض الآباء والأمهات والإخوة من باب الحرص والخوف على أبنائهم وبناتهم بالاطلاع والتفتيش على ما لدى أبنائهم من أشياء خاصة، بمعنى: التفتيش والبحث في أمتعتهم وكتبهم وحقائبهم من أجل معرفة أحوالهم وتصرفاتهم وسلوكهم؛ خوفًا عليهم من الفتن وأصحاب السوء، وما إلى ذلك، نسأل الله العافية، فهل يدخل ذلك ضمن الأشياء المحرمة شرعًا؟","title":"حكم تفتيش ما يخص الأبناء لأجل الحرص عليهم","answer":"الجواب: إذا كان هناك أسباب تدعو إلى هذا، فلا بأس من باب الحيطة، وإلا فلا ينبغي سوء الظن بهم. أما إذا كان هناك أسباب يخاف منها، فلا بأس بالتفتيش عند الحاجة؛ خوفًا عليهم من جلساء السوء، ومن دعاة الباطل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13885/حكم-تفتيش-ما-يخص-الابناء-لاجل-الحرص-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56712.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":15434,"question":"سماحة الشيخ -حفظكم الله-: ما هي الكتب التي ترشدون المسلمين في قراءتها الكتب؟ والوسائل التي تجعل المسلم على عقيدة سليمة وصحيحة؟","title":"ما الكتب التي ترشدون المسلمين بقراءتها؟","answer":"الجواب: أعظمها القرآن العظيم، يتدبر القرآن فيه الهدى والنور، إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] فالواجب على طالب العلم، وعلى حامل القرآن أن يتدبره ويتعقله، وإذا كان لا يقرأ يستمع يستفيد من القارئ، ومن إذاعة القرآن الكريم؛ حتى يستفيد من كلام الله، فيه الهدى والدعوة إلى مكارم الأخلاق، إلى توحيد الله والإخلاص له، إلى المحافظة على الصلاة، إلى الصدقة، إلى الإكثار من الذكر -ذكر الله-، الإكثار من الاستغفار، التحذير من المعاصي، القرآن فيه الهدى والنور. وهكذا أحاديث الرسول ﷺ يعتني بها، يحفظ ما تيسر منها، يسمعها، مثل: رياض الصالحين، الترغيب والترهيب، غيرها من كتب الحديث التي في أيدي المسلمين حتى يستفيد منها، وهكذا يسأل أهل العلم عما أشكل عليه، لا يسكت يسأل أهل العلم، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] يسأل العلماء عما أشكل عليه، ثم يعمل بما أوجب الله، وينتهي عما حرم الله، نعم.","link":"https://binbaz.org.sa/fatwas/13953/ما-الكتب-التي-ترشدون-المسلمين-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56804.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15535,"question":"هذا سائل للبرنامج يقول: ما نصيحتكم يا سماحة الشيخ، لطالب العلم المبتدئ من حيث حفظ المتون؟ مع العلم بأنه يحفظ القرآن كاملًا، والحمد لله.","title":"المتون التي ينصح طالب العلم بحفظها","answer":"الجواب: نصيحتنا له يحفظ المتون المهمة، مثل: كتاب التوحيد، كشف الشبهات، ثلاثة الأصول، العقيدة الواسطية لشيخ الإسلام ابن تيمية، والكتب الأولى للشيخ محمد بن عبد الوهاب: كتاب التوحيد كتاب عظيم، ثلاثة الأصول مع القواعد الأربع، فيها فائدة للشيخ -رحمه الله-، كشف الشبهات التي يتشبث بها عباد القبور، كونه يحفظها طيب، حتى يعرف الشبهات التي يشبه بها عباد القبور، والرد عليها، كذلك العقيدة الواسطية في بيان عقيدة أهل السنة والجماعة، كتاب مختصر جليل طيب. وفي الحديث: عمدة الحديث، بلوغ المرام كتابان جيدان، والأربعين النووية، وتتمتها لابن رجب خمسون حديثًا مهمة من جوامع الكلم، ننصح بحفظ هذه. وفي الفقه: مثل زاد المستقنع، كتاب جيد في الفقه، ومثل عمدة الفقه للموفق -رحمه الله- صاحب المغني، كتابان مختصران في الفقه جيدان، نعم.","link":"https://binbaz.org.sa/fatwas/14078/المتون-التي-ينصح-طالب-العلم-بحفظها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69117.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15536,"question":"سماحة الشيخ، ترديد كلمة مثلًا المرأة تقول لابنها: يا حياتي، يا عمري، ما حكم ترديد مثل هذه العبارات؟","title":"حكم قول الأم لابنها: يا حياتي .. يا عمري","answer":"الجواب: ما أعلم في هذا شيء، من اللطف، والعطف عليه، هذه كلمات ما أعلم فيها شيئًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14073/حكم-قول-الام-لابنها-يا-حياتي-يا-عمري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56926.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":15563,"question":"ما هي أفضل الكتب الإسلامية النافعة التي ترشدوننا -سماحة الشيخ- في تربية الأولاد تربية إسلامية؟ وما هو النهج الصحيح في تربيتهم؟","title":"ما النهج الصحيح في تربية الأولاد؟","answer":"الجواب: النهج الصحيح أن يعلم الأولاد دينهم، حتى قال ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فيعلم دينه، ويعلم التوحيد، ويعلم الصلاة، وهكذا، حتى إذا بلغ السبع يؤمر بها، وإذا بلغ عشر يضرب عليها إذا تخلف، والبنت كذلك، ويعلم الآداب الشرعية في البيت ومع والديه، ومع إخوانه ومع أهل البيت يعلم ولو صغير حتى يستفيد، فالصغير قد يتلقن وينفع، يعلمه يسلم، يعلمه يحترم أمه، يحترم أباه، يعلمونه حتى لا يعبث يكسر شيء، أو يجلب أشياء، أو يفسد أشياء كالبول في الطعام، أو صب التراب على الطعام، أو ما أشبه ذلك، مما قد يقع، يعلم كل ما ينفعه، يعلمه أبوه، ويعلمه أمه، ويعلمه غيرهم من إخوانه الكبار وخالاته وعماته، ونحو ذلك. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14099/ما-النهج-الصحيح-في-تربية-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57004.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":15612,"question":"تساهل بعض الناس -سماحة الشيخ- في العبادات، ومن ثم يسألون بعد ذلك، هل لكم توجيه حول ذلك؟","title":"توجيه للمسلم بالاهتمام بتعلم أحكام العبادات","answer":"الجواب: الواجب على المؤمن أن يهتم بعبادته، الحج، والعمرة، والصلاة وغيرها، الواجب عليه أن يهتم بذلك، وأن يعتني وأن يتعلم حتى يؤدي الصلاة على وجهها، ويؤدي الصوم على وجهه، والحج على وجهه، والعمرة على وجهها، يجب أن يتعلم ويتفقه؛ لأن الله أوجب عليه الصلاة، وأوجب عليه صيام رمضان، وأوجب عليه الحج، وأوجب عليه العمرة؛ فلا بد أن يتعلم ما يؤدي به هذا الفرض، ولا يتساهل في هذا، وما لا يتم الواجب إلا به فهو واجب، وقد قال ﷺ: من يرد الله به خيرًا يفقهه في الدين فالتفقه في الدين من علامات أن الله أراد بالعبد خيرًا، والإعراض والغفلة من علامات الشر، ونسأل الله العافية. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14148/توجيه-للمسلم-بالاهتمام-بتعلم-احكام-العبادات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57021.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":15653,"question":"هذه عدة أسئلة من الأخت المستمعة (م. هـ. أ) من مكة المكرمة، سؤالها الأول تقول: هناك بعض الكتب الخاصة بالأذكار والأدعية الواردة عن رسول الله ﷺ منها مثلًا: كتاب الدعاء المستجاب، وقد وجدت فيه أدعية لكل يوم من أيام الأسبوع، فهناك أدعية وأذكار ليوم الجمعة، وأخرى ليوم السبت.. وهكذا، فهل الالتزام بهذه الأذكار بدعة أم هو من السنة؟","title":"ما صحة ما تضمنه كتاب الدعاء المستجاب؟","answer":"الجواب:  هذا كتاب غير معتمد، وصاحبه حاطب ليل، يجمع الغث والسمين، والصحيح والضعيف والموضوع، فلا يعتمد عليه، ولا يجوز أن يخصص أي يوم أو أي ليلة بشيء إلا بدليل عن المعصوم -عليه الصلاة والسلام-. فالكتاب هذا لا يعتمد عليه، ولكن تراجع الكتب الأخرى، فما ثبت عن رسول الله -عليه الصلاة والسلام- من أذكار الصباح أو المساء أو أدعية تقال في الصباح أو المساء، شرع ذلك وما لا فلا.  وأما هذا الكتاب وهو الدعاء المستجاب فلا يعتمد عليه؛ لأن صاحبه ليس بأهل لذلك؛ ولأنه يجمع بين الغث والسمين، والصحيح والضعيف والموضوع، فلا يعتمد على هذا الكتاب، نعم.","link":"https://binbaz.org.sa/fatwas/14196/ما-صحة-ما-تضمنه-كتاب-الدعاء-المستجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69902.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15734,"question":"سماحة الشيخ، هذه السائلة أم خالد من البحرين، تقول: سماحة الشيخ، أود أن أستفسر منكم عن الكتب؛ فأنا -ولله الحمد- شابة ملتزمة، أود أن أقرأ في العقيدة؛ فما هي الكتب التي تنصحونني أولًا في العقيدة؟ وهذا هو سؤالي الأول.","title":"الكتب التي ينصح بها في العقيدة وغيرها","answer":"الجواب: كتاب ثلاثة الأصول للشيخ محمد بن عبد الوهاب، وأربع القواعد، كتاب التوحيد له -رحمه الله-، وكشف الشبهات؛ هذه مختصرات طيبة، والعقيدة الواسطية لشيخ الإسلام ابن تيمية هذه ننصحك بحفظها طيبة. وفي الحديث الأربعين النووية؛ لأنها مختصرة، اثنين وأربعين حديث، معها ثمانية ابن رجب الجميع خمسون من جوامع الكلم، نوصيك بحفظها، وإذا تيسر أن تحفظي عمدة الحديث لشيخ عبد الغني بن سرور المقدسي، طيب، أو بلوغ المرام للحافظ ابن حجر، طيب. وفي الفقه مثل زاد المستقنع، أو دليل الطالب، أو عمدة الفقه للموفق، كتب مفيدة نافعة في الفقه، يستعان بها على معرفة المسائل حتى يقام عليها الدليل، نعم. المقدم: وفي الفقه يا سماحة الشيخ.\nالشيخ: زاد المستقنع، وهو للحجاوي، أو عمدة الفقه للموفق بن قدامة، أو دليل الطالب، أو غيرها من الكتب الطيبة الصغيرة المفيدة في الفقه.\nالمقدم: والتفسير يا سماحة الشيخ، حفظكم الله. الشيخ: التفسير نوصي بمراجعة تفسير ابن كثير، تفسير طيب مفيد، وابن جرير، والبغوي، تفسير ابن سعدي، تفسير الشنقيطي -رحمة الله عليهم-، الجلالين مفيد، لكن فيه بعض الأغلاط، إذا كان طالب العلم يفهمها لا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/14311/الكتب-التي-ينصح-بها-في-العقيدة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57418.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15816,"question":"القضية هامة سماحة الشيخ كما تقدرون -جزاكم الله خيرًا-، هل تنصحون إخوتنا المستمعين بقراءة كتب معينة كيما يكونوا على العقيدة السليمة الصحيحة؟","title":"الحث على قراءة الكتب النافعة لتصحيح العقيدة","answer":"الجواب: نعم، ننصح الجميع بقراءة القرآن، هو أصدق كتاب، وأعظم كتاب، وأنفع كتاب، وهو كلام الله ، ننصح جميع المسلمين من الرجال والنساء في كل مكان أن يعتنوا بالقرآن، وأن يكثروا من تلاوته بالتدبر والتعقل، وإذا تيسر حفظه فهو نعمة عظيمة، يقول الله : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ[ص:29] ويقول سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ[الإسراء:9] يعني: للطريقة التي هي أشد الطرق وأقومها وأهداها، ويقول سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44] ويقول سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ[النحل:89].  فالقرآن العظيم هو أصل كل خير، وهو الصراط المستقيم، وهو الذي يهدي به الله من اتبع رضوانه سبل السلام، فالواجب على أهل الإسلام أن يعتنوا به، ويتدبروه، ويتعقلوه، وأن يوضحوا للناس معانيه، على العلماء أن يوضحوا للناس معانيه حتى يتفقهوا في ذلك، وحتى يستقيموا على ذلك. كما ننصح أيضًا العلماء، وطلبة العلم بقراءة التفاسير المأمونة الطيبة كتفسير ابن جرير، وتفسير ابن كثير والبغوي وأشباهها حتى يعلموا الناس الخير، وحتى يرشدوهم إلى ما قد يخفى عليهم من كتاب الله، فطالب العلم إذا أشكل عليه شيء من القرآن يراجع كتب التفسير المعتمدة حتى يستفيد، وإذا كان عاميًا يسأل أهل العلم الذين عنده، أو في بلاد أخرى بالمكاتبة، أو من طريق الهاتف -التلفون- يسألهم عما أشكل عليه. فالقرآن هو الهادي إلى الصراط المستقيم، هو أصدق الكتب وأنفعها وأعظمها، وهو كتاب الله ، فالواجب تدبره وتعقله، والعمل بما فيه. ثم سنة الرسول ﷺ فيها الهدى والنور، فيها بيان ما في كتاب الله، فيها الدعوة إلى كل خير، فالرسول ﷺ هو المبين عن الله، والدال على كل خير -عليه الصلاة والسلام-، فعلى المسلمين الاعتصام بكتاب الله، وسنة الرسول ﷺ والدعوة إليهما، والتبشير بهما، وبيان معانيهما، على العلماء أن يبينوا ذلك، وأن يوضحوا للعامة ما يجب عليهم، وما يخفى عليهم، حتى يكون الجميع على بصيرة. ومن ذلك كتب أهل السنة والجماعة تفيد وتعين مثل كتب السلف الصالح؛ البخاري، ومسلم، وسنن أبي داود، والترمذي، والنسائي، وابن ماجه، وسنن الدارمي، ومسند أحمد، كتب مفيدة يعلمها العلماء، ويستفيد العلماء منها، وهكذا كتب أهل السنة بعدهم مثل شيخ الإسلام ابن تيمية، ابن القيم، ابن كثير؛ لأن كتبهم مفيدة عظيمة جيدة. ومثل كتب أئمة الدعوة في نجد في القرن الثاني عشر الشيخ محمد بن عبد الوهاب، وأتباعه من العلماء الذين دعوا إلى الله، ونشروا التوحيد، ونشروا السنة، في وقت الغربة، في القرن الثاني عشر وما بعده، كتبهم عظيمة ومفيدة، ومنها كتاب التوحيد وفتح المجيد، ومنها الدرر السنية التي جمع فيها فتاواهم، كلها مفيدة وعظيمة، ومنها شرح كتاب التوحيد للشيخ سليمان بن عبد الله أيضًا، ومنها مجموعة التوحيد فيها فوائد عظيمة، ومنها ردود للمشايخ مثل رد الشيخ عبد اللطيف بن عبد الرحمن والشيخ عبد الرحمن بن حسن والشيخ سليمان بن سمحان ، وكتب أخرى كلها جيدة ومفيدة، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم، إذًا تنصحون المسلم والحال ما ذكر أن يجعل جزءًا من دخله الشهري كيما يشتري الكتب النافعة التي تفيده في عقيدته وثقافته الدينية؟ الشيخ: نعم، نوصي كل طالب علم، وكل مؤمن بالعناية بالقرآن، والإكثار من تلاوته في الليل والنهار بالتدبر والتعقل، وسؤال أهل العلم عما أشكل عليه، وحفظ ما تيسر من كتاب الله، كما نوصيه أيضًا بشراء الكتب الطيبة التي ذكرنا بعضها حتى يستفيد منها طالب العلم تكون في مكتبته إذا كان طالب علم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14403/الحث-على-قراءة-الكتب-النافعة-لتصحيح-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74402.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15841,"question":"من أسئلة هذا السائل في سؤاله الثاني يقول: هل حفظ متون الكتب المختصرة في فنون العلم ضروري لطالب العلم، أم يكفي الفهم والفقه مثل: كتاب بلوغ المرام، ألفية ابن مالك في النحو والصرف؟ علمًا بأن الوقت لا يسمح بالجمع بين المصلحتين، وكذلك الحال مع حفظ القرآن والتضلع بتفسيره.","title":"أهمية حفظ القرآن والمتون العلمية لطالب العلم","answer":"الجواب: المهم فهم المعاني والحفظ للمعاني والأحكام، وإذا تيسر له حفظ المتون هذا خير عظيم، كما يشرع له حفظ القرآن، لكن إذا لم يتيسر فالمهم أن يكثر من تلاوته، وأن يفهم المعنى، ويعمل بالحكم الشرعي، وإن لم يحفظ المتون، وإن لم يحفظ القرآن، لكن إذا تيسر حفظ القرآن، وتيسر حفظ البلوغ -بلوغ المرام-، عمدة الحديث، زاد المستقنع في الفقه، ألفية ابن مالك في النحو، هذا خير عظيم؛ لأن هذا يعينه على الفهم، وإذا تيسر له الفهم، ولم يتيسر له الحفظ فلا بأس، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14432/اهمية-حفظ-القران-والمتون-العلمية-لطالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57602.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15913,"question":"يسأل سؤالًا آخر سماحة الشيخ فيقول: هل تجوز قراءة كتب تفسير الأحلام، والاعتبار بما فيها؟جزاكم الله خيرًا.","title":"حكم قراءة كتب تفسير الأحلام","answer":"الجواب: لا أعلم حرجًا في قراءة كتب التفسير، ابن سيرين وغيره، كتب الأحلام يستفيد منها طالب العلم، لكن لا يعتمد عليها، بل بالأدلة، لا بد ينظر إلى الأدلة، ويتعلم، وينظر القرائن، وإذا أشكل عليه لا يجزم، يقول: لعل المراد كذا، إذا رأى رؤيا طيبة حمد الله عليها، مثل: رأى أنه يتفقه في الدين، رأى أنه دخل الجنة، هذا يحمد الله على ذلك، رأى أنه بار بوالديه، رأى أنه يحافظ على الصلوات، كل هذا خير، يحمد الله على ذلك. فإن رأى ما يكره، كأن يرى أنه سقط في بئر، أو أنه قتل، أو أنه يشرب الخمر، أو ما أشبه ذلك، هذه من الشيطان، إذا رأى أمره النبي ﷺ أن يتفل عن يساره ثلاثًا، ويقول: أعوذ بالله من الشيطان، ومن شر ما رأيت -ثلاث مرات- ثم ينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا. فالذي يعبر الرؤيا ينظر ما قاله النبي ﷺ، يعرف الأحاديث الواردة، يستفيد من الكتب، لكن لا يعتمد على قول فلان وفلان، يعتمد على الأحاديث والدلائل الشرعية، والقرائن الشرعية لتفيده، ويتثبت في الأمور، ولا يعبر الرؤيا إلا عن بصيرة، وإذا شك، يقول: لعل كذا، لعل كذا، والنبي ﷺ لما سئل عن الرؤيا الصالحة، قال: يحمد الله عليها إذا رأى ما يحب، أو ما يسره، قال: يحمد الله، ويخبر بها من أحب ولما سئل عن إذا رأى الإنسان ما يكره، قال ﷺ: إذا رأى أحدكم ما يكره فلينفث عن يساره ثلاثًا، ويتعوذ بالله من الشيطان، ومن شر ما رأى -ثلاث مرات-، ثم ينقلب على جنبه الآخر، فإنها لا تضره، ولا يخبر بها أحدًا هذا منهج عظيم بينه النبي ﷺ. أيها المسلم وأيها المسلمة؛ إذا رأى الإنسان ما يحب مثل يرى أنه يصلي على الوجه الشرعي، يرى أنه يتعلم علمًا يتفقه في الدين، يرى أنه دخل الجنة، وما أشبه ذلك من المرائي الطيبة، يرى أنه يجالس الصالحين والأخيار، يرى أنه في حلقات العلم، هذه رؤية طيبة، يحمد الله، يقول: الحمد لله، إذا استيقظ، الحمد لله، يسر بهذا الشيء، يخبر بها أحبابه ومن أحب، لا بأس. أما إذا رأى ما يكره، رأى أنه يضرب، أو يتوعد، أو أنه مع الأشرار، أو أنه دخل النار، أو أنه مريض، أو ما أشبه ذلك من الأشياء المكروهة، إذا استيقظ فزع منها، كرهها، فالرسول ﷺ قد أوصاه أنه: يتفل عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطانن، ومن شر ما رأيت -ثلاث مرات-، ثم ينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا. وبين ﷺ أن هذه من الشيطان، أن هذه الرؤيا من الشيطان؛ ليحزن الإنسان؛ ليؤذيه، يريه هذه الرؤية ليحزنه ليؤذيه، فلا ينبغي أن يقر الشيطان ويسره، لا؛ بل ينبغي له أن يكون عدوًا للشيطان، يتعوذ بالله من الشيطان، يتفل عن يساره ثلاث مرات، ويتعوذ بالله من الشيطان، ومن شر ما رأى، حتى يغيظ الشيطان، ثم ينقلب على جنبه الآخر، كما أمر النبي ﷺ، ولا يخبر به، لا يقول: رأيت رأيت، يتركها، فإنها لا تضره، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14507/حكم-قراءة-كتب-تفسير-الاحلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_708/nour_70804.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16095,"question":"إبراهيم أبو حامد من الرياض يقول: ما حكم الشرع فيمن يقول بأنه غير مقتنع بالحجاب الشرعي؟","title":"توجيه لمن يقول إنه غير مقتنع بالحجاب الشرعي","answer":"الجواب: يعلَّم من قال: إنه غير مقتنع، يعلم أنه الحجاب الشرعي مأمور به، والله يقول -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ويقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنّ.. [النور:31] إلى آخره. فالحجاب الشرعي جاء به النص، وهو أيضًا من وسائل العفة والسلامة، وعدم الحجاب من وسائل الفتن، فالذي لم يقتنع؛ يعلم، يوجه إلى الخير، نعم. وحديث أسماء -الذي يروى عن أسماء- أن النبي ﷺ قال لها: إذا بلغت المحيض؛ لم يحل أن يرى منها إلا هذا وهذا، وأشار إلى وجهه وكفيه حديث ضعيف، لا يصح عن النبي ﷺ نعم.","link":"https://binbaz.org.sa/fatwas/14737/توجيه-لمن-يقول-انه-غير-مقتنع-بالحجاب-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57915.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16137,"question":"أخيرًا تسأل أختنا بعض الأسئلة، حول القرآن الكريم، وحول تفسيره، فتسأل أولًا: عن تفسير الجلالين؟","title":"توجيه حول كتاب تفسير الجلالين","answer":"الجواب: تفسير مفيد، وفيه بعض الأخطاء في الصفات، وفي بعض التفسير لكن مفيد، تفسير مفيد، وقل كتاب إلا ويكون فيه بعض الأخطاء إلا كتاب الله  فكتب الناس يكون فيها بعض الأخطاء، لكن مقل ومكثر، فتفسير الجلالين فيه بعض الأخطاء، فإذا تيسر أن يدرسه صاحب سنة ليعرف كلام أهل السنة والجماعة؛ حتى ينبه على الأخطاء، فهذا طيب، وإذا أشكل شيء على الدارس يسأل أهل العلم، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ! هل تنادون أحد طلبة العلم بتتبع هذا التفسير والإرشاد إلى ما فيه من أخطاء، والقول الصحيح أيضًا؟ الشيخ: نعم، عندي نية في هذا، وقد كتبت فيه بعض الشيء، عندي نية أن أتتبع هذا -إن شاء الله- وأن أكتب ما تيسر في ذلك، ولعلي أوصي أيضًا بعض أهل العلم؛ لأنهم أفرغ مني، قد يفعلون هذا أسرع مني، فأرجو أن أوصي بعض أهل العلم بذلك -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا، طلبة كلية أصول الدين سماحة الشيخ كثيرًا ما يتناولون الدراسات القرآنية لنيل شهادة الماجستير، أو الدكتوراه هل تنصحون أحدًا منهم بتناول هذا الكتاب؟ الشيخ: لعله يتيسر إن شاء الله. المقدم: ليكون أطروحة علمية. الشيخ: أنا أوصي بهذا، نعم. أوصي بهذا؛ لأن فيه مصلحة كبيرة، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14807/توجيه-حول-كتاب-تفسير-الجلالين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80407.mp3","categories":["القرآن وعلومه","العالم والمتعلم","نصائح وتوجيهات"]},{"id":16204,"question":"يقول: هل يجب على من يحفظ القرآن الكريم، هل يجب عليه أن يحفظ التفسير كاملًا أيضًا؟ أم أن الإنسان مخير في هذا؟ جزاكم الله خيرًا.","title":"حكم دراسة التفسير لمن يحفظ القرآن","answer":"الجواب: لا، لا يلزمه، حتى حفظ القرآن مستحب، لكن يحفظ من القرآن ما يسر الله له، حتى يصلي به، والواجب حفظ الفاتحة الحمد لله رب العالمين وحفظ ما سواها مستحب للمؤمن، يحفظ ما تيسر حتى يقرأ به في الصلاة، وفي غير الصلاة، وإذا يسر الله له حفظ الكتاب كله، حفظ القرآن العظيم؛ فهذا خير عظيم، وفائدة عظيمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14908/حكم-دراسة-التفسير-لمن-يحفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80616.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16276,"question":"في سؤال له آخر يقول: تعرفون -بارك الله فيكم- أن الكتب الدينية قد كثرت في هذه الأيام، وتجدنا حائرين عند شراء أي كتاب، خاصةً أن بعض المؤلفين قد أثنى على كتبه ثناءً بالغًا لغرض الربح -والله أعلم- فأرجو التفضل من سماحتكم بأن تفيدونا عن بعض الكتب الموثوق بها، أو الطريقة التي نشتري بها كتبنا التي نرجع إليها في بعض المسائل، أو الاطلاع، جزاكم الله خيرًا.","title":"ما ينصح بقراءته من الكتب","answer":"الجواب: تسأل أهل العلم إذا أردت أن تشتري كتابًا، تسأل أهل العلم في بلدك، تسألهم، أهل العلم المعروفين بالاستقامة، وحسن السيرة، والعلم، والفضل، تسألهم عن الكتب التي تريد لعلهم يفيدونك. وأنا أذكر لك بعض الكتب، لكن أهمها، وأعظمها العناية بالقرآن، هو أفضل كتاب، وأصدق كتاب، وأشرف كتاب كتاب الله، نوصيك بالقرآن، نوصيك أنت وكل مسلم، نوصيك بالقرآن، ونوصي كل مسلم، وكل مسلمة بالعناية بالقرآن، والإكثار من تلاوته، وحفظ ما تيسر منه، وتدبر لمعانيه عند القراءة، فهو كتاب الله العظيم، فيه الهدى والنور، فيه العلم العظيم، يقول الله : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] ويقول سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155]. فنوصي الجميع جميع المسلمين رجالاً ونساء، نوصيهم جميعًا بالعناية بالقرآن، بالإكثار من تلاوته، وتعلمه، وسؤال أهل العلم عن معناه، والإكثار من مراجعة كتب التفسير الموثوقة، كتفسير ابن كثير، والبغوي، وابن جرير، والشوكاني، هذه الكتب العظيمة، وأشباهها يجب على المؤمن، وطالب العلم يعتني بها، ويكثر من تلاوة القرآن في الأوقات المناسبة، ويتدبر، ويتعقل، ويراجع كتب التفسير عما أشكل عليه، ويسأل أهل العلم. ثم كتب الحديث، نوصيك بكتب الحديث، مثل الصحيحين للبخاري ومسلم، مثل رياض الصالحين، مثل المنتقى لابن تيمية منتقى الأخبار، مثل بلوغ المرام كتب جيدة، عمدة الحديث للشيخ عبدالغني المقدسي كتب جيدة، نوصيك بها، والاستفادة منها، مثل زاد المعاد لابن القيم في هدي خير العباد كتاب عظيم، وزاد المعاد في هدي خير العباد للعلامة ابن القيم -رحمه الله- كتاب مفيد جيد، فيه أحكام، وأدلة من الحديث الشريف، والآيات فيه خير كثير، نسأل الله للجميع التوفيق والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14991/ما-ينصح-بقراءته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80913.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16317,"question":"رسالة وصلت إلى البرنامج من المستمع عبدالرحمن محمود يقول: عند قراءتي لكتاب الله العزيز أخطئ في بعض الكلمات، فما الحكم؟","title":"توجيه لمن يقرأ القرآن ويخطئ في بعض الكلمات","answer":"الجواب: عليك أن تجتهد، وأن تتعلم من الذين يعرفون، وأبشر بالخير -إن شاء الله- يقول النبي ﷺ: الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق، ويتتعتع فيه له أجران فأنت -إن شاء الله- مع الاجتهاد، والتحري لك أجران، لكن عليك أن تجتهد في القراءة على أهل العلم من زملائك، ومن المدرسين، وممن تظن أن عنده علمًا حتى تستفيد، اجتهد، وأبشر بالخير -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15015/توجيه-لمن-يقرا-القران-ويخطى-في-بعض-الكلمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753015.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":16357,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من دمشق باعثها أحد الإخوة المستمعين من هناك رمز إلى اسمه بالحروف (أ. ن) أخونا يسأل سماحتكم أولًا عن كتاب: حلية الأولياء ما هو رأيكم فيه؟ وما هو توجيهكم للمهتمين بمثل هذا الكتاب؟ جزاكم الله خيرًا.","title":"حكم قراءة طلبة العلم المبتدئين لكتاب حلية الأولياء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فكتاب حلية الأولياء كتاب معروف لصاحبه الحافظ أبي نعيم، وهو كتاب يجمع الضعيف والصحيح والموضوع، فينبغي ألا يقرأه إلا أهل العلم الذين يعرفون درجات الحديث، ويميزون بين الغث والسمين. أما هذا الكتاب فهو لا يصلح للعامة، وطلبة العلم الذين لم يصلوا إلى حد التمييز بين الضعيف والصحيح، وننصح طلبة العلم، وإخواننا جميعًا أن يقرؤوا الكتب المفيدة الصحيحة، مثل صحيح البخاري، صحيح مسلم، رياض الصالحين كتاب مفيد، الترغيب والترهيب مفيد، وفيه أحاديث ضعيفة، لكن نبه عليها صاحب الترغيب، نبه عليها، فإذا قال: يروى، أو روي هي علامة الضعيف، والصحيح يجزم بها، ولا يقول فيها روي. المقصود: أني أنصح إخواني أن يتحروا الكتب المعروفة التي اعتنى أصحابها بالأحاديث الصحيحة، كالصحيحين، ورياض الصالحين، الترغيب والترهيب، منتقى الأخبار لابن تيمية المجد بلوغ المرام وحفظ البلوغ للحافظ ابن حجر، كلها أحاديث مفيدة وإن كان فيها أحاديث ضعيفة، لكن نبه عليها الحافظ نبه على الضعيف، والمنتقى الأحاديث الضعيفة قليلة، وطالب العلم يستطيع يعرف الضعيف من شرح المنتقى للشوكاني مفيد، كذلك عمدة الحديث للشيخ عبدالغني بن عبدالواحد المقدسي كتاب عظيم ومفيد، وأحاديثه صحيحة. أما مثل حلية الأولياء فهذا لا يصلح إلا لأهل العلم الذين يميزون بين الصحيح والسقيم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15052/حكم-قراءة-طلبة-العلم-المبتدىين-لكتاب-حلية-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71501.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16378,"question":"يقول: أريد حفظ القرآن الكريم، لكنني لم أستطع؛ نظرًا لمشاغل الحياة، فما هو توجيهكم؟","title":"توجيه لمن أراد حفظ كتاب الله","answer":"الجواب: الحفظ للقرآن ليس بواجب، لكنه مستحب، فإذا تيسر لك الحفظ؛ فالحمد لله، وإلا فلا حرج عليك، ولا شك أن الحفظ من نعم الله العظيمة، فإذا تيسر للمؤمن حفظ القرآن، أو المؤمنة، فهذا من نعم الله العظيمة. والمقصود من ذلك: التدبر، أن تكثر من قراءته، فإذا تيسر لك الحفظ؛ فهذه نعمة كبيرة، وإلا فعليك بالقراءة من المصحف، مع التدبر، والتعقل؛ لأن المقصود من إنزاله: العمل به، وقراءته بالتدبر، والتعقل من أسباب فهمه، ومن أسباب العمل به. فالمشروع للجميع -من الرجال والنساء- العناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، والتفقه فيه، والعمل بما دل عليه من فعل الأوامر، وترك النواهي، والاعتبار بما قص الله علينا من أخبار الماضين؛ حتى نحذر أعمالهم الخبيثة، وحتى نعمل ما يكون سببًا لمرضاة ربنا، ونجاتنا في الدنيا والآخرة، يقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] ويقول سبحانه في كتابه العظيم: أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]، ويقول -جل وعلا-: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9].  فالمشروع لكل مؤمن ومؤمنة العناية بالقرآن، والإكثار من تلاوته بالتدبر، والتعقل، والتفهم، ومراجعة كتب التفسير للفائدة، وسؤال أهل العلم عما يشكل، والعمل. المقصود: العمل، أن تعمل بطاعة ربك، وأن تؤدي فرائضه، وأن تحذر محارمه عن بصيرة، وعن علم، وعن رغبة فيما عند الله، وحذر من عقابه  ولك بكل حرف حسنة، والحسنة بعشر أمثالها، كما صح به الحديث عن رسول الله ﷺ يقول -عليه الصلاة والسلام-: من قرأ حرفًا من القرآن؛ فله به حسنة، والحسنة بعشر أمثالها هذه من نعم الله العظيمة أن يحصل لك الخير العظيم بقراءة كتاب الله، من العلم والعمل، وهذه الحسنات العظيمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15079/توجيه-لمن-اراد-حفظ-كتاب-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75409.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16396,"question":"سماحة الشيخ يعتقد البعض أنكم تقفون عند مذهب معين، هل تتفضلون بقول كلمة في هذا المقام؟","title":"توجيه حول التقيد في الفتوى بمذهب معين","answer":"الجواب: الفتاوى الصادرة مني لا أقف فيها، ولا أعتمد فيها على مذهب أحد، لا أحمد، ولا غيره، إنما عمدتنا في ذلك تحري ما قاله الله ورسوله ﷺ، سواء كان في مذهب أحمد، أو مذهب الشافعي، أو مالك، أو أبي حنيفة، أو الظاهرية، أو بعض السلف المتقدمين. المقصود: تحري ما يدل عليه الكتاب والسنة، هذا هو الذي نعتمد عليه، لا نعتمد على مذهب أحمد، ولا على غيره، إنما نعتمد على ما قاله الله ورسوله ﷺ، وما دل عليه الكتاب والسنة، في الأحكام؛ لأن هذا هو الواجب على كل طالب علم، نعم. المقدم: جزاكم الله خيرًا. الشيخ: نسأل الله للجميع التوفيق، والهداية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15105/توجيه-حول-التقيد-في-الفتوى-بمذهب-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81109.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":16401,"question":"سماحة الشيخ يعتقد البعض أنكم تقفون عند مذهب معين، هل تتفضلون بقول كلمة في هذا المقام؟","title":"توجيه حول التقيد في الفتوى بمذهب معين","answer":"الجواب: الفتاوى الصادرة مني لا أقف فيها، ولا أعتمد فيها على مذهب أحد، لا أحمد، ولا غيره، إنما عمدتنا في ذلك تحري ما قاله الله ورسوله ﷺ، سواء كان في مذهب أحمد، أو مذهب الشافعي، أو مالك، أو أبي حنيفة، أو الظاهرية، أو بعض السلف المتقدمين. المقصود: تحري ما يدل عليه الكتاب والسنة، هذا هو الذي نعتمد عليه، لا نعتمد على مذهب أحمد، ولا على غيره، إنما نعتمد على ما قاله الله ورسوله ﷺ، وما دل عليه الكتاب والسنة، في الأحكام؛ لأن هذا هو الواجب على كل طالب علم، نعم. المقدم: جزاكم الله خيرًا. الشيخ: نسأل الله للجميع التوفيق، والهداية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15105/توجيه-حول-التقيد-في-الفتوى-بمذهب-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81109.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":16462,"question":"يسأل سماحتكم رأيكم في كتاب الروح لابن القيم ؟","title":"تقييم كتاب الروح لابن القيم","answer":"الجواب: كتاب الروح لابن القيم كتاب عظيم، كتاب عظيم الفائدة، ولكن وقع فيه بعض التساهل في حكايات المرائي المنامية، وبعض التساهل في بعض الأحكام، ولعله كان من أول كتبه رحمه الله، ومن ذلك ما ذكر من إهداء القرب إهداء القرآن للموتى، قراءة القرآن هذا فيه نظر. فالمقصود: أنه كتاب عظيم ومفيد، ولكن فيه بعض الأشياء التي تلاحظ عليه، فالواجب أن توزن بالأدلة الشرعية، الواجب أن توزن بالأدلة الشرعية، والمرائي المنامية لا يعتمد عليها في الأحكام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15214/تقييم-كتاب-الروح-لابن-القيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81312.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16502,"question":"سماحة الشيخ: تتيح لنا هذه المستمعة بعض الأسئلة لو تكرمتم، جزاكم الله خيرًا.الشيخ: نعم.المقدم: بعض الأسر عندما ينشأ بينها شاب ملتزم، داعية إلى الله، ويلتزم بالسنة النبوية؛ تجد كثيرًا من الأسر تتذمر من هذا وتحاول أن تعيده على سيرتهم التي لم تكن مرضية، لعل لسماحتكم توجيه في هذا الباب؟ جزاكم الله خيرًا.","title":"حكم تذمر الأسرة عند التزام أبنائها","answer":"الجواب: هذا لا يجوز، الواجب على الأسرة أن تشجع على الخير، فإذا نشأ فيها شاب، والتزم بالحق، وحافظ على الصلوات، وترك الإسبال، وترك حلق لحيته الواجب مساعدته في هذا، وأن يشكر على هذا الخير العظيم، ويعان، ويرغب في الاستمرار والثبات. وهكذا الجارية إذا نشأت ملتزمة، محافظة على الصلاة، وعلى الحجاب، تشكر على هذا، وتشجع من أبيها وأمها وأخواتها، هذا هو الواجب على الجميع؛ لأن الله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] أما أنه يثبط، ويستهزأ به هذا منكر لا يجوز، وهكذا مع المرأة لا يجوز تثبيطها، ولا الاستهزاء بها إذا تحفظت، واحتجبت، وابتعدت عن أسباب الشر، وحافظت على الصلاة، واطمأنت فيها، وأدتها في أوقاتها، كل هذا يجب التشجيع عليه، والثناء على من فعله، وعدم تثبيطه، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15264/حكم-تذمر-الاسرة-عند-التزام-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81410.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":16505,"question":"سماحة الشيخ: تتيح لنا هذه المستمعة بعض الأسئلة لو تكرمتم، جزاكم الله خيرًا.الشيخ: نعم.المقدم: بعض الأسر عندما ينشأ بينها شاب ملتزم، داعية إلى الله، ويلتزم بالسنة النبوية؛ تجد كثيرًا من الأسر تتذمر من هذا وتحاول أن تعيده على سيرتهم التي لم تكن مرضية، لعل لسماحتكم توجيه في هذا الباب؟ جزاكم الله خيرًا.","title":"حكم تذمر الأسرة عند التزام أبنائها","answer":"الجواب: هذا لا يجوز، الواجب على الأسرة أن تشجع على الخير، فإذا نشأ فيها شاب، والتزم بالحق، وحافظ على الصلوات، وترك الإسبال، وترك حلق لحيته الواجب مساعدته في هذا، وأن يشكر على هذا الخير العظيم، ويعان، ويرغب في الاستمرار والثبات. وهكذا الجارية إذا نشأت ملتزمة، محافظة على الصلاة، وعلى الحجاب، تشكر على هذا، وتشجع من أبيها وأمها وأخواتها، هذا هو الواجب على الجميع؛ لأن الله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] أما أنه يثبط، ويستهزأ به هذا منكر لا يجوز، وهكذا مع المرأة لا يجوز تثبيطها، ولا الاستهزاء بها إذا تحفظت، واحتجبت، وابتعدت عن أسباب الشر، وحافظت على الصلاة، واطمأنت فيها، وأدتها في أوقاتها، كل هذا يجب التشجيع عليه، والثناء على من فعله، وعدم تثبيطه، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15264/حكم-تذمر-الاسرة-عند-التزام-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81410.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":16535,"question":"من أسئلة هذه السائلة، تقول: ما حكم ضرب الأطفال الذين دون سن العاشرة على أي أمر يفعلونه؟ وما توجيهكم بذلك مأجورين؟","title":"حكم ضرب الأطفال دون سن العاشرة","answer":"الجواب: للوالد والوالدة تأديب الأطفال إذا رأيا ذلك، ولو كان دون العشر، ولو كان دون السابعة، إذا رأى أن يؤدب ولده ذكرًا كان أو أنثى؛ لا بأس، لكن بالشيء الذي يناسبه، لا يضره، التأديب الخفيف ينفعه، ولا يضره، إذا كان يتعدى على إخوانه الصغار، إذا كان يعبث في البيت عبثًا يؤذي، أو ما أشبه ذلك؛ يؤدبه، الضربات الخفيفة، أو بالكلام الشديد الذي يردعه، أو بالضربات الخفيفة، أو منعه من بعض حاجاته التي يريدها حتى يتأدب، من الأم والأب، ومن أخيه الكبير إذا كان ما عنده أب ولا أم، أو من عمه، أو من خالته، على حسب حاله، يعني ممن يربيه ويقوم عليه، له أن يؤدبه، سواء كان أمًا، أو أبًا، أو خالًا، أو خالة، أو أخًا كبيرًا، على حسب الحال، فالذي يربيه، ويقوم عليه له أن يؤدبه بالشيء الذي لا يضره، شيئًا خفيفًا، لكن يحصل به النفع. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15259/حكم-ضرب-الاطفال-دون-سن-العاشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58311.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":16571,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية اليمنية، وباعثتها إحدى الأخوات من هناك، رمزت إلى اسمها بالحروف (ف. ع. ج) لها جمع من الأسئلة، ملخص سؤالها الأول تقول: إن والدها يعارضها في مواصلة الدراسة، وترجو من سماحتكم التوجيه لها ولوالدها؟","title":"نصيحة لمن يمنع بناته من الدراسة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن طلب العلم للنوعين الرجال والنساء من أفضل القربات، ومن أهم الطاعات؛ لقول النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل له به طريقًا إلى الجنة ولقوله -عليه الصلاة والسلام-: من يرد الله به خيرًا؛ يفقهه في الدين ولقوله ﷺ: خيركم من تعلم القرآن وعلمه. فنصيحتي لك وللوالد الاستمرار في الدراسة الإسلامية النافعة المفيدة على يد العلماء المعروفين بالاستقامة، وحسن العقيدة، والسيرة، وذلك من التفقه في الدين الذي هو علامة الخير، وعلامة أن الله أراد بالعبد خيرًا، وعلى الوالد أن يلاحظ ما ينبغي أن يلاحظ من ذهابك إلى المدرسة بصحبة الثقات المأمونات، وعدم ذهابك مع السائق وحده، ومن جهة العناية بالمدرسة إذا كانت المدرسة جيدة، وفيها معلمات معروفات بحسن العقيدة والسيرة، فهذا مما ينبغي للوالد أن يعين عليه. أما إن كانت الدراسة فيها شيء يخشاه الوالد عليك، فاسمعي، وأطيعي للوالد، وهذا من نصحه لك، وبره لك. فالخلاصة: أن عليك أن تتفاهمي مع الوالد في الموضوع، فإذا كانت الدراسة على مدرسات طيبات معروفات بالخير، وتيسر لك الذهاب إلى المدرسة بطريقة سليمة، ليس فيها خلوة بالسائق، ولا غيره، فالوالد يوافق -إن شاء الله- على هذا الخير العظيم، وإن كان هناك أسباب للمنع، فالوالد لا يريد لك إلا الخير -إن شاء الله- فاسمعي، وأطيعي للوالد، وبره من أهم المهمات، والله -جل وعلا- أوصى ببر الوالدين في آيات كثيرات  منها قوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] أسأل الله أن يوفقك، ووالدك لما فيه براءة ذمة الجميع، وصلاح الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15284/نصيحة-لمن-يمنع-بناته-من-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81601.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":16579,"question":"له حالة معينة تخصه بالذات سماحة الشيخ هل أذكرها، أو لا؟ ويطلب التوجيه فيها؟الشيخ: لا بأس.المقدم: جزاكم الله خيرًا، يقول: إنني عندي طلاقة في الحديث، ولكن ينقصها المعرفة، والعلم الجيد، أي: أنني -هكذا يصف نفسه- أي: أنني إناء فارغ، ولكني إناء قوي -يريد من يستعمله إن صح التعبير- وجهوني جزاكم الله خيرًا.","title":"الوصية بالتفقه في الدين","answer":"الجواب: نوصيك بطلب العلم، والتفقه في الدين؛ حتى تستغل هذا الإناء، فاجتهد في طلب العلم، واحضر حلقات العلم، وإن تيسر لك الالتحاق بالمعاهد العلمية، ثم كلية، فهذا أكمل. ونوصيك بالعناية بالقرآن الكريم، والإكثار من تلاوته، تدبر معانيه؛ فهو أصل كل خير، وينبوع كل خير، وفقك الله ويسر أمرك، نعم. المقدم: آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15305/الوصية-بالتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75804.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":16622,"question":"سؤالها الأخير الذي نعرضه تقول فيه: أريد أن أحفظ القرآن الكريم، إلا أني أجد في ذلك صعوبة، فما هي نصيحتكم، وإرشاداتكم لي في هذا الموضوع؟ جزاكم الله خيرًا.","title":"توجيهات لمن أراد حفظ كتاب الله تعالى","answer":"الجواب: نوصيك بالاستعانة بالله.. الضراعة إلى الله، أن تسأليه في السجود، في آخر التحيات، في الليل، في آخر الليل، في جوف الليل، تسألينه سبحانه أن يعينك على حفظه، وأنت صادقة خاشعة، تقولي: يا رب أعني على حفظ كتابك العظيم، اللهم أعني على حفظه، اللهم يسر لي حفظه، ومع الدعاء الصادق تجتهدين في العمل، تجتهدين في الحفظ في الأوقات المناسبة التي أنت فيها فارغة في الليل، أو في النهار، تبدئين من البقرة، أو من المفصل، وتقرئين ما تيسر، كل يوم شيئًا ولو قليلًا، تقرئين كل يوم شيئًا، ولو قليلًا، وتجتهدين في دراسته... تكراره حتى يستقر، وهكذا حتى تكملي، إن شاء الله. تحرصين على الأوقات المناسبة في الليل، أو في النهار التي فيها القلب فارغ، وترتبين شيئًا فشيئًا قليلًا: نصفًا... ثمنًا... صفحة كل يوم، كل ليلة صفحتين، حسب التيسير، ومع الصدق، والرغبة فيما عند الله، وسؤال الله التوفيق، والإعانة؛ أبشري بالخير، يقول الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2، 3]. فهو سبحانه مع أوليائه المتقين بالتيسير، والتسديد، والتوفيق، والإعانة، يسر الله أمرك، وأعانك، وثبتنا وإياك وجميع المسلمين على الحق والهدى. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15359/توجيهات-لمن-اراد-حفظ-كتاب-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_759/nour_75903.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":16690,"question":"تسأل عن بعض الكتب لو تكرمتم سماحة الشيخ، وتطلب رأي سماحتكم فيها، فذكرت مثلًا كتاب (تحفة العروس)؟","title":"ما ينصح باقتنائه ومطالعته من الكتب؟","answer":"الجواب: الكتب تختلف، وأحسنها، وأصدقها، وأعظمها، وأوجبها كتاب الله، القرآن هو أحسن كتاب، وأصدق كتاب، وأعظم كتاب، وهو أصل الدين وأساسه، فنصيحتي لكل مسلم ومسلمة العناية بالقرآن تلاوة، وتدبرًا، وحفظًا، وفهمًا، وعملًا، فهو أحسن كتاب، وأصدق كتاب. وأوصي كل مسلم ومسلمة بالعناية بكتاب الله، وحفظ ما تيسر منه، وقراءته نظرًا بالتدبر، والتعقل، والعمل، وإذا تيسر حفظه فذلك فضل عظيم، مع الإكثار من التلاوة، والتدبر، والتعقل، والفهم، والمذاكرة مع العلماء والزملاء في المعاني، ومراجعة كتب التفسير المعتمدة، كابن جرير، وابن كثير، والبغوي، ونحوها لمعرفة المعاني من كتاب الله . ثم يلي ذلك كتب السنة، كتب الحديث الشريف، وأولاها، وأصحها الصحيحان، صحيح البخاري، وصحيح مسلم، فهما أصح الكتب بعد القرآن العظيم، ثم السنن الأربع؛ سنن أبي داود، والترمذي، والنسائي، وابن ماجة فهي كتب عظيمة في الحديث الشريف، ولكنها ليست .... الصحيحين، بل هي دون الصحيحين؛ لأن فيها بعض الأحاديث الضعيفة. ويلتحق بذلك مسند أحمد -رحمه الله- وموطأ مالك، وسنن الدارمي، والدارقطني، وصحيح الحاكم، وصحيح ابن حبان، هذه كتب مفيدة عظيمة، لكن فيها الضعيف، وفيها الصحيح، وطالب العلم يجتهد في معرفة الصحيح، ويسأل أهل العلم، ويجتهد في معرفة المصطلح، وما قاله العلماء في بيان الحديث الصحيح، والضعيف حتى يكون على بينة، وعلى بصيرة.  ومن الكتب التي ينبغي أن يعتنى بها: كتب العقيدة؛ لأنها تعين على فهم كتاب الله، وسنة رسوله ﷺ التي ألفها أهل العلم من أهل السنة، مثل كتاب التوحيد لابن خزيمة، مثل كتاب الدارمي في الرد على بشر المريسي، مثل كتاب السنة لعبدالله بن أحمد بن حنبل، مثل منهاج السنة لشيخ الإسلام ابن تيمية في الرد على الرافضة، ومثل زاد المعاد لابن القيم في بيان هدي النبي ﷺ في العبادات وغيرها، مثل فتح المجيد للشيخ عبدالرحمن بن حسن آل الشيخ شرح كتاب التوحيد، ومثل كتاب التوحيد، كذلك كتاب عظيم كتاب التوحيد، كشف الشبهات، ثلاثة الأصول للشيخ محمد عبدالوهاب -رحمه الله- العقيدة الواسطية لشيخ الإسلام ابن تيمية، وهكذا الحموية والتدمرية له أيضًا -رحمه الله- كلها كتب عظيمة، ينبغي أن تقتنى، ويعتنى بها، وهكذا شرح الطحاوية لابن أبي العز، كتاب جيد وعظيم، نسأل الله للجميع التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15452/ما-ينصح-باقتناىه-ومطالعته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82006.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16700,"question":"تسأل عن مختصر تفسير ابن كثير لـ الصابوني؟","title":"توجيه حول مختصر تفسير ابن كثير للصابوني","answer":"الجواب: أنصح بتركه؛ لأن فيه بعض .. عليه بعض الملاحظات، فأنصح بتركه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15456/توجيه-حول-مختصر-تفسير-ابن-كثير-للصابوني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82008.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":16831,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من العراق (نينوى) باعثة الرسالة إحدى المستمعات من هناك تقول: المرسلة أميرة محمد، محلة أبي تمام، المستمعة أميرة لها جمع من الأسئلة، في أحدها تقول: كيف أستطيع أن أتفقه في القرآن الكريم، جزاكم الله خيرًا.","title":"كيفية التفقه في القرآن الكريم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله نبينا وإمامنا وسيدنا محمد بن عبدالله، وعلى آله وأصحابه ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد: فإن التفقه في القرآن من أعظم العبادات، ومن أفضل القربات، ومن أعظم أسباب السعادة في الدنيا والآخرة؛ لأنه كتاب الله، فيه الهدى، والنور، من اتبعه، واستقام على ما فيه؛ فله السعادة، والعاقبة الحميدة في الدنيا والآخرة، ومن حاد عنه؛ هلك يقول الله : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] ويقول سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] والتفكر، والتفقه فيه يكون بالتدبر، والتعقل، وجمع الآيات بعضها إلى بعض إذا كانت في معنى واحد؛ حتى يفهم القارئ مراد الله  فإذا كان يتدبر فيما يتعلق بالصلاة، درس الكثير من آيات الصلاة، وتفقه فيها؛ حتى يفهم المعنى، وحتى يعمل به، وهكذا آيات الزكاة.. هكذا آيات الصيام.. الحج.. آيات البيع والربا.. آيات متعلقة بقصص الأنبياء، وبالجنة، والنار.. إلى غير ذلك، يتدبر، ويتعقل، ويجمع قلبه حين يقرأ وحين يتدبر. ويراجع ما جاء في الأحاديث الصحيحة في معنى الآية من كتاب تفسير ابن كثير -رحمه الله- أو ابن جرير -رحمه الله- أو البغوي -رحمه الله- أو غيرهم من أهل أئمة التفسير؛ حتى يستعين بالأحاديث الصحيحة، وبكلام العلم على فهم القرآن العظيم، والتفقه فيه. ولا يجوز أن ينقل عن القرآن ما لم يتحققهن ويطمئن قلبه إلى أنه هو المعنى؛ لأن قوله على الله بغير علم أمره عظيم، وخطير، ومن أقبح المحرمات. فالواجب على المؤمن، والمؤمنة عند تدبر القرآن العناية بذلك، والاستكثار من ذلك، والتثبت، والاستعانة بكلام أهل التفسير، وما جاء من الأحاديث في معنى الآية؛ حتى يكون الفقه على أصول مستقيمة ثابتة، وحتى يكون المتفقه بعيدًا عن الخطأ، والغلط في ذلك، رزقك الله التوفيق، ومن علينا وعليك بالفقه في الدين والثبات عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15587/كيفية-التفقه-في-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76401.mp3","categories":["العالم والمتعلم","القرآن وعلومه"]},{"id":16916,"question":"رسالة أخرى من الإخوة: مجدي رمزي حافظ، وحارث عبد المنعم السعدي، وأشرف عاطف مختار، مصريون مقيمون في العراق، إخوتنا لهم جمع من الأسئلة، يسألون ويقولون: نعلم أن الكتب الصحيحة الستة كتب خيرة، فالرجاء أن تفيدونا: هل تختلف هذه الكتب من طبعةٍ إلى أخرى؛ لأنني -ونظرًا لكثرة الكتب- لم أعرف ما هو الصحيح فيها، الرجاء أن تفيدونا عن ذلك؟ جزاكم الله خيرًا.","title":"كيفية اختيار أفضل طبعات الكتب المفيدة","answer":"الجواب: نعم، تختلف، الطبعات بعضها رديء، بعضها فيه أغلاط، فينبغي لطالب العلم أن يختار الطباعة الجيدة، ويسأل أهل العلم الذين يعرفهم عن الطبعات الجيدة؛ حتى يستعملها، ويشتريها، ليست الطبعات على حدٍ سواء، لا في الصحيحين، ولا في السنن الأربع، ولا في غيرها من الكتب، حتى القرآن قد يقع فيه غلط من الطابعين، فطالب العلم .. يكون عنده انتباه، وعنده بصيرة، حتى لا يقتني إلا الطبعة الجيدة التي عرفها العلماء بالصحة، والسلامة من الأخطاء، وفي إمكانك إمكان كل واحدٍ منكم أن يسأل عن الطبعة الجيدة، إذا كان عنده قصور، ما يعرف، يسأل أهل العلم، يقول: عندي طبعة كذا، طبعة حق فلان، من كتاب التفسير لابن كثير، من كتاب البخاري، كتاب مسلم، كتاب سنن للترمذي، إلى غيره، يسأل أهل العلم الذي يعرفونه، الذين يعرفهم؛ حتى يدلوه ويرشدوه على الطبعة الجيدة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15684/كيفية-اختيار-افضل-طبعات-الكتب-المفيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16964,"question":"يقول: أسأل سماحتكم عمن قرأ القرآن كاملًا، وحفظه كذلك، ولكنه لم يعمل بشيء منه كما ذكر، فما حكم الإسلام في هذا الرجل؟ جزاكم الله خيرًا.","title":"حكم من يحفظ القرآن دون أن يمتثل تعاليمه","answer":"الجواب: يقول النبي ﷺ: القرآن حجة لك أو عليك فهو حجة لمن عمل به، وهو من أسباب دخوله الجنة، وحجة على من لم يعمل به، وهو من أسباب دخوله النار، ويقول ﷺ: اقرؤوا القرآن فإنه يأتي يوم القيامة شفيعًا لأصحابه يعني: العاملين به، وفي اللفظ الآخر: يدعى بالقرآن وأهله الذين يعملون به تقدمه سورة البقرة، وآل عمران، تحاجان عن أصحابهما.  ورأى -حين أسري به- رجلًا يرضخ رأسه بالحجر، عليه رجل واقف يرضخه بالحجر، وكلما تدهور الحجر ذهب وأخذه، ورجع رأسه إلى حاله، والتأم رأسه، فضربه مرة أخرى، وهكذا، يعذب، قال: لأنه رجل آتاه الله القرآن، فنام عنه بالليل، ولم يعمل به في النهار نسأل الله العافية. فالمقصود: أن من عمل به؛ فهو حجة له، ومن أسباب سعادته، ومن حفظه، قرأه ولم يعمل به؛ فهو من أسباب عذابه، وغضب الله عليه، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15761/حكم-من-يحفظ-القران-دون-ان-يمتثل-تعاليمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_766/nour_76604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16990,"question":"ما هي النصيحة التي تتفضلون بها، وتنصحونني عندما أقرأ القرآن الكريم، ولاسيما وأن حفظي بسيط؟","title":"نصيحة لمن أراد قراءة القرآن الكريم","answer":"الجواب: أنصحك بالعناية بالدراسة، وتحري الأوقات المناسبة التي يكون قلبك فيها حاضرًا، والمشاغل فيها قليلة؛ حتى تنتفع بالقراءة أكثر، أوصيك أيضًا بأن تسأل ربك الإعانة والتوفيق، وأن يمنحك حفظ كتابه، وفهمه، والعمل به، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15772/نصيحة-لمن-اراد-قراءة-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82903.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":17024,"question":"تقول: لقد اختلط على الناس أمر الأحاديث التي يقرؤونها، أو يسمعونها هل هي صحيحة، أم ضعيفة؟ ويقال: إن كتاب صحيح الجامع الصغير وزيادته للألباني يوضح الأحاديث الضعيفة من الصحيحة، ما هو توجيهكم؟","title":"توجيه حول كتب الألباني وتصحيحه وتضعيفه للأحاديث","answer":"الجواب: نعم كتب الألباني جيدة، ومفيدة، وفقه الله، وهو الشيخ محمد ناصر الألباني، هو رجل متفرغ لهذا الأمر، وقد اعتنى به كثيرًا في تحري الأحاديث الصحيحة، والتنبيه عليها، والأحاديث الضعيفة، فكتبه مفيدة، ونافعة، ولكن ليس معصومًا، فقد يقع بعض الخطأ في بعض الأحاديث، وقد يعتقدها صحيحة وهي ضعيفة، وقد يعتقدها ضعيفة وهي صحيحة، لكن هذا قليل، وطالب العلم يجتهد في معرفة الصحيح، والسقيم بالطرق التي أوضحها العلماء. والاستفادة من كتب الشيخ ناصر الدين الألباني طيبة، ينبغي للمؤمن، والمؤمنة أن يستفيد منها ومن أمثالها، مثل: صحيح البخاري .. صحيح مسلم .. رياض الصالحين، كلام العلماء على الأحاديث الضعيفة في كتبهم المؤلفة في هذا الباب مثل: شرح الجامع الصغير.. كشف الخفاء، وغير ذلك من الكتب التي ألفت في هذا الباب، حتى يستفيد المؤمن من كلام العلماء. نعم. المقدم: جزاكم الله خيرًا، ما رأيكم سماحة الشيخ فيما ضعفه الشيخ الألباني ؟ الشيخ: مثل ما تقدم، الغالب على ما ضعفه وصححه الصحة؛ لأنه معتني -وفقه الله- وله خبرة بهذا الباب، فالغالب على ما صححه وضعفه أن كلامه فيه جيد، ومستقيم. نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15809/توجيه-حول-كتب-الالباني-وتصحيحه-وتضعيفه-للاحاديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83004.mp3","categories":["الحديث وعلومه","العالم والمتعلم"]},{"id":17051,"question":"تقول يا سماحة الشيخ السائلة: كيف أستطيع الحصول على العلم الشرعي بدون المدارس؟ هل أستطيع الحصول عليه من الكتب؟ وما هي الكتب التي تنصحونني بقراءتها؟ جزاكم الله خيرًا.","title":"كيفية الحصول على العلم من غير المدارس","answer":"الجواب:  نعم، إذا تيسرت الحلقات العلمية عند بعض الناس من بعض أهل العلم، أو عند المعلمات الطيبات هذا خير عظيم، أو حضور الحلقات العلمية في المساجد تسمعه من بعيد مع التستر والحشمة، وكذا من إذاعة القرآن فيها خير عظيم، إذاعة القرآن فيها حلقات علمية، فيها نصائح، فيها وصايا، وفيها محاضرات، وفيها سماع القرآن، وفيها نور على الدرب، أسئلة كثيرة من العالم للعلماء، هذه الإذاعة فيها خير عظيم، فأنا أوصيك بالاستفادة من إذاعة القرآن لما فيها من الخير العظيم. ومن الكتب مثل رياض الصالحين، مثل كتاب التوحيد للشيخ محمد بن عبد الوهاب، ومثل العقيدة الواسطية لشيخ الإسلام ابن تيمية، مثل ثلاثة الأصول، وشروط الصلاة، والقواعد الأربع للشيخ محمد بن عبد الوهاب، هذه كتب مفيدة أوصيك بها، وفق الله الجميع، نعم. المقدم: اللهم آمين، أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/15840/كيفية-الحصول-على-العلم-من-غير-المدارس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58726.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":17073,"question":"تقول أخيرًا هذه السائلة: بأن عندها ولد يريد أن يحفظ القرآن كاملًا عن ظهر قلب، ترجو من سماحة الشيخ عبدالعزيز توجيه طريقة معينة تعينه على حفظ كتاب الله -جل وعلا- وأن تدعو له في ظهر الغيب، أن يكون من حفاظ كتاب الله، وجزاكم الله خيرًا، وبارك في عمركم على طاعة الله.","title":"وسائل حفظ القرآن","answer":"الجواب: نسأل الله له العون، نسأل الله له العون والتوفيق، نسأل الله أن يعينه ويوفقه، ونوصيه بالعناية بحفظ القرآن في الأوقات المناسبة التي قلبه فيها يكون مستعدًا للقراءة، مثل: بعد صلاة الفجر، مثل: في أثناء الليل، في الأوقات التي يراها مناسبة يجتمع فيها قلبه ولسانه، حتى يدرس وحتى يتحفظ. نعم.","link":"https://binbaz.org.sa/fatwas/15878/وساىل-حفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58813.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":17087,"question":"من أحد الإخوة المستمعين يقول من بور سودان، يقول: منذ أكثر من ثلاثة عشر عامًا طلقت زوجتي، ولي منها ولدان وبنتان، ويتم خصم نفقة أولادي منها بواسطة المحكمة، وقد قسمت المحكمة مرتبي مناصفة بيني وبين أولادي؛ لأنني متزوج من امرأة أخرى، ولي منها أطفال، أكبر أبنائي منها ذكر، وكان يقيم معي عند طلاقي منها، لم أتركه يصاحبها حتى يتربى تحت يدي، لكنها لم تتركه، وسعت خلفه حتى أخذته، وكانت النتيجة الفشل في الدراسة، والعمل أيضًا، وهو الآن عاطل، ويشكل عبئًا عليها، هل يجوز لي أن آخذ أولادي منها؟ جزاكم الله خيرًا.","title":"أخذ الأولاد من أمهم المطلقة يرجع إلى المحكمة","answer":"الجواب: هذا إلى المحكمة بارك الله فيك، تراجع المحكمة، وفيها البركة إن شاء الله.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15913/اخذ-الاولاد-من-امهم-المطلقة-يرجع-الى-المحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83106.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":17135,"question":"السائل من سوريا يقول: سماحة الشيخ! أنا أريد أن أتفقه في أمور ديني وخصوصًا في العقيدة، فما الكتب التي توصونني وزملائي بقراءتها في كتب العقيدة؟ مأجورين.","title":"كتب ينصح بقراءتها في العقيدة","answer":"الجواب: أوصيك وكل مسلم بالقرآن، هو كتاب العقيدة العظيمة، نوصيك بالقرآن الكريم، والإكثار من تلاوته، وتدبر معانيه، وحفظه إذا تيسر، هو كتاب الله، هو أعظم كتاب، وأصدق كتاب، وهو فيه بيان العقيدة التي أمر الله بها عباده من التوحيد، والأسماء، والصفات.. وغير ذلك، فعليكم بالإكثار من قراءة القرآن، الإكثار من تدبره، وتدبر معانيه، والسؤال عما أشكل عليكم، فهو كتاب الله، فيه الهدى والنور، وهكذا الحديث عن الرسول ﷺ إذا تيسر، مثل كتاب الأربعين النووية، وتتمته لابن رجب خمسين حديثًا، إذا تيسر لك حفظها فيها أحاديث جيدة، كذلك عمدة الحديث للشيخ عبدالغني، عمدة الحديث فيها أحاديث صحيحة تحفظها، والعقيدة الواسطية لشيخ الإسلام ابن تيمية كتابٌ طيب عقيدة طيبة، ملخصة من الكتاب والسنة، كتاب عظيم، كتاب التوحيد للشيخ محمد بن عبدالوهاب -رحمه الله- ثلاثة الأصول للشيخ محمد، ثلاثة الأصول، والقواعد الأربع، كل هذه كتبٌ طيبة، كشف الشبهات للشيخ محمد أيضًا، كتابٌ طيب. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15958/كتب-ينصح-بقراءتها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58926.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17226,"question":"تقول أم سعد: يا شيخ -حفظكم الله- عندي أولاد لا يصلون، وقد نصحتهم كثيرًا، ولم يستجيبوا لنصحي، ماذا أفعل معهم؟ وهل آثم بتركهم؟","title":"كيفية التعامل مع الأولاد الذين لا يصلون","answer":"الجواب: الواجب نصيحتهم، وتأديبهم إذا استطعت أن تؤدبيهم، أو ترفعي أمرهم إلى الهيئة، أو إلى المحكمة؛ حتى يؤدبوا، لا يجوز السكوت عنهم، بل يجب العناية بهم، تجب العناية بهم، والحرص على إقامتهم الصلاة؛ لأن من تركها كفر، أمر الصلاة عظيم، فعليك أن تجتهدي في نصيحتهم، أو بضربهم إن استطعت، فإن لم تستطيعي، ارفعي شأنهم لولاة الأمور، للهيئة، إذا كان ببلدكم هيئة، أو للمحكمة، أو للأمير، حتى يعينوك عليهم؛ لأن السكوت عنهم لا يجوز.  الله -جل وعلا- يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6].. ويقول الله -جل وعلا-: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132].. ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] وترك الصلاة من أعظم المنكرات. فالواجب العناية بهم، والحرص عليهم، ووعظهم، وتذكيرهم، ونصيحتهم، وتأديبهم إذا استطعت، أو أبوهم، إن كان له أبٌ موجود، أو أخٌ كبير يؤدبهم، فإن لم تستطيعي؛ فارفعي أمرهم إلى الإمارة، أو الهيئة، أو المحكمة. نعم.  المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16052/كيفية-التعامل-مع-الاولاد-الذين-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59103.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":17253,"question":"هذا أخونا السائل عبد السلام قداريه من الجزائر، يقول في هذا السؤال حفظكم الله: سماحة الشيخ! كيف يكون طلب العلم الدنيوي مثل الرياضيات، والفيزياء، والكيمياء، كيف يكون علمًا في سبيل الله؟ وهل الأحاديث الشريفة التي تحث على طلب العلم مثل: من سلك طريقًا يبتغي فيه علمًا؛ سهل الله له طريقًا إلى الجنة تعني العلم الأخروي فقط؟ أم العلم الدنيوي، والأخروي معًا؟ والسائل من الجزائر.","title":"ما العلم الذي وردت فيه الفضائل؟","answer":"الجواب: الأظهر من النصوص أن المراد بالأحاديث العلم الشرعي قوله ﷺ: من يرد الله به خيرًا يفقهه في الدين من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة المراد بالعلم إذا أطلق في النصوص العلم الشرعي؛ علم الكتاب والسنة، علم الأحكام، علم ما أمر الله به، وما شرع الله لعباده، وما نهاهم عنه، وعلوم الدنيا إذا كانت تنفع الناس لا بأس بها، علوم الدنيا من الطب، والحساب وغيرها، إذا تعلمها لينفع بها نفسه، وينفع بها الناس؛ لا بأس بها من باب المباح، أما العلوم الشرعية فهي سنة، وقربة، وإذا كانت تتعلق بالواجبات وجبت، فالنصوص التي فيها الحث على العلم المراد بها العلم الشرعي. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16085/ما-العلم-الذي-وردت-فيه-الفضاىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59207.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17272,"question":"سماحة الشيخ! هناك أناس يتصدرون للفتيا بغير علم كقول صاحبنا لهذه المسكينة: إنه لا أجر لك في صيام عشرة أيام من رجب، وعشرة أيام من شعبان، فما هو توجيهكم للناس حول هذا؟ جزاكم الله خيرًا.","title":"خطر الفتوى بغير علم","answer":"الجواب: الفتوى بغير علم منكر عظيم، وهو مما حرمه الله على عباده، وجعل مرتبته فوق الشرك، قال سبحانه في سورة الأعراف: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] فالواجب على طالب العلم أن يتقي الله، وأن يحذر القول على الله بغير علم، وإذا كان هذا في حق طالب العلم فكيف بغيره، لا يجوز لأحد أن يفتي بغير علم، لا رجل، ولا امرأة، ولا طالب علم، ولا غيره، يجب على المؤمن أن يتقي الله، وأن يخاف الله سبحانه، وألا يتكلم في الحلال والحرام إلا بعلم، قال الله سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علم. وأخبر سبحانه في سورة البقرة أن الفتوى بغير علم مما يأمر به الشيطان، قال تعالى: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:169] هذا من أمر الشيطان، يأمر الناس أن يقولوا على الله ما لا يعلمون. فالواجب على كل مؤمن ومؤمنة الحذر من طاعة الشيطان في القول على الله بغير علم، والفتوى بغير علم، لا في العبادات، ولا في غيرها، يقول الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] فالفتوى تكون من أهل الذكر، يعني: من أهل العلم بالقرآن العظيم، والسنة المطهرة، العلماء بكتاب الله، وسنة رسوله ﷺ وهم الذين يفتون الناس، وهم الذين يسألون، نسأل الله للجميع الهداية، نسأل الله لنا ولإخواننا جميعًا الهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16115/خطر-الفتوى-بغير-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76808.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17358,"question":"نعود في بداية هذه الحلقة إلى رسالة الأخت المستمعة (ف. ح. م) المطيري، أختنا عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها عدد من الأسئلة في أحدها تقول: إن لي أخًا يبلغ من العمر عشر سنوات، يتكلم على أمي، ويتلفظ عليها بعبارات غير لائقة؛ لأنها تأمره بالصلاة، وطاعة الله، فأنا أضربه ضربًا شديدًا، وأحيانًا أضربه؛ لأنه لا يذاكر دروسه، أو لأنه يأخذ شيئًا دون أن تعلم به أمي، وأحيانًا أكويه بالنار، فهل أكون آثمة في فعلي هذا؟ جزاكم الله خيرًا.","title":"حكم ضرب الأخ لتركه الصلاة وعصيان أمه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.. أما بعد.  فأنت جزاك الله خيرًا مأجورة على اجتهادك، وحرصك على صلاحه، وعلى تأدبه مع والدته، وعلى بره لها، ولا حرج عليك في تأديبه، وضربه حتى يستقيم، وحتى يقوم بما يلزم من جهة والدته. والحاصل: أنك مأجورة في ضربه حتى يصلي، وحتى يذاكر في دروسه، وحتى لا يتكلم على والدته بما لا ينبغي، كل هذا أنت مأجورة عليه، وإذا كان أبوه موجودًا فالواجب على أبيه أن يقوم بهذه المهمة، أو أخوه الكبير حتى يتساعد معك بذلك، وإذا كان أبوه يقوم بالواجب؛ كفى عنك. فالحاصل: أن الواجب على أبيه إن كان موجودًا، أو أخيه الكبير إن كان موجودًا أن يقوم بذلك، وإن قامت أمه بذلك فلا بأس، وإذا لم تقم به أمه، ولم يقم بذلك أحد غيرك فأنت مأجورة على ذلك، وجزاك الله خيرًا، لكن لا تكويه بالنار، أما الكي بالنار فلا يجوز. وإذا كان يأخذ شيئًا يسيرًا من المال لحاجة الأطفال فينبغي التسامح بهذا، أما الشيء الذي قد يضر الوالدة، أو قد يعوده السرقة فلا مانع من ضربك له ضربًا خفيفًا، لا تضربيه ضربًا خطيرًا لا في الصلاة، ولا في غيرها، ضربًا خفيفًا يؤلمه، ويردعه، ولكن ليس فيه خطر، بارك الله فيك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16193/حكم-ضرب-الاخ-لتركه-الصلاة-وعصيان-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83401.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":17402,"question":"سماحة الشيخ! هذه السائلة أختنا استعرضنا سؤالًا لها في حلقة سابقة، بقي لها هذا السؤال تقول: سماحة الشيخ! ما حكم سفر الطالبات إلى ما يزيد عن الثمانين كيلو مترًا؛ وذلك طلبًا للعلم، مع العلم بأن ذلك يكون في باص به حوالي ما يقارب من خمسين طالبة، وذلك لا يتطلب المبيت، وإنما العودة في نفس اليوم، وكذلك بالنسبة للمدرسات؟ جزاكم الله خيرًا.","title":"حكم سفر الطالبات لطلب العلم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالحكم في هذا أنه لا يجوز سفر النساء بغير محرم، لا طالبات، ولا مدرسات، هذا هو المعروف في الأحاديث الصحيحة، يقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم.  فالواجب على الطالبات أن يكون طلبهن في البلد، وهكذا المدرسات في البلد، أما السفر بدون محرم فلا يجوز. بعض أهل العلم رخص في ذلك إذا كان الطريق آمنًا، وليس فيه خطر عند الحاجة، ولكن ظاهر الأحاديث الصحيحة تمنع ذلك؛ لأنه ﷺ قال: لا تسافر امرأة إلا مع ذي محرم ولم يستثن، عليه -الصلاة والسلام- نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16257/حكم-سفر-الطالبات-لطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77101.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":17418,"question":"سماحة الشيخ! من حوطة بني تميم السائل الذي رمز لاسمه بـ (ف. ش. ك) يذكر بأنه شاب يبلغ من العمر الخامسة عشرة، ويرغب في طلب العلم الشرعي، فما هي نصيحتكم سماحة الشيخ لمثل هذا؟ وما هي الأمور التي لابد أن يعملها، ويتمثل بها؟ يقول: علمًا بأن مدينتنا قليلة من الدعاة، وطلبة العلم، جزاكم الله خيرًا.","title":"بيان كيفية طلب العلم","answer":"الجواب: نوصيه بطلب العلم في المدارس التي فتحتها الحكومة المتوسطة، والثانوي، أو المعاهد العلمية ... يجتهد حتى يلحق بها، وإذا كان عندهم حلقات علم لأهل العلم من القضاة، أو غيرهم يحضر حلقات العلم إذا تيسر في الليل، أو في النهار يجمع بين هذا وهذا، يلتحق بالمدارس النظامية، ويجتهد، ويقرأ على العلماء في بلده إذا كان عندهم حلقات علم في الليل، أو في النهار، يحضر الحلقات، ويستفيد، ويجتهد في حفظ القرآن الكريم، وحفظ الكتب النافعة، مثل كتاب التوحيد، كشف الشبهات، ثلاثة الأصول، والقواعد الأربع للشيخ محمد -رحمه الله- محمد بن عبد الوهاب، وكذلك العقيدة الواسطية لشيخ الإسلام ابن تيمية، هذه كتب جيدة مهمة يحفظها، ومثل الأربعين النووية، وتكملتها لابن رجب خمسين حديثًا من جوامع الكلم، يحفظ هذه الأحاديث العظيمة، والنافعة.  على كل حال، فالوصية لهذا الشاب أن يجتهد في طلب العلم في المدارس النظامية، وعلى المشايخ إذا كان عنده من يقرأ عليه من المشايخ في حلقات العلم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16293/بيان-كيفية-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77119.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17422,"question":"سماحة الشيخ! من حوطة بني تميم السائل الذي رمز لاسمه بـ (ف. ش. ك) يذكر بأنه شاب يبلغ من العمر الخامسة عشرة، ويرغب في طلب العلم الشرعي، فما هي نصيحتكم سماحة الشيخ لمثل هذا؟ وما هي الأمور التي لابد أن يعملها، ويتمثل بها؟ يقول: علمًا بأن مدينتنا قليلة من الدعاة، وطلبة العلم، جزاكم الله خيرًا.","title":"بيان كيفية طلب العلم","answer":"الجواب: نوصيه بطلب العلم في المدارس التي فتحتها الحكومة المتوسطة، والثانوي، أو المعاهد العلمية ... يجتهد حتى يلحق بها، وإذا كان عندهم حلقات علم لأهل العلم من القضاة، أو غيرهم يحضر حلقات العلم إذا تيسر في الليل، أو في النهار يجمع بين هذا وهذا، يلتحق بالمدارس النظامية، ويجتهد، ويقرأ على العلماء في بلده إذا كان عندهم حلقات علم في الليل، أو في النهار، يحضر الحلقات، ويستفيد، ويجتهد في حفظ القرآن الكريم، وحفظ الكتب النافعة، مثل كتاب التوحيد، كشف الشبهات، ثلاثة الأصول، والقواعد الأربع للشيخ محمد -رحمه الله- محمد بن عبد الوهاب، وكذلك العقيدة الواسطية لشيخ الإسلام ابن تيمية، هذه كتب جيدة مهمة يحفظها، ومثل الأربعين النووية، وتكملتها لابن رجب خمسين حديثًا من جوامع الكلم، يحفظ هذه الأحاديث العظيمة، والنافعة.  على كل حال، فالوصية لهذا الشاب أن يجتهد في طلب العلم في المدارس النظامية، وعلى المشايخ إذا كان عنده من يقرأ عليه من المشايخ في حلقات العلم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16293/بيان-كيفية-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77119.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17444,"question":"رسالة من الطالب (خالد . م. ص. غ) من المملكة، أخونا يقول: أنا طالب علم، انتهيت من الثانوية، في قريتي لا يوجد فرع للجامعة التي أسكن فيها، لذلك فأنا مضطر للسفر إلى مدينة تبعد عن قريتنا ما يقرب من ستمائة كيلو مترًا، أبي غير موافق على سفري، فهل إذا سافرت للدراسة والوالد غير راضٍ أكون آثمًا؟ أو لا؟","title":"حكم السفر لطلب العلم بدون موافقة الأب","answer":"الجواب: هذا فيه تفصيل: فإن كان الوالد في حاجة إليك؛ فالواجب عليك أن تبقى عند والدك، وتقوم بحاجته، فبره واجب، والمزيد من طلب العلم مستحب، وفي إمكانك أن تزداد من العلم من طريق سماع نور على الدرب، وسماع المحاضرات التي تذاع من إذاعة القرآن، وسماع العلم من المحاضرات في بلدك، وخطبة الجمعة في بلدك. أما إذا كان الوالد عنده من يقوم بحاجاته من إخوانك، ولا يحتاج إليك، فإنك لا حرج عليك أن تسافر لإكمال العلم، والواجب على أبيك أن يساعدك في هذا، وألا يحرجك؛ لأن طلب العلم من أهم المهمات، ومن أفضل القربات، والنبي  قال: إنما الطاعة في المعروف وليس من المعروف أن يمنعك من طلب العلم بدون حق، ودون حاجة، أما إذا كان محتاجًا لك فبره أوجب، نسأل الله للجميع التوفيق.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16299/حكم-السفر-لطلب-العلم-بدون-موافقة-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83603.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17502,"question":"في آخر أسئلة هذه السائلة تقول: ما حكم من يقرأ القرآن، ويريد أن يحفظه وهو لا يعرف أحكام التجويد ولا يعطي الحروف حقها أثناء التلاوة لظروف أو أسباب صعبة جدًا لا تسمح له بالتعلم أفيدونا مأجورين؟","title":"حكم حفظ القرآن مع وجود الأخطاء","answer":"الجواب: مأجور هذا، مأجور إن شاء الله، ينبغي له أن يجتهد في حفظ القرآن، وقراءة القرآن، ولو حصل بعض التتعتع وبعض الأغلاط يجتهد، وإذا تيسر له أحد يقرأ عليه بعض الأحيان ويستفيد هذا طيب، يقول النبي ﷺ: الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق ويتتعتع فيه له أجران، فالفضل من الله جل وعلا، فالإنسان يتعلم القرآن، ويقرأ، ولو تتعتع، ولو حصل منه بعض الأغلاط حتى يستفيد، وإذا تيسر له في بعض الأوقات من يقرأ عليه، ويستفيد منه؛ فعل ذلك، والحمد لله. نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16415/حكم-حفظ-القران-مع-وجود-الاخطاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77407.mp3","categories":["العالم والمتعلم","القرآن وعلومه"]},{"id":17592,"question":"يقول: إنني تابعت أحد القراء في إذاعة القرآن الكريم وصححت قراءتي كما سمعته، فهل ما فعلته صحيحًا؟","title":"حكم متابعة القراء لتصحيح التلاوة","answer":"الجواب: كل هذا طيب، متابعة القراء الطيبين والاستفادة من قراءتهم هذا طيب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16518/حكم-متابعة-القراء-لتصحيح-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84105.mp3","categories":["العالم والمتعلم","القرآن وعلومه"]},{"id":17738,"question":"سماحة الشيخ هذه السائلة للبرنامج تقول: ما حكم قبول الهدايا من الطالبات؟ جزاكم الله خيرًا.","title":"حكم قبول الهدايا من الطلاب","answer":"الجواب: الأقرب- والله أعلم- أنه لا ينبغي قبولها؛ لأنها قد تكون رشوة، فالذي ينبغي ترك القبول، وتعليمهم عدم الإهداء؛ لأن الهدية إذا جاءت المعلمة أو المعلم قد تفضي به إلى الغش والمحاباة لهذا الذي أهدى، فالأحوط والذي ينبغي ترك ذلك.","link":"https://binbaz.org.sa/fatwas/16694/حكم-قبول-الهدايا-من-الطلاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17763,"question":"هذا السائل يقول: قراءة الكتب الإسلامية بدون معلم، هل هي مفيدة، وأرجو أن تذكروا بعض الكتب التي تنصحوننا باقتنائها وقراءتها ويعتمد عليها؟","title":"نصيحة حول قراءة الكتب الدينية وبيان أفضلها","answer":"الجواب: قراءة الكتب فيها تفصيل: أما قراءة الكتب للتعلم، فلا بد أن يقرأها الإنسان على أهل العلم؛ حتى يعلموه ويفقهوه، أما قراءتها للحفظ حتى يستفيد منها ويسأل أهل العلم؛ فهذا طيب، ولكن أهم شيء القرآن، كونه يحفظ القرآن هذا أهم شيء، القرآن هو أصل كل خير، وهو أصدق كتاب وأفضل كتاب، إذا تيسر حفظه؛ فهو مقدم على كل شيء، ومن لم يحفظه يستحب له الإكثار من قراءته، يستحب الإكثار من قراءته، للرجل والمرأة في الليل والنهار؛ لما فيه من العلم العظيم والدعوة إلى الخير، فيستحب لكل مؤمن ومؤمنة الإكثار من قراءة القرآن الكريم من المصحف أو عن ظهر قلب.\nأما الكتب الأخرى: فإذا تيسر له حفظ كتاب التوحيد للشيخ محمد بن عبد الوهاب رحمه الله في العقيدة، كشف الشبهات له في العقيدة، ثلاثة الأصول له في العقيدة، والقواعد الأربع، شروط الصلاة كتاب جيد مختصر، العقيدة الواسطية، حفظ هذه جيد ينفع، بلوغ المرام في الحديث للحافظ ابن حجر ، عمدة الحديث للحافظ عبد الغني بن سرور المقدسي كتاب طيب إذا تيسر حفظه، الأربعين النووية وتتمتها لـابن رجب خمسين حديثًا هذه جيدة إذا تيسر حفظها، هذا طيب. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16738/نصيحة-حول-قراءة-الكتب-الدينية-وبيان-افضلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59619.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":17766,"question":"نبدأ هذا اللقاء الطيب المبارك برسالة الجزائر (س. ح) رمز لاسمه بهذا الاسم البليدة يقول في هذا  سماحة الشيخ! ما هو العلم الواجب؟ هل هو الديني؟ أم الدنيوي؟ أم معًا؟ أفيدونا مأجورين وجزاكم الله خيرًا.","title":"العلم الواجب على المكلف","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفإن العلم علمان: علم ديني، وعلم دنيوي.\nفالعلم الديني واجب على كل مكلف أن يتعلم ما أوجب الله عليه، وما حرم الله عليه، وما لا يسعه جهله كما نص على ذلك أهل العلم، فالواجب على كل مكلف من الرجال والنساء أن يتعلم ما أوجب الله عليه، وأن يتفقه في دينه فيعرف ما أوجب الله من صلاة وغيرها ويعرف ما حرم الله عليه من الشرك وغيره حتى يعبد ربه على بصيرة، ويعبر كثير من أهل العلم بقولهم: يجب على المكلف أن يتعلم من دينه ما لا يسعه جهله، والمعنى: أن يتعلم ما أوجب الله عليه، وما حرم الله عليه، فيتعلم معنى لا إله إلا الله وايش معناها، وايش معنى شهادة أن محمدًا رسول الله، ما هي الصلاة؟ ما هي الزكاة؟ ما هو صوم رمضان؟ ما هو الحج؟ يتعلم هذه الأشياء اللي أوجبها الله عليه.\nويتعلم الأشياء اللي حرم الله ما هو الزنا؟ ما هو الربا؟ ما هو المسكر؟ يتعلم حتى يعرف الواجب فيؤديه، وحتى يعرف المحرم فيجتنبه حسب الطاقة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] يتعلم حسب الطاقة بسؤال أهل العلم بقراءة القرآن، والتفقه فيه، بقراءة الأحاديث عن النبي ﷺ، بحضور حلقات العلم، بالسؤال من طريق المكاتبة، من طريق التلفون، يجتهد حسب الطاقة، يلزمه أن يتعلم حسب الطاقة، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، لا يسكت ولا يرضى بالجهل بل يتعلم؛ لأنه مخلوق لعبادة الله كما قال الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ[الذاريات:56] مأمورون بذلك، يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ[البقرة:21]، فهذه العبادة التي خلق لها وهو مأمور بها يجب أن يعرفها، ما هي العبادة؟ يجب أن يتعلم حتى يعرف هذه العبادة التي خلق لها، وأوجبها الله عليه، وهي: أداء فرائض الله، وترك محارم الله.\nوأصلها وأساسها توحيد الله، والإخلاص له، والإيمان به وبرسوله محمد ﷺ، والإيمان بكل ما أخبر الله به ورسوله مما كان وما يكون من أمر الآخرة، والجنة والنار، والحساب والجزاء، وما مضى من خلق الله آدم، وبعث الرسل يؤمن بكل ما أخبر الله به ورسوله عن بصيرة، ويعلم أن هذا حق، ويعمل فيؤدي ما أوجب الله، وينتهي عما حرم الله، هذا واجب عليه حسب الطاقة من طريق حلقات العلم، من طريق تدبر القرآن، من طريق حفظ السنة، من طريق سؤال أهل العلم، من طريق المكاتبة ... إلى غير ذلك، لا يغفل ولا يتساهل.\nأما القسم الثاني: علوم الدنيا فيتعلم منها ما يعينه على كسب المعيشة، على سد فاقته حتى يقوم بما أوجب الله عليه، كيف يبيع، كيف يشتري، كيف يعمل ما يسبب الرزق الذي يقوم بحاله، لا يجلس في بيته وبس، لا بد يتعلم الشيء الذي يستعين به على طاعة ربه، أي علم .... ويباح يحصل به له الرزق الكافي الحمد لله، وإذا لم يعرف يسأل، يسأل أهل البصيرة من جيرانه ... من أقربائه ... من زملائه حتى يتعلم شيئًا ينتفع به بيع أو شراء، أو يؤجر نفسه، أو يحتطب أو يحش، كانوا في عهد النبي ﷺ يتعلمون، وكثير منهم يذهب إلى البرية، ويأتي بالحطب، يأتي بالحشيش يبيع، وينقذ نفسه وينقذ من تحت يده، وبعضهم يذهب ويحمل الحطب ونحوه، ويأتي ويبيع ويتصدق على الفقراء لما أمر النبي ﷺ بالصدقة صار كثير من الصحابة يحمل على ظهره لحاجات الناس، ثم يتصدق بالأجرة، فعلى المسلم أن يتعلم من الدنيا ما يعينه على سد خلته وحاجته في كسوة وطعام وسكن وغير ذلك، ويتعلم ما يعينه على القيام بحاجة أهله.\nفعليه علمان وعملان: علم الآخرة وهو الأهم وهو الأوجب أن يتعلم دينه، ويتفقه في دينه، ويعمل بما أوجب الله عليه، وينتهي عما حرم الله عليه، وعليه أيضًا علم ثاني وعمل ثاني وهو التعلم لما يحصل به الرزق والكفاف، والقيام بحاجة أهله من أمور الدنيا، ويعمل بذلك من كونه يحتطب، كونه يحتش، كونه يبيع، كونه يشتري، كونه يؤجر نفسه ... إلى غير هذا يتعلم الأسباب التي يحصل بها الرزق الكافي الذي يقوم بحاله، وحال من تحت يديه، والله ولي التوفيق.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء سماحة الشيخ! تعلم العلوم الأخرى يا سماحة الشيخ الفيزياء.. الكيمياء وغيرها؟\nالشيخ: الشيء اللي ينفع الناس ولا فيه محذور يتعلمه، حساب.. فيزياء الشيء اللي فيه مصلحة للمسلمين يتعلمه، ولا حرج فيه، إذا لم يكن فيه محذور شرعًا، فالعلوم التي يستعان بها على أمر الدين أو الدنيا وليس فيها منكر لا بأس به سواء كانت من علوم الأولين، أو من علوم الآخرين، أي علم ينفع الناس وليس فيه ما يغضب الله، ليس فيه ربا، وليس فيه معصية، وليس فيه غش للناس إنما هي علوم تنفع، ويحتاجها بعض الناس، وليس فيها غش لأحد، ولا ظلم لأحد، ولا ركوب لمعصية لا حرج فيها والحمد لله.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16749/العلم-الواجب-على-المكلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77801.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17832,"question":"من أسئلة هذا السائل يقول: في كثير من البيوت أولاد بالغين، والآباء يذهبون إلى المسجد للصلوات، وهؤلاء الأولاد البالغين في الصلاة: إما نيام أو مشغولين، ولا يأمرونهم بالصلاة، فهل من كلمة لمثل هؤلاء سماحة الشيخ للآباء؟","title":"نصيحة للمتساهلين مع أبنائهم في أمر الصلاة","answer":"الجواب: هذا لا يجوز، بل الواجب على الآباء أن يأمروهم، على آبائهم وأمهاتهم وإخوانهم الكبار أن يأمروهم ويلزموهم بالصلاة، ويضربوهم -أيضًا- حتى يصلوا مع الناس في المساجد، يقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فإذا كان فوق العشر أشد وأشد، فالواجب على الآباء أن يأمروهم وأن يحرضوهم وأن يعاقبوهم أيضًا، وهكذا إخوتهم الكبار. نعم.","link":"https://binbaz.org.sa/fatwas/16824/نصيحة-للمتساهلين-مع-ابناىهم-في-امر-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59729.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":17942,"question":"هذا سائل يقول يا فضيلة الشيخ: بالنسبة للرجل الذي ليس عنده علم شرعي كيف يطلب العلم الشرعي؟ وما هو المحدد له من هذا العلم الشرعي؟","title":"كيفية طلب العلم الشرعي","answer":"الجواب: يحضر حلقات العلم عند أهل العلم، أو في دور العلم التي فيها دروس معينة في أوقات معينة، يجتهد، وإذا كان ما يستطيع، في حلقات العلم في المساجد، يحضرها ويستفيد ويسأل، ويعتني بالقرآن ويكثر من تلاوته، لعل الله جل وعلا ينفعه بذلك.","link":"https://binbaz.org.sa/fatwas/16946/كيفية-طلب-العلم-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59826.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":17954,"question":"هذا السائل عوض أحمد القرني يستفسر ويقول سماحة الشيخ: ما هي أفضل الكتب التي تنصحوننا باقتنائها في قصص الأنبياء وفي حياة الصحابة؟","title":"كتب ينصح باقتنائها","answer":"الجواب: الكتب كثيرة لكن من أفضل الكتب للاقتناء تفسير ابن كثير، وتفسير ابن جرير، وتفسير البغوي، والشوكاني هذه كلها كتب مفيدة نافعة.\nوفي الحديث: الصحيحان؛ صحيح البخاري وصحيح مسلم، منتقى الأخبار، بلوغ المرام، عمدة الحديث، جامع العلوم والحكم لابن رجب، هذه كتب مفيدة، فتح المجيد في العقيدة للشيخ عبد الرحمن بن حسن، كتاب التوحيد للشيخ محمد بن عبد الوهاب رحمه الله، كشف الشبهات للشيخ محمد رحمه الله، ثلاثة الأصول وشروط الصلاة، والقواعد الأربع للشيخ محمد رحمه الله كتاب صغير مفيد جدًا، والعقيدة الواسطية لشيخ الإسلام ابن تيمية رحمه الله، الترغيب والترهيب للحافظ المنذري، رياض الصالحين للنووي رحمه الله، هذه كتب مفيدة، التخويف من النار للحافظ ابن رجب، أهوال القبور للحافظ ابن رجب فيه مواعظ وتذكير. نعم.\nالمقدم: أحسن الله إليك وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16970/كتب-ينصح-باقتناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78016.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17983,"question":"هل يجوز للإنسان المسلم الاشتغال بالعلوم الدنيوية، كالفيزياء، والرياضيات، والكيمياء، بحيث لا تشغله عن الصلاة، وعن ذكر الله؟","title":"حكم اشتغال المسلم بالعلوم الدنيوية","answer":"الجواب: لا حرج، الاشتغال بالعلوم الدنيوية التي قد ينتفع بها الإنسان؛ هذا لا حرج فيه. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16991/حكم-اشتغال-المسلم-بالعلوم-الدنيوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72905.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18014,"question":"المستمع إبراهيم حسين من ضياء بعث يسأل ويقول: ولدي تارك للصلاة، قلت له: إذا لم تصل فحرام علي أن أحادثك، لكني لم أصبر وحادثته، فماذا علي؟","title":"كيفية تعامل الأب مع ابنه التارك للصلاة","answer":"الجواب: يجب عليك أن تنكر عليه، وأن تؤدبه على ذلك بالضرب حتى يصلي، وعليك أن تهجره أيضًا؛ لأنه مستحق لذلك والصلاة عمود الإسلام من تركها كفر نسأل الله العافية، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، في أحاديث أخرى تدل على كفر تارك الصلاة. فالواجب عليك الإنكار عليه والتشديد عليه في ذلك حتى يصلي، وهجره من أهم المهمات إذا لم تنفع فيه النصيحة، وإذا استطعت تأديبه بالضرب فلك أن تؤدبه بل عليك أن تؤدبه، فإذا كان الصغير يضرب عليها إذا بلغ عشرًا فالكبير يضرب أشد إذا تركها، ولك أن ترفع أمره إلى ولاة الأمور حتى يستتاب فإن تاب وإلا قتل كافرًا، لكن مهما أمكن أن تستر عليه وأن تنصحه حتى يستقيم قبل أن يرفع إلى ولي الأمر فلعل الله يهديه بأسبابك، ولك أن تعمل ما تستطيع من الأسباب من هجر وضرب وغير ذلك من الأسباب التي تراها مجدية ونافعة في طلب هدايته، نسأل الله أن يهديه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17053/كيفية-تعامل-الاب-مع-ابنه-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85006.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":18137,"question":"السائل من الكويت يقول: كيف تكون المعاملة الصحيحة مع الأبناء حتى يكونون ملتزمين بأمور دينهم الحنيف؟فهل علي أن أجبرهم على الذهاب إلى المسجد في كل فرض؟ علمًا بأنهم في كثير من الفروض يصلونها في المسجد إلا أن النوم في بعض الأحيان يأخذهم، وإنهم في بعض الأوقات يؤخرون الصلاة عن وقتها، بعضهم وصل إلى سن البلوغ.وكيف أحببهم بالدين الإسلامي الصحيح، وبالصحبة الصالحة؟ وجهونا سماحة الشيخ عبد العزيز.","title":"الوسائل المعينة على التربية الصحيحة للأبناء","answer":"الجواب: الواجب عليك أن تأمرهم بالصلاة، وأن تلزمهم بذلك حتى يصلوا مع الناس، ولا يصلوا في البيت، بل عليهم أن يصلوا مع الناس، يقول النبي ﷺ: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع فكيف إذا بلغ الحلم؟ الأمر أعظم. فالمقصود أن الواجب عليك أن تأمرهم وأن تلزمهم بالصلاة في الجماعة، وأن تؤدب من تخلف، ولا تضعف في هذا، وعليك أن تنصحهم، وتعظهم، وتذكرهم بالقرآن والحديث، وتحثهم على صحبة الأخيار الطيبين؛ حتى يساعدوك في هذا، ولا تغفل عن هذا الشيء، ولا تتساهل فالأمر عظيم، وهم في ذمتك. نعم.","link":"https://binbaz.org.sa/fatwas/17183/الوساىل-المعينة-على-التربية-الصحيحة-للابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78115.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":18334,"question":"هذه رسالة وصلتنا من الأردن من السائل جاهد ذيب يقول: بماذا ينصح سماحة الشيخ طالب العلم أن يبدأ هل يبدأ -يقول- في المرحلة الأولى والثانية والثالثة في متون الفقه وأصول الفقه، ومصطلح الحديث، وفقه الحديث، والعقيدة، والنحو، والتفسير، بماذا يبدأ طالب العلم في هذه المرحلة؟","title":"نصيحة لطالب علم مبتدئ","answer":"الجواب: يبدأ بالقرآن، يجتهد في القرآن يبدأ، ثم كتب العقيدة، مثل: العقيدة الواسطية يحفظها، كتاب التوحيد للشيخ محمد بن عبدالوهاب، مثل كشف الشبهات، ثلاثة الأصول، يحفظ هذه الكتب المختصرة في العقيدة. ثم كتب الحديث؛ كبلوغ المرام، عمدة الحديث، الأربعين النووية، تتمتها لابن رجب؛ كتب جيدة، ثم الفقه. نعم. المقدم: أحسن الله إليكم وبارك فيكم، بالنسبة يا فضيلة الشيخ للنحو والتفسير يقول؟ الشيخ: ..... بأصول الفقه ومصطلح الحديث والنحو كل هذا طيب، لكن بعد العناية بالقرآن والعناية بكتب العقيدة وكتب الحديث، أما مصطلح الحديث يقرأ مصطلح الحديث مع الحديث، وأصول الفقه مع الفقه، والنحو كذلك يتعلم النحو؛ لأنه يعينه على طلب العلم.","link":"https://binbaz.org.sa/fatwas/17387/نصيحة-لطالب-علم-مبتدى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91317.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":18366,"question":"فضيلة الشيخ يقول هذا السائل: كيف يكون تربية الأولاد؟ وكيف يتم تعليمهم على الصلوات إذا كانوا قد نشؤوا نشأة غير صالحة؟","title":"وجوب المجاهدة والصبر في تربية الأولاد","answer":"الجواب: بالمجاهدة يجاهدهم والدهم وأخوهم الأكبر حتى يستقيموا على طاعة الله، يجاهدوهم بالكلام الطيب والتأديب حتى يستقيموا على الصلاة وعلى الأخلاق الطيبة، لابد من مجاهدة وصبر، يقول جل وعلا: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69]، ويقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6]، ويقول النبي ﷺ: كلكم راعي وكلكم مسئول عن رعيته، فالإمام راع ومسئول عن رعيته، والرجل راع في أهل بيته ومسئول عن رعيته لابد من الصبر. المقدم: بارك الله فيكم ونفع الله بعلمكم.","link":"https://binbaz.org.sa/fatwas/17431/وجوب-المجاهدة-والصبر-في-تربية-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91327.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":18398,"question":"هذا المستمع من اليمن صنعاء يقول يا سماحة الشيخ: هل يجوز الخروج لطلب العلم بدون إذن الوالدين، إذا كان الطالب لا يتمكن من تحصيل العلم في بلد الوالدين، علمًا بأن له إخوة قد يقومون بخدمة الوالدين؟ وجهونا في ضوء ذلك.","title":"حكم استئذان الوالدين في السفر لطلب العلم","answer":"الجواب: نعم، إذا كان هناك من يقوم بخدمتهما يخرج في طلب العلم يلزمه الخروج لطلب العلم والتفقه في الدين، أما إذا كانا في حاجة إليه وضرورة إليه فيبقى عندهما ويطلب العلم في البلد، يجمع بين المصلحتين. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17462/حكم-استىذان-الوالدين-في-السفر-لطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91330.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18399,"question":"يقول هذا السائل: يا سماحة الشيخ! هل يجوز لطالب العلم أن يؤجل الزواج ليتفرغ لطلب العلم؟","title":"حكم تأخير الزواج بسبب الاشتغال بطلب العلم","answer":"الجواب: نعم، له أن يؤجل الزواج ليتفرغ لطلب العلم ويجتهد في طلب العلم والتفقه في الدين، إذا كان لا يخشى فتنة، أما إن كان يخشى الفتنة فليبادر بالزواج. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17465/حكم-تاخير-الزواج-بسبب-الاشتغال-بطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91331.mp3","categories":["حكم الزواج وأهميته","العالم والمتعلم"]},{"id":18582,"question":"تقول السائلة من جدة: هل يجوز لطالب العلم أن يترك والدته وحيدة ويذهب لطلب العلم الشرعي؟","title":"حكم ترك أحد الوالدين للذهاب لطلب العلم","answer":"الجواب: هذا فيه تفصيل، إذا كان عندها من يقوم بحالها، ويخدمها، ويقضي حاجاتها؛ لا بأس؛ لأن طلب العلم واجب، فعليه أن يؤمن حاجاتها، ويذهب لطلب العلم، ولا بأس ولا حرج، والحمد لله، نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/17706/حكم-ترك-احد-الوالدين-للذهاب-لطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78624.mp3","categories":["بر الوالدين","العالم والمتعلم"]},{"id":18644,"question":"رسالة وصلت إلى البرنامج من المستمع: (س. ع. د) أخونا قضيته في الواقع أيضًا نهايتها يطلب من سماحة الشيخ إذا أمكن أن ترسل له بعض الكتب، كتفسير ابن كثير، وفتح الباري، وصحيح مسلم، والفتاوى الكبرى، إذا أمكن ذلك شيخ عبد العزيز.","title":"طلب إرسال بعض الكتب","answer":"الجواب: لا مانع من إرسال الكتب بعد أن ترسل كتابًا -رسالة منك إليّ مصحوبة بمؤهلاتك- وبعد هذا ننظر في الموضوع، هل مؤهلاته موجودة الآن مؤهلاته؟ المقدم: لم يرفق شيء. الشيخ: لا بد من إرفاق المؤهلات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17759/طلب-ارسال-بعض-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91904.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18715,"question":"في آخر أسئلة هذه السائلة تقول: سماحة الشيخ: هل خروج المرأة لتلقي العلم الشرعي والتدريس في المدارس منافٍ لقوله تعالى: وَقَرْنَ فِي بُيُوتِكُنَّ[الأحزاب:33]؟","title":"حكم خروج المرأة لطلب العلم والتدريس","answer":"الجواب: لا خروجها للتعلم لا، خرجوها للمدرسة ليس مخالفاً لهذا، مأمورة بالخروج للدراسة، ومأمورة بالخروج لصلاة العيد مع المسلمين، وإذا خرجت متسترة لسماع خطبة الجمعة، أو للصلاة مع الناس؛ لا بأس كما قال ﷺ في الحديث الصحيح: لا تمنعوا إماء الله مساجد الله لكن بيتها خير لها كما في الحديث: بيوتهن خير لهن وإذا خرجت للتعلم في المدارس فلا بأس هذا فيه فائدة عظيمة، لكن يكون بإذن زوجها، تستأذن زوجها هذا إذا كان لها زوج، نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/17833/حكم-خروج-المراة-لطلب-العلم-والتدريس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78817.mp3","categories":["قضايا المرأة","العالم والمتعلم"]},{"id":18735,"question":"السائل والذي أرسل بمجموعة من الأسئلة صالح سعد من اليمن، يقول في هذا  كثيرًا سماحة الشيخ ما نسمع عن العقيدة الواسطية، فلا ندري ما معنى الواسطية، فهل يعني بذلك: العقيدة الصحيحة، أم ماذا يعني؟وجهونا في ضوء سؤالنا فنحن مجموعة من طلاب العلم.","title":"معنى \"العقيدة الواسطية\"","answer":"الجواب: العقيدة الواسطية كتاب ألفه أبو العباس أحمد بن عبد الحليم بن عبد السلام ابن تيمية الحراني، الملقب بشيخ الإسلام ابن تيمية، والملقب تقي الدين، المولود سنة إحدى وستين وستمائة، والمتوفى سنة ثمان وعشرين وسبعمائة، وهو من الأئمة المجتهدين، ومن أهل السنة والجماعة، بل هو من أئمة أهل السنة والجماعة -رحمه الله- وله المؤلفات الكثيرة منها: منهاج السنة في الرد على المعتزلة والرافضة، ومنها: كتابه اقتضاء الصراط المستقيم مخالفة أصحاب الجحيم، ومنها: كتابه العقيدة الواسطية. سميت الواسطية؛ لأنه كتبها إلى أهل واسط في العراق، كتبها إليهم، فقيل لها: الواسطية؛ لأنه كتبها إلى جماعة سألوه من أهل واسط، فقيل لها: الواسطية، وله رسالة أخرى في العقيدة يقال لها: الحموية، كتبها إلى أهل حماة في الشام، وله رسالة أخرى ثالثة في الصفات تسمى التدمرية، كتبها إلى أهل تدمر في بلاد الشام. هذا أسباب التسمية، واسطية؛ لأن العقيدة كتبت إلى أهل واسط، وحموية؛ عقيدة كتبت إلى أهل حماة، وتدمرية عقيدة كتبت إلى أهل تدمر، وهي كتب ثلاثة عظيمة في عقيدة أهل السنة والجماعة مفيدة، نوصي بقراءتها، والاستفادة منها، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17862/معنى-العقيدة-الواسطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78913.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18739,"question":"أخت تقول: المرسلة: (ن. م) تسأل سؤالين، في سؤالها الأول تقول: إنني ممن يستمعون لبرنامجكم هذا والحمد لله، وأقوم بتسجيل كل حلقة على شريط؛ لكي يكون مرجعًا لي، ولمن يريد حل مشكلة قد تعرض لها، أو حكم يتمنوه، فهل هذا العمل أستمر عليه أم لا؟ علمًا بأنني أنظم تسجيل الحلقات؛ لكي لا يكون اختلاط في الحروف.","title":"الاهتمام بحلقات نور على الدرب وتسجيلها","answer":"الجواب:   هذا عمل طيب، وأنت مأجورة، شكر الله لك سعيك؛ لأن هذا من باب تحصيل العلم، ومن باب حفظ العلم لك ولغيرك، تسجيل مثل هذه البرامج فيه خير كثير، وفيه فائدة كثيرة، فاستمري على هذا، وأبشري بالخير. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17879/الاهتمام-بحلقات-نور-على-الدرب-وتسجيلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87507.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18775,"question":"سماحة الشيخ يستفسر عن كتاب الدعاء المستجاب في الحديث والكتاب يقول: ورد فيه مجموعة من الأحاديث، وأورد هذا الحديث الذي ذكرتم عنه، ويقول أيضًا ورد فيه هذا الحديث قال النبي ﷺ: من قلم أظافره يوم الجمعة وقي من السوء مثلها","title":"تقييم كتاب الدعاء المستجاب","answer":"الجواب: هذا كتاب لا يعتمد عليه؛ لأنه يروي الغث والسمين، لا يعتمد عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17901/تقييم-كتاب-الدعاء-المستجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79107.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18851,"question":"يسأل أخونا أيضًا ويقول: هل كتاب رياض السامعين وبستان الواعظين صحيح، ذلكم أني رأيت فيه كثيرًا من الترهيب الشديد؟","title":"تقييم كتاب رياض السامعين وبستان الواعظين","answer":"الجواب: لست أعرف الكتاب المذكور، ليس عندي علم بالكتاب المذكور، ولكن يغني عنه رياض الصالحين؛ فإنه كتاب جليل، كتاب طيب، وأغلبه صحيح، فالاستفادة من رياض الصالحين أولى؛ لأنه كتاب معروف عند أهل العلم، وهو كتاب مفيد، فينبغي الاعتياض عن هذا برياض الصالحين. أما هذا الكتاب فلا أعرفه، فإذا تفضل السائل بإرسال هذا الكتاب، وإلا سوف نسأل عنه -إن شاء الله- وبعد ذلك نتكلم عنه -إن شاء الله- في حلقة تأتي -إن شاء الله- وسنعمد -إن شاء الله- من يلتمسه؛ حتى نتكلم عنه بما يقتضيه الحال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18013/تقييم-كتاب-رياض-السامعين-وبستان-الواعظين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_879/nour_87907.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18872,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: أم ياسر من السعودية، أختنا تقول: إني أنجبت بنتين معوقتين، وهما أختان من الأب والأم، البنت الأولى عمرها ثلاث عشرة سنة، وهي تسمع وترى، لكنها لا تعرف أن تتكلم، أو أن تنطق اسمها، ولا تعرف حتى الليل من النهار، ودرست ست سنوات في المعهد الفكري في جدة، ولم تستفد شيئًا، ولا حتى حرفًا واحدًا من القرآن الكريم، فبماذا تنصحوني يا فضيلة الشيخ، ولا سيما في أمر الصلاة؛ ذلك أنها لا تعرف شيئًا عنها، وإنني احترت معها، وأنا أعلمها، هل علي إثم إذا تركتها؟أرجو إرشادي، جزاكم الله خيرًا.","title":"كيفية تعليم المعاق والأصم الصلاة","answer":"الجواب: إذا كانت تعقل بالإشارة؛ فعلموها بالإشارة كيف تصلي وكيف تطهر، وإذا كانت لا عقل لها؛ فالحرج منتفي حينئذٍ، ولا تكليف عليها حينئذٍ؛ لقول النبي ﷺ في الحديث الصحيح: رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن الصغير حتى يبلغ، وعن المعتوه حتى يفيق فهي الآن بين الأمرين: إما أن تكون تعقل؛ فعلموها ولو بالإشارة، كيف تصلي، كيف تتوضأ، كيف تستنجي، علموها، فإذا تعلمت، كفى والحمد لله، وهي تصلي بقلبها ولو لم تنطق: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وأحسنوا إليها، وأبشروا بالخير، وارحموها يرحمكم الله. أما إن كانت لا تعقل، ولا تفهم الإشارة، ولا تستفيد؛ فليس عليكم شيء، والتكليف عنها مرفوع، كالمجنون ونحوه، نسأل الله السلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18036/كيفية-تعليم-المعاق-والاصم-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88008.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":18890,"question":"يسأل سماحتكم مجموعة من الكتب، أولًا : الكتب التي تبحث في العقيدة.","title":"ما الكتب التي ينصح بقراءتها في العقيدة؟","answer":"الجواب: ... فتح المجيد للشيخ عبد الرحمن بن حسن، تيسير العزيز الحميد للشيخ سليمان بن عبد الله، التدمرية لشيخ الإسلام ابن تيمية، الحموية لشيخ الإسلام ابن تيمية أيضًا، العقيدة الواسطية له أيضًا، زاد المعاد لابن القيم -رحمه الله- إغاثة اللهفان لابن القيم -رحمه الله- الصواعق المرسلة لابن القيم -رحمه الله- اجتماع الجيوش الإسلامية لابن القيم -رحمه الله- كتاب التوحيد للشيخ محمد بن عبد الوهاب، ثلاثة الأصول، كشف الشبهات له أيضًا -رحمه الله- كل هذه كتب عظيمة مفيدة. الطحاوية وشرحها لابن أبي العز، كلها طيبة في العقيدة، وأعظم ذلك وأكبرها القرآن العظيم، هو أعظم وأكبر، وهو أصدق كتاب، وأعظم كتاب، كتاب الله القرآن، هو كتاب عقيدة، وكتاب أحكام، فنوصي كل مسلم ومسلمة بالعناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، ففيه العلم العظيم بالعقيدة والأحكام الشرعية. وهكذا أحاديث الرسول ﷺ كتب الحديث الشريف الصحيحين: البخاري ومسلم، مثل رياض الصالحين، منتقى الأخبار لابن تيمية، بلوغ المرام للحافظ ابن حجر، كتب جيدة عظيمة في الحديث، عمدة الحديث للشيخ: عبد الغني بن عبد الواحد المقدسي، كتاب عظيم، نعم. المقدم: جزاكم الله خيرًا، أيضًا يسأل سماحتكم عناوين لبعض كتب الفقه. الشيخ: كتب الفقه كثيرة، لكن من أفضلها، كتاب المغني للموفق عبد الله بن قدامة، والمجموع للنووي -رحمه الله-، والمقنع للموفق -رحمه الله- عبد الله بن قدامة، كشاف القناع والمنتهى للحنابلة، شرح الزاد الروض المربع للحنابلة، وحاشيته لابن أبي القاسم، كل هذه كتب مفيدة، نعم. المقدم: جزاكم الله خيرًا. الحديث؟ الجواب: تقدم بيانه، نعم. المقدم: السيرة؟ الشيخ: سيرة ابن إسحاق، سيرة ابن هشام، زاد المعاد لابن القيم، كلها فيها السيرة النبوية، كتاب الشيخ عبد الله بن محمد بن عبد الوهاب السيرة النبوية، وكتاب الشيخ محمد -رحمه الله- أيضاً، السيرة النبوية كلها مطبوعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18033/ما-الكتب-التي-ينصح-بقراءتها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73620.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18915,"question":"هذه الأخت السائلة، أرسلت بمجموعة من الأسئلة تقول: سماحة الشيخ، أرجو إرشادي إلى بعض الكتب التي تنصحون بقراءتها في الأحاديث القدسية.","title":"بعض الكتب التي ينصح بقراءتها في الحديث","answer":"الجواب: ننصحك بالعناية بالقرآن، والإكثار من قراءة القرآن، فهو كتاب الله، فيه الهدى والنور، فنوصيك وغيرك بالإكثار من قراءة القرآن، والكتب الصحيحة مثل كتاب رياض الصالحين، وبلوغ المرام، وعمدة الحديث، ومنتقى الأخبار، تستفيدون منها، هذه كتب حديث أغلبها جيد وصحيح، فاستفيدوا منها، ولكن عليكم بالقرآن أكثر، أكثروا من قراءة القرآن بالتدبر والتعقل ليلًا ونهارًا، وإذا راجعتم كتب الحديث كرياض الصالحين، منتقى الأخبار، بلوغ المرام، عمدة الحديث، صحيح البخاري، صحيح مسلم، هذا فيه خير عظيم، فائدة كبيرة. المقدم: أحسن الله إليكم، وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18093/بعض-الكتب-التي-ينصح-بقراءتها-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88220.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18953,"question":"يقول بالنسبة للكتب التي تنصحوننا في قراءتها في هذه المجالس سماحة الشيخ؟","title":"ما الكتب التي تنصحون بقراءتها؟","answer":"الجواب: أعظم كتاب القرآن أنصحك بالقرآن العظيم، ننصح جميع المسلمين بالعناية بالقرآن، والإكثار من تلاوته، فهو كتاب الله فيه الهدى والنور، كما قال سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ[الإسراء:9] قال تعالى: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44] وقال سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ[ص:29] قال سبحانه: أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا[محمد:24]. فنوصي جميع المسلمين رجالًا ونساءً نوصيهم بالقرآن، نوصيهم بالإكثار من تلاوته، وتدبر معانيه، وحفظه، أو ما تيسر منه، فهو كتاب الله فيه الهدى والنور، فيه الدعوة إلى مكارم الأخلاق، ومحاسن الأعمال، فيه الدعوة إلى فعل ما أوجب الله، وترك ما حرم الله، فيه قصص الأنبياء والمرسلين، فيه قصص الأخيار حتى يتأسى بهم، فيه قصص الأشرار حتى تجتنب أعمالهم. ثم كتب الحديث الشريف كالصحيحين للبخاري، ومسلم، السنن الأربعة لمن كان عنده علم يقرأ فيهما. وأما المبتدئ -طالب العلم المبتدئ- فنوصيه بمثل المختصرات التي يستطيع حفظها مثل بلوغ المرام، مثل كتاب التوحيد، العقيدة الواسطية، ثلاثة الأصول، الأربع القواعد للشيخ محمد بن عبد الوهاب -رحمه الله- كتاب التوحيد، وثلاثة الأصول، والقواعد الأربع للشيخ محمد بن عبد الوهاب -رحمه الله- كشف الشبهات كذلك له -رحمه الله-، العقيدة الواسطية لشيخ الإسلام ابن تيمية، بلوغ المرام للحافظ ابن حجر، عمدة الحديث للحافظ الشيخ عبد الغني بن سرور المقدسي، هذه كتب ينبغي حفظها، تفيد تنفع؛ لأنها كتب مهمة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ على هذا التوجيه الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/18144/ما-الكتب-التي-تنصحون-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79210.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18964,"question":"السائلة تقول: في حديث ما معناه بأن: \"من طلب العلم لغير وجه الله؛ فإنه يتبوأ مقعده من النار\" تقول: حيث أنني صممت أن أكمل دراستي الجامعية، وكان ذلك أيضًا رغبة والدي، فكانت الأفكار تراودني في أثناء الدراسة أن لا أكمل ذلك، ولكنني عزمت بشدة أن أكمل لأحقق رغبة والدي، وأجلب له الفرح بذلك، فهل ينطبق علي حكم الحديث؟","title":"حكم طلب العلم لغير وجه الله","answer":"الجواب: عليك التوبة إلى الله، الواجب طلب العلم لابتغاء وجه الله، هذا هو الواجب، ولا ينبغي طلب العلم للوظيفة أو لإرضاء فلان أو فلان، بل الواجب أن يكون طلب العلم ابتغاء وجه الله، يقول النبي ﷺ: ثلاثة هم أول من تسعر بهم النار: رجل تعلم العلم ليقال له: عالم، وتفقه ليقال: فقيه نسأل الله العافية. فالمقصود: أن الواجب على المؤمن في عباداته كلها، ومنها طلب العلم أن يتعلم ابتغاء وجه الله؛ ليعرف دينه؛ ليتبصر في دينه؛ ليعرف ما أوجب الله عليه، وما حرم الله عليه، والوظائف تبع، لكن المقصود تعلمه ليتفقه في الدين؛ ليعرف ما شرع الله له؛ ليعلم ما أوجب الله عليه، وما حرم الله عليه حتى يكون على بصيرة في دينه. المقدم: سماحة الشيخ، بماذا توجهون طلاب العلم وطالبات العلم للتزود من العلم الشرعي؟ الشيخ: نصيحتي للجميع العناية بطلب العلم الشرعي، والتفقه في القرآن والسنة، والسؤال عما أشكل، وإذا تعلم مع هذا أمورًا أخرى في أمور الدنيا فلا بأس، لكن ليهتم بالتفقه في الدين يقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18104/حكم-طلب-العلم-لغير-وجه-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88225.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18980,"question":"سماحة الشيخ هذه الفتاوى التي بدأت تنتشر في الصحف والمجلات، سواءً كانت الصحف من الداخل، أو الخارج قد يعتمد عليها بعض المسلمين، هل لكم من توجيه؟","title":"التحذير من الفتاوى التي لا تستند إلى دليل","answer":"الجواب: الواجب عدم الاعتماد على الفتاوى التي تنشر في الصحف، أو تذاع في الإذاعة، أو في التلفاز، حتى يتأكد المؤمن ممن نسبت إليه، فإذا تأكد منه وهو أهل للفتوى فلا بأس؛ لأن كثيرًا من الناس قد يكذب الآن، وقد يلبس عليه، فإذا سمع المؤمن أو المؤمنة فتوى، فالواجب أن يتثبت في ذلك، وألا يجزم بذلك إلا إذا سمعها من صوت المفتي، وهو يعرف صوته، وإلا فلا بد من سؤال المفتي بالهاتف أو بالكتابة حتى يتحقق أنها صدرت منه. وقد علمنا أن كثيرًا من الناس يكذبون علي وعلى غيري في فتاوى كثيرة، كما كذبوا على النبي ﷺ وعلى الصحابة، فالذي وقع في الأول من الكذب على النبي ﷺ وعلى الصحابة لا يستغرب أن يقع في وقتنا هذا من باب أولى.  فالواجب في مثل هذا التثبت، وعدم تصديق من يقول: قال فلان، وقال فلان، وأفتى فلان، وأفتى فلان. وهكذا ما ينشر في الصحف قد يحرف، وقد لا يكون على وجهه، وقد يكون مكذوبًا، هذا كله يوجب على المؤمن والمؤمنة التثبت فيما يذاع وينشر من الفتاوى، وفيما ينقله الناس، حتى يتأكد من وقف على الفتوى من مشافهة صاحبها وسؤاله، هل صدرت منه هذه الفتوى، سواء كانت مشافهة أو بالكتابة أو بالهاتف، حتى يستيقن الأمر وحتى يحتاط لدينه، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.\nإذًا: إذا كانت الفتوى بصوت المفتي فهي المعتمدة؟ الشيخ: نعم يزول الإشكال، إذا سمع صوته يفهمه جيدًا، يزول الإشكال، أما إذا اشتبه عليه صوته فليسأل أيضًا. المقدم: إذًا توجيهكم بالنسبة لتلكم الفتاوى في الصحف والمجلات المتعددة. الشيخ: مثلما تقدم. المقدم: وهو؟ الشيخ: الواجب ألا يعتمد عليها إلا بعد التثبت من صدورها ممن أفتى بها، وبعد العلم بأنه أهل لذلك. المقدم: أيوه، إذًا يجب معرفة من هو المفتي. الشيخ: نعم. المقدم: فإن كان أهلًا للفتوى اعتمدت فتواه، وإن لم يكن فالأمر غير ذلك. الشيخ: بعد سؤاله، والتأكد أنها صدرت منه. المقدم: بارك الله فيكم، وجزاكم الله خيرًا. الشيخ: وإياكم.","link":"https://binbaz.org.sa/fatwas/18128/التحذير-من-الفتاوى-التي-لا-تستند-الى-دليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92503.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18985,"question":"من الباحة هذه رسالة بعثت بها إحدى الأخوات تقول: مشاعل الغامدي، أختنا لها مجموعة من الأسئلة في أحد أسئلتها سؤال يقول: هل يجوز الغش في الامتحان؟ علمًا بأن ذلك ليس في المواد الدينية.","title":"حكم الغش في الامتحانات في غير المواد الدينية","answer":"الجواب: لا يجوز الغش في الامتحان لا في المواد الدينية، ولا في غيرها، الواجب على الطالب والطالبة أن يؤدي الامتحان بغاية الأمانة؛ لأن المقصود أن تعرف منزلته في العلم وأهليته ومدى ذكائه وفطنته، فالخيانة تفسد هذا وتضيع هذا، فالواجب على الطالب وعلى الطالبة أن يؤدي الأمانة، وأن يبتعد عن الغش؛ لعموم قوله ﷺ: من غشنا فليس منا فالرسول ﷺ نهى عن الغش، وقال: من غشنا فليس منا وهذا من جوامع الكلم يعم الغش في البيع والشراء، ويعم الغش في الامتحان والاختبار، ويعم الغش في غير ذلك، حتى ولو كانت المادة إنجليزية أو حسابية أو غير ذلك، الواجب أن تؤدي الأمانة الطالبة والطالب جميعًا، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18083/حكم-الغش-في-الامتحانات-في-غير-المواد-الدينية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92406.mp3","categories":["الأخلاق المذمومة","العالم والمتعلم"]},{"id":19036,"question":"في آخر أسئلة السائلة من اليمن أم رشيدة اليمن الخضراء تقول: إذا دعاني الزوج من أجل أن يعلمني العلم الشرعي ولم أجبه؛ حيث إنني أغلب الأوقات مشغولة في البيت، هل أعتبر بذلك آثمة؟","title":"امتناع الزوجة عن التعلم بسبب أعمال البيت","answer":"الجواب: يخشى عليك من ذلك، الواجب عليك طاعة زوجك إذا دعاك أجيبي إذا دعاك أجيبي، إما أن يأمرك بشيء وإما أن تكون له حاجة فالواجب عليك أن تجيبيه، إلا من ضرورة لا تستطيعين معها الإجابة وإلا فالواجب الإجابة. نعم.","link":"https://binbaz.org.sa/fatwas/18206/امتناع-الزوجة-عن-التعلم-بسبب-اعمال-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88306.mp3","categories":["العالم والمتعلم","الحقوق الزوجية"]},{"id":19097,"question":"سؤالها الأخير تقول: ما هو رأي سماحتكم في كتاب: مشاهد القيامة في القرآن، لـسيد قطب؟","title":"تقييم كتاب: مشاهد القيامة في القرآن لـسيد قطب","answer":"الجواب: لم أقرأه، ولكن فيما بلغني عنه أنه لا بأس به، كتب الـسيد قطب مفيدة ونافعة، وليس معناها أن ليس فيها خطأ، كل عالم له بعض الأخطاء والأغلاط، لكني لم أقرأ الكتاب وهو فيما بلغني كتاب مفيد ومؤثر، رحم الله مؤلفه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18304/تقييم-كتاب-مشاهد-القيامة-في-القران-لـسيد-قطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88410.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19101,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد سعيد محمود من الجمهورية العراقية، وهو مصري الجنسية، أخونا بدأ رسالته بقوله: السادة الأساتذة الكرام وعلماءنا ومعلمينا الأفاضل في برنامج: نور على الدرب، سلام الله عليكم ورحمته وبركاته.. وبعد، قرأت في كتاب يسمى بدائع الزهور في وقائع الدهور: لما دخل نبي الله يعقوب إلى مصر مشى العسكر بين يديه حتى وصل إلى قصر ابنه يوسف حيث كان وزير وعزيز مصر في ذلك الوقت، وعندما دخل القصر رفع يوسف أباه وخالته على سريره، وأمر العسكر أن يسجدوا لهما، وكان ذلك عادة أهل مصر في التحية.فهل سجود التحية مباح في مثل هذه المواقف؟ أرجو من سيادتكم تفسيرًا عن ذلك حفظكم الله وزادكم من علمه ونفعنا بكم والمسلمين، آمين.","title":"ما تقييم كتاب: بدائع الزهور؟، وحكم السجود لغير الله للتحية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فينبغي أن يعلم أن هذا الكتاب وهو بدائع الزهور ليس من الكتب المعتمدة، بل هو حاطب ليل، يذكر الغث والسمين، والصحيح والباطل، فلا يعتمد عليه، وأخبار بني إسرائيل أخبار قديمة، لا يعتمد عليها إلا ما ثبت عن الله أو عن رسوله محمد عليه الصلاة والسلام، ونص القرآن أن يوسف عليه الصلاة والسلام رفع أبويه على العرش، وهما أبوه وأمه لا خالته، بل أبوه وأمه؛ لأن الله قال: وَرَفَعَ أَبَوَيْهِ عَلَى الْعَرْشِ وَخَرُّوا لَهُ سُجَّدًا [يوسف:100]. وكانت السجدة ذلك الوقت مباحة للإكرام والتحية، وليست للعبادة، وكما سجد الملائكة لـآدم إكرامًا وتعظيمًا لا عبادة، فهذه السجدة ليست من باب العبادة ولكن من باب التحية والإكرام، وهي جائزة في شرع من قبلنا، ولكن في شريعة محمد عليه الصلاة والسلام ممنوع ذلك، ولهذا ثبت عنه عليه الصلاة والسلام أنه قال: لو كنت آمرًا أحدًا أن يسجد لأحد لأمرت المرأة أن تسجد لزوجها لعظم حقه عليها. وبين أن السجود لله ، فلا يسجد إلا لله وحده ، وقال  في آخر سورة النجم: فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا [النجم:62]، وقال في سورة اقرأ: وَاسْجُدْ وَاقْتَرِبْ [العلق:19] ، فالسجود لله وحده، وشريعة محمد عليه الصلاة والسلام هي أكمل الشرائع وأتمها، فلا يجوز فيها السجود لغير الله، لا تحية ولا عبادة، أما العبادة فلا تصح إلا لله وحده في جميع الشرائع؛ لأن الله جل وعلا قال: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، قال سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]. فالعبادة حق الله وحده في كل زمان ومكان، ولكن كان السجود فيما مضى يستعمل تحية وإكرامًا كما فعل أبوي يوسف وإخوته، وكما فعلت الملائكة لـآدم هذا من باب التحية والإكرام وليس من باب العبادة، أما في شريعة محمد عليه الصلاة والسلام فإن الله  منع من ذلك، وجعل السجود لله وحده  ولا يجوز أن يسجد لأحد، لا للأنبياء ولا غيرهم، حتى محمد عليه الصلاة والسلام منع أن يسجد له أحد، وأخبر أن السجود لله وحده  فعلم بهذا أن جميع أنواع العبادة كلها لله وحده  ومن أعظمها السجود، فإنه ذل وانكسار لله  فهو من أفضل العبادات، فلا يصرف لغيره من الناس لا للأنبياء ولا للجن ولا للإنس، ولا غيرهم، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18299/ما-تقييم-كتاب-بداىع-الزهور-وحكم-السجود-لغير-الله-للتحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88406.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19128,"question":"من هم أهل الفتوى الذين يجب على عامة المسلمين الأخذ بفتواهم، ولنا أخ في الله مؤمن مسلم وسلوكه جيد في الدين، وفي الحياة العامة، ولكنه ليس متفقهًا في الدين لدرجة أن يفتي، وفي بعض المسائل يفتينا ويقول: هذا على مسئوليتي، فهل نأخذ بفتواه أم لا، وهل من حقه أن يفتي أم لا؟","title":"تعريف أهل الفتوى","answer":"الجواب: أهل الفتوى هم الذين قد تفقهوا في كتاب الله وسنة رسوله عليه الصلاة والسلام، وحصلت لهم معرفة جيدة بما أحل الله، وما حرم الله، وما أوجب الله، وشهد لهم أهل العلم والفقه والخير، عن المعرفة، وأنهم أهل لأن يفتوا، ولا ينبغي أن يستفتى كل أحد، ولو انتسب إلى الدين أو إلى العبادة، أو إلى العلم حتى يسأل عنه أهل العلم، ويتبصر السائل بواسطة العارفين به، والذين يطمئن إليهم أنهم أهل علم حتى يذكروا له أنه أهل للفتوى وأهل لأن يفتي في الحلال والحرام ونحو ذلك. المقصود أن هذا يحتاج إلى تثبت في الأمر، وعدم تساهل، فليس كل من انتسب إلى الدين، أو إلى العبادة، أو إلى العلم يصلح لذلك، بل لا بد من فقه في الدين وتبصر، ولا بد من ورع وتقوى لله، ولا بد من حذر من التساهل في الفتوى والجرأة عليها بغير علم وبغير حق، ولا حول ولا قوة إلا بالله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18310/تعريف-اهل-الفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88504.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19172,"question":"أخونا أيضًا يقول: إن نظام وقوانين الشهادات تسبب في تعطيل كثير من العلم النافع، فلم يوجد المدرس الكفء الصالح الذي يربي النشء تربية حقيقية، وأصبح الطالب لا يهمه إلا حمل الشهادة بغض النظر عن دينه وعقيدته، وفقهه وخلقه، إلى درجة أن بعض الطلبة، بل أيضًا بعض المدرسين لا يعرف كيف يصلي على الجنازة، وأكثرهم لا يصلون الصلوات الخمس، وإذا صلى بعضهم صلى بعض الصلوات وترك البعض الآخر.و ما هو الواجب على المدرسين نحو أنفسهم وطلبتهم؛ لأن أغلب الطلبة يتمثلون في مدرسيهم، ويأخذون عنهم الكثير مما هم عليه من الجهل بشرع الله، والإهمال في عبادة الله، والعادات والتقاليد المخالفة لدين الله، والسؤال أيضًا: ما هو الواجب على الطلبة نحو أنفسهم، وما هو الواجب على ولاة الأمور تجاه الطلبة؟جزاكم الله خيرًا.","title":"ما هو الواجب على المدرسين نحو أنفسهم وطلبتهم؟","answer":"الجواب: التنظيم الذي وقع في الناس منذ دهر طويل حصل به مصالح جمة، من تنشيط الطلبة وترغيبهم في طلب العلم، وأخذ الشهادات التي تشجعهم على طلب العلم، والاستعانة بها على الوظائف وعلى مصالحهم الدنيوية، فيه مصالح، وفيه مضار؛ لأن كثيرًا من الطلبة لا يطلب العلم للآخرة، وإنما يطلبه للدنيا، ومصالحها وفوائدها، ووظائفها، ففيه خير وشر، فمن طلب العلم لله من طريق النظم المتبعة، فأخذ الشهادات واستعان بها على طاعة الله، وتفقه في الدين نفع الله به الأمة، وصارت هذه الشهادات عونًا له وزادًا له على أداء المهمة، وعلى دعوة الناس إلى الخير، وعلى أن يقدر ويعرف له فضله، ومن استعان بها على الدنيا ونسي الآخرة، صارت حظه من الدنيا ولم يكن له من الآخرة.. ولم يكن له في الآخرة نصيب إذا لم يعمل للآخرة ولم يكدح لها. فالحاصل أن هذه الشهادات التي يأخذها الطالب وهذه التنظيمات التي يسير عليها الطالب تنفع المجد الصالح الطيب الذي يريد الآخرة، تنفعه وتعينه، والآخر الذي لا يريد الآخرة ما تزيده إلا خبالًا، ولا تزيده قربًا من الله ؛ لأنه ما أراد بها الآخرة، وإنما أراد بها الدنيا، وحظها العاجل، وقد يوفق بعض الناس فيتعلم للدنيا ثم يهديه الله ويتعلم للآخرة، ويستفيد كما قال بعض السلف: طلبنا العلم لغير الله فأبى أن يكون إلا لله. فالواجب على المدرسين أن يتقوا الله، وأن يلتزموا بالإسلام، وبأخلاق الإسلام، وأعمال الإسلام، حتى يكونوا قدوة للطلبة، ولاسيما من يدرس العلوم الشرعية، فإن الواجب عليه أن يكون أقرب الناس إلى الخير، وأكملهم في الخير، وأسبق الناس إلى طاعة الله ورسوله، وأبعد الناس عن معصية الله ورسوله، حتى يتأسى به تلاميذه، وحتى يقتدوا به في الخير. والواجب على الأستاذ أيضًا أن يكون حريصًا على تفقيه الطلبة وتشجيعهم على الخير، وترغيبهم فيه، وأن يحثهم على طاعة الله ورسوله، ويحذرهم من معصية الله ورسوله، وأن يحثهم على التأسي بالرسول ﷺ وبأصحابه الكرام، وبأهل الخير، وأن يحذرهم من التأسي بأهل الشر، فهو يحثهم باللسان ويحثهم بالعمل، يكون قدوة صالحة في عمله، ومع ذلك هو يرغبهم ويحثهم بلسانه، فيجمع بين الأمرين، بين التشجيع القولي، والتشجيع العملي، فيرون من أعماله وسيرته ما يسرهم وما يعينهم على طاعة الله ورسوله، ويسمعون منه الدرس وفي غير الدرس من الكلام الطيب والتوجيه الصالح، والأمر بالمعروف والنهي عن المنكر ما يسرهم ويعينهم على طاعة الله ورسوله، هذا هو الواجب على الجميع. وعلى الطالب أن يتقي الله، عليه أن يتقي الله وألا تكون همه.. وألا يكون همه الشهادة، بل عليه أن يتقي الله حتى يستعين بالشهادة على طاعة الله ورسوله، وحتى يستعين بالشهادة على نفع العباد في توجيههم إلى الخير، وأمرهم بالمعروف، ونهيهم عن المنكر، وتعليم جاهلهم، وإرشاد ضالهم إلى غير ذلك، لا تكن الشهادة وسيلة فقط للدنيا، لا، بل عليه أن يستعملها في أمر الدين والدنيا، يستعين بها على طاعة الله، وينتفع بها في الوظيفة التي يوظف بسببها حتى ينتفع في دنياه وأخراه. فهذه الدور العلمية من معاهد ومدارس وجامعات، أنشئت للعلم في بلاد المسلمين، ولتعليم الناس ولتوجيه الناس إلى الخير، فعلى القائمين عليها أن ينصحوا لله ولعباده، وأن يجتهدوا في توجيه الناس إلى الخير، وإرشادهم إليه، وعلى الطالب أن يتقي الله وأن يجتهد في طلب العلم النافع، وأن يجتهد أيضًا في سؤال أهل العلم، والاستفادة من آرائهم، وأن يكون متواضعًا، يريد العلم، يريد الفقه في الدين، وعليه أن يعمل بعلمه في أقواله وأفعاله، عليه أن يعمل، تعرف عليه آثار العلم في خشيته لله، وفي قيامه بأمر الله، وفي محافظته على طاعة الله، وفي بره لوالديه، وفي صلته لأرحامه، وفي إكرامه لجاره، وفي غير هذا من أعمال الخير، ولاسيما الصلاة في المحافظة عليها، والمسارعة إليها في الجماعة والخشوع فيها، هكذا يكون الطالب الصالح المجد. وعلى المدرس أن يعتني بالطلبة ويوجههم، وأن يكون قدوة صالحة كما تقدم لهم في الخير كله، ونسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، نفع الله بكم.","link":"https://binbaz.org.sa/fatwas/18369/ما-هو-الواجب-على-المدرسين-نحو-انفسهم-وطلبتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88703.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19258,"question":"يسأل سماحتكم، ما هي أفضل الكتب في العقيدة؟","title":"أفضل الكتب في العقيدة","answer":"الجواب: أفضل الكتب وأصحها: القرآن العظيم فقد بين العقيدة الصحيحة، فالقرآن هو كتاب الله وأصدق كتاب، وأفضل كتاب، وأعظم كتاب فيه بيان العقيدة الصحيحة، بيان أسماء الله صفاته وتوحيده والإخلاص له  هو أعظم كتاب. ثم يليه بعد ذلك: البخاري ومسلم الصحيحان هي أعظم الكتب المفيدة من كتب الحديث بعد القرآن؛ لأن فيها أحاديث الرسول ﷺ الصحيحة فالصحيحان: صحيح البخاري وصحيح مسلم هما أصح الكتب وأنفعها بعد كتاب الله  . ثم بقية الكتب المعروفة، سنن أبي داود والترمذي والنسائي وابن ماجة وموطأ مالك، وسنن الدارمي كتب جيدة مفيدة، وإن كان فيها بعض الأحاديث الضعيفة لكنها كتب مفيدة عظيمة. وكتب العقيدة كثيرة لكن منها ما ألفه السلف الصالح مثل: عثمان بن سعيد الدارمي في الرد على الجهمية، مثل كتاب عبد الله بن أحمد بن حنبل في بيان السنة والرد على أهل البدع مثل كتاب التوحيد لابن خزيمة فيه عن التوحيد والرد على أهل البدع، وأشباهه من الكتب المفيدة، مثل الطحاوية وشرحها، ومثل لمعة الاعتقاد للموفق، والعقيدة الواسطية، والتدمرية، والحموية لشيخ الإسلام ابن تيمية كلها في العقيدة، وكتاب التوحيد للشيخ محمد بن عبد الوهاب رحمه الله، كتاب عظيم ومفيد، كشف الشبهات في العقيدة كذلك للشيخ محمد بن عبد الوهاب رحمه الله، الثلاثة الأصول، كتاب مختصر جيد في العقيدة للشيخ محمد رحمه الله. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18451/افضل-الكتب-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73904.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19275,"question":"تسأل أختنا وتقول: سماحة الشيخ! جزاك الله عنا وعن المسلمين خيرًا، لو تفضلت أن توضح لنا ما هو الكتاب الذي يفيد المرأة في حياتها الأخرى، وتستقيم به حياتها في الدنيا؟ جزاكم الله خيرًا.","title":"ما ينصح بقراءته من الكتب","answer":"الجواب: أعظم كتاب، وأحسن كتاب، وأصدق كتاب ينفع المرأة والرجل جميعًا كتاب الله القرآن، كتاب الله القرآن هو الهدى والنور يقول الله سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ[الإسراء:9]، ويقول : قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44]، ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ[ص:29]، ويقول سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ[النحل:89] يعني: يا محمد! لأنه خطاب للنبي ﷺ: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ[النحل:89]. فأوصي جميع المسلمين ذكورًا وإناثًا أوصيهم ونفسي بتقوى الله جل وعلا في جميع الأمور، والحرص على أداء ما أوجب، وترك ما حرم، والإكثار من ذكره سبحانه بقراءة القرآن، وأنواع الذكر، وأوصيهم وصية خاصة بالقرآن العناية بالقرآن، العناية بالقرآن، الإكثار من تلاوته، وتدبر معانيه، والعمل بما فيه، وحفظه إذا تيسر أو ما تيسر منه، هو أصدق كتاب، وأنفع كتاب. فأوصي الجميع بكتاب الله، أوصي الجميع بكتاب الله تدبرًا وتعقلًا، وإكثارًا من تلاوته في الليل والنهار، وعملاً بما فيه، فيه كل خير، فيه الأمر بالصلاة، والزكاة، والصدقة، والصيام، والحج، وحسن المعاملة إلى غير هذا، الإكثار من ذكر الله، تسبيحه وتهليله، الصلاة على النبي ﷺ إلى غير هذا، يأمر بكل خير، فيه الدعوة إلى كل خير، وفيه النهي عن كل شر يقول  في كتابه العظيم: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ[التوبة:71]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا ۝ وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا[الأحزاب:41-42]، ويقول جل وعلا: فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلا تَكْفُرُونِ[البقرة:152]، ويقول جل وعلا: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا[الأحزاب:56]، ويقول جل وعلا: أَقِمِ الصَّلاةَ طَرَفِيِ النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ذَلِكَ ذِكْرَى لِلذَّاكِرِينَ[هود:114]، ويقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى[البقرة:238] يعني: العصر. وَقُومُوا لِلَّهِ قَانِتِينَ[البقرة:238]، ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ[البقرة:43]، ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ[النور:56] إلى غير هذا، فيه الأوامر بكل خير. وفيه التحذير من كل شر يقول سبحانه: وَلا تَقْرَبُوا الزِّنَى إِنَّهُ كَانَ فَاحِشَةً[الإسراء:32]، ويقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا[الحجرات:12]، ويقول : اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ وَلا تَجَسَّسُوا[الحجرات:12]، ويقول سبحانه في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ[المائدة:90]، والخمر: كل شيء يسكر يقال له: خمر، والميسر: هو القمار، ففي كتاب الله العظيم الدعوة إلى جميع الخيرات، والنهي عن جميع الشرور. ثم بعد ذلك سنة النبي ﷺ مثل الصحيحين البخاري، صحيح البخاري وصحيح مسلم كتابان عظيمان هما أصح الكتب وأنفعها بعد كتاب الله ، ومثل رياض الصالحين كتاب جيد، ومثل المنتقى للمجد ابن تيمية كتاب جيد، وبلوغ المرام في الحديث كتاب جيد، عمدة الحديث للشيخ عبد الغني بن عبد الواحد بن سرور المقدسي كتاب جيد مفيد، مثل كتاب التوحيد فيه حديث، وفيه آيات للشيخ محمد بن عبد الوهاب رحمه الله كتاب جيد عظيم ثلاثة الأصول كتاب جيد مختصر للشيخ محمد بن عبد الوهاب رحمه الله، العقيدة الواسطية في عقيدة أهل السنة والجماعة كتاب مختصر جيد لشيخ الإسلام ابن تيمية رحمه الله. فأنا أوصي بهذه الأشياء كلها جيدة بعد كتاب الله ، نسأل الله للجميع التوفيق والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18462/ما-ينصح-بقراءته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_800/nour_80006.mp3","categories":["العالم والمتعلم","قضايا المرأة"]},{"id":19304,"question":"ننتقل إلى رسالة أخرى وصلت إلى البرنامج من قطر، منطقة دخان، وباعثها أخ لنا من هناك يقول: عبد الله محمد الماحي -فيما يبدو- أخونا يسأل ويقول: هل هناك كتب تتحدث عن الملائكة، أرجو إعلامي بأيسرها حصولًا وفهمًا؟ جزاكم الله خيرًا.","title":"كتب تتكلم عن الملائكة","answer":"الجواب: أعظمها وأحسنها وأصدقها كتاب الله، ففيه البيان الكثير عن الملائكة وأعمالهم عليهم الصلاة والسلام ثم الأحاديث عن رسول الله ﷺ صحيح البخاري عقد للملائكة بابًا مستقلًا في كتابه الصحيح، وهكذا صحيح مسلم وهكذا السنن كلها فيها جملة أحاديث عن الملائكة وأخبار الملائكة عليهم الصلاة والسلام. ثم كتب أهل العلم فيما يتعلق بالملائكة وفي سيرة النبي عليه الصلاة والسلام، ومن أحسن ذلك صحيح البخاري وصحيح مسلم، ثم السنن الأربع فيما يتعلق بالملائكة، ثم ما كتب أهل العلم، ومن أحسن ذلك زاد المعاد في هدي خير العباد لابن القيم رحمه الله فإنه ذكر في الملائكة ما يشفي ويكفي رحمه الله.  المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18509/كتب-تتكلم-عن-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89408.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19369,"question":"تسأل أيضًا عن كتاب سبل السلام؟","title":"تقييم كتاب (سبل السلام) للصنعاني","answer":"الجواب: كتاب سبل السلام معروف أيضًا، وهو للأمير محمد بن إسماعيل الصنعاني، وأصله لمؤلف مغربي وهو كتاب جيد مفيد على بلوغ المرام، وليس بشاف الشرح فيه نقص من جهة الشرح، ولكنه مفيد. المقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18588/تقييم-كتاب-سبل-السلام-للصنعاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_943/nour_94302.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19370,"question":"نعود في بداية هذه الحلقة إلى رسالة إحدى الأخوات المستمعات من العيون في الأحساء، هي: نوال سعد، أختنا نوال عرضنا بعض أسئلتها في حلقة مضت، وبقي لها في هذه الحلقة سؤالان تسأل في سؤالها الأول عن كتاب الترغيب والترهيب؟","title":"تقييم كتاب (الترغيب والترهيب) للمنذري","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فكتاب الترغيب كتاب مشهور معروف للحافظ المنذري، مشتمل على أحاديث كثيرة فيها الصحيح، وفيها الضعيف، وفيها الحسن، وقد أشار في كتابه إلى الضعيف بقوله: وروي، إذا لم يجزم به بل حكاه بصيغة التمريض، فذلك إشارة منه إلى أنه من الأحاديث الضعيفة، وهو كتاب مفيد وعظيم رحم الله مؤلفه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18587/تقييم-كتاب-الترغيب-والترهيب-للمنذري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_943/nour_94301.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19424,"question":"إذا كنت أقيم بمنطقة جبلية وأريد أن أحج، فأي الكتب تنصحوني بقراءتها كي أحج على بصيرة؟ جزاكم الله خيرًا.","title":"كتب ينصح بقراءتها لمن أراد الحج والعمرة","answer":"الجواب: ننصحك بقراءة الكتب التي بينت أحكام الحج، مثل عمدة الحديث للشيخ عبد الغني المقدسي، مثل بلوغ المرام، مثل المنتقى هذه موجودة، وهناك مناسك فيها كفاية وبركة، إذا قرأتها استفدت منها، منها منسك كتبناه في هذا وسميناه: التحقيق والإيضاح لكثير من مسائل الحج والعمرة والزيارة وهو جيد ونافع ومفيد، وهناك مناسك أخرى لغيري من المشايخ والإخوان، مثل منسك الشيخ عبد الله بن جاسم منسك جيد ومفيد، فإذا استعملت شيئًا منه واستفدت منه طيب. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18659/كتب-ينصح-بقراءتها-لمن-اراد-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73614.mp3","categories":["مسائل متفرقة في الحج والعمرة","العالم والمتعلم","نصائح وتوجيهات"]},{"id":19524,"question":"يا سماحة الشيخ! هذه السائلة تقول: هل للمرأة أن تذهب لطلب العلم، وما هي المواد الشرعية التي تنصحون بدراستها؟","title":"حكم طلب العلم للمرأة وكيفية ذلك","answer":"الجواب: نعم، يشرع لها بل يجب عليها أن تتعلم لسماع العلم من طريق الإذاعة، من طريق إذاعة القرآن، من طريق زيارة النساء المعلمات، حضور مجالس العلم التي تستطيع حضورها مع التستر حتى تسمع الفائدة والعلم، سؤال أهل العلم بالتلفون، أو بالمكاتبة، كل هذا من طلب العلم، النبي  يقول: من يرد الله به خيرًا يفقهه في الدين فإذا كان هناك امرأة تعلم النساء وجب عليها أن تذهب إليها مع النساء للتعلم، والتفقه في الدين، وإذا كان هناك حلقات علم للرجال، وحولها مجالس للنساء، محلات نساء خاصة يسمعن العلم تذهب تسمع العلم مع التستر والتحفظ، والبعد عن أسباب الفتنة، وإذا سألت من طريق الهاتف، من طريق التلفون أو المكاتبة تسأل أهل العلم عما أشكل عليها كل هذا من أسباب تحصيل العلم، والله يقول جل وعلا في كتابه العظيم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] . المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18779/حكم-طلب-العلم-للمراة-وكيفية-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94618.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19581,"question":"كيف يمكن للمرأة أن تطلب العلم وهي في منزلها؟ وهل قراءة الكتب وسماع المحاضرات عبر الأشرطة يعتبر من طلب العلم؟","title":"كيفية طلب المرأة للعلم","answer":"الجواب: نعم، سماع الأشرطة، والندوات العلمية، ونور على الدرب من إذاعة القرآن، كل هذا من طلب العلم، قراءة الكتب المفيدة، وسؤال أهل العلم من طريق الهاتف، أو من طريق المكاتبة هذا كله من سبل العلم، ومن تحصيل العلم؛ لأن الله يقول سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ[النحل:43]، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة، ولم يحدد طريقًا دون طريق. فسؤال أهل العلم من طريق الهاتف، ومن طريق المكاتبة أو المشافهة كله من طلب العلم، وقراءة الكتب المفيدة من طلب العلم، وسماع القرآن، والإكثار من قراءة القرآن من أعظم سبل العلم؛ لأن القرآن هو كتاب الله، هو أعظم دليل على العلم، وهو أعظم مرشد، فينبغي الإكثار من قراءة القرآن بالتدبر، والتعقل، والسؤال عما أشكل، كل هذا من طرق العلم. وإذاعة القرآن من أفضل الأسباب، أنا أوصي بالعناية بإذاعة القرآن لسماع ما يذاع فيها من العلوم النافعة، ونور على الدرب، والمواضيع الكثيرة. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/18857/كيفية-طلب-المراة-للعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94731.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19706,"question":"بعد هذا ننتقل إلى حفر الباطن من المنطق الشرقية، عبر رسالة بعث بها المستمع محمد طه إبراهيم، الأخ محمد يقول: لو تكرمتم سماحة الشيخ دلوني على الكتب الفقهية التي أستفيد منها في ديني ودنياي؟","title":"بعض الكتب الفقهية المفيدة","answer":"الجواب:\nنعم، كتب الفقه كثيرة لكن من أحسنها الحاشية لابن جاسم الشيخ عبد الرحمن بن جاسم على الروض المربع في شرح زاد المستقنع، وهي مطبوعة وموجودة ومن أحسنها، المقنع للموفق ابن قدامة عليه حاشية للشيخ سليمان بن عبد الله آل الشيخ جيدة مفيدة، ومن أحسنها العمدة للموفق مختصرة في الفقه، لعبد الله بن أحمد بن قدامة صاحب المغني، ومن أحسنها دليل الطالب وشرحه منار السبيل شرح الدليل وعليه تخريج لأخينا في الله العلامة الشيخ محمد ناصر الدين الألباني هذه كلها كتب مفيدة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/26341/بعض-الكتب-الفقهية-المفيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D8%A8%D8%B9%D8%B6%20%D8%A7%D9%84%D9%83%D8%AA%D8%A8%20%D8%A7%D9%84%D9%81%D9%82%D9%87%D9%8A%D8%A9%20%D8%A7%D9%84%D9%85%D9%81%D9%8A%D8%AF%D8%A9.MP3","categories":["الدعوة والدعاة","العالم والمتعلم"]}]
